const ACADEMY_MEDIA_MAX_FILE_BYTES = 512 * 1024 * 1024;
const ACADEMY_MEDIA_ALLOWED_DOCUMENT_MIME_TYPES = new Set([
  "application/pdf",
  "application/msword",
  "application/vnd.ms-powerpoint",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
  "application/vnd.ms-excel",
  "application/zip",
  "application/x-zip-compressed",
  "text/plain",
  "application/json",
]);

const academyMediaUpload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: ACADEMY_MEDIA_MAX_FILE_BYTES,
  },
  fileFilter: (_req, file, cb) => {
    const mimetype = String(file.mimetype || "").toLowerCase();
    const extension = path.extname(file.originalname || "").toLowerCase();
    const isImage = mimetype.startsWith("image/");
    const isVideo = mimetype.startsWith("video/");
    const isAudio = mimetype.startsWith("audio/");
    const hasKnownImageExtension = [
      ".png",
      ".jpg",
      ".jpeg",
      ".webp",
      ".gif",
      ".svg",
    ].includes(extension);
    const hasKnownVideoExtension = [
      ".mp4",
      ".mov",
      ".webm",
      ".mkv",
      ".avi",
      ".m4v",
      ".mpeg",
      ".mpg",
      ".wmv",
      ".flv",
    ].includes(extension);
    const hasKnownAudioExtension = [
      ".mp3",
      ".wav",
      ".aac",
      ".m4a",
      ".flac",
      ".ogg",
      ".opus",
    ].includes(extension);
    const isKnownDocument =
      ACADEMY_MEDIA_ALLOWED_DOCUMENT_MIME_TYPES.has(mimetype) ||
      [
        ".pdf",
        ".doc",
        ".docx",
        ".ppt",
        ".pptx",
        ".xls",
        ".xlsx",
        ".zip",
        ".txt",
        ".json",
      ].includes(extension);

    if (
      isImage ||
      isVideo ||
      isAudio ||
      hasKnownImageExtension ||
      hasKnownVideoExtension ||
      hasKnownAudioExtension ||
      isKnownDocument ||
      mimetype === "application/octet-stream" ||
      mimetype === "binary/octet-stream"
    ) {
      cb(null, true);
      return;
    }

    cb(new Error("Invalid academy media format"));
  },
});

const PROJECT_FILE_MAX_BYTES = 512 * 1024 * 1024;
const projectFileUpload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: PROJECT_FILE_MAX_BYTES,
  },
  fileFilter: (_req, file, cb) => {
    const mimetype = String(file.mimetype || "").toLowerCase();
    const extension = path.extname(file.originalname || "").toLowerCase();
    const isImage = mimetype.startsWith("image/");
    const isVideo = mimetype.startsWith("video/");
    const isAudio = mimetype.startsWith("audio/");
    const isArchive = [
      "application/zip",
      "application/x-zip-compressed",
      "application/gzip",
      "application/x-gzip",
    ].includes(mimetype);
    const isDocument = [
      "application/pdf",
      "application/msword",
      "application/vnd.ms-powerpoint",
      "application/vnd.ms-excel",
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      "application/vnd.openxmlformats-officedocument.presentationml.presentation",
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
      "text/plain",
      "text/csv",
      "application/json",
    ].includes(mimetype);
    const isKnownExtension = [
      ".pdf",
      ".doc",
      ".docx",
      ".ppt",
      ".pptx",
      ".xls",
      ".xlsx",
      ".zip",
      ".gz",
      ".txt",
      ".csv",
      ".json",
      ".png",
      ".jpg",
      ".jpeg",
      ".webp",
      ".gif",
      ".svg",
      ".mp4",
      ".mov",
      ".webm",
      ".mkv",
      ".avi",
      ".m4v",
      ".mp3",
      ".wav",
      ".aac",
      ".m4a",
      ".flac",
      ".ogg",
      ".opus",
    ].includes(extension);

    if (
      isImage ||
      isVideo ||
      isAudio ||
      isArchive ||
      isDocument ||
      isKnownExtension ||
      mimetype === "application/octet-stream" ||
      mimetype === "binary/octet-stream"
    ) {
      cb(null, true);
      return;
    }

    cb(new Error("Ugyldig prosjektfilformat."));
  },
});

const app = express();

app.post(
  "/api/role-room/billing/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const stripe = getRoleRoomStripeClient();
    if (!stripe) {
      return res.status(503).json({
        error: "Stripe er ikke konfigurert på serveren.",
      });
    }

    const signatureHeader = req.headers["stripe-signature"];
    const webhookSecret = getRoleRoomStripeWebhookSecret();
    const rawBody = Buffer.isBuffer(req.body)
      ? req.body
      : Buffer.from(String(req.body ?? ""), "utf8");

    let event: Stripe.Event;
    try {
      if (webhookSecret) {
        if (typeof signatureHeader !== "string" || !signatureHeader.trim()) {
          return res.status(400).json({
            error: "Mangler stripe-signature-header.",
          });
        }
        event = stripe.webhooks.constructEvent(
          rawBody,
          signatureHeader,
          webhookSecret,
        );
      } else if (process.env.NODE_ENV === "production") {
        return res.status(503).json({
          error: "Stripe webhook-secret mangler på serveren.",
        });
      } else {
        event = JSON.parse(rawBody.toString("utf8")) as Stripe.Event;
      }
    } catch (error) {
      console.error("Role Room Stripe webhook signature error:", error);
      return res.status(400).json({
        error: "Kunne ikke verifisere Stripe-webhooken.",
      });
    }

    try {
      const eventTimestamp = event.created
        ? new Date(event.created * 1000).toISOString()
        : new Date().toISOString();

      switch (event.type) {
        case "checkout.session.completed":
        case "checkout.session.async_payment_succeeded": {
          const session = event.data.object as Stripe.Checkout.Session;
          // Route agent add-on checkouts to our handler first. If the
          // metadata tag doesn't match, the commercial sync runs as usual.
          const agentResult = await handleAgentCheckoutSessionCompleted(pool, session);
          if (!agentResult.matched) {
            await syncRoleRoomCommercialStripeCheckoutSession(session, eventTimestamp);
          }
          break;
        }
        case "invoice.paid":
          await syncRoleRoomCommercialStripeInvoice(
            event.data.object as Stripe.Invoice,
            eventTimestamp,
          );
          break;
        case "invoice.payment_failed": {
          const invoice = event.data.object as Stripe.Invoice;
          const agentResult = await handleAgentPaymentFailed(pool, invoice);
          if (!agentResult.matched) {
            await clearRoleRoomCommercialStripeSubscription(invoice);
          }
          break;
        }
        case "customer.subscription.deleted": {
          const subscription = event.data.object as Stripe.Subscription;
          const agentResult = await handleAgentSubscriptionRevoked(
            pool,
            subscription,
            "customer.subscription.deleted",
          );
          if (!agentResult.matched) {
            await clearRoleRoomCommercialStripeSubscription(subscription);
          }
          break;
        }
        default:
          break;
      }

      return res.json({ received: true });
    } catch (error) {
      console.error("Role Room Stripe webhook handling error:", error);
      return res.status(500).json({
        error: "Kunne ikke behandle Stripe-webhooken.",
      });
    }
  },
);

app.post(
  "/api/platform/billing/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    const stripe = getCreatorHubStripeClient();
    if (!stripe) {
      return res.status(503).json({
        error: "Stripe er ikke konfigurert for CreatorHub.",
      });
    }

    const signatureHeader = req.headers["stripe-signature"];
    const webhookSecret = getCreatorHubStripeWebhookSecret();
    const rawBody = Buffer.isBuffer(req.body)
      ? req.body
      : Buffer.from(String(req.body ?? ""), "utf8");

    let event: Stripe.Event;
    try {
      if (webhookSecret) {
        if (typeof signatureHeader !== "string" || !signatureHeader.trim()) {
          return res.status(400).json({
            error: "Mangler stripe-signature-header.",
          });
        }
        event = stripe.webhooks.constructEvent(
          rawBody,
          signatureHeader,
          webhookSecret,
        );
      } else if (process.env.NODE_ENV === "production") {
        return res.status(503).json({
          error: "CreatorHub Stripe webhook-secret mangler på serveren.",
        });
      } else {
        event = JSON.parse(rawBody.toString("utf8")) as Stripe.Event;
      }
    } catch (error) {
      console.error("CreatorHub Stripe webhook signature error:", error);
      return res.status(400).json({
        error: "Kunne ikke verifisere CreatorHub Stripe-webhooken.",
      });
    }

    try {
      switch (event.type) {
        case "checkout.session.completed":
        case "checkout.session.async_payment_succeeded": {
          const session = event.data.object as Stripe.Checkout.Session;
          // Also accept agent add-on checkouts on the CreatorHub webhook so
          // Stripe accounts that only have a single webhook registered
          // still work end-to-end.
          const agentResult = await handleAgentCheckoutSessionCompleted(pool, session);
          if (!agentResult.matched) {
            await syncCreatorHubStripeCheckoutSession(session);
          }
          break;
        }
        case "invoice.paid":
          await syncCreatorHubStripeInvoice(
            event.data.object as Stripe.Invoice,
          );
          break;
        case "invoice.payment_failed": {
          const invoice = event.data.object as Stripe.Invoice;
          const agentResult = await handleAgentPaymentFailed(pool, invoice);
          if (!agentResult.matched) {
            await clearCreatorHubStripeSubscription(invoice);
          }
          break;
        }
        case "customer.subscription.deleted": {
          const subscription = event.data.object as Stripe.Subscription;
          const agentResult = await handleAgentSubscriptionRevoked(
            pool,
            subscription,
            "customer.subscription.deleted",
          );
          if (!agentResult.matched) {
            await clearCreatorHubStripeSubscription(subscription);
          }
          break;
        }
        // Slice 10.2 — gallery checkout completion. We only act when
        // metadata.galleryId is present so other PaymentIntent flows
        // (subscriptions, agent add-ons) pass through untouched.
        case "payment_intent.succeeded": {
          const intent = event.data.object as Stripe.PaymentIntent;
          const galleryId = intent.metadata?.galleryId;
          if (!galleryId) break;
          // Stamp the row + emit a download token. Photo-zip endpoint
          // already accepts any 'succeeded' row for this gallery+email
          // pair, so the token is mostly an audit-trail breadcrumb;
          // future Slice 10.4 print-checkout will use it for download
          // links emailed to the client.
          const downloadToken = crypto.randomBytes(24).toString('base64url');
          const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30d
          try {
            await pool.query(
              `UPDATE client_image_payments
               SET payment_status = 'succeeded',
                   download_token = $1,
                   download_expires_at = $2,
                   updated_at = NOW()
               WHERE stripe_payment_intent_id = $3`,
              [downloadToken, expiresAt, intent.id],
            );
          } catch (err) {
            console.error('[client-gallery] payment_intent.succeeded persist failed:', err);
          }
          // Analytics — registrer betaling i ecosystem-loggen.
          recordAnalyticsEvent('payment.succeeded', {
            entityType: 'gallery',
            entityId: String(galleryId),
            actorUserId: intent.metadata?.userId ?? null,
            metadata: {
              amount: intent.amount,
              currency: intent.currency,
              stripeIntentId: intent.id,
              clientEmail: intent.metadata?.clientEmail ?? null,
            },
          });
          // Slice 10.4 — print-order branch. Hvis metadata.kind ===
          // 'print_order', stempel print_orders-rad i tillegg.
          // payment_status='succeeded' så frontend kan vise
          // bekreftelse, fulfillment_status fortsetter på 'pending'
          // til fotograf manuelt markerer som sendt.
          if (intent.metadata?.kind === 'print_order') {
            try {
              await pool.query(
                `UPDATE print_orders
                 SET payment_status = 'succeeded', updated_at = NOW()
                 WHERE stripe_payment_intent_id = $1`,
                [intent.id],
              );
            } catch (printErr) {
              console.warn('[print-store] mark-paid failed:', printErr);
            }
            recordAnalyticsEvent('print_order.paid', {
              entityType: 'print_order',
              entityId: String(intent.metadata?.galleryId ?? ''),
              actorUserId: intent.metadata?.photographerId ?? null,
              metadata: {
                amount: intent.amount,
                currency: intent.currency,
                stripeIntentId: intent.id,
              },
            });
            // Slice 9D.5.D — varsle fotograf via WebSocket så
            // pending-print-orders-badgen oppdateres umiddelbart.
            const photographerOwner = typeof intent.metadata?.photographerId === 'string'
              ? intent.metadata.photographerId
              : null;
            if (photographerOwner) {
              broadcastChatEventToUser(photographerOwner, {
                type: 'print_order_paid',
                galleryId: intent.metadata?.galleryId ?? null,
                amount: intent.amount,
                currency: intent.currency,
                paidAt: new Date().toISOString(),
              });
            }
          }
          break;
        }
        case "payment_intent.payment_failed": {
          const intent = event.data.object as Stripe.PaymentIntent;
          if (!intent.metadata?.galleryId) break;
          try {
            await pool.query(
              `UPDATE client_image_payments
               SET payment_status = 'failed', updated_at = NOW()
               WHERE stripe_payment_intent_id = $1`,
              [intent.id],
            );
          } catch (err) {
            console.error('[client-gallery] payment_intent.payment_failed persist failed:', err);
          }
          recordAnalyticsEvent('payment.failed', {
            entityType: 'gallery',
            entityId: String(intent.metadata?.galleryId ?? ''),
            actorUserId: intent.metadata?.userId ?? null,
            metadata: {
              amount: intent.amount,
              currency: intent.currency,
              stripeIntentId: intent.id,
              clientEmail: intent.metadata?.clientEmail ?? null,
              lastError: intent.last_payment_error?.message ?? null,
            },
          });
          break;
        }
        default:
          break;
      }

      return res.json({ received: true });
    } catch (error) {
      console.error("CreatorHub Stripe webhook handling error:", error);
      return res.status(500).json({
        error: "Kunne ikke behandle CreatorHub Stripe-webhooken.",
      });
    }
  },
);

