const tableColumnsCache = new Map<string, Set<string>>();
const tableExistsCache = new Map<string, boolean>();
const firmwareCompatColumnDefinitions = [
  ['description', 'text'],
  ['importance', "varchar default 'normal'"],
  ['release_notes', 'text'],
  ['last_checked', 'timestamp'],
] as const;
let firmwareCompatColumnsPromise: Promise<void> | null = null;

async function getTableColumns(tableName: string): Promise<Set<string>> {
  const cached = tableColumnsCache.get(tableName);
  if (cached) return cached;

  const result = await pool.query(
    "select column_name from information_schema.columns where table_schema = current_schema() and table_name = $1",
    [tableName],
  );
  const columns = new Set<string>(
    result.rows.map((row) => String(row.column_name)),
  );
  tableColumnsCache.set(tableName, columns);
  return columns;
}

async function hasTable(tableName: string): Promise<boolean> {
  const cached = tableExistsCache.get(tableName);
  if (typeof cached === "boolean") return cached;

  try {
    const result = await pool.query(
      "select exists(select 1 from information_schema.tables where table_schema = current_schema() and table_name = $1) as exists",
      [tableName],
    );
    const exists = Boolean(result.rows?.[0]?.exists);
    tableExistsCache.set(tableName, exists);
    return exists;
  } catch {
    return false;
  }
}

async function ensureFirmwareUpdatesCompatibilityColumns(): Promise<void> {
  if (firmwareCompatColumnsPromise) {
    await firmwareCompatColumnsPromise;
    return;
  }

  firmwareCompatColumnsPromise = (async () => {
    if (!(await hasTable("firmware_updates"))) return;

    const existingColumns = await getTableColumns("firmware_updates");
    const missingColumns = firmwareCompatColumnDefinitions.filter(
      ([columnName]) => !existingColumns.has(columnName),
    );

    if (!missingColumns.length) return;

    for (const [columnName, definition] of missingColumns) {
      await pool.query(
        `alter table "firmware_updates" add column if not exists "${columnName}" ${definition}`,
      );
    }

    tableColumnsCache.delete("firmware_updates");
  })().catch((error) => {
    firmwareCompatColumnsPromise = null;
    throw error;
  });

  await firmwareCompatColumnsPromise;
}

