function normalizeIncomingApiUrl(rawUrl: string): string {
  if (!rawUrl) return rawUrl;

  const [rawPath, rawQuery = ""] = rawUrl.split("?", 2);
  let normalizedPath = rawPath.trim();
  if (normalizedPath.startsWith("api/")) {
    normalizedPath = `/${normalizedPath}`;
  }
  if (!normalizedPath.startsWith("/api/")) {
    return rawUrl;
  }

  normalizedPath = normalizedPath
    .replace(/\/{2,}/g, "/")
    .split("/")
    .map((segment, index) =>
      index === 0 ? segment : segment.replace(/,+$/u, ""),
    )
    .join("/");

  if (normalizedPath.length > 1 && normalizedPath.endsWith("/")) {
    normalizedPath = normalizedPath.slice(0, -1);
  }

  const searchParams = new URLSearchParams(rawQuery);
  const sanitizedParams = new URLSearchParams();
  for (const [key, value] of searchParams.entries()) {
    const normalizedKey = key.trim().replace(/,+$/u, "");
    if (!normalizedKey) continue;
    sanitizedParams.append(normalizedKey, value.trim().replace(/,+$/u, ""));
  }

  const query = sanitizedParams.toString();
  return query ? `${normalizedPath}?${query}` : normalizedPath;
}

app.use((req, _res, next) => {
  const normalizedUrl = normalizeIncomingApiUrl(req.url);
  if (normalizedUrl !== req.url) {
    req.url = normalizedUrl;
  }
  next();
});

// ── Role Room API (x-api-key or Bearer session token) ────
type ActiveSessionData = {
  userId: string;
  email: string;
  name: string;
  role: string;
  loginAt: string;
  roleLabel?: string;
  permissions?: string[];
  profession?: string;
  userType?: string;
  displayName?: string;
  picture?: string;
  verified_email?: boolean;
  impersonatedByAdmin?: boolean;
  isAdmin?: boolean;
  vendorId?: string;
  businessName?: string;
  coupleProfileId?: string;
  requestedRole?: string | null;
  loginAs?: string;
};

const activeSessions: Map<string, ActiveSessionData> = new Map();
void hydratePersistedAuthSessions<ActiveSessionData>(pool, activeSessions)
  .then((count) => {
    if (count > 0) {
      console.log(`[Auth] Hydrated ${count} persisted session(s)`);
    }
  })
  .catch((error) => {
    console.warn("[Auth] Failed to hydrate persisted sessions:", error);
  });
const DEV_LOCAL_ADMIN_SESSION_TOKEN = "dev-admin-local-session";
const DEV_LOCAL_ADMIN_PERMISSIONS = [
  "users:read",
  "users:write",
  "roles:write",
  "academy:admin",
  "billing:admin",
  "impersonate",
];

const ADMIN_SESSION_ROLES = new Set(["admin", "super_admin"]);
const ACADEMY_ADMIN_ROLES = new Set(["academy_admin"]);
const INVITE_REQUEST_APPROVER_ROLES = new Set([
  "admin",
  "super_admin",
  "academy_admin",
  "instructor",
]);

function readActiveSessionToken(req: express.Request): string | null {
  const authorizationHeader = readString(req.headers.authorization);
  const bearerToken =
    authorizationHeader && authorizationHeader.startsWith("Bearer ")
      ? authorizationHeader.slice("Bearer ".length).trim()
      : null;

  return (
    bearerToken ||
    readString(req.headers["x-session-token"]) ||
    readString(req.headers["x-auth-token"]) ||
    null
  );
}

function getLocalDevelopmentSession(
  sessionToken: string | null,
): ActiveSessionData | null {
  if (
    process.env.NODE_ENV === "production" ||
    !sessionToken ||
    sessionToken !== DEV_LOCAL_ADMIN_SESSION_TOKEN
  ) {
    return null;
  }

  return {
    userId: "local-admin",
    email: "admin@local.dev",
    name: "Local Admin",
    role: "admin",
    roleLabel: "Admin",
    permissions: [...DEV_LOCAL_ADMIN_PERMISSIONS],
    profession: "photographer",
    userType: "photographer",
    displayName: "Local Admin",
    verified_email: true,
    isAdmin: true,
    loginAt: new Date().toISOString(),
  };
}

function getActiveSessionFromRequest(req: express.Request) {
  const sessionToken = readActiveSessionToken(req);
  if (!sessionToken) {
    return null;
  }

  return activeSessions.get(sessionToken) || getLocalDevelopmentSession(sessionToken);
}

async function resolveActiveSessionFromRequest(
  req: express.Request,
): Promise<ActiveSessionData | null> {
  const sessionToken = readActiveSessionToken(req);
  if (!sessionToken) {
    return null;
  }

  const inMemorySession = activeSessions.get(sessionToken);
  if (inMemorySession) {
    return inMemorySession;
  }

  const localDevelopmentSession = getLocalDevelopmentSession(sessionToken);
  if (localDevelopmentSession) {
    return localDevelopmentSession;
  }

  const persistedSession = await loadPersistedAuthSession<ActiveSessionData>(
    pool,
    sessionToken,
  );
  if (persistedSession) {
    activeSessions.set(sessionToken, persistedSession);
    return persistedSession;
  }

  return null;
}

function requireAdminSession(
  req: express.Request,
  res: express.Response,
): { userId: string; email: string; name: string; role: string; loginAt: string } | null {
  const session = getActiveSessionFromRequest(req);
  if (!session) {
    res.status(401).json({ error: "Admin-innlogging kreves" });
    return null;
  }

  const normalizedRole = String(session.role || "").trim().toLowerCase();
  if (!ADMIN_SESSION_ROLES.has(normalizedRole)) {
    res.status(403).json({ error: "Admin-tilgang kreves" });
    return null;
  }

  return session;
}

function requireInviteRequestApproverSession(
  req: express.Request,
  res: express.Response,
): { userId: string; email: string; name: string; role: string; loginAt: string } | null {
  const session = getActiveSessionFromRequest(req);
  if (!session) {
    res.status(401).json({ error: "Innlogging kreves for å behandle forespørsler" });
    return null;
  }

  const normalizedRole = String(session.role || "").trim().toLowerCase();
  if (!INVITE_REQUEST_APPROVER_ROLES.has(normalizedRole)) {
    res
      .status(403)
      .json({ error: "Kun instruktører eller administratorer kan godkjenne tilgang" });
    return null;
  }

  return session;
}

