const maybeStartRoleRoomGoogleRedirectBridge = () => {
  const redirectCandidate =
    process.env.CREATORHUB_GOOGLE_REDIRECT_URI ||
    process.env.ROLE_ROOM_GOOGLE_REDIRECT_URI ||
    null;
  if (!redirectCandidate) {
    return;
  }

  let parsedRedirect: URL;
  try {
    parsedRedirect = new URL(redirectCandidate);
  } catch {
    return;
  }

  if (!["localhost", "127.0.0.1"].includes(parsedRedirect.hostname)) {
    return;
  }

  const bridgePort = parsedRedirect.port
    ? Number(parsedRedirect.port)
    : parsedRedirect.protocol === "https:"
      ? 443
      : 80;
  if (!Number.isFinite(bridgePort) || bridgePort === PORT) {
    return;
  }

  const callbackPaths = new Set([
    "/api/auth/google/callback",
    "/auth/google/callback",
  ]);
  if (!callbackPaths.has(parsedRedirect.pathname)) {
    return;
  }

  const bridgeApp = express();
  const bridgeHandler = (req: express.Request, res: express.Response) => {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(req.query)) {
      if (Array.isArray(value)) {
        for (const entry of value) {
          if (entry != null) {
            params.append(key, String(entry));
          }
        }
        continue;
      }
      if (value != null) {
        params.set(key, String(value));
      }
    }

    const queryString = params.toString();
      const state = String(req.query.state || "").trim();
      const callbackPath = state.startsWith("chg_")
        ? "/api/creatorhub/google/oauth/callback"
        : "/api/role-room/google/oauth/callback";
      res.redirect(
        `http://localhost:${PORT}${callbackPath}${queryString ? `?${queryString}` : ""}`,
      );
  };

  bridgeApp.get("/api/auth/google/callback", bridgeHandler);
  bridgeApp.get("/auth/google/callback", bridgeHandler);

  const bridgeServer = createServer(bridgeApp);
  bridgeServer.on("error", (error: NodeJS.ErrnoException) => {
    if (error.code === "EADDRINUSE") {
      console.warn(
        `Role Room Google redirect bridge skipped: port ${bridgePort} is already in use.`,
      );
      return;
    }
    console.warn("Role Room Google redirect bridge failed:", error);
  });
  bridgeServer.listen(bridgePort, "0.0.0.0", () => {
    console.log(
      `Role Room Google redirect bridge listening on http://localhost:${bridgePort}`,
    );
  });
};

const maybeStartRoleRoomLinkedInRedirectBridge = () => {
  const redirectCandidate = process.env.ROLE_ROOM_LINKEDIN_REDIRECT_URI;
  if (!redirectCandidate) {
    return;
  }

  let parsedRedirect: URL;
  try {
    parsedRedirect = new URL(redirectCandidate);
  } catch {
    return;
  }

  if (!["localhost", "127.0.0.1"].includes(parsedRedirect.hostname)) {
    return;
  }

  const bridgePort = parsedRedirect.port
    ? Number(parsedRedirect.port)
    : parsedRedirect.protocol === "https:"
      ? 443
      : 80;
  if (!Number.isFinite(bridgePort) || bridgePort === PORT) {
    return;
  }

  const callbackPaths = new Set([
    "/api/auth/linkedin/callback",
    "/auth/linkedin/callback",
  ]);
  if (!callbackPaths.has(parsedRedirect.pathname)) {
    return;
  }

  const bridgeApp = express();
  const bridgeHandler = (req: express.Request, res: express.Response) => {
    const params = new URLSearchParams();
    for (const [key, value] of Object.entries(req.query)) {
      if (Array.isArray(value)) {
        for (const entry of value) {
          if (entry != null) {
            params.append(key, String(entry));
          }
        }
        continue;
      }
      if (value != null) {
        params.set(key, String(value));
      }
    }

    const queryString = params.toString();
    res.redirect(
      `http://localhost:${PORT}/api/role-room/linkedin/oauth/callback${queryString ? `?${queryString}` : ""}`,
    );
  };

  bridgeApp.get("/api/auth/linkedin/callback", bridgeHandler);
  bridgeApp.get("/auth/linkedin/callback", bridgeHandler);

  const bridgeServer = createServer(bridgeApp);
  bridgeServer.on("error", (error: NodeJS.ErrnoException) => {
    if (error.code === "EADDRINUSE") {
      console.warn(
        `Role Room LinkedIn redirect bridge skipped: port ${bridgePort} is already in use.`,
      );
      return;
    }
    console.warn("Role Room LinkedIn redirect bridge failed:", error);
  });
  bridgeServer.listen(bridgePort, "0.0.0.0", () => {
    console.log(
      `Role Room LinkedIn redirect bridge listening on http://localhost:${bridgePort}`,
    );
  });
};

// ── Reference image proxy (shot.cafe + Unsplash) ──────────
app.use("/api", createReferenceProxyRouter());

// Ensure UTF-8 charset for all JSON responses (æøå support)
app.use((req, res, next) => {
  res.charset = "utf-8";
  const originalJson = res.json.bind(res);
  res.json = (body: any) => {
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    return originalJson(body);
  };
  next();
});

type CompatCatalogSpecificationValue = string | number | boolean;

const normalizeCompatCatalogSpecifications = (
  specifications: Record<string, CompatCatalogSpecificationValue | undefined>,
): Record<string, CompatCatalogSpecificationValue> =>
  Object.entries(specifications).reduce<Record<string, CompatCatalogSpecificationValue>>(
    (normalized, [key, value]) => {
      if (value !== undefined) {
        normalized[key] = value;
      }
      return normalized;
    },
    {},
  );

