type CompatLensSeed = {
  id: string;
  brand: string;
  model: string;
  description: string;
  priceNOK: number;
  releaseYear: number;
  mount: string;
  type: string;
  focalLength: string;
  maxAperture: string;
  weight: string;
  filterSize?: string;
  closeFocus?: string;
  imageStabilization?: boolean;
  weatherSealed?: boolean;
  norwegianSupplier?: string;
  availability?: CompatCatalogItem["availability"];
  imageUrl?: string;
  productUrl?: string;
};

const createCompatLensCatalogItem = (
  seed: CompatLensSeed,
): CompatCatalogItem => ({
  id: seed.id,
  brand: seed.brand,
  model: seed.model,
  category: "lenses",
  description: seed.description,
  priceNOK: seed.priceNOK,
  releaseYear: seed.releaseYear,
  mount: seed.mount,
  type: seed.type,
  norwegianSupplier: seed.norwegianSupplier || "Foto.no",
  productUrl:
    seed.productUrl ||
    `https://www.foto.no/search?q=${encodeURIComponent(
      `${seed.brand} ${seed.model}`,
    )}`,
  availability: seed.availability || "available",
  imageUrl: seed.imageUrl || "",
  specifications: {
    focalLength: seed.focalLength,
    maxAperture: seed.maxAperture,
    mount: seed.mount,
    lensType: seed.type,
    imageStabilization: seed.imageStabilization ?? false,
    weatherSealed: seed.weatherSealed ?? true,
    weight: seed.weight,
    ...(seed.filterSize ? { filterSize: seed.filterSize } : {}),
    ...(seed.closeFocus ? { closeFocus: seed.closeFocus } : {}),
  },
});

type CompatAccessorySeed = {
  id: string;
  brand: string;
  model: string;
  description: string;
  priceNOK: number;
  releaseYear: number;
  type: string;
  norwegianSupplier?: string;
  availability?: CompatCatalogItem["availability"];
  imageUrl?: string;
  productUrl?: string;
  specifications: Record<string, CompatCatalogSpecificationValue | undefined>;
};

const createCompatAccessoryCatalogItem = (
  seed: CompatAccessorySeed,
): CompatCatalogItem => ({
  id: seed.id,
  brand: seed.brand,
  model: seed.model,
  category: "accessories",
  description: seed.description,
  priceNOK: seed.priceNOK,
  releaseYear: seed.releaseYear,
  type: seed.type,
  norwegianSupplier: seed.norwegianSupplier || "Foto.no",
  productUrl:
    seed.productUrl ||
    createFotoNoSearchProductUrl(`${seed.brand} ${seed.model}`),
  availability: seed.availability || "available",
  imageUrl: seed.imageUrl || "",
  specifications: normalizeCompatCatalogSpecifications({
    accessoryType: seed.type,
    ...seed.specifications,
  }),
});

const slugifyCompatCatalogId = (value: string): string =>
  value
    .normalize("NFKD")
    .replace(/[^\x00-\x7F]/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "");

const createFotoNoSearchProductUrl = (query: string): string =>
  `https://www.foto.no/search?q=${encodeURIComponent(query)}`;

