const buildBrandPortalFirmwareProfile = (
  camera: Pick<
    FirmwareSeedCandidate,
    "brand" | "model" | "type" | "category" | "version"
  >,
  sourceUrl: string,
  kind: "photo" | "audio" | "lighting" | "video" | "lens",
): CanonicalFirmwareProfile => {
  const normalizedSourceUrl = sourceUrl.toLowerCase();
  const normalizedModelToken = normalizeCameraToken(
    stripLeadingBrandFromModel(camera.brand || "", camera.model || "") ||
      camera.model ||
      "",
  );
  const looksModelSpecific =
    Boolean(normalizedModelToken) &&
    normalizeCameraToken(sourceUrl).includes(normalizedModelToken);
  const hasSupportLikePath =
    normalizedSourceUrl.includes("search") ||
    normalizedSourceUrl.includes("/download") ||
    normalizedSourceUrl.includes("/downloads") ||
    normalizedSourceUrl.includes("/support") ||
    normalizedSourceUrl.includes("/maintenance/") ||
    normalizedSourceUrl.includes("/product/") ||
    normalizedSourceUrl.includes("/products/") ||
    normalizedSourceUrl.includes("/catalog/products/") ||
    looksModelSpecific;

  return {
    brandToken: toFirmwareBrandToken(camera.brand || ""),
    modelTokens: [normalizeCameraToken(camera.model || "")],
    version: toDiscoveryFirmwareVersion({
      brand: camera.brand,
      model: camera.model,
      type: camera.type,
      category: camera.category,
      version: camera.version,
    }),
    sourceUrl,
    downloadUrl: sourceUrl,
    importance: "normal",
    description:
      kind === "photo"
        ? `Produsentens firmware-side for ${camera.brand} ${stripLeadingBrandFromModel(camera.brand || "", camera.model || "") || camera.model}.`
        : kind === "lens"
          ? `Produsentens firmware-side for objektivet ${camera.brand} ${stripLeadingBrandFromModel(camera.brand || "", camera.model || "") || camera.model}.`
        : kind === "lighting"
          ? `Produsentens firmware-side for lysutstyr ${camera.brand} ${camera.model}.`
          : kind === "video"
            ? `Produsentens firmware-side for video-/motion-utstyr ${camera.brand} ${camera.model}.`
            : `Produsentens firmware-portal for lydutstyr ${camera.brand} ${camera.model}.`,
    releaseNotes: [
      kind === "photo"
        ? "Firmware må bekreftes mot produsentens modellspesifikke nedlastingsside."
        : kind === "lens"
          ? "Objektiv-firmware må bekreftes mot produsentens modellspesifikke nedlastingsside eller lens utility."
        : kind === "lighting"
          ? "Firmware må bekreftes mot produsentens modellspesifikke nedlastingsside for lysutstyr."
          : kind === "video"
            ? "Firmware må bekreftes mot produsentens modellspesifikke nedlastingsside for video-/motion-utstyr."
            : "Firmware må bekreftes mot produsentens modellspesifikke nedlastingsside for lydutstyr.",
    ],
    urlKind:
      kind === "photo" || kind === "lens" || hasSupportLikePath
        ? "model-support"
        : "brand-portal",
  };
};

const resolveCanonicalFirmwareProfile = (
  camera: Pick<
    FirmwareSeedCandidate,
    "brand" | "model" | "type" | "category" | "version"
  >,
): CanonicalFirmwareProfile | null => {
  const categoryToken = normalizeCameraCategory(camera.category || "");
  const brandToken = toFirmwareBrandToken(camera.brand || "");
  const modelToken = normalizeCameraToken(camera.model || "");
  if (!brandToken || !modelToken) return null;

  const exactProfile = CINE_FIRMWARE_PROFILES.find(
    (entry) =>
      entry.brandToken === brandToken &&
      entry.modelTokens.some((token) =>
        modelTokenMatchesProfile(modelToken, token),
      ),
  );
  if (exactProfile) {
    return exactProfile;
  }

  if (categoryToken.includes("cine") || categoryToken.includes("cinema")) {
    return null;
  }

  const isAudioCategory =
    categoryToken.includes("audio") ||
    (categoryToken.includes("recorder") &&
      !categoryToken.includes("video") &&
      !categoryToken.includes("monitor")) ||
    categoryToken.includes("mic") ||
    (categoryToken.includes("wireless") &&
      !categoryToken.includes("video")) ||
    categoryToken.includes("intercom") ||
    categoryToken.includes("headset") ||
    categoryToken.includes("ifb");
  if (isAudioCategory) {
    const audioPortal = resolveAudioFirmwareSupportUrl(brandToken, camera);
    if (!audioPortal) return null;
    return buildBrandPortalFirmwareProfile(camera, audioPortal, "audio");
  }

  const isLightingCategory =
    categoryToken.includes("flash") ||
    categoryToken.includes("lighting") ||
    categoryToken.includes("light") ||
    categoryToken.includes("strobe") ||
    categoryToken.includes("led") ||
    categoryToken.includes("panel") ||
    categoryToken.includes("tube") ||
    categoryToken.includes("cob") ||
    categoryToken.includes("monolight");
  if (isLightingCategory) {
    const lightingPortal = resolveLightingFirmwareSupportUrl(brandToken, camera);
    if (!lightingPortal) return null;
    return buildBrandPortalFirmwareProfile(camera, lightingPortal, "lighting");
  }

  const isLensCategory =
    categoryToken.includes("lens") ||
    categoryToken.includes("objektiv") ||
    categoryToken.includes("optic") ||
    categoryToken.includes("optics");
  if (isLensCategory) {
    const lensPortal = resolveLensFirmwareSupportUrl(brandToken, camera);
    if (!lensPortal) return null;
    return buildBrandPortalFirmwareProfile(camera, lensPortal, "lens");
  }

  const isVideoSupportCategory =
    categoryToken.includes("video") ||
    categoryToken.includes("gimbal") ||
    categoryToken.includes("drone") ||
    categoryToken.includes("action") ||
    categoryToken.includes("monitor") ||
    categoryToken.includes("recorder") ||
    categoryToken.includes("transmitter") ||
    categoryToken.includes("timecode") ||
    categoryToken.includes("stabilizer") ||
    categoryToken.includes("switcher") ||
    categoryToken.includes("capture") ||
    categoryToken.includes("teleprompter") ||
    categoryToken.includes("ptz") ||
    categoryToken.includes("wirelessvideo");
  if (camera.type === "video" || isVideoSupportCategory) {
    const videoPortal = resolveVideoFirmwareSupportUrl(brandToken, camera);
    if (!videoPortal) return null;
    return buildBrandPortalFirmwareProfile(camera, videoPortal, "video");
  }

  const isPhotoCandidate =
    camera.type === "photo" ||
    categoryToken.includes("photo") ||
    categoryToken.includes("mirrorless") ||
    categoryToken.includes("dslr") ||
    categoryToken.includes("compact") ||
    categoryToken.includes("medium-format") ||
    categoryToken.includes("webcam");
  if (isPhotoCandidate) {
    const photoPortal = resolvePhotoFirmwareSupportUrl(brandToken, camera);
    if (!photoPortal) return null;
    return buildBrandPortalFirmwareProfile(camera, photoPortal, "photo");
  }

  return null;
};

const resolveCanonicalFirmwareProfileByDevice = (
  brand: string,
  model: string,
  category?: string | null,
): CanonicalFirmwareProfile | null => {
  return resolveCanonicalFirmwareProfile({
    brand,
    model,
    type: inferCameraTypeFromEquipmentCategory(category),
    category: category || undefined,
    version: 1,
  });
};

const isGenericDiscoveryVersion = (
  version: string | null | undefined,
): boolean => {
  if (!version) return true;
  return /^1\.0\.\d+$/u.test(version.trim());
};

const normalizeSqlDateValue = (value: unknown): string | null => {
  if (!value) return null;
  if (value instanceof Date && Number.isFinite(value.getTime())) {
    return value.toISOString().slice(0, 10);
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed) return null;
    if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
    const parsed = new Date(trimmed);
    if (Number.isFinite(parsed.getTime())) {
      return parsed.toISOString().slice(0, 10);
    }
  }
  return null;
};

const hasBetterCanonicalSource = (
  existingSourceUrl: string | null | undefined,
  canonicalSourceUrl: string,
): boolean => {
  if (!existingSourceUrl) return true;
  if (existingSourceUrl.includes("example.com")) return true;
  return existingSourceUrl.trim() !== canonicalSourceUrl.trim();
};

const hasBetterCanonicalReleaseDate = (
  existingReleaseDate: string | null | undefined,
  canonicalReleaseDate: string | null | undefined,
): boolean => {
  if (!canonicalReleaseDate) return false;
  if (!existingReleaseDate) return true;

  const existingTime = new Date(existingReleaseDate).getTime();
  const canonicalTime = new Date(canonicalReleaseDate).getTime();
  if (!Number.isFinite(canonicalTime)) return false;
  if (!Number.isFinite(existingTime)) return true;
  return canonicalTime !== existingTime;
};

const buildCanonicalFirmwarePayload = (
  camera: FirmwareSeedCandidate,
  profile: CanonicalFirmwareProfile,
  nowIso: string,
  releaseDateFallback: string,
): Record<string, unknown> => ({
  version: profile.version,
  update_type: "firmware",
  release_date: profile.releaseDate || releaseDateFallback,
  is_latest: true,
  is_critical: profile.importance === "critical",
  importance: profile.importance || "high",
  description:
    profile.description ||
    `Produsentoppdatering for ${camera.brand} ${camera.model}.`,
  download_url: profile.downloadUrl || profile.sourceUrl,
  source_url: profile.sourceUrl,
  release_notes: (profile.releaseNotes || []).join("\n"),
  compatibility: JSON.stringify([camera.category]),
  requirements: JSON.stringify([
    "Oppdater med produsentens offisielle prosedyre.",
  ]),
  known_issues: JSON.stringify([]),
  installation_steps: JSON.stringify([
    "1. Last ned firmware fra produsent.",
    "2. Følg produsentens oppdateringsguide.",
    "3. Verifiser versjon etter restart.",
  ]),
  last_checked: nowIso,
  last_verified: nowIso,
  updated_at: nowIso,
});

const toFirmwareReleaseDate = (
  camera: FirmwareSeedCandidate,
): string | null => {
  const preferred = [camera.releaseDate, camera.lastUpdated, camera.lastSeenAt];
  for (const value of preferred) {
    if (!value || typeof value !== "string") continue;
    const trimmed = value.trim();
    if (!trimmed) continue;
    if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
    const parsed = new Date(trimmed);
    if (Number.isFinite(parsed.getTime())) {
      return parsed.toISOString().slice(0, 10);
    }
  }
  return null;
};

const toDiscoveryFirmwareVersion = (camera: FirmwareSeedCandidate): string => {
  const patch =
    Number.isFinite(camera.version) && (camera.version || 0) > 0
      ? (camera.version || 0) - 1
      : 0;
  return `1.0.${patch}`;
};

type OfficialFirmwarePageMetadata = {
  title: string | null;
  imageUrl: string | null;
  version: string | null;
  releaseDate: string | null;
  sourceUrl: string | null;
  downloadUrl: string | null;
  followUpUrl: string | null;
};

const OFFICIAL_FIRMWARE_METADATA_TTL_MS = 12 * 60 * 60 * 1000;
const officialFirmwareMetadataCache = new Map<
  string,
  { value: OfficialFirmwarePageMetadata | null; expiresAt: number }
>();

const toFirmwareMetadataCacheKey = (
  url: string,
  brandToken: string,
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
): string => {
  const brand = camera?.brand ? normalizeCameraToken(camera.brand) : "";
  const model = camera?.model ? normalizeCameraToken(camera.model) : "";
  return [url, brandToken, brand, model].join("::");
};

const resolveAbsoluteUrl = (
  baseUrl: string,
  value: string | null | undefined,
): string | null => {
  const rawValue = readString(value);
  const normalized = rawValue ? readString(decodeHtmlEntities(rawValue)) : null;
  if (!normalized) return null;

  try {
    return new URL(normalized, baseUrl).toString();
  } catch {
    return null;
  }
};

const extractHtmlMetaContent = (html: string, key: string): string | null => {
  const patterns = [
    new RegExp(
      `<meta[^>]+(?:property|name)=["']${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}["'][^>]+content=["']([^"']+)["']`,
      "i",
    ),
    new RegExp(
      `<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']${key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}["']`,
      "i",
    ),
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    const rawValue = readString(match?.[1]);
    const value = rawValue ? readString(decodeHtmlEntities(rawValue)) : null;
    if (value) return value;
  }
  return null;
};

const extractHtmlTitle = (html: string): string | null => {
  const match = html.match(/<title>([\s\S]*?)<\/title>/iu);
  const rawValue = readString(match?.[1]?.replace(/\s+/gu, " ") || "");
  return rawValue ? readString(decodeHtmlEntities(rawValue)) : null;
};

const isLikelyImageAssetUrl = (value: string | null | undefined): boolean =>
  Boolean(
    readString(value) &&
      /\.(?:png|jpe?g|webp|avif|gif|svg)(?:$|[?#])/iu.test(readString(value) || ""),
  );

const extractPrimaryHtmlImageUrl = (
  html: string,
  baseUrl: string,
): string | null => {
  const imageTagPattern = /<img\b([^>]+)>/giu;
  let best: { url: string; score: number } | null = null;

  const readTagAttribute = (tag: string, key: string): string | null =>
    readString(
      tag.match(
        new RegExp(`${key.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&")}=["']([^"']+)["']`, "iu"),
      )?.[1] || null,
    );

  for (const match of html.matchAll(imageTagPattern)) {
    const tag = match[1];
    const rawSrcset = readTagAttribute(tag, "srcset");
    const preferredSrcset = rawSrcset
      ? readString(rawSrcset.split(",")[0]?.trim().split(/\s+/u)[0] || null)
      : null;
    const source =
      preferredSrcset ||
      readTagAttribute(tag, "src") ||
      readTagAttribute(tag, "data-src") ||
      readTagAttribute(tag, "data-lazy-src");
    const url = resolveAbsoluteUrl(baseUrl, source);
    if (!url || /\.svg(?:$|[?#])/iu.test(url)) continue;

    const normalizedBlob = decodeHtmlEntities(`${tag} ${url}`).toLowerCase();
    if (
      /logo|icon|avatar|flag|payment|placeholder|spinner|loader|sprite|badge/iu.test(
        normalizedBlob,
      )
    ) {
      continue;
    }

    let score = 0;
    if (/product|products|lens|lenses|cine|cinema|prime|zoom|macro|anamorphic/iu.test(normalizedBlob)) {
      score += 70;
    }
    if (/wp-content|shopify|cdn|uploads|product|products|lens|cine/iu.test(url)) {
      score += 35;
    }
    if (/hero|gallery|featured|primary|main/iu.test(normalizedBlob)) {
      score += 20;
    }

    const width = Number(readTagAttribute(tag, "width") || 0);
    const height = Number(readTagAttribute(tag, "height") || 0);
    if ((width && width < 160) || (height && height < 160)) {
      score -= 60;
    }

    if (!best || score > best.score) {
      best = { url, score };
    }
  }

  return best?.score && best.score > 0 ? best.url : null;
};

type FirmwareSupportSearchTerms = {
  normalizedModel: string;
  rawModel: string;
  tokens: string[];
  boundaryPattern: RegExp | null;
};

const buildFirmwareSupportSearchTerms = (
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
): FirmwareSupportSearchTerms | null => {
  const brand = readString(camera?.brand);
  const model = readString(camera?.model);
  if (!brand || !model) return null;

  const rawModel = stripLeadingBrandFromModel(brand, model) || model;
  const normalizedModel = normalizeCameraToken(rawModel);
  if (!normalizedModel) return null;

  const tokenSource = rawModel
    .replace(/([a-z])([0-9])/giu, "$1 $2")
    .replace(/([0-9])([a-z])/giu, "$1 $2");
  const tokens = Array.from(
    new Set(
      tokenSource
        .toLowerCase()
        .match(/[a-z0-9]+/gu)
        ?.map((token) => token.trim())
        .filter((token) => token.length > 0) || [],
    ),
  );
  const boundaryPattern =
    tokens.length > 0
      ? new RegExp(
          `(?:^|[^a-z0-9])${tokens
            .map((token) => token.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&"))
            .join("[-_\\s]*")}(?![a-z0-9])`,
          "iu",
        )
      : null;

  return {
    normalizedModel,
    rawModel,
    tokens,
    boundaryPattern,
  };
};

type FirmwareAnchorCandidate = {
  url: string;
  text: string;
  score: number;
  isDownloadFile: boolean;
};

const extractFirmwareAnchorCandidates = (
  html: string,
  baseUrl: string,
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
): FirmwareAnchorCandidate[] => {
  const searchTerms = buildFirmwareSupportSearchTerms(camera);
  if (!searchTerms) return [];

  const anchorPattern =
    /<a\b[^>]*href=["']([^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/giu;
  const candidates = new Map<string, FirmwareAnchorCandidate>();

  for (const match of html.matchAll(anchorPattern)) {
    const url = resolveAbsoluteUrl(baseUrl, match[1]);
    if (!url || url === baseUrl) continue;

    if (
      url.startsWith("javascript:") ||
      url.startsWith("mailto:") ||
      url.startsWith("tel:")
    ) {
      continue;
    }

    const text = decodeHtmlEntities(
      match[2].replace(/<[^>]+>/gu, " ").replace(/\s+/gu, " ").trim(),
    );
    const normalizedBlob = normalizeCameraToken(`${url} ${text}`);
    if (!normalizedBlob) continue;

    let score = 0;
    const exactBoundaryMatch = searchTerms.boundaryPattern
      ? searchTerms.boundaryPattern.test(`${url} ${text}`)
      : false;

    if (exactBoundaryMatch) {
      score += 160;
    } else if (normalizedBlob.includes(searchTerms.normalizedModel)) {
      score += 30;
    }

    searchTerms.tokens.forEach((token) => {
      const normalizedToken = normalizeCameraToken(token);
      if (normalizedToken && normalizedBlob.includes(normalizedToken)) {
        score += normalizedToken.length >= 4 ? 18 : 12;
      }
    });

    const lowerBlob = `${url} ${text}`.toLowerCase();
    const isDownloadFile =
      /\.(zip|bin|dmg|pkg|exe|msi|img|fw|upd)(?:$|[?#])/iu.test(url);
    if (isDownloadFile) score += 45;
    if (/firmware|update|upgrade/iu.test(lowerBlob)) score += 30;
    if (/download|downloads/iu.test(lowerBlob)) score += 20;
    if (/support|product|products/iu.test(lowerBlob)) score += 10;
    if (/manual|guide|faq|warranty|policy|dealer/iu.test(lowerBlob)) {
      score -= 45;
    }
    if (/search|query=|keyword=/.test(lowerBlob)) score -= 30;

    const existing = candidates.get(url);
    if (!existing || score > existing.score) {
      candidates.set(url, {
        url,
        text,
        score,
        isDownloadFile,
      });
    }
  }

  return Array.from(candidates.values()).sort((a, b) => b.score - a.score);
};

const extractModelSpecificDownloadUrl = (
  html: string,
  baseUrl: string,
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
): string | null => {
  const candidate = extractFirmwareAnchorCandidates(html, baseUrl, camera).find(
    (entry) => entry.isDownloadFile && entry.score >= 100,
  );
  return candidate?.url || null;
};

const extractModelSpecificFollowUpUrl = (
  html: string,
  baseUrl: string,
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
): string | null => {
  const candidate = extractFirmwareAnchorCandidates(html, baseUrl, camera).find(
    (entry) => !entry.isDownloadFile && entry.score >= 100,
  );
  return candidate?.url || null;
};

const pageHasFirmwareSignals = (text: string): boolean =>
  /firmware|software update|system software|update tools|firmware upgrade|download latest firmware|download firmware/iu.test(
    text,
  );

const normalizeLiveFirmwareVersion = (value: string | null): string | null => {
  const trimmed = readString(value);
  if (!trimmed) return null;
  return trimmed.replace(/^v(?:er(?:sion)?)?\.?\s*/iu, "").trim() || null;
};

const monthTokenToNumber = (value: string): string | null => {
  const normalized = value.trim().replace(/\.$/u, "").toLowerCase();
  const lookup: Record<string, string> = {
    jan: "01",
    january: "01",
    feb: "02",
    february: "02",
    mar: "03",
    march: "03",
    apr: "04",
    april: "04",
    may: "05",
    jun: "06",
    june: "06",
    jul: "07",
    july: "07",
    aug: "08",
    august: "08",
    sep: "09",
    sept: "09",
    september: "09",
    oct: "10",
    october: "10",
    nov: "11",
    november: "11",
    dec: "12",
    december: "12",
  };
  return lookup[normalized] || null;
};

const toIsoDate = (
  year: string,
  month: string,
  day: string,
): string | null => {
  const y = Number(year);
  const m = Number(month);
  const d = Number(day);
  if (
    !Number.isInteger(y) ||
    !Number.isInteger(m) ||
    !Number.isInteger(d) ||
    m < 1 ||
    m > 12 ||
    d < 1 ||
    d > 31
  ) {
    return null;
  }

  return `${String(y).padStart(4, "0")}-${String(m).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
};

const extractProfotoFirmwareVersion = (text: string): string | null => {
  const directVersion = text.match(/Version\s+([A-Z]\d+(?:\.\d+)?)/iu);
  if (directVersion?.[1]) {
    return normalizeLiveFirmwareVersion(directVersion[1]);
  }

  const fileVersion = text.match(/firmware[-_\s]*(?:rev[-_\s]*)?([A-Z]\d+(?:\.\d+)?)/iu);
  if (fileVersion?.[1]) {
    return normalizeLiveFirmwareVersion(fileVersion[1]);
  }

  return null;
};

const extractDjiFirmwareVersion = (text: string): string | null => {
  const firmwareSectionMatch = text.match(
    /<section[^>]*>[\s\S]*?<h3[^>]*>\s*Firmware\s*<\/h3>[\s\S]*?<div id="firmwares-[^"]+"[^>]*>([^<]+)<\/div>/iu,
  );
  if (firmwareSectionMatch?.[1]) {
    const fromSection = firmwareSectionMatch[1].match(
      /\bv([0-9]{2}(?:\.[0-9]{2}){3})\b/iu,
    );
    if (fromSection?.[1]) {
      return normalizeLiveFirmwareVersion(fromSection[1]);
    }
  }

  const firmwareName = text.match(
    /firmwares-name-[^>]+>\s*[^<]*?\bv([0-9]{2}(?:\.[0-9]{2}){3})/iu,
  );
  if (firmwareName?.[1]) {
    return normalizeLiveFirmwareVersion(firmwareName[1]);
  }

  const genericVersion = text.match(
    /\bDJI[^<\n]{0,120}\bv([0-9]{2}(?:\.[0-9]{2}){3})/iu,
  );
  if (genericVersion?.[1]) {
    return normalizeLiveFirmwareVersion(genericVersion[1]);
  }

  return null;
};

const extractDjiDownloadUrl = (
  html: string,
  baseUrl: string,
): string | null => {
  const patterns = [
    /class=["'][^"']*download-file[^"']*["'][^>]*href=["']([^"']+)["']/iu,
    /href=["']([^"']+)["'][^>]*class=["'][^"']*download-file[^"']*["']/iu,
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    const resolved = resolveAbsoluteUrl(baseUrl, match?.[1] || null);
    if (resolved) return resolved;
  }

  return null;
};

const extractProfotoDownloadUrl = (
  html: string,
  baseUrl: string,
): string | null => {
  const patterns = [
    /Download latest firmware[\s\S]{0,1200}?href=["']([^"']+\.zip)["']/iu,
    /href=["']([^"']+profoto_[^"']+_firmware[^"']+\.zip)["']/iu,
  ];

  for (const pattern of patterns) {
    const match = html.match(pattern);
    const resolved = resolveAbsoluteUrl(baseUrl, match?.[1] || null);
    if (resolved) return resolved;
  }

  return null;
};

const extractHtmlScriptSrc = (
  html: string,
  baseUrl: string,
  matcher: RegExp,
): string | null => {
  const scriptPattern = /<script\b[^>]*src=["']([^"']+)["'][^>]*>/giu;
  for (const match of html.matchAll(scriptPattern)) {
    const src = resolveAbsoluteUrl(baseUrl, match[1]);
    if (!src) continue;
    if (matcher.test(src)) return src;
  }
  return null;
};

const inferFirmwareVersionFromUrl = (value: string | null): string | null => {
  const decoded = readString(value ? decodeURIComponent(value) : null);
  if (!decoded) return null;

  const patterns = [
    /(?:^|[_\-/ ])v(?:er(?:sion)?)?[_\-. ]*([A-Z]?\d+(?:\.\d+){1,4})/iu,
    /firmware[-_\s]*(?:rev[-_\s]*)?([A-Z]\d+(?:\.\d+)?)/iu,
    /(?:^|[_\-/ ])([A-Z]\d+(?:\.\d+)?)(?:[_\-. ]|$)/iu,
  ];

  for (const pattern of patterns) {
    const match = decoded.match(pattern);
    const normalized = normalizeLiveFirmwareVersion(match?.[1] || null);
    if (normalized) return normalized;
  }

  return null;
};

const collectFirmwareVersions = (
  values: Array<string | null | undefined>,
): string[] =>
  values
    .map((value) => normalizeLiveFirmwareVersion(value || null))
    .filter((value): value is string => Boolean(value));

const pickLatestFirmwareVersion = (
  values: Array<string | null | undefined>,
): string | null => {
  let bestVersion: string | null = null;
  collectFirmwareVersions(values).forEach((candidate) => {
    if (!bestVersion || compareVersions(candidate, bestVersion) > 0) {
      bestVersion = candidate;
    }
  });
  return bestVersion;
};

const extractGodoxFirmwareVersion = (text: string): string | null => {
  const directVersion = text.match(
    /\b(?:Firmware|Flash)[^<\n]{0,80}?V(?:er(?:sion)?)?\.?\s*([0-9]+(?:\.[0-9]+)+)/iu,
  );
  if (directVersion?.[1]) {
    return normalizeLiveFirmwareVersion(directVersion[1]);
  }

  const fileVersion = text.match(
    /Godox_[^"' ]+?_V([0-9]+(?:\.[0-9]+)+)\.(?:zip|bin|exe|dmg|pkg)/iu,
  );
  if (fileVersion?.[1]) {
    return normalizeLiveFirmwareVersion(fileVersion[1]);
  }

  return null;
};

const extractSennheiserFirmwareVersion = (text: string): string | null => {
  const versions = new Set<string>();

  for (const match of text.matchAll(
    /Profile_Wireless_(?:Update_Tools|FW_Update_Tool)[^"' ]*?_V([0-9]+(?:\.[0-9]+)+)\.zip/giu,
  )) {
    const normalized = normalizeLiveFirmwareVersion(match[1]);
    if (normalized) versions.add(normalized);
  }

  for (const match of text.matchAll(
    /Release_Notes(?:_|-| )[^"'<>]*?Profile_Wireless(?:_Firmware)?_V([0-9]+(?:\.[0-9]+)+)/giu,
  )) {
    const normalized = normalizeLiveFirmwareVersion(match[1]);
    if (normalized) versions.add(normalized);
  }

  const directVersion = normalizeLiveFirmwareVersion(
    text.match(
      /Profile Wireless[^<\n]{0,120}?(?:Firmware|Update Tools?)[^<\n]{0,120}?V(?:er(?:sion)?)?\.?\s*([0-9]+(?:\.[0-9]+)+)/iu,
    )?.[1] || null,
  );
  if (directVersion) versions.add(directVersion);

  return pickLatestFirmwareVersion(Array.from(versions));
};

const extractSennheiserDownloadUrl = (
  text: string,
  baseUrl: string,
): string | null => {
  const candidates: Array<{
    url: string;
    version: string | null;
    platformRank: number;
  }> = [];
  const assetPattern =
    /https:\/\/assets\.sennheiser\.com\/download\/assets\/[^\s"'\\]+(?:\?attachment=true)?/giu;

  for (const match of text.matchAll(assetPattern)) {
    const rawUrl = resolveAbsoluteUrl(baseUrl, match[0]);
    if (!rawUrl) continue;
    const assetName = decodeURIComponent(rawUrl);
    const lowerAsset = assetName.toLowerCase();
    if (
      !lowerAsset.includes("profile_wireless") ||
      (!lowerAsset.includes("update_tool") &&
        !lowerAsset.includes("update_tools") &&
        !lowerAsset.includes("fw_update_tool"))
    ) {
      continue;
    }

    const version =
      normalizeLiveFirmwareVersion(
        assetName.match(/_V([0-9]+(?:\.[0-9]+)+)\.zip/iu)?.[1] || null,
      ) || inferFirmwareVersionFromUrl(rawUrl);
    candidates.push({
      url: rawUrl,
      version,
      platformRank: /windows|x86/iu.test(assetName)
        ? 2
        : /macos/iu.test(assetName)
          ? 1
          : 0,
    });
  }

  candidates.sort((left, right) => {
    const versionDiff = compareVersions(left.version, right.version);
    if (versionDiff !== 0) return -versionDiff;
    return right.platformRank - left.platformRank;
  });

  return candidates[0]?.url || null;
};

const extractSmallHdBundleMetadata = (
  bundleText: string,
): Partial<OfficialFirmwarePageMetadata> => {
  const candidates = Array.from(
    bundleText.matchAll(
      /https:\/\/downloads\.smallhd\.com\/[^"' ]*SmallHD_PageOS_V([0-9-]+)(?:-beta-([0-9]+))?\.zip/giu,
    ),
  ).map((match) => {
    const coreVersion = match[1].replace(/-/gu, ".");
    const betaToken = match[2] ? ` beta ${match[2]}` : "";
    return {
      downloadUrl: match[0],
      version: `${coreVersion}${betaToken}`.trim(),
      stableRank: match[2] ? 0 : 1,
    };
  });

  candidates.sort((left, right) => {
    const versionDiff = compareVersions(left.version, right.version);
    if (versionDiff !== 0) return -versionDiff;
    return right.stableRank - left.stableRank;
  });

  const best = candidates[0];
  if (!best) return {};

  const titleMatch = bundleText.match(
    /SmallHD PageOS[^"'`]{0,40}Firmware v([0-9.]+(?:-Beta[0-9]+)?)/iu,
  );

  return {
    title: titleMatch?.[0] || "SmallHD PageOS firmware",
    version: best.version,
    downloadUrl: best.downloadUrl,
  };
};

const extractHollylandFirmwareVersion = (text: string): string | null => {
  const matches = Array.from(
    text.matchAll(
      /resource-firmware-item-version[\s\S]{0,260}?<h5>\s*([^<]*?)\s*<\/h5>/giu,
    ),
  );

  let bestVersion: string | null = null;
  for (const match of matches) {
    const candidate = normalizeLiveFirmwareVersion(
      match[1].match(/\bV(?:er(?:sion)?)?\.?\s*([0-9]+(?:\.[0-9]+)+)/iu)?.[1] ||
        null,
    );
    if (!candidate) continue;
    if (!bestVersion || compareVersions(candidate, bestVersion) > 0) {
      bestVersion = candidate;
    }
  }

  return bestVersion;
};

const extractHollylandDownloadUrl = (
  text: string,
  baseUrl: string,
): string | null => {
  const firmwareSection = text.match(
    /download-firmware-pane[\s\S]{0,5000}?<\/div>\s*<\/div>\s*<\/div>/iu,
  )?.[0];
  if (!firmwareSection) return null;

  const directLink =
    firmwareSection.match(
      /href=["']([^"']+\.(?:zip|bin|dmg|pkg|exe))["']/iu,
    )?.[1] ||
    firmwareSection.match(
      /href=["']([^"']+)["'][^>]*>\s*<span>\s*Download\s*<\/span>/iu,
    )?.[1] ||
    null;

  return resolveAbsoluteUrl(baseUrl, directLink);
};

const extractNikonDetailUrl = (
  html: string,
  baseUrl: string,
): string | null =>
  resolveAbsoluteUrl(
    baseUrl,
    html.match(
      /href=["']([^"']*\/download\/fw\/\d+\.html)["'][^>]*>\s*(?:View download page|Details)\s*<\/a>/iu,
    )?.[1] || null,
  );

const extractNikonDownloadUrl = (
  html: string,
  baseUrl: string,
): string | null =>
  resolveAbsoluteUrl(
    baseUrl,
    html.match(
      /href=["']([^"']*crossgate\.nikonimglib\.com[^"']+)["'][^>]*>\s*(?:<span>\s*)?<strong>\s*Download\s*<\/strong>/iu,
    )?.[1] || null,
  );

const extractPanasonicDownloadUrl = (
  html: string,
  baseUrl: string,
): string | null =>
  resolveAbsoluteUrl(
    baseUrl,
    html.match(
      /<td[^>]*>\s*Download\s*<\/td>[\s\S]{0,300}?<a href=["']([^"']+)["'][^>]*>\s*(?:<img[^>]*alt=["']Download["'][^>]*>)?\s*Download/iu,
    )?.[1] || null,
  );

const extractVendorFirmwareMetadata = (
  text: string,
  brandToken: string,
  baseUrl: string,
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
): Partial<OfficialFirmwarePageMetadata> => {
  const genericDownloadUrl = extractModelSpecificDownloadUrl(
    text,
    baseUrl,
    camera,
  );
  const genericFollowUpUrl = extractModelSpecificFollowUpUrl(
    text,
    baseUrl,
    camera,
  );

  switch (brandToken) {
    case "dji":
      return {
        version: extractDjiFirmwareVersion(text),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl: extractDjiDownloadUrl(text, baseUrl),
      };
    case "profoto":
      return {
        version: extractProfotoFirmwareVersion(text),
        releaseDate:
          text.match(/Firmware update\s*\((20\d{2}-\d{2}-\d{2})\)/iu)?.[1] ||
          text.match(/Released\s+(\d{1,2}\s+[A-Za-z]+\s*,\s*20\d{2})/iu)?.[1] ||
          extractLiveFirmwareReleaseDate(text),
        downloadUrl: extractProfotoDownloadUrl(text, baseUrl),
      };
    case "godox":
      return {
        version:
          extractGodoxFirmwareVersion(text) ||
          inferFirmwareVersionFromUrl(genericDownloadUrl),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl: genericDownloadUrl,
      };
    case "canon":
      return {
        version:
          normalizeLiveFirmwareVersion(
            text.match(/Firmware Notice[^<\n]{0,120}?Version\s*([0-9]+(?:\.[0-9]+)+)/iu)?.[1] ||
              null,
          ) || extractLiveFirmwareVersion(text, brandToken),
        releaseDate: extractLiveFirmwareReleaseDate(text),
      };
    case "fujifilm":
      return {
        version:
          normalizeLiveFirmwareVersion(
            text.match(/Version:\s*([0-9]+(?:\.[0-9]+)+)/iu)?.[1] ||
              text.match(/Firmware Update[^<\n]{0,120}?Ver\.?\s*([0-9]+(?:\.[0-9]+)+)/iu)?.[1] ||
              null,
          ) || extractLiveFirmwareVersion(text, brandToken),
        releaseDate:
          text.match(/Last Updated:\s*([0-9]{2}\.[0-9]{2}\.[0-9]{4})/iu)?.[1] ||
          extractLiveFirmwareReleaseDate(text),
        imageUrl:
          resolveAbsoluteUrl(
            baseUrl,
            text.match(
              /support-header__img[\s\S]{0,300}?src=["']([^"']+)["']/iu,
            )?.[1] || null,
          ) || undefined,
      };
    case "nikon":
      return {
        version:
          normalizeLiveFirmwareVersion(
            text.match(
              /(?:This service supplies software that can be used to update[^<]{0,160}?version\s*<span>\s*([0-9]+(?:\.[0-9]+)+)\s*<\/span>|(?:[A-Z]:)?Ver\.?\s*([0-9]+(?:\.[0-9]+)+))/iu,
            )?.[1] ||
              text.match(
                /(?:This service supplies software that can be used to update[^<]{0,160}?version\s*<span>\s*([0-9]+(?:\.[0-9]+)+)\s*<\/span>|(?:[A-Z]:)?Ver\.?\s*([0-9]+(?:\.[0-9]+)+))/iu,
              )?.[2] ||
              text.match(/Firmware version[:\s]*([0-9]+(?:\.[0-9]+)+)/iu)?.[1] ||
              null,
          ) || extractLiveFirmwareVersion(text, brandToken),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        followUpUrl: extractNikonDetailUrl(text, baseUrl),
        downloadUrl: extractNikonDownloadUrl(text, baseUrl),
      };
    case "sony":
      return {
        version:
          normalizeLiveFirmwareVersion(
            text.match(
              /(?:System Software|Firmware)[^<\n]{0,120}?Ver\.?\s*([0-9]+(?:\.[0-9]+)+)/iu,
            )?.[1] || null,
          ) || extractLiveFirmwareVersion(text, brandToken),
        releaseDate: extractLiveFirmwareReleaseDate(text),
      };
    case "hollyland":
      return {
        version:
          extractHollylandFirmwareVersion(text) ||
          inferFirmwareVersionFromUrl(genericDownloadUrl),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl:
          extractHollylandDownloadUrl(text, baseUrl) || genericDownloadUrl,
        followUpUrl: genericFollowUpUrl,
      };
    case "sennheiser":
      return {
        version:
          extractSennheiserFirmwareVersion(text) ||
          inferFirmwareVersionFromUrl(genericDownloadUrl),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl:
          extractSennheiserDownloadUrl(text, baseUrl) || genericDownloadUrl,
      };
    case "smallhd":
      if (/downloads\.smallhd\.com\/static\/js\//iu.test(baseUrl)) {
        return extractSmallHdBundleMetadata(text);
      }
      return {
        version:
          extractLiveFirmwareVersion(text, brandToken) ||
          inferFirmwareVersionFromUrl(genericDownloadUrl),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl: genericDownloadUrl,
        followUpUrl:
          extractHtmlScriptSrc(
            text,
            baseUrl,
            /\/static\/js\/main\.[a-f0-9]+\.js(?:$|\?)/iu,
          ) || genericFollowUpUrl,
      };
    case "panasonic":
      return {
        version:
          normalizeLiveFirmwareVersion(
            text.match(
              /Date\/Version[\s\S]{0,500}?[A-Z][a-z]{2}\.?\s+\d{1,2},\s+20\d{2}<br>\s*Ver\.?\s*([0-9]+(?:\.[0-9]+)+)/iu,
            )?.[1] || null,
          ) || extractLiveFirmwareVersion(text, brandToken),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl: extractPanasonicDownloadUrl(text, baseUrl),
      };
    default:
      return {
        version:
          extractLiveFirmwareVersion(text, brandToken) ||
          inferFirmwareVersionFromUrl(genericDownloadUrl),
        releaseDate: extractLiveFirmwareReleaseDate(text),
        downloadUrl: genericDownloadUrl,
        followUpUrl: genericFollowUpUrl,
      };
  }
};

const extractLiveFirmwareVersion = (
  text: string,
  brandToken: string,
): string | null => {
  const vendorPatterns: Record<string, RegExp[]> = {
    canon: [
      /Firmware(?: Notice)?[^<\n]{0,120}?Version\s*([A-Z]?\d+(?:\.\d+)+)/iu,
    ],
    dji: [
      /\bv(?:ersion)?\s*([0-9]{2}(?:\.[0-9]{2}){3})\b/iu,
      /\b([0-9]+(?:\.[0-9]+){1,3})\b/iu,
    ],
    fujifilm: [
      /Firmware Update[^<\n]{0,120}?Ver\.?\s*([A-Z]?\d+(?:\.\d+)+)/iu,
    ],
    nikon: [/Firmware version[:\s]*([A-Z]?\d+(?:\.\d+)+)/iu],
    profoto: [/firmware update[^<\n]{0,80}\s([A-Z]?\d+(?:\.\d+)?)/iu],
    sony: [
      /(?:Firmware|System Software)[^<\n]{0,120}?Ver\.?\s*([A-Z]?\d+(?:\.\d+)+)/iu,
    ],
    atomos: [/AtomOS\s*([0-9]+(?:\.[0-9]+)?)/iu],
  };

  const genericPatterns = [
    /Firmware(?: Update| Notice)?[^<\n]{0,120}?Version\s*([A-Z]?\d+(?:\.\d+)+)/iu,
    /Ver\.?\s*([A-Z]?\d+(?:\.\d+)+)/iu,
    /Version\s*([A-Z]?\d+(?:\.\d+)+)/iu,
  ];

  const patterns = [...(vendorPatterns[brandToken] || []), ...genericPatterns];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    const normalized = normalizeLiveFirmwareVersion(match?.[1] || null);
    if (normalized) return normalized;
  }
  return null;
};

const extractLiveFirmwareReleaseDate = (text: string): string | null => {
  const isoMatch = text.match(/\b(20\d{2}-\d{2}-\d{2})\b/u);
  if (isoMatch?.[1]) return isoMatch[1];

  const dottedNumericMatch = text.match(
    /\b(\d{2})[./-](\d{2})[./-](20\d{2})\b/u,
  );
  if (dottedNumericMatch) {
    return (
      toIsoDate(
        dottedNumericMatch[3],
        dottedNumericMatch[1],
        dottedNumericMatch[2],
      ) || null
    );
  }

  const monthFirstMatch = text.match(
    /\b((?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?)\s+(\d{1,2}),\s*(20\d{2})\b/iu,
  );
  if (monthFirstMatch?.[1] && monthFirstMatch?.[2] && monthFirstMatch?.[3]) {
    const month = monthTokenToNumber(monthFirstMatch[1]);
    if (month) {
      return toIsoDate(monthFirstMatch[3], month, monthFirstMatch[2]);
    }
  }

  const dayFirstMatch = text.match(
    /\b(\d{1,2})\s+((?:Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|Jul(?:y)?|Aug(?:ust)?|Sep(?:t(?:ember)?)?|Oct(?:ober)?|Nov(?:ember)?|Dec(?:ember)?)\.?),?\s*(20\d{2})\b/iu,
  );
  if (dayFirstMatch?.[1] && dayFirstMatch?.[2] && dayFirstMatch?.[3]) {
    const month = monthTokenToNumber(dayFirstMatch[2]);
    if (month) {
      return toIsoDate(dayFirstMatch[3], month, dayFirstMatch[1]);
    }
  }

  return null;
};

const shouldPreferLiveFirmwareVersion = (
  liveVersion: string | null,
  profileVersion: string | null | undefined,
): boolean => {
  if (!liveVersion) return false;
  if (!profileVersion) return true;
  if (isGenericDiscoveryVersion(profileVersion)) return true;
  if (/^[A-Z]/iu.test(liveVersion)) return liveVersion !== profileVersion;
  return compareVersions(liveVersion, profileVersion) >= 0;
};

const fetchOfficialFirmwarePageMetadata = async (
  url: string,
  brandToken: string,
  camera?: Pick<FirmwareSeedCandidate, "brand" | "model"> | null,
  depth = 0,
): Promise<OfficialFirmwarePageMetadata | null> => {
  const now = Date.now();
  const cacheKey = toFirmwareMetadataCacheKey(url, brandToken, camera);
  const cached = officialFirmwareMetadataCache.get(cacheKey);
  if (cached && cached.expiresAt > now) {
    return cached.value;
  }

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    const response = await fetch(url, {
      headers: {
        "user-agent":
          "Mozilla/5.0 (compatible; CreatorHubFirmwareBot/1.0; +https://creatorhub.no)",
      },
      signal: controller.signal,
    });
    clearTimeout(timeout);

    if (!response.ok) {
      officialFirmwareMetadataCache.set(cacheKey, {
        value: null,
        expiresAt: now + OFFICIAL_FIRMWARE_METADATA_TTL_MS,
      });
      return null;
    }

    const html = await response.text();
    const pageUrl = readString(response.url) || url;
    const vendorMetadata = extractVendorFirmwareMetadata(
      html,
      brandToken,
      pageUrl,
      camera,
    );
    const hasFirmwareSignals = pageHasFirmwareSignals(html);
    let metadata: OfficialFirmwarePageMetadata = {
      title: extractHtmlTitle(html),
      imageUrl:
        extractHtmlMetaContent(html, "og:image") ||
        extractHtmlMetaContent(html, "twitter:image") ||
        extractPrimaryHtmlImageUrl(html, pageUrl),
      version:
        normalizeLiveFirmwareVersion(vendorMetadata.version || null) ||
        extractLiveFirmwareVersion(html, brandToken),
      releaseDate:
        vendorMetadata.releaseDate ||
        (hasFirmwareSignals ? extractLiveFirmwareReleaseDate(html) : null),
      sourceUrl: pageUrl,
      downloadUrl:
        resolveAbsoluteUrl(pageUrl, vendorMetadata.downloadUrl || null) ||
        pageUrl,
      followUpUrl:
        depth === 0
          ? resolveAbsoluteUrl(pageUrl, vendorMetadata.followUpUrl || null)
          : null,
    };

    if (metadata.followUpUrl && metadata.followUpUrl !== pageUrl && depth < 1) {
      const followUpMetadata = await fetchOfficialFirmwarePageMetadata(
        metadata.followUpUrl,
        brandToken,
        camera,
        depth + 1,
      );
      if (followUpMetadata) {
        const followUpSourceUrl =
          followUpMetadata.sourceUrl || metadata.followUpUrl;
        const followUpLooksLikeAsset = /\.(?:js|json|zip|bin|dmg|pkg|exe)(?:$|[?#])/iu.test(
          followUpSourceUrl || "",
        );
        metadata = {
          title: followUpMetadata.title || metadata.title,
          imageUrl: followUpMetadata.imageUrl || metadata.imageUrl,
          version: followUpMetadata.version || metadata.version,
          releaseDate: followUpMetadata.releaseDate || metadata.releaseDate,
          sourceUrl: followUpLooksLikeAsset
            ? metadata.sourceUrl
            : followUpSourceUrl,
          downloadUrl:
            followUpMetadata.downloadUrl ||
            metadata.downloadUrl ||
            followUpMetadata.sourceUrl ||
            metadata.sourceUrl,
          followUpUrl: null,
        };
      }
    }

    officialFirmwareMetadataCache.set(cacheKey, {
      value: metadata,
      expiresAt: now + OFFICIAL_FIRMWARE_METADATA_TTL_MS,
    });
    return metadata;
  } catch (error) {
    console.warn("Official firmware metadata fetch failed:", {
      url,
      error: error instanceof Error ? error.message : error,
    });
    officialFirmwareMetadataCache.set(cacheKey, {
      value: null,
      expiresAt: now + 30 * 60 * 1000,
    });
    return null;
  }
};

const resolveLiveCanonicalFirmwareProfile = async (
  camera: Pick<FirmwareSeedCandidate, "brand" | "model">,
  profile: CanonicalFirmwareProfile,
): Promise<CanonicalFirmwareProfile> => {
  if (profile.urlKind === "brand-portal") {
    return profile;
  }

  const metadata = await fetchOfficialFirmwarePageMetadata(
    profile.sourceUrl,
    profile.brandToken,
    camera,
  );
  if (!metadata) {
    return profile;
  }

  return {
    ...profile,
    version: shouldPreferLiveFirmwareVersion(metadata.version, profile.version)
      ? metadata.version || profile.version
      : profile.version,
    releaseDate: metadata.releaseDate || profile.releaseDate,
    sourceUrl: metadata.sourceUrl || profile.sourceUrl,
    downloadUrl:
      metadata.downloadUrl ||
      profile.downloadUrl ||
      metadata.sourceUrl ||
      profile.sourceUrl,
    description:
      profile.description ||
      metadata.title ||
      `Produsentoppdatering for ${camera.brand} ${camera.model}.`,
    officialImageUrl: metadata.imageUrl || profile.officialImageUrl,
    officialTitle: metadata.title || profile.officialTitle,
  };
};

const inferCameraTypeFromEquipmentCategory = (
  value: string | null | undefined,
): DiscoveryCameraType => {
  const normalized = normalizeCameraCategory(value || "");
  if (
    normalized.includes("video") ||
    normalized.includes("cine") ||
    normalized.includes("drone") ||
    normalized.includes("action") ||
    normalized.includes("mobile") ||
    normalized.includes("phone") ||
    normalized.includes("tablet") ||
    normalized.includes("audio")
  ) {
    return "video";
  }
  return "photo";
};

const toFirmwareSeedCandidate = (
  camera: Pick<
    CameraRecord,
    | "brand"
    | "model"
    | "type"
    | "category"
    | "releaseDate"
    | "lastUpdated"
    | "lastSeenAt"
    | "version"
  >,
): FirmwareSeedCandidate => ({
  brand: camera.brand,
  model: camera.model,
  type: camera.type,
  category: camera.category,
  releaseDate: camera.releaseDate,
  lastUpdated: camera.lastUpdated,
  lastSeenAt: camera.lastSeenAt,
  version: camera.version,
});

async function loadFirmwareSeedCandidatesFromUserEquipment(filters?: {
  type?: DiscoveryCameraType;
  userId?: string | null;
  profession?: string | null;
}): Promise<FirmwareSeedCandidate[]> {
  const tableAvailable = await hasTable("user_equipment");
  if (!tableAvailable) return [];

  const conditions = [];
  if (filters?.userId) {
    conditions.push(eq(schema.userEquipment.userId, filters.userId));
  }
  if (filters?.profession) {
    conditions.push(eq(schema.userEquipment.userType, filters.profession));
  }

  const rows = await db
    .select({
      brand: schema.userEquipment.brand,
      model: schema.userEquipment.model,
      category: schema.userEquipment.category,
      updatedAt: schema.userEquipment.updatedAt,
      createdAt: schema.userEquipment.createdAt,
    })
    .from(schema.userEquipment)
    .where(conditions.length ? and(...conditions) : sql`true`);

  const candidates: FirmwareSeedCandidate[] = [];
  rows.forEach((row) => {
    const brand = row.brand?.trim();
    const model = row.model?.trim();
    if (!brand || !model) return;
    const inferredType = inferCameraTypeFromEquipmentCategory(row.category);
    if (filters?.type && inferredType !== filters.type) return;

    const lastSeenAt =
      row.updatedAt || row.createdAt || new Date().toISOString();
    candidates.push({
      brand,
      model,
      type: inferredType,
      category: row.category || undefined,
      lastSeenAt,
      lastUpdated: lastSeenAt,
      version: 1,
    });
  });
  return candidates;
}

function loadFirmwareSeedCandidatesFromAudioStorageDatabase(filters?: {
  type?: DiscoveryCameraType;
}): FirmwareSeedCandidate[] {
  if (filters?.type === "photo") return [];
  return AUDIO_STORAGE_DEVICE_DATABASE.map((device) => ({
    brand: device.brand,
    model: device.model,
    type: "video",
    category: "audio",
    releaseDate: device.releaseDate,
    lastSeenAt: device.lastSeenAt,
    lastUpdated: device.lastSeenAt,
    version: Math.max(1, device.releaseYear - 2019),
  }));
}

async function loadFirmwareSeedCandidates(
  type: DiscoveryCameraType | null,
  filters?: { userId?: string | null; profession?: string | null },
): Promise<FirmwareSeedCandidate[]> {
  const shouldLoadCatalogDefaults =
    !filters?.userId && !filters?.profession;
  const cameraSources = shouldLoadCatalogDefaults
    ? await loadCameraSourceBundle(type)
    : { source: [] as CameraRecord[] };
  const catalogCandidates = cameraSources.source.map((camera) =>
    toFirmwareSeedCandidate(camera),
  );
  const equipmentCandidates = await loadFirmwareSeedCandidatesFromUserEquipment(
    {
      type: type || undefined,
      userId: filters?.userId,
      profession: filters?.profession,
    },
  );
  const audioCandidates = shouldLoadCatalogDefaults
    ? loadFirmwareSeedCandidatesFromAudioStorageDatabase({
        type: type || undefined,
      })
    : [];

  const preferredByKey = new Map<string, FirmwareSeedCandidate>();
  for (const candidate of [
    ...catalogCandidates,
    ...equipmentCandidates,
    ...audioCandidates,
  ]) {
    const brand = candidate.brand?.trim();
    const model = candidate.model?.trim();
    if (!brand || !model) continue;
    const key = toFirmwareDeviceKey(brand, model);
    const existing = preferredByKey.get(key);
    if (!existing) {
      preferredByKey.set(key, candidate);
      continue;
    }

    const existingScore =
      (existing.releaseDate ? 2 : 0) +
      (existing.lastUpdated ? 1 : 0) +
      (existing.version && existing.version > 1 ? 1 : 0);
    const candidateScore =
      (candidate.releaseDate ? 2 : 0) +
      (candidate.lastUpdated ? 1 : 0) +
      (candidate.version && candidate.version > 1 ? 1 : 0);
    if (candidateScore > existingScore) {
      preferredByKey.set(key, candidate);
    }
  }

  return Array.from(preferredByKey.values());
}

async function ensureFirmwareRowsForCameras(
  cameras: FirmwareSeedCandidate[],
  options?: { liveRefresh?: boolean },
): Promise<DiscoveryFirmwareSyncResult> {
  if (!cameras.length) {
    return {
      tableAvailable: true,
      considered: 0,
      inserted: 0,
      existing: 0,
      skippedInvalid: 0,
      failed: 0,
    };
  }

  await ensureFirmwareUpdatesCompatibilityColumns();
  const tableAvailable = await hasTable("firmware_updates");
  if (!tableAvailable) {
    return {
      tableAvailable: false,
      considered: cameras.length,
      inserted: 0,
      existing: 0,
      skippedInvalid: 0,
      failed: 0,
    };
  }
  const firmwareColumns = await getTableColumns("firmware_updates");

  const preferredByKey = new Map<string, FirmwareSeedCandidate>();
  let skippedInvalid = 0;

  cameras.forEach((camera) => {
    const brand = camera.brand?.trim();
    const model = camera.model?.trim();
    if (!brand || !model) {
      skippedInvalid += 1;
      return;
    }
    const key = toFirmwareDeviceKey(brand, model);
    const existing = preferredByKey.get(key);
    if (!existing) {
      preferredByKey.set(key, camera);
      return;
    }

    const existingUpdated = new Date(
      existing.lastUpdated || existing.lastSeenAt || 0,
    ).getTime();
    const candidateUpdated = new Date(
      camera.lastUpdated || camera.lastSeenAt || 0,
    ).getTime();
    const existingVersion = existing.version ?? 0;
    const candidateVersion = camera.version ?? 0;
    if (
      candidateVersion > existingVersion ||
      candidateUpdated > existingUpdated
    ) {
      preferredByKey.set(key, camera);
    }
  });

  const uniqueCameras = Array.from(preferredByKey.values());
  if (!uniqueCameras.length) {
    return {
      tableAvailable: true,
      considered: 0,
      inserted: 0,
      existing: 0,
      skippedInvalid,
      failed: 0,
    };
  }

  const selectableColumns = [
    "brand",
    "model",
    "category",
    "version",
    "release_date",
    "source_url",
    "download_url",
    "importance",
  ].filter((column) => firmwareColumns.has(column));
  const selectedSqlColumns = selectableColumns
    .map((column) => `"${column}"`)
    .join(", ");
  const existingRowParams = uniqueCameras.flatMap((camera) => [
    camera.brand,
    camera.model,
  ]);
  const existingRowClauses = uniqueCameras.map((_, index) => {
    const brandParam = index * 2 + 1;
    const modelParam = index * 2 + 2;
    return `(
      regexp_replace(lower(coalesce("brand", '')), '[^a-z0-9]+', '', 'g') =
      regexp_replace(lower($${brandParam}), '[^a-z0-9]+', '', 'g')
      and regexp_replace(lower(coalesce("model", '')), '[^a-z0-9]+', '', 'g') =
      regexp_replace(lower($${modelParam}), '[^a-z0-9]+', '', 'g')
    )`;
  });
  const existingRowsResult = await pool.query(
    `select ${selectedSqlColumns || '"brand", "model"'} from "firmware_updates"
     where ${existingRowClauses.join(" or ")}`,
    existingRowParams,
  );
  const existingRows: ExistingFirmwareRow[] = existingRowsResult.rows.map(
    (row) => ({
      brand: row.brand ? String(row.brand) : "",
      model: row.model ? String(row.model) : "",
      category: row.category ? String(row.category) : null,
      version: row.version ? String(row.version) : null,
      releaseDate: normalizeSqlDateValue(row.release_date),
      sourceUrl: row.source_url ? String(row.source_url) : null,
      downloadUrl: row.download_url ? String(row.download_url) : null,
      importance: row.importance ? String(row.importance) : null,
    }),
  );

  const existingByKey = new Map<string, ExistingFirmwareRow>();
  existingRows.forEach((row) => {
    const key = toFirmwareDeviceKey(row.brand, row.model);
    const existing = existingByKey.get(key);
    if (!existing) {
      existingByKey.set(key, row);
      return;
    }

    if (compareVersions(row.version, existing.version) > 0) {
      existingByKey.set(key, row);
    }
  });

  let inserted = 0;
  let upgraded = 0;
  let failed = 0;
  const nowIso = new Date().toISOString();

  for (const camera of uniqueCameras) {
    const key = toFirmwareDeviceKey(camera.brand, camera.model);
    const existing = existingByKey.get(key);
    const canonicalBase = resolveCanonicalFirmwareProfile(camera);
    const canonical = canonicalBase
      ? options?.liveRefresh
        ? await resolveLiveCanonicalFirmwareProfile(camera, canonicalBase)
        : canonicalBase
      : null;
    const releaseDate = toFirmwareReleaseDate(camera) ?? nowIso.slice(0, 10);

    if (existing) {
      if (!options?.liveRefresh) continue;
      if (!canonical) continue;

      const shouldUpgrade =
        (isGenericDiscoveryVersion(existing.version) &&
          !isGenericDiscoveryVersion(canonical.version)) ||
        compareVersions(canonical.version, existing.version) > 0 ||
        hasBetterCanonicalSource(existing.sourceUrl, canonical.sourceUrl) ||
        hasBetterCanonicalReleaseDate(
          existing.releaseDate,
          canonical.releaseDate || releaseDate,
        );

      if (!shouldUpgrade) continue;

      try {
        const updatePayload = buildCanonicalFirmwarePayload(
          camera,
          canonical,
          nowIso,
          releaseDate,
        );
        const updateEntries = Object.entries(updatePayload).filter(
          ([column, value]) =>
            firmwareColumns.has(column) && value !== undefined,
        );
        if (!updateEntries.length) continue;

        const setSql = updateEntries
          .map(([column], index) => `"${column}" = $${index + 1}`)
          .join(", ");
        const params = updateEntries.map(([, value]) => value);
        params.push(camera.brand, camera.model);
        const result = await pool.query(
          `update "firmware_updates"
           set ${setSql}
           where regexp_replace(lower(coalesce("brand", '')), '[^a-z0-9]+', '', 'g') =
                 regexp_replace(lower($${params.length - 1}), '[^a-z0-9]+', '', 'g')
             and regexp_replace(lower(coalesce("model", '')), '[^a-z0-9]+', '', 'g') =
                 regexp_replace(lower($${params.length}), '[^a-z0-9]+', '', 'g')`,
          params,
        );
        if (result.rowCount && result.rowCount > 0) {
          upgraded += result.rowCount;
          existingByKey.set(key, {
            ...existing,
            category: camera.category || existing.category || null,
            version: canonical.version,
            sourceUrl: canonical.sourceUrl,
            downloadUrl: canonical.downloadUrl || canonical.sourceUrl,
            releaseDate: canonical.releaseDate || releaseDate,
            importance: canonical.importance || existing.importance,
          });
        }
      } catch (error) {
        failed += 1;
        console.warn("Unable to apply canonical firmware profile:", {
          brand: camera.brand,
          model: camera.model,
          error,
        });
      }
      continue;
    }

    try {
      const insertPayload: Record<string, unknown> = {
        brand: camera.brand,
        model: camera.model,
        category:
          camera.category || (camera.type === "video" ? "video" : "camera"),
        version: canonical?.version || toDiscoveryFirmwareVersion(camera),
        update_type: "firmware",
        release_date: canonical?.releaseDate || releaseDate,
        is_latest: true,
        is_critical: canonical?.importance === "critical",
        importance: canonical?.importance || "normal",
        download_url: canonical?.downloadUrl || null,
        download_size: null,
        installation_time: "10 minutter",
        photographer_benefits: JSON.stringify([
          "Bedre stabilitet i arbeidsflyt",
        ]),
        videographer_benefits: JSON.stringify(["Bedre stabilitet i opptak"]),
        music_producer_benefits: JSON.stringify(["Forbedret enhetsstabilitet"]),
        general_improvements: JSON.stringify([
          `Automatisk registrert via discovery for ${camera.brand} ${camera.model}.`,
        ]),
        bug_fixes: JSON.stringify(["Metadata-normalisering"]),
        new_features: JSON.stringify([
          "Automatisk firmware-sporing for nye kamera",
        ]),
        requirements: JSON.stringify([
          "Bekreft produsentens offisielle firmware før installasjon",
        ]),
        compatibility: JSON.stringify([camera.category]),
        known_issues: JSON.stringify([]),
        description:
          canonical?.description ||
          `Firmware-oppdatering tilgjengelig for ${camera.brand} ${camera.model}.`,
        release_notes: (canonical?.releaseNotes || []).join("\n"),
        installation_steps: JSON.stringify([
          "1. Last ned firmware fra produsent.",
          "2. Følg produsentens oppdateringsguide.",
          "3. Verifiser versjon etter restart.",
        ]),
        rollback_instructions: JSON.stringify([
          "Bruk produsentens gjenopprettingsprosedyre hvis oppdatering feiler.",
        ]),
        photographer_recommendation: "recommended",
        videographer_recommendation: "recommended",
        music_producer_recommendation: "optional",
        risk_level: "low",
        source_url: canonical?.sourceUrl || null,
        last_checked: nowIso,
        last_verified: nowIso,
        created_at: nowIso,
        updated_at: nowIso,
      };

      const supportedEntries = Object.entries(insertPayload).filter(
        ([column]) => firmwareColumns.has(column),
      );
      if (!supportedEntries.length) {
        failed += 1;
        continue;
      }

      const sqlColumns = supportedEntries
        .map(([column]) => `"${column}"`)
        .join(", ");
      const sqlValues = supportedEntries
        .map((_, index) => `$${index + 1}`)
        .join(", ");
      const params = supportedEntries.map(([, value]) => value);
      await pool.query(
        `insert into "firmware_updates" (${sqlColumns}) values (${sqlValues})`,
        params,
      );
      inserted += 1;
      existingByKey.set(key, {
        brand: camera.brand,
        model: camera.model,
        category: camera.category || null,
        version: canonical?.version || toDiscoveryFirmwareVersion(camera),
        releaseDate: canonical?.releaseDate || releaseDate,
        sourceUrl: canonical?.sourceUrl || null,
        downloadUrl: canonical?.downloadUrl || null,
        importance: canonical?.importance || "normal",
      });
    } catch (error) {
      failed += 1;
      console.warn("Unable to seed firmware row from camera sync:", {
        brand: camera.brand,
        model: camera.model,
        error,
      });
    }
  }

  if (!options?.liveRefresh) {
    const considered = uniqueCameras.length;
    const existing = Math.max(0, considered - inserted - failed);
    return {
      tableAvailable: true,
      considered,
      inserted,
      upgraded,
      existing,
      skippedInvalid,
      failed,
    };
  }

  for (const existing of existingByKey.values()) {
    const canonicalBase = resolveCanonicalFirmwareProfileByDevice(
      existing.brand,
      existing.model,
      existing.category || undefined,
    );
    const canonical = canonicalBase
      ? options?.liveRefresh
        ? await resolveLiveCanonicalFirmwareProfile(
            {
              brand: existing.brand,
              model: existing.model,
            },
            canonicalBase,
          )
        : canonicalBase
      : null;
    if (!canonical) continue;

    const shouldUpgrade =
      (isGenericDiscoveryVersion(existing.version) &&
        !isGenericDiscoveryVersion(canonical.version)) ||
      compareVersions(canonical.version, existing.version) > 0 ||
      hasBetterCanonicalSource(existing.sourceUrl, canonical.sourceUrl) ||
      hasBetterCanonicalReleaseDate(existing.releaseDate, canonical.releaseDate);

    if (!shouldUpgrade) continue;

    try {
      const updatePayload = buildCanonicalFirmwarePayload(
        {
          brand: existing.brand,
          model: existing.model,
          type: inferCameraTypeFromEquipmentCategory(existing.category),
          category: existing.category || "camera",
        },
        canonical,
        nowIso,
        existing.releaseDate || nowIso.slice(0, 10),
      );

      const updateEntries = Object.entries(updatePayload).filter(
        ([column, value]) => firmwareColumns.has(column) && value !== undefined,
      );
      if (!updateEntries.length) continue;

      const setSql = updateEntries
        .map(([column], index) => `"${column}" = $${index + 1}`)
        .join(", ");
      const params = updateEntries.map(([, value]) => value);
      params.push(existing.brand, existing.model);
      const result = await pool.query(
        `update "firmware_updates"
         set ${setSql}
         where regexp_replace(lower(coalesce("brand", '')), '[^a-z0-9]+', '', 'g') =
               regexp_replace(lower($${params.length - 1}), '[^a-z0-9]+', '', 'g')
           and regexp_replace(lower(coalesce("model", '')), '[^a-z0-9]+', '', 'g') =
               regexp_replace(lower($${params.length}), '[^a-z0-9]+', '', 'g')`,
        params,
      );
      if (result.rowCount && result.rowCount > 0) {
        upgraded += result.rowCount;
        existingByKey.set(toFirmwareDeviceKey(existing.brand, existing.model), {
          ...existing,
          category: existing.category || null,
          version: canonical.version,
          sourceUrl: canonical.sourceUrl,
          downloadUrl: canonical.downloadUrl || canonical.sourceUrl,
          releaseDate: canonical.releaseDate || existing.releaseDate,
          importance: canonical.importance || existing.importance,
        });
      }
    } catch (error) {
      failed += 1;
      console.warn(
        "Unable to apply canonical firmware profile (fallback pass):",
        {
          brand: existing.brand,
          model: existing.model,
          error,
        },
      );
    }
  }

  const considered = uniqueCameras.length;
  const existing = Math.max(0, considered - inserted - failed);

  return {
    tableAvailable: true,
    considered,
    inserted,
    upgraded,
    existing,
    skippedInvalid,
    failed,
  };
}

let firmwareAutoRefreshPromise: Promise<void> | null = null;

async function runAutomaticFirmwareRefresh(reason: string): Promise<void> {
  if (firmwareAutoRefreshPromise) {
    return firmwareAutoRefreshPromise;
  }

  firmwareAutoRefreshPromise = (async () => {
    try {
      const firmwareCandidates = await loadFirmwareSeedCandidates(null);
      await ensureFirmwareRowsForCameras(firmwareCandidates, {
        liveRefresh: true,
      });
      catalogPreviewImageCache.clear();
      console.info("[Firmware Auto Refresh] completed", {
        reason,
        candidates: firmwareCandidates.length,
        refreshedAt: new Date().toISOString(),
      });
    } catch (error) {
      console.error("[Firmware Auto Refresh] failed", {
        reason,
        error: error instanceof Error ? error.message : error,
      });
    } finally {
      firmwareAutoRefreshPromise = null;
    }
  })();

  return firmwareAutoRefreshPromise;
}

app.post("/api/equipment/discovery/sync", async (req, res) => {
  try {
    const type = resolveDiscoveryType(req.query.type);
    if (!type) {
      res.status(400).json({ error: "Invalid type. Use photo|video" });
      return;
    }

    const nowIso = new Date().toISOString();
    const syncId = `${type}-${Date.now()}`;
    const candidates = buildDiscoveryCandidates(type);
    const store = getCameraArrayByType(type);

    const byId = new Map(store.map((camera) => [camera.id, camera]));
    const byExternalId = new Map(
      store.map((camera) => [camera.externalId, camera.id]),
    );

    let inserted = 0;
    let updated = 0;
    let rejected = 0;
    let conflicts = 0;

    candidates.forEach((candidate) => {
      const existingId = byId.has(candidate.id)
        ? candidate.id
        : byExternalId.get(candidate.externalId);
      if (!existingId) {
        store.push(candidate);
        byId.set(candidate.id, candidate);
        byExternalId.set(candidate.externalId, candidate.id);
        inserted += 1;
        return;
      }

      const existing = byId.get(existingId);
      if (!existing) {
        rejected += 1;
        return;
      }

      if (
        existing.externalId !== candidate.externalId &&
        existing.id === candidate.id
      ) {
        conflicts += 1;
        return;
      }

      const merged = buildCameraRecord({
        ...existing,
        ...candidate,
        id: existing.id,
        externalId: existing.externalId,
        source: "discovery",
        lastSeenAt: nowIso,
        lastUpdated: nowIso,
        version: Math.max(existing.version, candidate.version) + 1,
        specs: { ...existing.specs, ...candidate.specs },
      });

      const hasMeaningfulChange =
        existing.description !== merged.description ||
        JSON.stringify(existing.features) !== JSON.stringify(merged.features) ||
        JSON.stringify(existing.logFormats ?? []) !==
          JSON.stringify(merged.logFormats ?? []) ||
        JSON.stringify(existing.resolution ?? []) !==
          JSON.stringify(merged.resolution ?? []);

      if (hasMeaningfulChange) {
        const index = store.findIndex((camera) => camera.id === existing.id);
        if (index >= 0) {
          store[index] = merged;
        }
        byId.set(existing.id, merged);
        updated += 1;
      }
    });

    const firmwareCandidates = await loadFirmwareSeedCandidates(type);
    const firmwareSync = await ensureFirmwareRowsForCameras(firmwareCandidates, {
      liveRefresh: true,
    });

    EQUIPMENT_DISCOVERY_STATUS[type] = {
      ...EQUIPMENT_DISCOVERY_STATUS[type],
      lastUpdate: nowIso,
      syncId,
      inserted,
      updated,
      rejected,
      conflicts,
      source: `backend-${type}-sync`,
    };

    res.json({
      success: true,
      type,
      source: EQUIPMENT_DISCOVERY_STATUS[type].source,
      timestamp: nowIso,
      syncId,
      inserted,
      updated,
      rejected,
      conflicts,
      totalCameras: store.length,
      firmwareSync,
    });
  } catch (error) {
    console.error("Discovery sync error:", error);
    res.status(500).json({ error: "Failed to run discovery sync" });
  }
});

