app.get("/api/equipment/audio-interfaces", (req, res) => {
  const q = typeof req.query.q === "string" ? req.query.q.trim() : "";
  const records = searchAudioStorageDevices({
    q,
    yearFrom: 2020,
    yearTo: 2026,
  }).map((device) => {
    const maxSampleRateKhz = Math.round(device.maxSampleRateHz / 1000);
    const storageFeature = `Lagring: ${device.storageMedia.join(", ")}`;
    return {
      id: device.id,
      brand: device.brand,
      model: device.model,
      type: device.category,
      inputs: Math.max(1, Math.ceil(device.channelCount / 2)),
      outputs: Math.max(1, Math.ceil(device.channelCount / 2)),
      preamps: Math.max(1, Math.ceil(device.channelCount / 2)),
      maxSampleRate: `${maxSampleRateKhz} kHz`,
      bitDepth: device.bitDepthOptions,
      features: [...device.recordingFormats, storageFeature],
      description: device.description,
      compatibility: ["macOS", "Windows", "iOS", "Android"],
      category: device.category,
      storageMedia: device.storageMedia,
      releaseYear: device.releaseYear,
    };
  });

  res.json(records);
});

const CATALOG_PRICE_BY_RANGE: Record<CameraRecord["priceRange"], number> = {
  budget: 9990,
  "mid-range": 21990,
  professional: 44990,
  cinema: 89990,
};

const CATALOG_AUDIO_CATEGORY_PRICE: Record<
  (typeof AUDIO_STORAGE_DEVICE_DATABASE)[number]["category"],
  number
> = {
  "field-recorder": 8990,
  "mixer-recorder": 39990,
  "pocket-recorder": 2990,
  "wireless-recorder": 5990,
  "on-camera-recorder": 4990,
  "camera-attached-digital-mic": 3490,
  "desktop-production-console": 29990,
};

const catalogSortByLatest = (
  a: CompatCatalogItem,
  b: CompatCatalogItem,
): number => {
  if (b.releaseYear !== a.releaseYear) return b.releaseYear - a.releaseYear;
  const brandCompare = a.brand.localeCompare(b.brand, "nb");
  if (brandCompare !== 0) return brandCompare;
  return a.model.localeCompare(b.model, "nb");
};

const categoryFromCameraRecord = (
  camera: CameraRecord,
): CompatCatalogItem["category"] => {
  if (camera.type === "video") return "video";
  const normalizedCategory = normalizeCameraCategory(camera.category || "");
  if (
    normalizedCategory.includes("cinema") ||
    normalizedCategory.includes("video")
  )
    return "video";
  return "cameras";
};

const slugifyCatalogIdentityPart = (value: string): string =>
  normalizeModelLookupValue(value)
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "") || "item";

const toCatalogItemFromCameraRecord = (
  camera: CameraRecord,
): CompatCatalogItem => {
  const releaseYear = Number.parseInt(
    String(camera.releaseDate || "").slice(0, 4),
    10,
  );
  const resolvedYear = Number.isInteger(releaseYear) ? releaseYear : 2026;
  const category = categoryFromCameraRecord(camera);
  const supportedMemoryCardTypes =
    toFlexibleStringArray(camera.specs.supportedMemoryCardTypes) ??
    toFlexibleStringArray(camera.specs.cardTypeIds) ??
    [];
  const supportedMemoryCardLabels =
    toFlexibleStringArray(camera.specs.cardTypes) ??
    supportedMemoryCardTypes.map(
      (cardTypeId) => getMemoryCardTypeByIdFromDatabase(cardTypeId)?.fullName || cardTypeId,
    );

  return {
    id: `camera-${slugifyCatalogIdentityPart(camera.brand)}-${slugifyCatalogIdentityPart(camera.model)}-${slugifyCatalogIdentityPart(category)}`,
    brand: camera.brand,
    model: camera.model,
    category,
    description: camera.description || `${camera.brand} ${camera.model}`,
    priceNOK: CATALOG_PRICE_BY_RANGE[camera.priceRange] ?? 0,
    releaseYear: resolvedYear,
    mount: camera.mount,
    type: camera.category,
    norwegianSupplier: "Foto.no",
    availability: camera.isDeprecated ? "limited" : "available",
    imageUrl: "",
    specifications: {
      sensorSize: camera.sensorSize || "",
      megapixels: camera.megapixels ?? "",
      mount: camera.mount || "",
      logFormats: (camera.logFormats || []).join(", "),
      videoResolution: (camera.videoResolution || camera.resolution || []).join(
        ", ",
      ),
      videoFrameRates: (camera.videoFrameRates || camera.frameRates || []).join(
        ", ",
      ),
      netflixCertified: Boolean(camera.isNetflixCertified),
      supportedMemoryCardTypes: supportedMemoryCardTypes.join(", "),
      supportedMemoryCardLabels: supportedMemoryCardLabels.join(", "),
    },
  };
};

const toCatalogItemFromAudioStorageDevice = (
  device: (typeof AUDIO_STORAGE_DEVICE_DATABASE)[number],
): CompatCatalogItem => ({
  id: `audio-storage-${device.id}`,
  brand: device.brand,
  model: device.model,
  category: "audio",
  description: device.description,
  priceNOK: CATALOG_AUDIO_CATEGORY_PRICE[device.category] ?? 5990,
  releaseYear: device.releaseYear,
  type: device.category,
  norwegianSupplier: "Foto.no",
  availability: device.isDeprecated ? "limited" : "available",
  imageUrl: "",
  specifications: {
    storageMedia: device.storageMedia.join(", "),
    maxStorage: device.maxStorage,
    formats: device.recordingFormats.join(", "),
    maxSampleRateHz: device.maxSampleRateHz,
    bitDepth: device.bitDepthOptions.join(", "),
    channels: device.channelCount,
    timecode: device.supportsTimecode,
  },
});

const toCatalogItemFromMemoryCard = (
  card: (typeof MEMORY_CARD_PRODUCTS_DB)[number],
): CompatCatalogItem => {
  const cardType = getMemoryCardTypeByIdFromDatabase(card.cardTypeId);
  return {
    id: `memory-card-${card.id}`,
    brand: card.brand,
    model: `${card.model} ${card.capacity}GB`,
    category: "accessories",
    description:
      cardType?.description || `${card.model} minnekort ${card.capacity}GB`,
    priceNOK: card.priceNOK,
    releaseYear: 2026,
    type: cardType?.name || card.cardTypeId,
    norwegianSupplier: "Foto.no",
    availability: "available",
    imageUrl: "",
    specifications: {
      cardTypeId: card.cardTypeId,
      capacityGB: card.capacity,
      readSpeedMBs: card.speedRead,
      writeSpeedMBs: card.speedWrite,
      fullName: cardType?.fullName || card.model,
      videoClass: cardType?.videoClass || "",
      maxCapacity: cardType?.maxCapacity || "",
    },
  };
};

