async function getLegacyStoryLogicEntry(
  projectId: string,
): Promise<LegacyStoryLogicEntry | null> {
  const dbEntry = await compatStoreGet<LegacyStoryLogicEntry>(
    dbLegacyStoryLogicKey(projectId),
  );
  if (dbEntry && typeof dbEntry === "object") {
    legacyStoryLogicByProject.set(projectId, dbEntry);
    return dbEntry;
  }
  return legacyStoryLogicByProject.get(projectId) || null;
}

