app.post(
  "/api/casting/favorites/:projectId/:favoriteType/add",
  async (req, res) => {
    const { projectId, favoriteType } = req.params;
    const itemId = typeof req.body?.itemId === "string" ? req.body.itemId : "";
    if (!itemId) {
      res.status(400).json({ error: "itemId is required" });
      return;
    }
    const key = legacyFavoritesKey(projectId, favoriteType);
    const dbFavorites = await compatStoreGet<string[]>(
      dbLegacyFavoritesKey(projectId, favoriteType),
    );
    const source = Array.isArray(dbFavorites)
      ? dbFavorites
      : legacyFavoritesStore.get(key) || [];
    const current = new Set(source);
    current.add(itemId);
    const updated = Array.from(current);
    legacyFavoritesStore.set(key, updated);
    await compatStoreSet(
      dbLegacyFavoritesKey(projectId, favoriteType),
      updated,
    );
    res.json({ ok: true, favorites: updated });
  },
);

app.post(
  "/api/casting/favorites/:projectId/:favoriteType/remove",
  async (req, res) => {
    const { projectId, favoriteType } = req.params;
    const itemId = typeof req.body?.itemId === "string" ? req.body.itemId : "";
    if (!itemId) {
      res.status(400).json({ error: "itemId is required" });
      return;
    }
    const key = legacyFavoritesKey(projectId, favoriteType);
    const dbFavorites = await compatStoreGet<string[]>(
      dbLegacyFavoritesKey(projectId, favoriteType),
    );
    const source = Array.isArray(dbFavorites)
      ? dbFavorites
      : legacyFavoritesStore.get(key) || [];
    const updated = source.filter((id) => id !== itemId);
    legacyFavoritesStore.set(key, updated);
    await compatStoreSet(
      dbLegacyFavoritesKey(projectId, favoriteType),
      updated,
    );
    res.json({ ok: true, favorites: updated });
  },
);

// Candidate pool (legacy compatibility)
app.get("/api/casting/candidate-pool", async (_req, res) => {
  const dbRows = await compatStoreListByPrefix<any>("casting:candidate-pool:");
  if (dbRows.length > 0) {
    const candidates = dbRows
      .map((row) => row.value)
      .filter((candidate) => candidate && typeof candidate === "object");
    legacyCandidatePool.clear();
    for (const candidate of candidates) {
      const candidateId = typeof candidate.id === "string" ? candidate.id : "";
      if (!candidateId) continue;
      legacyCandidatePool.set(candidateId, candidate);
    }
    res.json({ success: true, candidates });
    return;
  }
  res.json({
    success: true,
    candidates: Array.from(legacyCandidatePool.values()),
  });
});

app.post("/api/casting/candidate-pool", async (req, res) => {
  const payload = req.body || {};
  const candidateId =
    typeof payload.id === "string" && payload.id.trim()
      ? payload.id
      : `pool-candidate-${Date.now()}`;
  const now = new Date().toISOString();
  const current = legacyCandidatePool.get(candidateId) || {};
  const candidate = {
    ...current,
    ...payload,
    id: candidateId,
    createdAt: current.createdAt || now,
    updatedAt: now,
  };
  legacyCandidatePool.set(candidateId, candidate);
  await compatStoreSet(dbLegacyCandidatePoolKey(candidateId), candidate);
  res.status(201).json({ success: true, candidateId, candidate });
});

