function findByIdInProjectMap(
  source: Map<string, any[]>,
  id: string,
): { projectId: string; index: number } | null {
  for (const [projectId, items] of source.entries()) {
    const index = items.findIndex((item) => item.id === id);
    if (index >= 0) return { projectId, index };
  }
  return null;
}

async function findByIdInDbProjectArrays(
  prefix: string,
  id: string,
): Promise<{ projectId: string; index: number; items: any[] } | null> {
  const rows = await compatStoreListByPrefix<any[]>(prefix);
  for (const row of rows) {
    if (!Array.isArray(row.value)) continue;
    const index = row.value.findIndex((item) => item?.id === id);
    if (index < 0) continue;
    const projectId = row.key.slice(prefix.length);
    if (!projectId) continue;
    return {
      projectId,
      index,
      items: row.value,
    };
  }
  return null;
}

function getProjectItems(source: Map<string, any[]>, projectId: string): any[] {
  return source.get(projectId) || [];
}

function setProjectItems(
  source: Map<string, any[]>,
  projectId: string,
  items: any[],
): void {
  source.set(projectId, items);
}

function normalizeProjectAgreementStatus(
  value: unknown,
): "draft" | "sent" | "signed" {
  if (value === "sent" || value === "signed") {
    return value;
  }
  return "draft";
}

function createProjectAgreementRecord(
  payload: Record<string, any>,
): Record<string, any> | null {
  const projectId =
    typeof payload.projectId === "string" ? payload.projectId : "";
  const title = typeof payload.title === "string" ? payload.title.trim() : "";
  const counterpartyType =
    typeof payload.counterpartyType === "string"
      ? payload.counterpartyType
      : "";
  const counterpartyName =
    typeof payload.counterpartyName === "string"
      ? payload.counterpartyName.trim()
      : "";

  if (!projectId || !title || !counterpartyType || !counterpartyName) {
    return null;
  }

  return {
    id: `agreement-${Date.now()}`,
    project_id: projectId,
    agreement_type:
      typeof payload.agreementType === "string"
        ? payload.agreementType
        : "client_nda",
    counterparty_type: counterpartyType,
    counterparty_id:
      typeof payload.counterpartyId === "string" &&
      payload.counterpartyId.trim()
        ? payload.counterpartyId
        : null,
    title,
    purpose:
      typeof payload.purpose === "string" && payload.purpose.trim()
        ? payload.purpose.trim()
        : null,
    disclosing_party_name:
      typeof payload.disclosingPartyName === "string" &&
      payload.disclosingPartyName.trim()
        ? payload.disclosingPartyName.trim()
        : null,
    disclosing_party_company_name:
      typeof payload.disclosingPartyCompanyName === "string" &&
      payload.disclosingPartyCompanyName.trim()
        ? payload.disclosingPartyCompanyName.trim()
        : null,
    disclosing_party_organization_number:
      typeof payload.disclosingPartyOrganizationNumber === "string" &&
      payload.disclosingPartyOrganizationNumber.trim()
        ? payload.disclosingPartyOrganizationNumber.trim()
        : null,
    counterparty_name: counterpartyName,
    counterparty_email:
      typeof payload.counterpartyEmail === "string" &&
      payload.counterpartyEmail.trim()
        ? payload.counterpartyEmail.trim()
        : null,
    counterparty_company_name:
      typeof payload.counterpartyCompanyName === "string" &&
      payload.counterpartyCompanyName.trim()
        ? payload.counterpartyCompanyName.trim()
        : null,
    counterparty_organization_number:
      typeof payload.counterpartyOrganizationNumber === "string" &&
      payload.counterpartyOrganizationNumber.trim()
        ? payload.counterpartyOrganizationNumber.trim()
        : null,
    sections: Array.isArray(payload.sections) ? payload.sections : [],
    start_date:
      typeof payload.startDate === "string" && payload.startDate.trim()
        ? payload.startDate
        : null,
    end_date:
      typeof payload.endDate === "string" && payload.endDate.trim()
        ? payload.endDate
        : null,
    signed_date: null,
    status: "draft",
    metadata:
      payload.metadata && typeof payload.metadata === "object"
        ? payload.metadata
        : {},
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
}

