type FirmwarePriority = "critical" | "high" | "medium" | "low";
type EquipmentType =
  | "camera"
  | "lens"
  | "audio"
  | "software"
  | "accessory"
  | "computer"
  | "lighting"
  | "memory"
  | "tripod"
  | "slider"
  | "flash";
type EquipmentCondition = "excellent" | "good" | "fair" | "poor" | "critical";
type MaintenanceTaskType =
  | "cleaning"
  | "calibration"
  | "repair"
  | "inspection"
  | "replacement"
  | "upgrade";
type MaintenancePriority = "low" | "medium" | "high" | "critical";
type MaintenanceStatus =
  | "scheduled"
  | "in_progress"
  | "completed"
  | "cancelled"
  | "overdue";

function parseSettings(settings: unknown): Record<string, unknown> {
  if (!settings) return {};
  if (typeof settings === "string") {
    try {
      return JSON.parse(settings);
    } catch {
      return {};
    }
  }
  if (typeof settings === "object") return settings as Record<string, unknown>;
  return {};
}

function normalizeNotes(notes?: string | null): string[] {
  if (!notes) return [];
  return notes
    .split(/\r?\n|•/)
    .map((line) => line.trim())
    .filter(Boolean);
}

function mapImportance(importance?: string | null): FirmwarePriority {
  switch ((importance || "").toLowerCase()) {
    case "critical":
      return "critical";
    case "high":
      return "high";
    case "low":
      return "low";
    default:
      return "medium";
  }
}

function compareVersions(a?: string | null, b?: string | null): number {
  if (!a && !b) return 0;
  if (!a) return -1;
  if (!b) return 1;
  const aParts = a
    .split(/[^0-9]+/)
    .filter(Boolean)
    .map(Number);
  const bParts = b
    .split(/[^0-9]+/)
    .filter(Boolean)
    .map(Number);
  const len = Math.max(aParts.length, bParts.length);
  for (let i = 0; i < len; i += 1) {
    const av = aParts[i] ?? 0;
    const bv = bParts[i] ?? 0;
    if (av > bv) return 1;
    if (av < bv) return -1;
  }
  return 0;
}

function estimateInstallMinutes(
  deviceType?: string | null,
  updateSize?: number | null,
): number {
  if (updateSize && updateSize > 0) {
    return Math.max(5, Math.min(45, Math.round(updateSize / 10)));
  }
  if (deviceType === "software") return 15;
  return 10;
}

