function getCompatPlatformSubscriptionPlan(
  planId: string | null | undefined,
): CompatPlatformSubscriptionPlan | null {
  if (!planId) return null;
  const normalized = normalizeBillingPlanId(planId);
  return (
    buildCompatPlatformSubscriptionPlans().find(
      (plan) => plan.id === normalized,
    ) ?? null
  );
}

function getCreatorHubPlanAmountMajor(
  plan: CompatPlatformSubscriptionPlan | null | undefined,
  billingCycle: "monthly" | "yearly",
) {
  if (!plan) {
    return 0;
  }

  if (
    billingCycle === "yearly" &&
    typeof plan.yearlyPrice === "number" &&
    Number.isFinite(plan.yearlyPrice) &&
    plan.yearlyPrice >= 0
  ) {
    return plan.yearlyPrice;
  }

  if (
    typeof plan.monthlyPrice === "number" &&
    Number.isFinite(plan.monthlyPrice) &&
    plan.monthlyPrice >= 0
  ) {
    return plan.monthlyPrice;
  }

  return plan.price;
}

function buildCompatSubscriptionStatus(
  userId: string,
  plan: CompatPlatformSubscriptionPlan | null,
  overrides?: Partial<CompatSubscriptionStatus>,
): CompatSubscriptionStatus {
  const nowIso = new Date().toISOString();
  const hasMemberSinceOverride =
    Boolean(overrides) &&
    Object.prototype.hasOwnProperty.call(overrides, "memberSince");
  const hasNextBillingOverride =
    Boolean(overrides) &&
    Object.prototype.hasOwnProperty.call(overrides, "nextBillingDate");
  const hasAccessUntilOverride =
    Boolean(overrides) &&
    Object.prototype.hasOwnProperty.call(overrides, "accessUntil");
  const memberSince = hasMemberSinceOverride
    ? (overrides?.memberSince ?? null)
    : plan
      ? nowIso
      : null;
  const nextBillingDate = hasNextBillingOverride
    ? (overrides?.nextBillingDate ?? null)
    : plan
      ? addBillingCycleIso(memberSince || nowIso, plan.billingCycle)
      : null;
  const accessUntil = hasAccessUntilOverride
    ? (overrides?.accessUntil ?? null)
    : nextBillingDate;

  return {
    selectedPlan: overrides?.selectedPlan ?? plan?.id ?? null,
    planName: overrides?.planName ?? plan?.displayName ?? null,
    amount: overrides?.amount ?? plan?.price ?? 0,
    currency: overrides?.currency ?? plan?.currency ?? "NOK",
    subscriptionSelected: overrides?.subscriptionSelected ?? Boolean(plan),
    memberSince,
    nextBillingDate,
    accessUntil,
    paymentCompleted: overrides?.paymentCompleted ?? Boolean(plan),
    transactionId: overrides?.transactionId ?? null,
    organizationNumber: overrides?.organizationNumber ?? null,
    companyName: overrides?.companyName ?? null,
    email: overrides?.email ?? null,
    autoRenew: overrides?.autoRenew ?? true,
    source: overrides?.source ?? (plan ? "compat" : "default"),
  };
}

