function normalizeEventType(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;
  return EVENDI_EVENT_TYPES.has(normalized) ? normalized : null;
}

function isValidNorwegianOrgNumber(value: string): boolean {
  if (!/^[0-9]{9}$/.test(value)) return false;
  const digits = value.split("").map((digit) => Number(digit));
  const weights = [3, 2, 7, 6, 5, 4, 3, 2];
  const sum = weights.reduce(
    (total, weight, index) => total + weight * digits[index],
    0,
  );
  const remainder = 11 - (sum % 11);
  if (remainder === 11) return digits[8] === 0;
  if (remainder === 10) return false;
  return digits[8] === remainder;
}

function resolveMimeType(fileName?: string | null): string {
  const fallback = "image/png";
  if (!fileName) return fallback;
  const ext = fileName.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "jpg":
    case "jpeg":
      return "image/jpeg";
    case "svg":
      return "image/svg+xml";
    case "webp":
      return "image/webp";
    case "gif":
      return "image/gif";
    case "png":
      return "image/png";
    default:
      return fallback;
  }
}

function normalizeBase64Upload(payload: string, fileName?: string | null) {
  const trimmed = payload.trim();
  if (trimmed.startsWith("data:")) {
    const match = trimmed.match(/^data:(.+);base64,(.+)$/);
    if (!match) {
      throw new Error("Invalid data URL");
    }
    const [, mimeType, base64Data] = match;
    const buffer = Buffer.from(base64Data, "base64");
    return { dataUrl: trimmed, size: buffer.length, mimeType };
  }

  const mimeType = resolveMimeType(fileName);
  const buffer = Buffer.from(trimmed, "base64");
  return {
    dataUrl: `data:${mimeType};base64,${trimmed}`,
    size: buffer.length,
    mimeType,
  };
}

type BusinessBrandingInfoRecord = {
  businessName?: string | null;
  email?: string | null;
  phone?: string | null;
  businessAddress?: string | null;
  organizationNumber?: string | null;
  website?: string | null;
  vatNumber?: string | null;
  tagline?: string | null;
  brandingColor?: string | null;
  customLogo?: string | null;
  businessDescription?: string | null;
  customFooterText?: string | null;
  profession?: string | null;
};

function normalizeBrandingHexColor(value: unknown): string | null {
  const raw = readString(value);
  if (!raw) return null;
  const normalized = raw.startsWith("#") ? raw.slice(1) : raw;
  if (/^[0-9a-f]{3}$/i.test(normalized)) {
    return `#${normalized
      .split("")
      .map((entry) => `${entry}${entry}`)
      .join("")
      .toLowerCase()}`;
  }
  if (/^[0-9a-f]{6}$/i.test(normalized)) {
    return `#${normalized.toLowerCase()}`;
  }
  return null;
}

function normalizeBusinessBrandingInfo(
  payload: unknown,
): BusinessBrandingInfoRecord {
  const record = normalizeJsonObjectField(payload) || {};
  return {
    businessName:
      readString(record.businessName) ||
      readString(record.companyName) ||
      readString(record.name),
    email: readString(record.email) || readString(record.contactEmail),
    phone: readString(record.phone),
    businessAddress:
      readString(record.businessAddress) || readString(record.address),
    organizationNumber:
      readString(record.organizationNumber) || readString(record.orgNumber),
    website: readString(record.website),
    vatNumber: readString(record.vatNumber) || readString(record.taxId),
    tagline: readString(record.tagline),
    brandingColor:
      normalizeBrandingHexColor(record.brandingColor) ||
      normalizeBrandingHexColor(record.brandColor) ||
      normalizeBrandingHexColor(record.primaryColor),
    customLogo:
      readString(record.customLogo) ||
      readString(record.logoUrl) ||
      readString(record.logo),
    businessDescription:
      readString(record.businessDescription) || readString(record.description),
    customFooterText:
      readString(record.customFooterText) || readString(record.footerText),
    profession: readString(record.profession),
  };
}

