// CMS public read — alle CreatorHub-flater leser herfra med
// /api/cms/content/:key?profession=…&locale=…
// Returnerer payload-JSONB. Profesjon-spesifikk override vinner over
// generisk (profession=null) hvis begge finnes.
app.get("/api/cms/content/:key", async (req, res) => {
  const key = String(req.params.key || '').trim();
  if (!key) return res.status(400).json({ error: 'key_required' });
  const profession = typeof req.query.profession === 'string' ? req.query.profession.trim() : null;
  const locale = typeof req.query.locale === 'string' ? req.query.locale.trim() : 'nb-NO';
  try {
    await ensureCmsSchema();
    // Try profession-specific first; fall back to generic.
    const result = await pool.query(
      `SELECT content_key, content_type_key, profession, locale, payload, updated_at
       FROM cms_content
       WHERE content_key = $1
         AND is_published = true
         AND locale = $2
         AND (profession = $3 OR profession IS NULL)
       ORDER BY profession NULLS LAST
       LIMIT 1`,
      [key, locale, profession],
    );
    if (result.rowCount === 0) return res.status(404).json({ error: 'not_found' });
    const row = result.rows[0];
    res.json({
      key: row.content_key,
      contentType: row.content_type_key,
      profession: row.profession,
      locale: row.locale,
      payload: row.payload ?? {},
      updatedAt: row.updated_at,
    });
  } catch (err) {
    console.error('[cms] content fetch failed:', err);
    res.status(500).json({
      error: 'fetch_failed',
      detail: err instanceof Error ? err.message : String(err),
    });
  }
});

// CMS write (admin) — upsert by (content_key, profession, locale)
app.put("/api/cms/content/:key", async (req, res) => {
  const session = requireUserSession(req, res);
  if (!session) return;
  const key = String(req.params.key || '').trim();
  if (!key) return res.status(400).json({ error: 'key_required' });
  const { contentType, profession, locale, payload, isPublished } = req.body ?? {};
  try {
    await ensureCmsSchema();
    await pool.query(
      `INSERT INTO cms_content (content_key, content_type_key, profession, locale, payload, is_published, created_by, updated_by)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $7)
       ON CONFLICT (content_key, COALESCE(profession, ''), COALESCE(locale, 'nb-NO')) DO UPDATE SET
         content_type_key = EXCLUDED.content_type_key,
         payload = EXCLUDED.payload,
         is_published = EXCLUDED.is_published,
         updated_by = EXCLUDED.updated_by,
         updated_at = NOW()`,
      [key, contentType ?? null, profession ?? null, locale ?? 'nb-NO', JSON.stringify(payload ?? {}), isPublished !== false, session.userId],
    );
    res.json({ success: true });
  } catch (err) {
    console.error('[cms] content upsert failed:', err);
    res.status(500).json({
      error: 'upsert_failed',
      detail: err instanceof Error ? err.message : String(err),
    });
  }
});

// Analytics events foundation — unified ecosystem-wide event log.
// Every important user-facing action (gallery created, payment
// succeeded, project status change, photo enhancer batch pushed) skal
// skrive en rad her. BI-dashboardet og cross-system aggregations leser
// fra analytics_events istedenfor å forene siloer per query.
//
// Schema lever i 125_analytics_events.sql; vi sikrer at tabellen
// finnes ved oppstart slik at recordAnalyticsEvent aldri trenger å
// håndtere "table doesn't exist"-feil.
let analyticsEventsSchemaReady: Promise<void> | null = null;
function ensureAnalyticsEventsSchema(): Promise<void> {
  if (!analyticsEventsSchemaReady) {
    analyticsEventsSchemaReady = (async () => {
      try {
        await pool.query(`
          CREATE TABLE IF NOT EXISTS analytics_events (
            id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
            event_type VARCHAR(64) NOT NULL,
            entity_type VARCHAR(32),
            entity_id VARCHAR(64),
            actor_user_id VARCHAR(64),
            metadata JSONB DEFAULT '{}'::jsonb,
            created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
          );
          CREATE INDEX IF NOT EXISTS analytics_events_created_at_idx
            ON analytics_events (created_at DESC);
          CREATE INDEX IF NOT EXISTS analytics_events_entity_idx
            ON analytics_events (entity_type, entity_id, created_at DESC);
          CREATE INDEX IF NOT EXISTS analytics_events_actor_idx
            ON analytics_events (actor_user_id, created_at DESC);
          CREATE INDEX IF NOT EXISTS analytics_events_type_idx
            ON analytics_events (event_type, created_at DESC);
        `);
      } catch (err) {
        console.warn('[analytics-events] schema-ensure failed:', err);
        // Reset så neste call retry'er
        analyticsEventsSchemaReady = null;
        throw err;
      }
    })();
  }
  return analyticsEventsSchemaReady;
}

interface AnalyticsEventOptions {
  entityType?: string;
  entityId?: string;
  actorUserId?: string | null;
  metadata?: Record<string, unknown>;
}

/// Fire-and-forget. Call uten await — feil logges men aldri kastet,
/// så event-recording kan ikke knekke produksjons-endpoints.
function recordAnalyticsEvent(eventType: string, opts: AnalyticsEventOptions = {}): void {
  void (async () => {
    try {
      await ensureAnalyticsEventsSchema();
      await pool.query(
        `INSERT INTO analytics_events (event_type, entity_type, entity_id, actor_user_id, metadata)
         VALUES ($1, $2, $3, $4, $5)`,
        [
          eventType,
          opts.entityType ?? null,
          opts.entityId ?? null,
          opts.actorUserId ?? null,
          opts.metadata ?? {},
        ],
      );
    } catch (err) {
      console.warn(`[analytics-events] record ${eventType} failed:`, err);
    }
  })();
}

function buildGalleryShareUrl(accessToken: string): string {
  const host = (process.env.CREATORHUB_PUBLIC_URL ?? 'https://app.creatorhubn.com').replace(/\/$/, '');
  return `${host}/client/gallery/${accessToken}`;
}

// ── Slice 9 — checkout flow ────────────────────────────────────────────
// Two routes the gallery viewer has been calling for months without a
// server-side implementation: calculate-pricing and submit-selection.
// The pricing math is deliberately re-run server-side at every step
// (calculate-pricing AND submit-selection) so a malicious client can't
// just edit the totalAmount they POST. Stripe checkout (Slice 10) hooks
// in via the requiresPayment flag the submit endpoint returns.

interface GalleryPricing {
  selectedCount: number;
  includedImages: number;  // how many fit within contracted bucket
  extraImages: number;     // how many require extra payment
  pricePerImage: number;
  currency: string;
  totalAmount: number;     // extraImages × pricePerImage, rounded to 2 dp
}

/// Pure function — same gallery + same selectedImageIds always
/// produce identical pricing. No DB calls. Caller owns the gallery
/// fetch + ownership gate.
function calculateGalleryPricing(
  gallerySettings: Record<string, unknown> | null | undefined,
  selectedCount: number,
): GalleryPricing {
  const settings = (gallerySettings ?? {}) as Record<string, unknown>;
  const contractedImages = Math.max(0, Number(settings.contractedImages) || 0);
  const pricePerImage = Math.max(0, Number(settings.pricePerImage) || 0);
  const currency = typeof settings.currency === 'string' && settings.currency
    ? settings.currency
    : 'NOK';
  const sel = Math.max(0, Math.floor(selectedCount));
  const includedImages = Math.min(sel, contractedImages);
  const extraImages = Math.max(0, sel - contractedImages);
  const totalAmount = Math.round(extraImages * pricePerImage * 100) / 100;
  return {
    selectedCount: sel,
    includedImages,
    extraImages,
    pricePerImage,
    currency,
    totalAmount,
  };
}

/// gallerySettings lives on photographer_client_galleries.gallery_settings
/// as JSONB. Helper keeps the cast in one place + handles missing rows.
async function fetchGalleryWithSettingsByToken(
  accessToken: string,
): Promise<{ id: string; clientEmail: string; settings: Record<string, unknown> } | null> {
  const rows = await pool.query(
    `SELECT id, client_email, gallery_settings, status
     FROM photographer_client_galleries
     WHERE access_token = $1
     LIMIT 1`,
    [accessToken],
  );
  const row = rows.rows[0];
  if (!row) return null;
  if (row.status && row.status !== 'active') return null;
  return {
    id: row.id,
    clientEmail: row.client_email ?? '',
    settings: (row.gallery_settings ?? {}) as Record<string, unknown>,
  };
}

// Slice 9.4 — access-gate helper. Wraps fetchGallery + expiration +
// password checks so every client-gallery route gets identical treatment.
// Returns the gallery on success; on failure, an HTTP-shaped error with
// `requiresPassword: true` when the caller needs to prompt + retry.
//
// Password is sent as the `x-gallery-password` header — stateless
// design keeps things simple (no cookies, no JWTs, no separate
// auth-state table). The trade-off is that a determined attacker who
// already has the access token can probably also socially-engineer
// the password; this gate is "raise the bar against accidental
// access", not airtight security.
type GalleryAccessResult =
  | { ok: true; gallery: { id: string; clientEmail: string; settings: Record<string, unknown> }; settings: Record<string, unknown> }
  | { ok: false; status: number; error: string; requiresPassword?: boolean };

async function gateGalleryAccess(
  accessToken: string,
  providedPassword: string | null,
): Promise<GalleryAccessResult> {
  const gallery = await fetchGalleryWithSettingsByToken(accessToken);
  if (!gallery) return { ok: false, status: 404, error: 'not_found' };
  const settings = gallery.settings;

  // Expiration: gallery_settings.expiresAt is an ISO string when set.
  // Past expiration → 410 Gone (semantically "this resource WAS here
  // but isn't any more" — clearer than 404 which conflates with
  // wrong-token).
  const expiresAtRaw = settings.expiresAt;
  if (typeof expiresAtRaw === 'string' && expiresAtRaw.trim()) {
    const expiresAt = new Date(expiresAtRaw);
    if (Number.isFinite(expiresAt.getTime()) && expiresAt.getTime() < Date.now()) {
      return { ok: false, status: 410, error: 'gallery_expired' };
    }
  }

  // Password: only enforced when BOTH `requiresPassword` is truthy and
  // a hash is actually stored. A misconfigured row with requiresPassword
  // but no hash falls back to "no password" rather than being permanently
  // unreachable — defensive against admin UI bugs.
  const requiresPassword = settings.requiresPassword === true;
  const passwordHash = typeof settings.passwordHash === 'string' ? settings.passwordHash : null;
  if (requiresPassword && passwordHash) {
    if (!providedPassword) {
      return { ok: false, status: 401, error: 'password_required', requiresPassword: true };
    }
    const bcrypt = await import('bcrypt');
    const passwordOk = await bcrypt.default.compare(providedPassword, passwordHash);
    if (!passwordOk) {
      return { ok: false, status: 401, error: 'password_invalid', requiresPassword: true };
    }
  }

  return { ok: true, gallery, settings };
}

function readGalleryPasswordHeader(req: import('express').Request): string | null {
  const raw = req.header('x-gallery-password');
  if (!raw) return null;
  const trimmed = raw.trim();
  return trimmed.length === 0 ? null : trimmed;
}

app.post("/api/client/gallery/:accessToken/calculate-pricing", async (req, res) => {
  const accessToken = String(req.params.accessToken || "").trim();
  if (!accessToken) return res.status(400).json({ error: "missing_access_token" });
  const selectedImageIds = Array.isArray(req.body?.selectedImageIds)
    ? req.body.selectedImageIds.filter((s: unknown): s is string => typeof s === 'string')
    : null;
  if (!selectedImageIds) {
    return res.status(400).json({ error: "selectedImageIds_required" });
  }
  try {
    const access = await gateGalleryAccess(accessToken, readGalleryPasswordHeader(req));
    if (!access.ok) {
      return res.status(access.status).json({
        error: access.error,
        ...(access.requiresPassword ? { requiresPassword: true } : {}),
      });
    }
    const pricing = calculateGalleryPricing(access.settings, selectedImageIds.length);
    res.json({ pricing });
  } catch (error) {
    console.error("[client-gallery] calculate-pricing failed", error);
    res.status(500).json({ error: "calculate_pricing_failed" });
  }
});

app.post("/api/client/gallery/:accessToken/submit-selection", async (req, res) => {
  const accessToken = String(req.params.accessToken || "").trim();
  if (!accessToken) return res.status(400).json({ error: "missing_access_token" });
  const clientEmail = typeof req.body?.clientEmail === 'string' ? req.body.clientEmail.trim() : '';
  const selectedImageIds = Array.isArray(req.body?.selectedImageIds)
    ? req.body.selectedImageIds.filter((s: unknown): s is string => typeof s === 'string')
    : null;
  if (!selectedImageIds || selectedImageIds.length === 0) {
    return res.status(400).json({ error: "selectedImageIds_required" });
  }
  try {
    const access = await gateGalleryAccess(accessToken, readGalleryPasswordHeader(req));
    if (!access.ok) {
      return res.status(access.status).json({
        error: access.error,
        ...(access.requiresPassword ? { requiresPassword: true } : {}),
      });
    }
    const gallery = access.gallery;
    const effectiveEmail = clientEmail || gallery.clientEmail;
    if (!effectiveEmail) return res.status(400).json({ error: "client_email_required" });

    // Re-derive pricing server-side — never trust client-supplied total.
    const pricing = calculateGalleryPricing(access.settings, selectedImageIds.length);

    // Persist selections in one batch. Replace any stale 'selected' rows
    // for this client by setting them to 'rejected' first, then upserting
    // the chosen ids as 'selected'. Future Slice 10 download/checkout
    // gating reads from these rows.
    await pool.query('BEGIN');
    try {
      // Demote any 'selected' rows for this client+gallery that aren't
      // in the new selection list (they got unticked).
      await pool.query(
        `UPDATE client_image_selections
         SET selection_type = 'rejected', updated_at = NOW()
         WHERE gallery_id = $1
           AND client_email = $2
           AND selection_type = 'selected'
           AND NOT (image_id = ANY($3::uuid[]))`,
        [gallery.id, effectiveEmail, selectedImageIds],
      );
      // Upsert the new selection set.
      for (const imageId of selectedImageIds) {
        await pool.query(
          `INSERT INTO client_image_selections
             (gallery_id, image_id, client_email, selection_type, created_at, updated_at)
           VALUES ($1, $2, $3, 'selected', NOW(), NOW())
           ON CONFLICT (gallery_id, image_id, client_email)
           DO UPDATE SET selection_type = 'selected', updated_at = NOW()`,
          [gallery.id, imageId, effectiveEmail],
        );
      }
      await pool.query('COMMIT');
    } catch (err) {
      await pool.query('ROLLBACK');
      throw err;
    }

    res.json({
      ok: true,
      pricing,
      requiresPayment: pricing.totalAmount > 0,
      // Stripe payment intent comes from Slice 10's create-payment-intent
      // route — surfaced as a separate call so that endpoint owns the
      // Stripe API call + idempotency key handling.
    });

    // Slice 9.6 — fire-and-forget photographer notification with the
    // pricing snapshot baked into the email so Daniel knows whether
    // checkout still needs to happen. Same fire-and-forget posture as
    // the comment dispatcher — never blocks the client's POST.
    setImmediate(async () => {
      try {
        const photographerRow = await pool.query(
          `SELECT photographer_id, project_title, client_name, client_email
           FROM photographer_client_galleries WHERE id = $1 LIMIT 1`,
          [gallery.id],
        );
        const row = photographerRow.rows[0];
        if (!row?.photographer_id) return;
        void dispatchGalleryNotification('selection_submitted', row.photographer_id, {
          galleryId: gallery.id,
          galleryTitle: row.project_title ?? null,
          shareUrl: buildGalleryShareUrl(accessToken),
          clientName: row.client_name || effectiveEmail.split('@')[0] || 'Klient',
          clientEmail: effectiveEmail,
          details: {
            selectedCount: selectedImageIds.length,
            totalAmount: pricing.totalAmount,
            currency: pricing.currency,
            requiresPayment: pricing.totalAmount > 0,
          },
        });
      } catch (err) {
        console.warn('[gallery-notify] selection_submitted dispatch failed:', err);
      }
    });
    recordAnalyticsEvent('selection.submitted', {
      entityType: 'gallery',
      entityId: gallery.id,
      actorUserId: null,
      metadata: {
        selectedCount: selectedImageIds.length,
        totalAmount: pricing.totalAmount,
        currency: pricing.currency,
        requiresPayment: pricing.totalAmount > 0,
        clientEmail: effectiveEmail,
      },
    });
  } catch (error) {
    console.error("[client-gallery] submit-selection failed", error);
    res.status(500).json({ error: "submit_selection_failed" });
  }
});

// Slice 9.3 — bulk download. Streams a ZIP of selected images from R2
// straight into the response so we never buffer the full archive in
// memory. Auto-cleaned variants are preferred when the gallery row
// opted in (mirrors the viewer's display semantics). Watermark mode
// honoured. Payment-gated for galleries with extras (Slice 10 wires
// the actual gate; v1 just refuses unpaid extras with a clear error).
//
// Body: { imageIds: string[], clientEmail?: string }
// Returns: streamed ZIP, or 4xx on validation failures.
app.post("/api/client/gallery/:accessToken/download-zip", async (req, res) => {
  const accessToken = String(req.params.accessToken || "").trim();
  if (!accessToken) return res.status(400).json({ error: "missing_access_token" });
  const imageIds = Array.isArray(req.body?.imageIds)
    ? req.body.imageIds.filter((s: unknown): s is string => typeof s === 'string')
    : null;
  if (!imageIds || imageIds.length === 0) {
    return res.status(400).json({ error: "imageIds_required" });
  }
  if (imageIds.length > 1000) {
    // Defence-in-depth: huge zips are slow + Render request timeouts
    // hit. Photographers will rarely deliver more than a few hundred.
    return res.status(413).json({ error: "too_many_images", max: 1000 });
  }

  try {
    const access = await gateGalleryAccess(accessToken, readGalleryPasswordHeader(req));
    if (!access.ok) {
      return res.status(access.status).json({
        error: access.error,
        ...(access.requiresPassword ? { requiresPassword: true } : {}),
      });
    }
    const gallery = access.gallery;
    const settings = access.settings;
    if (settings.allowDownload === false) {
      return res.status(403).json({ error: "download_disabled" });
    }

    // Slice 10 will gate this on payment status. For now: refuse zip
    // download when the photographer's pricing model has extras and
    // the client hasn't paid yet — better than silently letting them
    // skip the checkout.
    const clientEmail = typeof req.body?.clientEmail === 'string'
      ? req.body.clientEmail.trim()
      : gallery.clientEmail;
    const pricing = calculateGalleryPricing(settings, imageIds.length);
    if (pricing.totalAmount > 0) {
      const paid = await pool.query(
        `SELECT 1 FROM client_image_payments
         WHERE gallery_id = $1
           AND client_email = $2
           AND payment_status = 'succeeded'
         LIMIT 1`,
        [gallery.id, clientEmail],
      );
      if (paid.rowCount === 0) {
        return res.status(402).json({
          error: "payment_required",
          pricing,
        });
      }
    }

    // Resolve image URLs the same way listClientGalleryImages does so
    // the zip contents match what the viewer is showing. This re-signs
    // each capture-sourced image's R2 key fresh — the caller doesn't
    // need to pre-pass URLs (which could go stale anyway).
    const allImages = await listClientGalleryImages(db, gallery.id);
    const idSet = new Set(imageIds);
    const picked = allImages.filter((img) => idSet.has(img.id));
    if (picked.length === 0) {
      return res.status(404).json({ error: "no_matching_images" });
    }
    const watermarked = settings.watermarkEnabled === true;

    const zipFilename = `gallery-${gallery.id.slice(0, 8)}-${Date.now()}.zip`;
    res.setHeader('Content-Type', 'application/zip');
    res.setHeader('Content-Disposition', `attachment; filename="${zipFilename}"`);

    const archive = archiverFactory('zip', { zlib: { level: 6 } });
    archive.on('warning', (err: Error & { code?: string }) => {
      if (err.code !== 'ENOENT') console.warn('[client-gallery] zip warning:', err);
    });
    archive.on('error', (err: Error) => {
      console.error('[client-gallery] zip error:', err);
      try { res.status(500).end(); } catch {}
    });
    archive.pipe(res);

    // Pull each image as a node-fetch stream and append. archiver
    // handles back-pressure so we only buffer one in flight at a
    // time (the connection drives consumption).
    let appended = 0;
    for (const img of picked) {
      const sourceUrl = watermarked && img.watermarkedUrl
        ? img.watermarkedUrl
        : (img.autoCleanedUrl ?? img.fullSizeUrl);
      try {
        const fetchRes = await fetch(sourceUrl);
        if (!fetchRes.ok || !fetchRes.body) {
          console.warn(`[client-gallery] zip skip ${img.id}: ${fetchRes.status}`);
          continue;
        }
        // node-fetch v3 returns a web ReadableStream; archiver wants a
        // Node Readable. The Node-native fetch gives us .body as a
        // web stream too — convert via Readable.fromWeb.
        const { Readable } = await import('node:stream');
        const nodeStream = Readable.fromWeb(fetchRes.body as never);
        const safeName = `${img.imageTitle.replace(/[\\/:*?"<>|]/g, '_')}.jpg`;
        archive.append(nodeStream, { name: safeName });
        appended++;
      } catch (err) {
        console.warn(`[client-gallery] zip fetch failed ${img.id}:`, err);
      }
    }

    if (appended === 0) {
      // We declared application/zip headers already; finalize an empty
      // archive rather than swap to JSON (which would confuse the client).
      console.warn(`[client-gallery] zip download produced 0 entries for gallery ${gallery.id}`);
    }
    await archive.finalize();
  } catch (error) {
    console.error("[client-gallery] download-zip failed", error);
    if (!res.headersSent) {
      res.status(500).json({ error: "download_zip_failed" });
    } else {
      try { res.end(); } catch {}
    }
  }
});

// Health check. Caches the ffmpeg probe for 60s so rapid pings from
// Render's health checker don't spawn an ffmpeg child every time.
let ffmpegHealthCache: { at: number; available: boolean; version: string | null } | null = null;

async function readFfmpegHealth(): Promise<{ available: boolean; version: string | null }> {
  const now = Date.now();
  if (ffmpegHealthCache && now - ffmpegHealthCache.at < 60_000) {
    return { available: ffmpegHealthCache.available, version: ffmpegHealthCache.version };
  }
  const version = await ffmpegVersionLine();
  ffmpegHealthCache = { at: now, available: Boolean(version), version };
  return { available: Boolean(version), version };
}

app.get("/api/health", async (req, res) => {
  const isRenderRuntime =
    String(process.env.RENDER || "").toLowerCase() === "true";
  const ffmpeg = await readFfmpegHealth();
  res.json({
    status: "ok",
    timestamp: new Date().toISOString(),
    startedAt: serverStartedAt,
    commit: process.env.RENDER_GIT_COMMIT || null,
    branch: process.env.RENDER_GIT_BRANCH || null,
    serviceId: process.env.RENDER_SERVICE_ID || null,
    serviceName: process.env.RENDER_SERVICE_NAME || null,
    instanceId: process.env.RENDER_INSTANCE_ID || null,
    runtime: isRenderRuntime ? "render" : process.env.NODE_ENV || "unknown",
    // Surfaces on Render's status-page poll so we can see at a glance
    // whether the reel normaliser has a usable ffmpeg binary on this
    // instance. Without it reels still ship, but unchanged — the
    // photographer sees any quality/size issues Meta flags.
    ffmpeg,
  });
});

// Auth endpoints - session-based login

// POST /api/auth/login — Email/password login
app.post("/api/auth/login", async (req, res) => {
  try {
    const { email, password } = req.body;
    const loginType =
      typeof req.body?.type === "string"
        ? req.body.type.toLowerCase()
        : "general";
    const loginAs =
      typeof req.body?.loginAs === "string"
        ? req.body.loginAs.toLowerCase().trim()
        : "";
    const requestedRole =
      typeof req.body?.role === "string"
        ? req.body.role.toLowerCase().trim()
        : "";
    const isRoleRoomLogin =
      loginAs === "production_team" || loginAs === "content_producer";
    const isProductionEnv = process.env.NODE_ENV === "production";
    const roleRoomGuestPassword =
      process.env.ROLE_ROOM_GUEST_PASSWORD ||
      process.env.PROTOTYPE_GUEST_PASSWORD ||
      "guest-access";
    const prototypeGuestPassword =
      process.env.PROTOTYPE_GUEST_PASSWORD || "guest-access";
    if (!email) return res.status(400).json({ error: "E-post er påkrevd" });
    const normalizedEmail = email.toLowerCase().trim();
    const prototypeGuestEmails = new Set(
      String(
        process.env.PROTOTYPE_GUEST_EMAILS ||
          (!isProductionEnv ? "academy-guest@creatorhubn.com" : ""),
      )
        .split(",")
        .map((entry) => entry.trim().toLowerCase())
        .filter(Boolean),
    );
    const canUseGeneralGuestPassword =
      prototypeGuestEmails.has(normalizedEmail) &&
      (password === "auto" || password === "" || password == null);
    const effectivePassword = canUseGeneralGuestPassword
      ? prototypeGuestPassword
      : password;
    const commercialRoleRoomLogin = isRoleRoomCommercialLoginIntent({
      loginAs,
      requestedRole,
    });

    if (commercialRoleRoomLogin) {
      const accessGate = await getRoleRoomCommercialLoginGate({
        email: normalizedEmail,
        loginAs,
        requestedRole,
      });
      if (!accessGate.allowed) {
        return res.status(403).json({ error: accessGate.reason });
      }
    }

    // Local environments are not guaranteed to have every optional users column.
    const userColumns = await getTableColumns("users");
    const userSelectColumns = [
      "id",
      "email",
      userColumns.has("username") ? "username" : "NULL::text AS username",
      userColumns.has("first_name") ? "first_name" : "NULL::text AS first_name",
      userColumns.has("last_name") ? "last_name" : "NULL::text AS last_name",
      userColumns.has("password") ? "password" : "NULL::text AS password",
      userColumns.has("role") ? "role" : "NULL::text AS role",
      userColumns.has("profession") ? "profession" : "NULL::text AS profession",
      userColumns.has("company_name") ? "company_name" : "NULL::text AS company_name",
    ];

    // Look up user by email
    let result = await pool.query(
      `SELECT ${userSelectColumns.join(", ")} FROM users WHERE email = $1`,
      [normalizedEmail],
    );

    if (
      (!result.rowCount || result.rowCount === 0) &&
      isRoleRoomLogin &&
      !isProductionEnv
    ) {
      const bcrypt = await import("bcrypt");
      const safePassword =
        typeof password === "string" && password.trim().length > 0
          ? password
          : roleRoomGuestPassword;
      const hashedPassword = await bcrypt.default.hash(safePassword, 10);
      const inferredFirstName =
        normalizedEmail.split("@")[0]?.slice(0, 64) || "Role Room";
      const inferredUsername =
        normalizedEmail
          .split("@")[0]
          ?.toLowerCase()
          .replace(/[^a-z0-9._-]/g, "-")
          .replace(/-+/g, "-")
          .replace(/^-|-$/g, "")
          .slice(0, 64) || `role-room-${Date.now()}`;

      result = await pool.query(
        `INSERT INTO users (email, username, first_name, role, password, created_at, updated_at)
         VALUES ($1, $2, $3, 'user', $4, NOW(), NOW())
         ON CONFLICT (email) DO UPDATE
         SET password = COALESCE(NULLIF(users.password, ''), EXCLUDED.password),
             username = COALESCE(NULLIF(users.username, ''), EXCLUDED.username),
             first_name = COALESCE(NULLIF(users.first_name, ''), EXCLUDED.first_name),
             updated_at = NOW()
         RETURNING ${userSelectColumns.join(", ")}`,
        [normalizedEmail, inferredUsername, inferredFirstName, hashedPassword],
      );
    }

    if (!result.rowCount || result.rowCount === 0) {
      return res.status(401).json({ error: "Ugyldig e-post eller passord" });
    }

    const dbUser = result.rows[0];
    const storedPassword =
      typeof dbUser.password === "string" ? dbUser.password : "";

    if (storedPassword) {
      const bcrypt = await import("bcrypt");
      const isPasswordHashed = /^\$2[ayb]\$/.test(storedPassword);
      const passwordValid = isPasswordHashed
        ? await bcrypt.default.compare(effectivePassword || "", storedPassword)
        : effectivePassword === storedPassword;

      if (!passwordValid) {
        return res.status(401).json({ error: "Ugyldig e-post eller passord" });
      }
    } else {
      const canUsePrototypeFallback =
        (loginType === "prototype" || canUseGeneralGuestPassword) &&
        prototypeGuestEmails.has(dbUser.email);
      const canUseRoleRoomFallback = isRoleRoomLogin && !isProductionEnv;
      const roleRoomPasswordValid =
        canUseRoleRoomFallback && effectivePassword === roleRoomGuestPassword;
      if (
        (!canUsePrototypeFallback ||
          effectivePassword !== prototypeGuestPassword) &&
        !roleRoomPasswordValid
      ) {
        return res.status(401).json({ error: "Ugyldig e-post eller passord" });
      }
      if (roleRoomPasswordValid) {
        const bcrypt = await import("bcrypt");
        const hashedPassword = await bcrypt.default.hash(
          roleRoomGuestPassword,
          10,
        );
        await pool
          .query(
            `UPDATE users
           SET password = $2, updated_at = NOW()
           WHERE id = $1 AND (password IS NULL OR password = '')`,
            [dbUser.id, hashedPassword],
          )
          .catch(() => undefined);
      }
    }

    // Determine role
    const dbRole = String(dbUser.role || "").trim().toLowerCase();
    let role =
      dbRole === "super_admin"
        ? "admin"
        : adminRoleCatalogById.has(dbRole)
          ? dbRole
          : "user";
    if (loginType === "prototype") {
      if (
        dbRole === "prototype_tester" ||
        prototypeGuestEmails.has(dbUser.email)
      ) {
        role = "prototype_tester";
      } else {
        return res
          .status(403)
          .json({ error: "Prototype tester-tilgang krever godkjenning" });
      }
    }

    // Check couple_profiles
    const coupleCheck = await pool
      .query(
        "SELECT id, display_name FROM couple_profiles WHERE email = $1 LIMIT 1",
        [dbUser.email],
      )
      .catch(() => ({ rows: [], rowCount: 0 }));

    if (loginType !== "prototype" && coupleCheck.rows.length > 0)
      role = "couple";

    // Check vendors table
    const vendorCheck = await pool
      .query("SELECT id, business_name FROM vendors WHERE email = $1 LIMIT 1", [
        dbUser.email,
      ])
      .catch(() => ({ rows: [], rowCount: 0 }));

    if (loginType !== "prototype" && vendorCheck.rows.length > 0)
      role = "vendor";

    // Create session token
    const sessionToken = crypto.randomUUID();
    const name =
      [dbUser.first_name, dbUser.last_name].filter(Boolean).join(" ") ||
      dbUser.username;

    const normalizedRequestedRole = requestedRole || null;
    const roleRoomSessionRole = isRoleRoomLogin
      ? loginAs === "content_producer"
        ? normalizedRequestedRole === "client" ||
          normalizedRequestedRole === "client_reviewer"
          ? "client_reviewer"
          : "content_producer"
        : normalizedRequestedRole || role
      : role;

    const normalizedSessionRole = normalizeAdminRoleId(roleRoomSessionRole);
    const sessionRoleEntry = buildAdminRoleEntry(normalizedSessionRole);
    const sessionProfession = normalizeAdminProfession(
      dbUser.profession,
      normalizedSessionRole,
    );
    const sessionData: ActiveSessionData = {
      userId: dbUser.id,
      email: dbUser.email,
      name,
      role: normalizedSessionRole,
      roleLabel: sessionRoleEntry.name,
      permissions: sessionRoleEntry.permissions,
      profession: sessionProfession || undefined,
      userType: sessionProfession || undefined,
      displayName: name,
      isAdmin: ADMIN_SESSION_ROLES.has(normalizedSessionRole),
      loginAs: loginAs || undefined,
      requestedRole: normalizedRequestedRole,
      loginAt: new Date().toISOString(),
    };
    if (role === "vendor" && vendorCheck.rows.length > 0) {
      sessionData.vendorId = vendorCheck.rows[0].id;
      sessionData.businessName = vendorCheck.rows[0].business_name;
    }
    if (role === "couple" && coupleCheck.rows.length > 0) {
      sessionData.coupleProfileId = coupleCheck.rows[0].id;
      sessionData.displayName =
        coupleCheck.rows[0].display_name || sessionData.displayName;
    }
    activeSessions.set(sessionToken, sessionData);
    await persistAuthSession(pool, sessionToken, sessionData);

    console.log(
      `[Auth] Login: ${dbUser.email} as ${roleRoomSessionRole} (session: ${sessionToken.substring(0, 8)}...)`,
    );

    res.json({
      success: true,
      token: sessionToken,
      user: {
        id: dbUser.id,
        email: dbUser.email,
        name,
        role: normalizedSessionRole,
        roleLabel: sessionRoleEntry.name,
        profession: sessionProfession || undefined,
        userType: sessionProfession || undefined,
        permissions: sessionRoleEntry.permissions,
        isAdmin: ADMIN_SESSION_ROLES.has(normalizedSessionRole),
        ...(isRoleRoomLogin
          ? {
              requestedRole: normalizedRequestedRole,
              loginAs,
            }
          : {}),
        ...(role === "vendor" && vendorCheck.rows.length > 0
          ? {
              vendorId: vendorCheck.rows[0].id,
              businessName: vendorCheck.rows[0].business_name,
            }
          : {}),
        ...(role === "couple" && coupleCheck.rows.length > 0
          ? {
              coupleProfileId: coupleCheck.rows[0].id,
              displayName: coupleCheck.rows[0].display_name,
            }
          : {}),
      },
    });
  } catch (error) {
    console.error("Login error:", error);
    res.status(500).json({ error: "Innlogging feilet" });
  }
});

// POST /api/couples/login — Couple login (compatible with deployed Evendi API)
app.post("/api/couples/login", async (req, res) => {
  try {
    const { email, password } = req.body;
    if (!email) return res.status(400).json({ error: "E-post er påkrevd" });

    console.log(`[CoupleLogin] Login attempt for email: ${email}`);

    // Look up couple profile
    const coupleResult = await pool.query(
      "SELECT id, email, display_name, password, partner_email, wedding_date FROM couple_profiles WHERE email = $1 LIMIT 1",
      [email.toLowerCase().trim()],
    );

    if (!coupleResult.rowCount || coupleResult.rowCount === 0) {
      console.log(`[CoupleLogin] Lookup result: Not found`);
      return res.status(401).json({ error: "Ugyldig e-post eller passord" });
    }

    const couple = coupleResult.rows[0];
    console.log(`[CoupleLogin] Lookup result: Found`);

    // Verify password with bcrypt if hashed, or plain comparison
    if (couple.password) {
      const bcrypt = await import("bcrypt");
      const isPasswordHashed = /^\$2[ayb]\$/.test(couple.password);
      let passwordValid = false;

      if (isPasswordHashed) {
        passwordValid = await bcrypt.default.compare(
          password || "",
          couple.password,
        );
      } else {
        passwordValid = password === couple.password;
      }

      if (!passwordValid) {
        return res.status(401).json({ error: "Ugyldig e-post eller passord" });
      }
    }

    // Also look up in users table
    const userResult = await pool
      .query("SELECT id FROM users WHERE email = $1 LIMIT 1", [
        email.toLowerCase().trim(),
      ])
      .catch(() => ({ rows: [] }));

    const userId = userResult.rows[0]?.id || couple.id;

    // Create session
    const sessionToken = crypto.randomUUID();
    const coupleRoleEntry = buildAdminRoleEntry("couple");
    const sessionData: ActiveSessionData = {
      userId,
      email: couple.email,
      name: couple.display_name || email,
      role: "couple" as const,
      roleLabel: coupleRoleEntry.name,
      permissions: coupleRoleEntry.permissions,
      profession: "couple",
      userType: "couple",
      displayName: couple.display_name || email,
      coupleProfileId: couple.id,
      loginAt: new Date().toISOString(),
    };
    activeSessions.set(sessionToken, sessionData);
    await persistAuthSession(pool, sessionToken, sessionData);

    console.log(
      `[CoupleLogin] Success: ${couple.email} (session: ${sessionToken.substring(0, 8)}...)`,
    );

    res.json({
      success: true,
      token: sessionToken,
      user: {
        id: userId,
        email: couple.email,
        name: couple.display_name || email,
        role: "couple",
        coupleProfileId: couple.id,
        displayName: couple.display_name,
        partnerEmail: couple.partner_email,
        weddingDate: couple.wedding_date,
      },
    });
  } catch (error) {
    console.error("[CoupleLogin] Error:", error);
    res.status(500).json({ error: "Innlogging feilet" });
  }
});

