app.post("/api/user/payment-methods", async (req, res) => {
  try {
    const userId = compatResolveUserId(req);
    const body = isRecord(req.body) ? req.body : {};
    const paymentType =
      readString(body.paymentType) || readString(body.payment_type) || "card";
    const lastFour = readString(body.lastFour) || readString(body.last_four);
    const expiryMonth =
      readNumber(body.expiryMonth) || readNumber(body.expiry_month);
    const expiryYear =
      readNumber(body.expiryYear) || readNumber(body.expiry_year);
    const shouldBeDefault =
      readBoolean(body.isDefault ?? body.is_default) ?? false;
    const existing = await readCompatPaymentMethods(userId);
    const nowIso = new Date().toISOString();

    const createdMethod: CompatPaymentMethod = {
      id: crypto.randomUUID(),
      payment_type: paymentType,
      last_four: lastFour,
      expiry_month: expiryMonth,
      expiry_year: expiryYear,
      is_default: shouldBeDefault || existing.length === 0,
      created_at: nowIso,
      updated_at: nowIso,
    };

    const nextMethods = existing.map((method) => ({
      ...method,
      is_default: createdMethod.is_default ? false : method.is_default,
    }));
    nextMethods.push(createdMethod);
    await writeCompatPaymentMethods(userId, nextMethods);

    res
      .status(201)
      .json({ paymentMethod: createdMethod, paymentMethods: nextMethods });
  } catch (error) {
    console.error("Error creating payment method:", error);
    res.status(500).json({ error: "Could not create payment method" });
  }
});

app.put("/api/user/payment-methods/:id", async (req, res) => {
  try {
    const userId = compatResolveUserId(req);
    const methodId = readString(req.params.id);
    if (!methodId) {
      return res.status(400).json({ error: "Payment method id is required" });
    }

    const body = isRecord(req.body) ? req.body : {};
    const markDefault = readBoolean(body.isDefault ?? body.is_default);
    const methods = await readCompatPaymentMethods(userId);
    const exists = methods.some((method) => method.id === methodId);
    if (!exists) {
      return res.status(404).json({ error: "Payment method not found" });
    }

    const nextMethods = methods.map((method) => {
      if (method.id !== methodId) {
        return markDefault ? { ...method, is_default: false } : method;
      }
      return {
        ...method,
        is_default: markDefault ?? method.is_default,
        updated_at: new Date().toISOString(),
      };
    });

    await writeCompatPaymentMethods(userId, nextMethods);
    res.json({
      paymentMethod:
        nextMethods.find((method) => method.id === methodId) ?? null,
      paymentMethods: nextMethods,
    });
  } catch (error) {
    console.error("Error updating payment method:", error);
    res.status(500).json({ error: "Could not update payment method" });
  }
});

app.delete("/api/user/payment-methods/:id", async (req, res) => {
  try {
    const userId = compatResolveUserId(req);
    const methodId = readString(req.params.id);
    if (!methodId) {
      return res.status(400).json({ error: "Payment method id is required" });
    }

    const methods = await readCompatPaymentMethods(userId);
    const filtered = methods.filter((method) => method.id !== methodId);
    if (filtered.length === methods.length) {
      return res.status(404).json({ error: "Payment method not found" });
    }

    if (filtered.length > 0 && !filtered.some((method) => method.is_default)) {
      filtered[0] = {
        ...filtered[0],
        is_default: true,
        updated_at: new Date().toISOString(),
      };
    }

    await writeCompatPaymentMethods(userId, filtered);
    res.json({ success: true, paymentMethods: filtered });
  } catch (error) {
    console.error("Error deleting payment method:", error);
    res.status(500).json({ error: "Could not delete payment method" });
  }
});

function canAccessCompatPaymentDocument(
  req: express.Request,
  record: CompatPaymentStatusRecord,
) {
  const session = getActiveSessionFromRequest(req);
  if (session) {
    const normalizedRole = String(session.role || "").trim().toLowerCase();
    if (ADMIN_SESSION_ROLES.has(normalizedRole)) {
      return true;
    }
  }

  const requestUserId = compatResolveUserId(req);
  const requestEmail =
    normalizeMailConfigValue(compatResolveUserEmail(req)).toLowerCase() || null;
  const recordEmail =
    normalizeMailConfigValue(record.email).toLowerCase() || null;

  return Boolean(
    (requestUserId && record.userId && requestUserId === record.userId) ||
      (requestEmail && recordEmail && requestEmail === recordEmail),
  );
}

function formatCompatPaymentDocumentAmount(amountMajor: number, currency: string) {
  try {
    return new Intl.NumberFormat("nb-NO", {
      style: "currency",
      currency: currency || "NOK",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amountMajor);
  } catch {
    return `${amountMajor.toFixed(2)} ${currency || "NOK"}`;
  }
}

function formatCompatPaymentDocumentDate(value: string | null | undefined) {
  if (!value) {
    return "Ikke tilgjengelig";
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "Ikke tilgjengelig";
  }
  return parsed.toLocaleString("nb-NO");
}

function buildCompatPaymentDocumentHtml(input: {
  title: string;
  subtitle: string;
  record: CompatPaymentStatusRecord;
  historyEntry: CompatPaymentHistoryItem | null;
  accountingReady?: boolean;
}) {
  const { title, subtitle, record, historyEntry, accountingReady = false } = input;
  const amountLabel = formatCompatPaymentDocumentAmount(
    record.amountMajor,
    record.currency,
  );
  const statusLabel =
    record.status === "completed"
      ? "Betalt"
      : record.status === "refunded"
        ? "Refundert"
        : record.status === "failed"
          ? "Betaling feilet"
          : "Venter betaling";

  return `<!doctype html>
<html lang="nb">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)}</title>
    <style>
      body{font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f6f2ea;color:#111827;margin:0;padding:32px}
      .sheet{max-width:820px;margin:0 auto;background:#fff;border:1px solid #e5e7eb;border-radius:24px;overflow:hidden;box-shadow:0 24px 60px rgba(15,23,42,.08)}
      .hero{padding:32px;background:linear-gradient(135deg,#18130f 0%,#2b1d16 55%,#1f1722 100%);color:#fff}
      .label{font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#ffba6c;font-weight:700;margin:0 0 10px}
      h1{margin:0;font-size:32px;line-height:1.1}
      .sub{margin:12px 0 0;color:rgba(255,255,255,.76);font-size:16px;line-height:1.6}
      .body{padding:28px}
      .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
      .card{border:1px solid #e5e7eb;border-radius:18px;padding:18px;background:#fff}
      .k{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#64748b;font-weight:700;margin:0 0 8px}
      .v{font-size:18px;font-weight:700;color:#0f172a;margin:0}
      .muted{margin:8px 0 0;color:#475569;font-size:14px;line-height:1.6}
      .footer{padding:0 28px 28px;color:#64748b;font-size:13px}
    </style>
  </head>
  <body>
    <div class="sheet">
      <div class="hero">
        <p class="label">CreatorHub betaling</p>
        <h1>${escapeHtml(title)}</h1>
        <p class="sub">${escapeHtml(subtitle)}</p>
      </div>
      <div class="body">
        <div class="grid">
          <div class="card">
            <p class="k">Plan</p>
            <p class="v">${escapeHtml(record.planName || "CreatorHub-abonnement")}</p>
            <p class="muted">Transaksjon ${escapeHtml(record.transactionId || record.id)}</p>
          </div>
          <div class="card">
            <p class="k">Beløp</p>
            <p class="v">${escapeHtml(amountLabel)}</p>
            <p class="muted">Betalingsmetode: ${escapeHtml(record.paymentMethod)}</p>
          </div>
          <div class="card">
            <p class="k">Status</p>
            <p class="v">${escapeHtml(statusLabel)}</p>
            <p class="muted">Registrert ${escapeHtml(formatCompatPaymentDocumentDate(record.completedAt || record.createdAt))}</p>
          </div>
          <div class="card">
            <p class="k">Tilgang / periode</p>
            <p class="v">${escapeHtml(formatCompatPaymentDocumentDate(historyEntry?.currentPeriodEnd || null))}</p>
            <p class="muted">Startet ${escapeHtml(formatCompatPaymentDocumentDate(historyEntry?.currentPeriodStart || record.createdAt))}</p>
          </div>
        </div>
        <div class="card" style="margin-top:16px">
          <p class="k">Regnskapsstatus</p>
          <p class="v">${accountingReady ? "Klar for regnskap" : "Kun kjøpskvittering"}</p>
          <p class="muted">${
            accountingReady
              ? "Kjøpet er registrert videre og kan brukes som grunnlag for Fiken eller Tripletex."
              : "Kjøpet har kvittering i historikken. Faktura eller bokføringsbilag kommer når regnskapsintegrasjonen er aktiv."
          }</p>
        </div>
      </div>
      <div class="footer">
        Dette dokumentet er generert fra betalingshistorikken i CreatorHub.
      </div>
    </div>
  </body>
</html>`;
}

app.get("/api/payments/history", async (req, res) => {
  try {
    const userId = readString(req.query.userId) || compatResolveUserId(req);
    const email =
      readString(req.query.userEmail) || compatResolveUserEmail(req);
    const history = await buildCompatPaymentHistory(userId || "guest", email);
    await writeCompatPaymentHistory(userId || "guest", history);
    res.json({
      history: await decorateCompatPaymentHistoryWithRefundRequests(
        history,
        userId || "guest",
        email,
      ),
    });
  } catch (error) {
    console.error("Error fetching payment history:", error);
    res.status(500).json({ error: "Could not fetch payment history" });
  }
});

app.get("/api/payments/receipt/:paymentId", async (req, res) => {
  try {
    const paymentId = compatHeaderString(req.params.paymentId);
    if (!paymentId) {
      return res.status(400).json({ error: "paymentId is required" });
    }

    const record = await findCompatPaymentStatusRecord(paymentId);
    if (!record) {
      return res.status(404).json({ error: "Receipt not found" });
    }
    if (!canAccessCompatPaymentDocument(req, record)) {
      return res.status(403).json({ error: "Du har ikke tilgang til denne kvitteringen" });
    }

    const history = await decorateCompatPaymentHistoryWithRefundRequests(
      await buildCompatPaymentHistory(record.userId, record.email),
      record.userId,
      record.email,
    );
    const historyEntry =
      history.find(
        (entry) => entry.id === record.id || entry.transactionId === record.transactionId,
      ) || null;

    res.type("html").send(
      buildCompatPaymentDocumentHtml({
        title: "Kvittering",
        subtitle: "Dokumentasjon for gjennomført kjøp og aktivt abonnement.",
        record,
        historyEntry,
        accountingReady: Boolean(historyEntry?.isInFiken),
      }),
    );
  } catch (error) {
    console.error("Error generating payment receipt document:", error);
    res.status(500).json({ error: "Could not generate receipt" });
  }
});

app.get("/api/payments/invoice/:paymentId", async (req, res) => {
  try {
    const paymentId = compatHeaderString(req.params.paymentId);
    if (!paymentId) {
      return res.status(400).json({ error: "paymentId is required" });
    }

    const record = await findCompatPaymentStatusRecord(paymentId);
    if (!record) {
      return res.status(404).json({ error: "Invoice not found" });
    }
    if (!canAccessCompatPaymentDocument(req, record)) {
      return res.status(403).json({ error: "Du har ikke tilgang til dette dokumentet" });
    }

    const history = await decorateCompatPaymentHistoryWithRefundRequests(
      await buildCompatPaymentHistory(record.userId, record.email),
      record.userId,
      record.email,
    );
    const historyEntry =
      history.find(
        (entry) => entry.id === record.id || entry.transactionId === record.transactionId,
      ) || null;

    if (!historyEntry?.isInFiken) {
      return res
        .status(404)
        .json({ error: "Regnskapsgrunnlag blir tilgjengelig når kjøpet er bokført i Fiken eller Tripletex" });
    }

    res.type("html").send(
      buildCompatPaymentDocumentHtml({
        title: "Regnskapsgrunnlag",
        subtitle: "Dokumentasjon for kjøp som er klargjort for regnskapsintegrasjon.",
        record,
        historyEntry,
        accountingReady: true,
      }),
    );
  } catch (error) {
    console.error("Error generating payment accounting document:", error);
    res.status(500).json({ error: "Could not generate accounting document" });
  }
});

app.post("/api/payments/create-payment-intent", async (req, res) => {
  try {
    const body = isRecord(req.body) ? req.body : {};
    const email =
      compatHeaderString(body.email ?? body.userEmail ?? body.user_email) ||
      compatResolveUserEmail(req);
    const requestId =
      compatHeaderString(body.requestId ?? body.request_id) || null;
    const userId = resolveCompatPaymentUserScope(
      compatHeaderString(body.userId ?? body.user_id) || compatResolveUserId(req),
      requestId,
      email,
    );
    const planId = normalizeBillingPlanId(body.planId ?? body.plan_id);
    const plan = getCompatPlatformSubscriptionPlan(planId);
    const planName =
      plan?.displayName ||
      readString(body.planName) ||
      readString(body.plan_name) ||
      "CreatorHub Plan";
    const paymentMethod = normalizeCompatPaymentMethod(
      body.paymentMethod ?? body.payment_method,
    );
    const amountMinor = normalizeCompatAmountMinor(body.amount, plan);
    const amountMajor = Number((amountMinor / 100).toFixed(2));
    const createdAt = new Date().toISOString();
    const paymentId = `pay_${crypto.randomUUID()}`;
    const transactionId = `txn_${crypto.randomUUID()}`;

    const record: CompatPaymentStatusRecord = {
      id: paymentId,
      transactionId,
      userId,
      email,
      requestId,
      planId: plan?.id || planId,
      planName,
      amountMinor,
      amountMajor,
      currency: readString(body.currency) || plan?.currency || "NOK",
      paymentMethod,
      status: "completed",
      createdAt,
      completedAt: createdAt,
      provider: "compat",
      metadata: {
        profession: readString(body.profession),
        requestId,
      },
      receiptSentAt: null,
      membershipCard: null,
    };

    await recordCompatPaymentCompletion(record);

    res.status(201).json({
      success: true,
      id: record.id,
      paymentId: record.id,
      transactionId: record.transactionId,
      status: record.status,
      amount: record.amountMinor,
      currency: record.currency,
      paymentMethod: record.paymentMethod,
      planId: record.planId,
      planName: record.planName,
      clientSecret: `compat_${record.id}`,
    });
  } catch (error) {
    console.error("Error creating payment intent:", error);
    res.status(500).json({ error: "Could not create payment intent" });
  }
});

app.post("/api/google-pay/process-payment", async (req, res) => {
  try {
    const body = isRecord(req.body) ? req.body : {};
    const paymentIntent = isRecord(body.paymentIntent) ? body.paymentIntent : {};
    const paymentData = isRecord(body.paymentData) ? body.paymentData : {};
    const metadata = isRecord(paymentIntent.metadata) ? paymentIntent.metadata : {};
    const paymentMethodData = isRecord(paymentData.paymentMethodData)
      ? paymentData.paymentMethodData
      : {};
    const paymentMethodInfo = isRecord(paymentMethodData.info)
      ? paymentMethodData.info
      : {};
    const planId = normalizeBillingPlanId(metadata.planId ?? body.planId);
    const plan = getCompatPlatformSubscriptionPlan(planId);
    const createdAt = new Date().toISOString();
    const paymentId = `pay_${crypto.randomUUID()}`;
    const transactionId = `txn_${crypto.randomUUID()}`;
    const email =
      compatHeaderString(paymentData.email ?? body.email) ||
      compatResolveUserEmail(req);
    const amountMinor = normalizeCompatAmountMinor(paymentIntent.amount, plan);
    const amountMajor = Number((amountMinor / 100).toFixed(2));
    const requestId =
      compatHeaderString(metadata.requestId ?? body.requestId ?? body.request_id) ||
      null;
    const userId = resolveCompatPaymentUserScope(
      compatHeaderString(paymentIntent.userId ?? body.userId ?? body.user_id) ||
        compatResolveUserId(req),
      requestId,
      email,
    );

    const record: CompatPaymentStatusRecord = {
      id: paymentId,
      transactionId,
      userId,
      email,
      requestId,
      planId: plan?.id || planId,
      planName:
        plan?.displayName ||
        readString(paymentIntent.productName) ||
        readString(body.planName) ||
        "CreatorHub Plan",
      amountMinor,
      amountMajor,
      currency:
        readString(paymentIntent.currency) ||
        readString(body.currency) ||
        plan?.currency ||
        "NOK",
      paymentMethod: "google-pay",
      status: "completed",
      createdAt,
      completedAt: createdAt,
      provider: "google-pay",
      metadata: {
        requestId,
        profession: readString(metadata.profession),
        recurring: metadata.recurring === true,
        cardNetwork: readString(paymentMethodInfo.cardNetwork),
      },
      receiptSentAt: null,
      membershipCard: null,
    };

    await recordCompatPaymentCompletion(record);

    res.status(201).json({
      success: true,
      paymentId: record.id,
      transactionId: record.transactionId,
      status: record.status,
      paymentData: {
        amount: record.amountMinor,
        currency: record.currency,
        paymentMethod: record.paymentMethod,
      },
    });
  } catch (error) {
    console.error("Error processing Google Pay payment:", error);
    res.status(500).json({ error: "Could not process Google Pay payment" });
  }
});

