async function getCompatUserProjectTypes(userId: string): Promise<
  Array<{
    id: number;
    userId: number;
    name: string;
    icon: string;
    category: string;
    description: string;
    usageCount: number;
    isGlobal: boolean;
    isTrending: boolean;
    createdAt: string;
    updatedAt: string;
  }>
> {
  const existing = compatProjectTypesStore.get(userId);
  if (existing) return existing;

  const dbEntry = await compatStoreGet<
    Array<{
      id: number;
      userId: number;
      name: string;
      icon: string;
      category: string;
      description: string;
      usageCount: number;
      isGlobal: boolean;
      isTrending: boolean;
      createdAt: string;
      updatedAt: string;
    }>
  >(dbCompatProjectTypesKey(userId));
  if (Array.isArray(dbEntry)) {
    compatProjectTypesStore.set(userId, dbEntry);
    return dbEntry;
  }

  const seed = seedFromString(userId);
  const defaults = getCompatDefaultProjectTypes().map((entry, idx) => ({
    ...entry,
    id: entry.id + (idx + 1) * 1000,
    userId: Number.isFinite(Number(userId)) ? Number(userId) : 0,
    isGlobal: false,
    isTrending: idx === 0,
    usageCount: seed % (idx + 4),
  }));
  compatProjectTypesStore.set(userId, defaults);
  await compatStoreSet(dbCompatProjectTypesKey(userId), defaults);
  return defaults;
}

app.get("/api/project-types", async (req, res) => {
  const userId = compatResolveUserId(req);
  const defaultTypes = getCompatDefaultProjectTypes();
  const userTypes = await getCompatUserProjectTypes(userId);
  const trendingTypes = [...defaultTypes, ...userTypes]
    .filter((type) => type.isTrending || type.usageCount > 1)
    .sort((a, b) => b.usageCount - a.usageCount)
    .slice(0, 6);
  res.json({ userTypes, defaultTypes, trendingTypes });
});

app.post("/api/project-types", async (req, res) => {
  const userId = compatResolveUserId(req);
  const userTypes = await getCompatUserProjectTypes(userId);
  const now = new Date().toISOString();
  const nextId =
    userTypes.length > 0 ? Math.max(...userTypes.map((t) => t.id)) + 1 : 2001;
  const next = {
    id: nextId,
    userId: Number.isFinite(Number(userId)) ? Number(userId) : 0,
    name: readString(req.body?.name) || "Untitled",
    icon: readString(req.body?.icon) || "📁",
    category: readString(req.body?.category) || "general",
    description: readString(req.body?.description) || "",
    usageCount: 0,
    isGlobal: false,
    isTrending: false,
    createdAt: now,
    updatedAt: now,
  };
  userTypes.push(next);
  compatProjectTypesStore.set(userId, userTypes);
  await compatStoreSet(dbCompatProjectTypesKey(userId), userTypes);
  res.status(201).json(next);
});

