const CREATORHUB_STRIPE_CHECKOUT_RECORD_PREFIX =
  "creatorhub:billing:checkout-session:";
const CREATORHUB_STRIPE_SUBSCRIPTION_RECORD_PREFIX =
  "creatorhub:billing:subscription:";
const ROLE_ROOM_STRIPE_CHECKOUT_RECORD_PREFIX =
  "role-room:billing:checkout-session:";
const ROLE_ROOM_STRIPE_SUBSCRIPTION_RECORD_PREFIX =
  "role-room:billing:subscription:";

let creatorHubStripeClient: Stripe | null | undefined;
let roleRoomStripeClient: Stripe | null | undefined;
const ROLE_ROOM_STRIPE_PRODUCT_TAX_CODE = "txcd_10103001";
const ROLE_ROOM_ACTIVATION_REQUIRED_JOURNEY_STATUS =
  "role_room_activation_required";
const ROLE_ROOM_ACTIVATED_JOURNEY_STATUS = "role_room_access_activated";
const ROLE_ROOM_ACTIVATION_TOKEN_TTL_MS = 1000 * 60 * 60 * 24 * 14;
const ROLE_ROOM_PAYMENT_REMINDER_HOURS = parseRoleRoomReminderHours(
  process.env.ROLE_ROOM_PAYMENT_REMINDER_HOURS,
  [2, 24, 72, 168],
);
const ROLE_ROOM_ACTIVATION_REMINDER_HOURS = parseRoleRoomReminderHours(
  process.env.ROLE_ROOM_ACTIVATION_REMINDER_HOURS,
  [24, 72, 168],
);
const ROLE_ROOM_PAYMENT_REMINDER_REPEAT_HOURS =
  parseRoleRoomReminderHours(
    process.env.ROLE_ROOM_PAYMENT_REMINDER_REPEAT_HOURS,
    [168],
  )[0] || 168;
const ROLE_ROOM_ACTIVATION_REMINDER_REPEAT_HOURS =
  parseRoleRoomReminderHours(
    process.env.ROLE_ROOM_ACTIVATION_REMINDER_REPEAT_HOURS,
    [168],
  )[0] || 168;
const ROLE_ROOM_REMINDER_INTERVAL_MS =
  Math.max(
    15,
    Number.parseInt(
      normalizeMailConfigValue(process.env.ROLE_ROOM_REMINDER_INTERVAL_MINUTES) ||
        "60",
      10,
    ) || 60,
  ) *
  60 *
  1000;
const ROLE_ROOM_REMINDER_STATUS_COMPAT_KEY = "role-room:billing:reminders:status";

type RoleRoomCommercialActivationStatus = "pending_approval" | "approved";
type RoleRoomCommercialBillingStatus =
  | "pending_payment"
  | "active"
  | "payment_failed";

type RoleRoomCommercialReminderDeliverySummary = {
  sent: boolean;
  reason: string | null;
  accepted: string[];
  provider: string | null;
  messageId: string | null;
};

type RoleRoomCommercialReminderSweepSummary = {
  reason: "startup" | "interval" | "manual";
  startedAt: string;
  finishedAt: string;
  isRunning: boolean;
  paymentCandidates: number;
  paymentRemindersSent: number;
  activationCandidates: number;
  activationRemindersSent: number;
  failures: number;
  skipped: number;
  notes: string[];
};

function parseRoleRoomReminderHours(
  value: unknown,
  fallback: number[],
): number[] {
  const normalized = normalizeMailConfigValue(value);
  const parsed = normalized
    .split(",")
    .map((entry) => Number.parseInt(entry.trim(), 10))
    .filter((entry) => Number.isFinite(entry) && entry > 0)
    .map((entry) => Math.floor(entry));

  return parsed.length > 0 ? parsed : [...fallback];
}

function isRoleRoomReminderRunnerEnabled() {
  const normalized = normalizeMailConfigValue(
    process.env.ROLE_ROOM_REMINDERS_ENABLED,
  ).toLowerCase();
  return !["0", "false", "off", "no"].includes(normalized);
}

function roleRoomCommercialCheckoutSessionKey(sessionId: string) {
  return `${ROLE_ROOM_STRIPE_CHECKOUT_RECORD_PREFIX}${sessionId}`;
}

function roleRoomCommercialSubscriptionKey(subscriptionId: string) {
  return `${ROLE_ROOM_STRIPE_SUBSCRIPTION_RECORD_PREFIX}${subscriptionId}`;
}

function getStripeCheckoutSessionCustomerId(session: Stripe.Checkout.Session) {
  const customer = session.customer;
  if (typeof customer === "string") {
    return customer;
  }
  if (customer && typeof customer === "object" && "id" in customer) {
    return String(customer.id || "");
  }
  return "";
}

function creatorHubStripeCheckoutSessionKey(sessionId: string) {
  return `${CREATORHUB_STRIPE_CHECKOUT_RECORD_PREFIX}${sessionId}`;
}

function creatorHubStripeSubscriptionKey(subscriptionId: string) {
  return `${CREATORHUB_STRIPE_SUBSCRIPTION_RECORD_PREFIX}${subscriptionId}`;
}

function getCreatorHubStripeSecretKey() {
  return normalizeMailConfigValue(
    process.env.CREATORHUB_STRIPE_SECRET_KEY ||
      process.env.STRIPE_SECRET_KEY ||
      process.env.STRIPE_API_KEY,
  );
}

function getCreatorHubStripeWebhookSecret() {
  return normalizeMailConfigValue(
    process.env.CREATORHUB_STRIPE_WEBHOOK_SECRET,
  );
}

function getCreatorHubStripePriceId(
  planId: string | null | undefined,
  billingCycle: "monthly" | "yearly" = "monthly",
) {
  switch (normalizeBillingPlanId(planId)) {
    case "basic":
      return normalizeMailConfigValue(
        billingCycle === "yearly"
          ? process.env.CREATORHUB_STRIPE_PRICE_ID_BASIC_YEARLY
          : process.env.CREATORHUB_STRIPE_PRICE_ID_BASIC,
      );
    case "professional":
      return normalizeMailConfigValue(
        billingCycle === "yearly"
          ? process.env.CREATORHUB_STRIPE_PRICE_ID_PROFESSIONAL_YEARLY
          : process.env.CREATORHUB_STRIPE_PRICE_ID_PROFESSIONAL,
      );
    case "premium":
      return normalizeMailConfigValue(
        billingCycle === "yearly"
          ? process.env.CREATORHUB_STRIPE_PRICE_ID_PREMIUM_YEARLY
          : process.env.CREATORHUB_STRIPE_PRICE_ID_PREMIUM,
      );
    case "enterprise":
      return normalizeMailConfigValue(
        billingCycle === "yearly"
          ? process.env.CREATORHUB_STRIPE_PRICE_ID_ENTERPRISE_YEARLY
          : process.env.CREATORHUB_STRIPE_PRICE_ID_ENTERPRISE,
      );
    default:
      return "";
  }
}

function getCreatorHubStripeClient() {
  const secretKey = getCreatorHubStripeSecretKey();
  if (!secretKey) {
    return null;
  }
  if (creatorHubStripeClient) {
    return creatorHubStripeClient;
  }

  creatorHubStripeClient = new Stripe(secretKey);
  return creatorHubStripeClient;
}

function getDefaultCreatorHubPublicOrigin() {
  return (
    normalizeMailConfigValue(process.env.CREATORHUB_PUBLIC_URL) ||
    normalizeMailConfigValue(process.env.PUBLIC_APP_URL) ||
    "https://creatorhubn.com"
  );
}

function normalizeCreatorHubBrowserOrigin(value: unknown) {
  const raw = typeof value === "string" ? value.trim() : "";
  if (!raw) {
    return getDefaultCreatorHubPublicOrigin();
  }

  try {
    const parsed = new URL(raw);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
      return getDefaultCreatorHubPublicOrigin();
    }
    return parsed.origin;
  } catch {
    return getDefaultCreatorHubPublicOrigin();
  }
}

function buildCreatorHubCheckoutReturnUrl(input: {
  browserOrigin: string;
  returnPath?: string | null;
  status: "success" | "cancel";
  includeSessionId?: boolean;
}) {
  const rawPath =
    typeof input.returnPath === "string" && input.returnPath.trim().startsWith("/")
      ? input.returnPath.trim()
      : "/subscription-selection";
  const url = new URL(rawPath, input.browserOrigin);
  url.searchParams.set("payment", input.status);
  if (input.includeSessionId) {
    url.searchParams.set("session_id", "{CHECKOUT_SESSION_ID}");
  } else {
    url.searchParams.delete("session_id");
  }
  return url
    .toString()
    .replace("%7BCHECKOUT_SESSION_ID%7D", "{CHECKOUT_SESSION_ID}");
}

