function isRoleRoomClientReviewerRole(value: unknown) {
  const normalized = toAdminString(value);
  return normalized === "client" || normalized === "client_reviewer";
}

function isRoleRoomCommercialLoginIntent(input: {
  loginAs?: unknown;
  requestedRole?: unknown;
}) {
  const loginAs = toAdminString(input.loginAs);
  if (loginAs === "production_team") {
    return true;
  }

  if (loginAs === "content_producer") {
    return !isRoleRoomClientReviewerRole(input.requestedRole);
  }

  return false;
}

function hashRoleRoomActivationToken(token: string) {
  return crypto.createHash("sha256").update(token).digest("hex");
}

function generateRoleRoomActivationToken() {
  return crypto.randomBytes(32).toString("hex");
}

function buildRoleRoomActivationUrl(input: {
  token: string;
  browserOrigin?: string | null;
  returnPath?: string | null;
}) {
  const browserOrigin =
    normalizeRoleRoomBrowserOrigin(input.browserOrigin) ||
    getDefaultRoleRoomPublicOrigin();
  const rawPath =
    typeof input.returnPath === "string" && input.returnPath.trim().startsWith("/")
      ? input.returnPath.trim()
      : "/";
  const url = new URL("/api/role-room/billing/activate", browserOrigin);
  url.searchParams.set("token", input.token);
  url.searchParams.set("browserOrigin", browserOrigin);
  url.searchParams.set("returnPath", rawPath);
  return url.toString();
}

function buildRoleRoomActivationReturnUrl(input: {
  browserOrigin?: string | null;
  returnPath?: string | null;
  status: "success" | "error";
  message?: string | null;
}) {
  const browserOrigin =
    normalizeRoleRoomBrowserOrigin(input.browserOrigin) ||
    getDefaultRoleRoomPublicOrigin();
  const rawPath =
    typeof input.returnPath === "string" && input.returnPath.trim().startsWith("/")
      ? input.returnPath.trim()
      : "/";
  const url = new URL(rawPath, browserOrigin);
  url.searchParams.set("rrActivation", input.status);
  if (input.message) {
    url.searchParams.set("rrActivationMessage", input.message);
  } else {
    url.searchParams.delete("rrActivationMessage");
  }
  return url.toString();
}

function getRoleRoomCommercialActivationStatus(
  inviteRequest: Record<string, unknown> | null | undefined,
) {
  const snapshot = parseRoleRoomCommercialAccessSnapshot(inviteRequest?.message);
  const approved =
    snapshot?.activationStatus === "approved" ||
    Boolean(snapshot?.activationApprovedAt) ||
    toAdminString(inviteRequest?.user_journey_status) ===
      ROLE_ROOM_ACTIVATED_JOURNEY_STATUS;
  const pendingApproval =
    Boolean(inviteRequest?.payment_completed) &&
    !approved &&
    (
      snapshot?.activationStatus === "pending_approval" ||
      toAdminString(inviteRequest?.user_journey_status) ===
        ROLE_ROOM_ACTIVATION_REQUIRED_JOURNEY_STATUS
    );

  return {
    approved,
    pendingApproval,
    emailSent: Boolean(snapshot?.activationEmailSentAt),
    tokenHash: snapshot?.activationTokenHash || null,
    tokenExpiresAt: snapshot?.activationTokenExpiresAt || null,
    snapshot,
  };
}

function getRoleRoomCommercialPaymentPendingSince(
  inviteRequest: Record<string, unknown> | null | undefined,
  snapshot?: RoleRoomCommercialAccessSnapshot | null,
) {
  const parsedSnapshot =
    snapshot || parseRoleRoomCommercialAccessSnapshot(inviteRequest?.message);
  return (
    parsedSnapshot?.paymentPendingSince ||
    toAdminString(inviteRequest?.updated_at) ||
    toAdminString(inviteRequest?.created_at) ||
    null
  );
}

function shouldSendRoleRoomReminder(input: {
  anchorAt?: string | null;
  lastSentAt?: string | null;
  sentCount?: number | null;
  thresholdHours: number[];
  repeatHours: number;
}) {
  const anchorTime = Date.parse(String(input.anchorAt || ""));
  if (!Number.isFinite(anchorTime) || anchorTime <= 0) {
    return false;
  }

  const count = Math.max(0, Math.floor(input.sentCount || 0));
  const now = Date.now();
  if (count < input.thresholdHours.length) {
    return (
      now - anchorTime >= input.thresholdHours[count] * 60 * 60 * 1000
    );
  }

  const lastSentTime = Date.parse(String(input.lastSentAt || ""));
  if (!Number.isFinite(lastSentTime) || lastSentTime <= 0) {
    return false;
  }

  return now - lastSentTime >= input.repeatHours * 60 * 60 * 1000;
}

function buildRoleRoomCommercialReminderSummary(
  reason: "startup" | "interval" | "manual",
): RoleRoomCommercialReminderSweepSummary {
  const startedAt = new Date().toISOString();
  return {
    reason,
    startedAt,
    finishedAt: startedAt,
    isRunning: true,
    paymentCandidates: 0,
    paymentRemindersSent: 0,
    activationCandidates: 0,
    activationRemindersSent: 0,
    failures: 0,
    skipped: 0,
    notes: [],
  };
}

function doesRoleRoomCommercialPaymentMatchCurrentSetup(input: {
  inviteRequest: Record<string, unknown> | null | undefined;
  planId: string;
  monthlyTotalExVat: number;
}) {
  const selectedPlan = normalizeInvitePlanId(
    input.inviteRequest?.selected_plan || input.inviteRequest?.plan_name,
  );
  const paymentCompleted = Boolean(input.inviteRequest?.payment_completed);
  const paymentAmount =
    input.inviteRequest?.payment_amount != null
      ? Number(input.inviteRequest.payment_amount)
      : input.inviteRequest?.plan_price != null
        ? Number(input.inviteRequest.plan_price)
        : null;

  return (
    paymentCompleted &&
    selectedPlan === input.planId &&
    typeof paymentAmount === "number" &&
    Number.isFinite(paymentAmount) &&
    Math.abs(paymentAmount - input.monthlyTotalExVat) < 0.0001
  );
}

function shouldPreserveRoleRoomCommercialPendingPaymentState(input: {
  existingSnapshot: RoleRoomCommercialAccessSnapshot | null;
  inviteRequest: Record<string, unknown> | null | undefined;
  planId: string;
  organizationNumber: string;
  teamLeadEmail: string;
  teamSize: number;
  monthlyTotalExVat: number;
}) {
  if (
    !input.existingSnapshot ||
    Boolean(input.inviteRequest?.payment_completed)
  ) {
    return false;
  }

  return (
    input.existingSnapshot.subscriptionType === input.planId &&
    input.existingSnapshot.organizationNumber === input.organizationNumber &&
    input.existingSnapshot.teamLeadEmail === input.teamLeadEmail &&
    input.existingSnapshot.teamSize === input.teamSize &&
    typeof input.existingSnapshot.monthlyTotalExVat === "number" &&
    Math.abs(
      input.existingSnapshot.monthlyTotalExVat - input.monthlyTotalExVat,
    ) < 0.0001
  );
}

async function resetRoleRoomCommercialInvitePaymentState(
  inviteRequestId: string,
  journeyStatus = "role_room_pending_payment",
  options?: {
    billingStatus?: RoleRoomCommercialBillingStatus;
    stripeSubscriptionId?: string | null;
    stripeCustomerId?: string | null;
    latestInvoiceId?: string | null;
    latestInvoiceStatus?: string | null;
    paymentFailureMessage?: string | null;
    paymentFailedAt?: string | null;
  },
) {
  if (!(await hasTable("invite_requests"))) {
    return null;
  }

  const inviteColumns = await getTableColumns("invite_requests");
  const updates: string[] = [];
  const values: unknown[] = [];
  const pushValue = (column: string, value: unknown) => {
    values.push(value);
    updates.push(`${column} = $${values.length}`);
  };

  if (inviteColumns.has("payment_completed")) {
    pushValue("payment_completed", false);
  }
  if (inviteColumns.has("payment_transaction_id")) {
    pushValue("payment_transaction_id", null);
  }
  if (inviteColumns.has("payment_amount")) {
    pushValue("payment_amount", null);
  }
  if (inviteColumns.has("payment_timestamp")) {
    pushValue("payment_timestamp", null);
  }
  if (inviteColumns.has("message")) {
    const existingInvite = await pool
      .query("SELECT * FROM invite_requests WHERE id = $1 LIMIT 1", [
        inviteRequestId,
      ])
      .then((result) => (result.rows[0] as Record<string, unknown> | undefined) || null)
      .catch(() => null);
    const existingSnapshot = parseRoleRoomCommercialAccessSnapshot(
      existingInvite?.message,
    );
    if (existingSnapshot) {
      pushValue(
        "message",
        serializeRoleRoomCommercialAccessSnapshot({
          ...existingSnapshot,
          billingStatus: options?.billingStatus || "pending_payment",
          stripeSubscriptionId:
            options?.stripeSubscriptionId === undefined
              ? existingSnapshot.stripeSubscriptionId
              : options.stripeSubscriptionId,
          stripeCustomerId:
            options?.stripeCustomerId === undefined
              ? existingSnapshot.stripeCustomerId
              : options.stripeCustomerId,
          latestInvoiceId:
            options?.latestInvoiceId === undefined
              ? existingSnapshot.latestInvoiceId
              : options.latestInvoiceId,
          latestInvoiceStatus:
            options?.latestInvoiceStatus === undefined
              ? existingSnapshot.latestInvoiceStatus
              : options.latestInvoiceStatus,
          paymentFailedAt:
            options?.paymentFailedAt === undefined
              ? existingSnapshot.paymentFailedAt
              : options.paymentFailedAt,
          paymentFailureMessage:
            options?.paymentFailureMessage === undefined
              ? existingSnapshot.paymentFailureMessage
              : options.paymentFailureMessage,
          paymentPendingSince: new Date().toISOString(),
          paymentReminderCount: 0,
          paymentReminderLastSentAt: null,
          paymentReminderProvider: null,
          paymentReminderMessageId: null,
        }),
      );
    }
  }
  if (inviteColumns.has("user_journey_status")) {
    pushValue("user_journey_status", journeyStatus);
  }
  if (inviteColumns.has("updated_at")) {
    updates.push("updated_at = NOW()");
  }

  if (updates.length === 0) {
    return null;
  }

  values.push(inviteRequestId);
  const result = await pool.query(
    `UPDATE invite_requests
     SET ${updates.join(", ")}
     WHERE id = $${values.length}
     RETURNING *`,
    values,
  );

  return result.rows[0] || null;
}

async function writeRoleRoomCommercialCheckoutSessionRecord(
  record: RoleRoomCommercialCheckoutSessionRecord,
) {
  await compatStoreSet(
    roleRoomCommercialCheckoutSessionKey(record.sessionId),
    record,
  );
  if (record.stripeSubscriptionId) {
    await compatStoreSet(
      roleRoomCommercialSubscriptionKey(record.stripeSubscriptionId),
      record,
    );
  }
}

async function readRoleRoomCommercialCheckoutSessionRecord(
  sessionId: string,
): Promise<RoleRoomCommercialCheckoutSessionRecord | null> {
  return compatStoreGet<RoleRoomCommercialCheckoutSessionRecord>(
    roleRoomCommercialCheckoutSessionKey(sessionId),
  );
}

async function readRoleRoomCommercialCheckoutRecordBySubscriptionId(
  subscriptionId: string,
): Promise<RoleRoomCommercialCheckoutSessionRecord | null> {
  const cached = await compatStoreGet<RoleRoomCommercialCheckoutSessionRecord>(
    roleRoomCommercialSubscriptionKey(subscriptionId),
  );

  const rows = await listRoleRoomCommercialReminderInviteRequests();
  const matchingRow =
    rows.find((row) => {
      const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
      return (
        snapshot?.stripeSubscriptionId === subscriptionId ||
        toAdminString(row.payment_transaction_id) === subscriptionId
      );
    }) || null;
  if (!matchingRow) {
    return cached;
  }

  const matchingSnapshot = parseRoleRoomCommercialAccessSnapshot(matchingRow.message);
  if (!matchingSnapshot) {
    return cached;
  }

  const teamKey = buildRoleRoomCommercialReminderTeamKey(matchingSnapshot);
  const teamRows = rows.filter((row) => {
    const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
    return snapshot && buildRoleRoomCommercialReminderTeamKey(snapshot) === teamKey;
  });
  const leaderRow =
    teamRows.find((row) => {
      const rowEmail = toAdminString(row.email)?.trim().toLowerCase() || "";
      return (
        matchingSnapshot.teamLeadEmail &&
        rowEmail === matchingSnapshot.teamLeadEmail
      );
    }) || matchingRow;

  const rebuilt = expandRoleRoomCommercialCheckoutRecordWithTeamRows(
    cached || buildRoleRoomCommercialCheckoutRecordFromInviteRequest(leaderRow),
    matchingSnapshot,
    teamRows,
  );
  if (!rebuilt) {
    return cached;
  }

  const record: RoleRoomCommercialCheckoutSessionRecord = {
    ...rebuilt,
    stripeSubscriptionId: subscriptionId,
  };
  await writeRoleRoomCommercialCheckoutSessionRecord(record);
  return record;
}

async function resolveCreatorHubStripeCheckoutRecordFromCompatPayment(
  record: CompatPaymentStatusRecord,
): Promise<CreatorHubStripeCheckoutSessionRecord | null> {
  const sessionId = getCompatPaymentStripeSessionId(record);
  if (sessionId) {
    const sessionRecord = await readCreatorHubStripeCheckoutSessionRecord(sessionId);
    if (sessionRecord) {
      return sessionRecord;
    }
  }

  const subscriptionId = getCompatPaymentStripeSubscriptionId(record);
  if (subscriptionId) {
    return readCreatorHubStripeCheckoutRecordBySubscriptionId(subscriptionId);
  }

  return null;
}

function getStripeInvoiceChargeId(invoice: Stripe.Invoice): string | null {
  const legacyCharge = (invoice as { charge?: string | { id?: string | null } | null })
    .charge;
  if (typeof legacyCharge === "string") {
    return legacyCharge || null;
  }
  if (legacyCharge && typeof legacyCharge === "object" && "id" in legacyCharge) {
    return String(legacyCharge.id || "") || null;
  }
  return null;
}

async function resolveCreatorHubStripeRefundTarget(input: {
  stripe: Stripe;
  paymentRecord: CompatPaymentStatusRecord;
  checkoutRecord: CreatorHubStripeCheckoutSessionRecord | null;
}) {
  const transactionId = normalizeMailConfigValue(input.paymentRecord.transactionId);
  if (transactionId.startsWith("pi_")) {
    return {
      paymentIntentId: transactionId,
      chargeId: null as string | null,
      subscriptionId:
        input.checkoutRecord?.stripeSubscriptionId ||
        getCompatPaymentStripeSubscriptionId(input.paymentRecord),
      customerId:
        input.checkoutRecord?.stripeCustomerId ||
        getCompatPaymentStripeCustomerId(input.paymentRecord),
      sessionId:
        input.checkoutRecord?.sessionId ||
        getCompatPaymentStripeSessionId(input.paymentRecord),
    };
  }
  if (transactionId.startsWith("ch_")) {
    return {
      paymentIntentId: null as string | null,
      chargeId: transactionId,
      subscriptionId:
        input.checkoutRecord?.stripeSubscriptionId ||
        getCompatPaymentStripeSubscriptionId(input.paymentRecord),
      customerId:
        input.checkoutRecord?.stripeCustomerId ||
        getCompatPaymentStripeCustomerId(input.paymentRecord),
      sessionId:
        input.checkoutRecord?.sessionId ||
        getCompatPaymentStripeSessionId(input.paymentRecord),
    };
  }

  const sessionId =
    input.checkoutRecord?.sessionId || getCompatPaymentStripeSessionId(input.paymentRecord);
  if (sessionId) {
    const session = await input.stripe.checkout.sessions.retrieve(sessionId, {
      expand: ["payment_intent", "subscription"],
    });
    const paymentIntent = session.payment_intent;
    if (typeof paymentIntent === "string" && paymentIntent) {
      return {
        paymentIntentId: paymentIntent,
        chargeId: null as string | null,
        subscriptionId:
          input.checkoutRecord?.stripeSubscriptionId ||
          getStripeCheckoutSessionSubscriptionId(session) ||
          getCompatPaymentStripeSubscriptionId(input.paymentRecord),
        customerId:
          input.checkoutRecord?.stripeCustomerId ||
          getStripeCheckoutSessionCustomerId(session) ||
          getCompatPaymentStripeCustomerId(input.paymentRecord),
        sessionId,
      };
    }
    if (paymentIntent && typeof paymentIntent === "object" && "id" in paymentIntent) {
      return {
        paymentIntentId: String(paymentIntent.id || ""),
        chargeId: null as string | null,
        subscriptionId:
          input.checkoutRecord?.stripeSubscriptionId ||
          getStripeCheckoutSessionSubscriptionId(session) ||
          getCompatPaymentStripeSubscriptionId(input.paymentRecord),
        customerId:
          input.checkoutRecord?.stripeCustomerId ||
          getStripeCheckoutSessionCustomerId(session) ||
          getCompatPaymentStripeCustomerId(input.paymentRecord),
        sessionId,
      };
    }
  }

  const subscriptionId =
    input.checkoutRecord?.stripeSubscriptionId ||
    getCompatPaymentStripeSubscriptionId(input.paymentRecord);
  const customerId =
    input.checkoutRecord?.stripeCustomerId ||
    getCompatPaymentStripeCustomerId(input.paymentRecord);
  if (subscriptionId) {
    const invoices = await input.stripe.invoices.list({
      subscription: subscriptionId,
      limit: 10,
      expand: ["data.payment_intent"],
    });
    const matchingPaidInvoice =
      invoices.data.find((invoice) => {
        const amountPaid =
          typeof invoice.amount_paid === "number" && Number.isFinite(invoice.amount_paid)
            ? invoice.amount_paid
            : 0;
        return invoice.status === "paid" && amountPaid > 0;
      }) || null;

    if (matchingPaidInvoice) {
      const paymentIntent = getStripeInvoicePaymentIntent(matchingPaidInvoice);
      if (typeof paymentIntent === "string" && paymentIntent) {
        return {
          paymentIntentId: paymentIntent,
          chargeId: null as string | null,
          subscriptionId,
          customerId:
            customerId ||
            (typeof matchingPaidInvoice.customer === "string"
              ? matchingPaidInvoice.customer
              : null),
          sessionId,
        };
      }
      if (paymentIntent && typeof paymentIntent === "object" && "id" in paymentIntent) {
        return {
          paymentIntentId: String(paymentIntent.id || ""),
          chargeId: null as string | null,
          subscriptionId,
          customerId:
            customerId ||
            (typeof matchingPaidInvoice.customer === "string"
              ? matchingPaidInvoice.customer
              : null),
          sessionId,
        };
      }

      const chargeId = getStripeInvoiceChargeId(matchingPaidInvoice);
      if (chargeId) {
        return {
          paymentIntentId: null as string | null,
          chargeId,
          subscriptionId,
          customerId:
            customerId ||
            (typeof matchingPaidInvoice.customer === "string"
              ? matchingPaidInvoice.customer
              : null),
          sessionId,
        };
      }
    }
  }

  if (customerId) {
    const paymentIntents = await input.stripe.paymentIntents.list({
      customer: customerId,
      limit: 10,
    });
    const successfulIntent =
      paymentIntents.data.find(
        (paymentIntent) =>
          paymentIntent.status === "succeeded" &&
          paymentIntent.amount_received > 0,
      ) || null;
    if (successfulIntent?.id) {
      return {
        paymentIntentId: successfulIntent.id,
        chargeId: null as string | null,
        subscriptionId,
        customerId,
        sessionId,
      };
    }
  }

  return null;
}

function getStripeCheckoutSessionSubscriptionId(
  session: Stripe.Checkout.Session,
) {
  const subscription = session.subscription;
  if (typeof subscription === "string") {
    return subscription;
  }
  if (subscription && typeof subscription === "object" && "id" in subscription) {
    return String(subscription.id || "");
  }
  return "";
}

function getStripeCheckoutSessionTransactionId(
  session: Stripe.Checkout.Session,
) {
  const subscriptionId = getStripeCheckoutSessionSubscriptionId(session);
  if (subscriptionId) {
    return subscriptionId;
  }

  const paymentIntent = session.payment_intent;
  if (typeof paymentIntent === "string") {
    return paymentIntent;
  }
  if (paymentIntent && typeof paymentIntent === "object" && "id" in paymentIntent) {
    return String(paymentIntent.id || "");
  }
  return session.id;
}

function isCreatorHubStripeSessionPaid(session: Stripe.Checkout.Session) {
  if (session.payment_status === "paid") {
    return true;
  }

  const subscription = session.subscription;
  if (subscription && typeof subscription === "object" && "status" in subscription) {
    return (
      subscription.status === "active" || subscription.status === "trialing"
    );
  }

  return false;
}

function deriveCreatorHubCheckoutStatus(
  session: Stripe.Checkout.Session,
): CreatorHubStripeCheckoutSessionRecord["checkoutStatus"] {
  if (isCreatorHubStripeSessionPaid(session)) {
    return "completed";
  }
  if (session.status === "expired") {
    return "expired";
  }
  if (session.status === "complete" && session.payment_status !== "paid") {
    return "payment_failed";
  }
  return "created";
}

function getCreatorHubStripeCheckoutEmail(session: Stripe.Checkout.Session) {
  const email =
    normalizeMailConfigValue(session.customer_details?.email) ||
    normalizeMailConfigValue(session.customer_email) ||
    normalizeMailConfigValue(session.metadata?.ch_email);
  return email ? email.toLowerCase() : null;
}

function deriveCreatorHubStripeCheckoutRecordFromSession(
  session: Stripe.Checkout.Session,
): CreatorHubStripeCheckoutSessionRecord | null {
  const metadata = session.metadata || {};
  const planId =
    normalizeBillingPlanId(metadata.ch_plan_id) ||
    normalizeBillingPlanId(metadata.planId);
  const plan = getCompatPlatformSubscriptionPlan(planId);
  const billingCycle = normalizeCreatorHubBillingCycle(
    metadata.ch_billing_cycle || metadata.billingCycle || plan?.billingCycle,
  );
  const planName =
    normalizeMailConfigValue(metadata.ch_plan_name) ||
    plan?.displayName ||
    "CreatorHub Plan";
  const userId = normalizeMailConfigValue(metadata.ch_user_id) || "guest";
  const amountMinor = Number(
    metadata.ch_amount_minor ||
      (plan ? Math.round(getCreatorHubPlanAmountMajor(plan, billingCycle) * 100) : 0),
  );
  const amountMajor = Number((amountMinor / 100).toFixed(2));
  const currency =
    normalizeMailConfigValue(metadata.ch_currency) || plan?.currency || "NOK";
  const createdAt = new Date(
    (session.created || Math.floor(Date.now() / 1000)) * 1000,
  ).toISOString();

  if (!planId || !planName || !Number.isFinite(amountMinor) || amountMinor < 0) {
    return null;
  }

  return {
    sessionId: session.id,
    userId,
    email: getCreatorHubStripeCheckoutEmail(session),
    requestId: normalizeMailConfigValue(metadata.ch_request_id),
    profession: normalizeMailConfigValue(metadata.ch_profession),
    planId,
    planName,
    billingCycle,
    amountMinor,
    amountMajor,
    currency,
    paymentCompleted: isCreatorHubStripeSessionPaid(session),
    checkoutStatus: deriveCreatorHubCheckoutStatus(session),
    paymentTimestamp: null,
    transactionId: null,
    stripeSubscriptionId: getStripeCheckoutSessionSubscriptionId(session) || null,
    stripeCustomerId: getStripeCheckoutSessionCustomerId(session) || null,
    createdAt,
    updatedAt: createdAt,
  };
}

async function writeCreatorHubStripeCheckoutSessionRecord(
  record: CreatorHubStripeCheckoutSessionRecord,
) {
  await compatStoreSet(creatorHubStripeCheckoutSessionKey(record.sessionId), record);
  if (record.stripeSubscriptionId) {
    await compatStoreSet(
      creatorHubStripeSubscriptionKey(record.stripeSubscriptionId),
      record,
    );
  }
}

async function readCreatorHubStripeCheckoutSessionRecord(
  sessionId: string,
): Promise<CreatorHubStripeCheckoutSessionRecord | null> {
  return compatStoreGet<CreatorHubStripeCheckoutSessionRecord>(
    creatorHubStripeCheckoutSessionKey(sessionId),
  );
}

async function readCreatorHubStripeCheckoutRecordBySubscriptionId(
  subscriptionId: string,
): Promise<CreatorHubStripeCheckoutSessionRecord | null> {
  const cached = await compatStoreGet<CreatorHubStripeCheckoutSessionRecord>(
    creatorHubStripeSubscriptionKey(subscriptionId),
  );
  if (cached) {
    return cached;
  }

  const allRecords = await compatStoreListByPrefix<CreatorHubStripeCheckoutSessionRecord>(
    CREATORHUB_STRIPE_CHECKOUT_RECORD_PREFIX,
  );
  const matched =
    allRecords
      .map((entry) => entry.value)
      .find((entry) => entry.stripeSubscriptionId === subscriptionId) || null;

  if (matched?.stripeSubscriptionId) {
    await compatStoreSet(
      creatorHubStripeSubscriptionKey(matched.stripeSubscriptionId),
      matched,
    );
  }

  return matched;
}

function toCreatorHubRecipientName(
  record: Record<string, unknown> | null | undefined,
  email: string | null,
) {
  const fullName =
    readString(record?.full_name) ||
    readString(record?.display_name) ||
    readString(record?.name) ||
    [readString(record?.first_name), readString(record?.last_name)]
      .filter(Boolean)
      .join(" ")
      .trim();
  if (fullName) {
    return fullName;
  }

  const emailLocalPart = normalizeMailConfigValue(email).split("@")[0] || "";
  if (!emailLocalPart) {
    return "CreatorHub-medlem";
  }

  return emailLocalPart
    .split(/[._-]+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(" ");
}

async function resolveCreatorHubBillingRecipientContext(
  record: CreatorHubStripeCheckoutSessionRecord,
) {
  const normalizedEmail = normalizeMailConfigValue(record.email).toLowerCase() || null;
  let matchedRecord: Record<string, unknown> | null = null;

  if (normalizedEmail) {
    matchedRecord = await getCreatorhubUserByEmail(normalizedEmail).catch(
      () => null,
    );
  }

  if (
    !matchedRecord &&
    isPersistableCompatUserId(record.userId) &&
    (await hasTable("users"))
  ) {
    const result = await pool
      .query(
        `SELECT *
         FROM users
         WHERE id::text = $1
         LIMIT 1`,
        [record.userId],
      )
      .catch(() => ({ rows: [] as Array<Record<string, unknown>> }));
    matchedRecord = (result.rows[0] as Record<string, unknown> | undefined) || null;
  }

  if (!matchedRecord && normalizedEmail && (await hasTable("users"))) {
    const result = await pool
      .query(
        `SELECT *
         FROM users
         WHERE LOWER(COALESCE(email, '')) = LOWER($1)
         LIMIT 1`,
        [normalizedEmail],
      )
      .catch(() => ({ rows: [] as Array<Record<string, unknown>> }));
    matchedRecord = (result.rows[0] as Record<string, unknown> | undefined) || null;
  }

  return {
    email: normalizedEmail,
    recipientName: toCreatorHubRecipientName(matchedRecord, normalizedEmail),
  };
}

async function markCreatorHubStripeCheckoutRecordPaid(
  record: CreatorHubStripeCheckoutSessionRecord,
  input: {
    transactionId: string;
    completedAt: string;
    amountMinor: number;
    amountMajor: number;
    stripeSubscriptionId?: string | null;
    stripeCustomerId?: string | null;
  },
) {
  const nowIso = new Date().toISOString();
  const wasPaymentFailed = record.checkoutStatus === "payment_failed";
  const wasPendingPayment = !record.paymentCompleted;
  const nextRecord: CreatorHubStripeCheckoutSessionRecord = {
    ...record,
    amountMinor: input.amountMinor,
    amountMajor: input.amountMajor,
    paymentCompleted: true,
    checkoutStatus: "completed",
    paymentTimestamp: record.paymentTimestamp || input.completedAt,
    transactionId: input.transactionId,
    stripeSubscriptionId:
      input.stripeSubscriptionId || record.stripeSubscriptionId,
    stripeCustomerId: input.stripeCustomerId || record.stripeCustomerId,
    updatedAt: nowIso,
  };

  await writeCreatorHubStripeCheckoutSessionRecord(nextRecord);

  const existingPaymentRecord =
    (await findCompatPaymentStatusRecord(input.transactionId)) ||
    (record.transactionId
      ? await findCompatPaymentStatusRecord(record.transactionId)
      : null) ||
    (await readCompatPaymentStatusRecord(`pay_${record.sessionId}`));

  const compatRecord: CompatPaymentStatusRecord = {
    id: existingPaymentRecord?.id || `pay_${record.sessionId}`,
    transactionId: input.transactionId,
    userId: nextRecord.userId,
    email: nextRecord.email,
    requestId: nextRecord.requestId,
    planId: nextRecord.planId,
    planName: nextRecord.planName,
    amountMinor: input.amountMinor,
    amountMajor: input.amountMajor,
    currency: nextRecord.currency,
    paymentMethod: "stripe",
    status: "completed",
    createdAt: existingPaymentRecord?.createdAt || nextRecord.createdAt,
    completedAt: nextRecord.paymentTimestamp,
    provider: "stripe",
    metadata: {
      ...(existingPaymentRecord?.metadata || {}),
      profession: nextRecord.profession,
      requestId: nextRecord.requestId,
      billingCycle: nextRecord.billingCycle,
      stripeSessionId: nextRecord.sessionId,
      stripeSubscriptionId: nextRecord.stripeSubscriptionId,
      stripeCustomerId: nextRecord.stripeCustomerId,
    },
    receiptSentAt: existingPaymentRecord?.receiptSentAt || null,
    membershipCard: existingPaymentRecord?.membershipCard || null,
  };

  await recordCompatPaymentCompletion(compatRecord);

  if (nextRecord.email && (wasPaymentFailed || wasPendingPayment)) {
    const recipient = await resolveCreatorHubBillingRecipientContext(nextRecord);
    if (recipient.email) {
      const mailOptions = {
        recipientEmail: recipient.email,
        recipientName: recipient.recipientName,
        planName: nextRecord.planName,
        amountMajor: nextRecord.amountMajor,
        currency: nextRecord.currency,
        billingCycle: nextRecord.billingCycle,
        creatorHubUrl: getDefaultCreatorHubPublicOrigin(),
      } as const;

      if (wasPaymentFailed) {
        await sendCreatorHubPaymentRecoveredEmail(mailOptions).catch((error) => {
          console.error("CreatorHub payment recovery email failed:", error);
        });
      } else {
        await sendCreatorHubPaymentConfirmedEmail(mailOptions).catch((error) => {
          console.error("CreatorHub payment confirmation email failed:", error);
        });
        await sendCreatorHubAccountActivatedEmail(mailOptions).catch((error) => {
          console.error("CreatorHub account activated email failed:", error);
        });
      }
    }
  }

  return nextRecord;
}

async function markCreatorHubStripeCheckoutRecordPaymentFailed(
  record: CreatorHubStripeCheckoutSessionRecord,
  input: {
    transactionId: string;
    stripeSubscriptionId?: string | null;
    stripeCustomerId?: string | null;
    failureMessage?: string | null;
  },
  options?: {
    suppressFailureEmail?: boolean;
  },
) {
  const nowIso = new Date().toISOString();
  const alreadyFailed = record.checkoutStatus === "payment_failed";
  const nextRecord: CreatorHubStripeCheckoutSessionRecord = {
    ...record,
    paymentCompleted: false,
    checkoutStatus: "payment_failed",
    transactionId: input.transactionId || record.transactionId,
    stripeSubscriptionId:
      input.stripeSubscriptionId || record.stripeSubscriptionId,
    stripeCustomerId: input.stripeCustomerId || record.stripeCustomerId,
    updatedAt: nowIso,
  };

  await writeCreatorHubStripeCheckoutSessionRecord(nextRecord);

  const existingPaymentRecord =
    (await findCompatPaymentStatusRecord(input.transactionId)) ||
    (record.transactionId
      ? await findCompatPaymentStatusRecord(record.transactionId)
      : null) ||
    (await readCompatPaymentStatusRecord(`pay_${record.sessionId}`));

  await writeCompatPaymentStatusRecord({
    id: existingPaymentRecord?.id || `pay_${record.sessionId}`,
    transactionId: input.transactionId || record.transactionId || record.sessionId,
    userId: nextRecord.userId,
    email: nextRecord.email,
    requestId: nextRecord.requestId,
    planId: nextRecord.planId,
    planName: nextRecord.planName,
    amountMinor: nextRecord.amountMinor,
    amountMajor: nextRecord.amountMajor,
    currency: nextRecord.currency,
    paymentMethod: "stripe",
    status: existingPaymentRecord?.status === "refunded" ? "refunded" : "failed",
    createdAt: existingPaymentRecord?.createdAt || nextRecord.createdAt,
    completedAt:
      existingPaymentRecord?.status === "refunded"
        ? existingPaymentRecord?.completedAt || null
        : null,
    provider: "stripe",
    metadata: {
      ...(existingPaymentRecord?.metadata || {}),
      profession: nextRecord.profession,
      requestId: nextRecord.requestId,
      billingCycle: nextRecord.billingCycle,
      stripeSessionId: nextRecord.sessionId,
      stripeSubscriptionId: nextRecord.stripeSubscriptionId,
      stripeCustomerId: nextRecord.stripeCustomerId,
      failureMessage: input.failureMessage || null,
    },
    receiptSentAt: existingPaymentRecord?.receiptSentAt || null,
    membershipCard: existingPaymentRecord?.membershipCard || null,
    refundReason: existingPaymentRecord?.refundReason || null,
    refundedAt: existingPaymentRecord?.refundedAt || null,
    stripeRefundId: existingPaymentRecord?.stripeRefundId || null,
  });

  const plan = getCompatPlatformSubscriptionPlan(nextRecord.planId);
  const existingSubscriptionStatus =
    nextRecord.userId && nextRecord.userId !== "guest"
      ? await readCompatSubscriptionStatus(nextRecord.userId)
      : null;
  if (plan && nextRecord.userId) {
    await writeCompatSubscriptionStatus(
      nextRecord.userId,
      buildCompatSubscriptionStatus(nextRecord.userId, plan, {
        ...(existingSubscriptionStatus || {}),
        selectedPlan: plan.id,
        planName: plan.displayName,
        amount: nextRecord.amountMajor,
        currency: nextRecord.currency,
        subscriptionSelected: true,
        paymentCompleted: false,
        transactionId:
          input.transactionId || nextRecord.transactionId || existingSubscriptionStatus?.transactionId || null,
        email: nextRecord.email,
        autoRenew: true,
        source: "compat",
      }),
    );
  }

  if (!options?.suppressFailureEmail && !alreadyFailed && nextRecord.email) {
    const recipient = await resolveCreatorHubBillingRecipientContext(nextRecord);
    if (recipient.email) {
      await sendCreatorHubPaymentFailedEmail({
        recipientEmail: recipient.email,
        recipientName: recipient.recipientName,
        planName: nextRecord.planName,
        amountMajor: nextRecord.amountMajor,
        currency: nextRecord.currency,
        billingCycle: nextRecord.billingCycle,
        creatorHubUrl: getDefaultCreatorHubPublicOrigin(),
        failureMessage: input.failureMessage,
      }).catch((error) => {
        console.error("CreatorHub payment failed email failed:", error);
      });
    }
  }

  return nextRecord;
}

async function syncCreatorHubStripeCheckoutSession(
  session: Stripe.Checkout.Session,
) {
  const derived = deriveCreatorHubStripeCheckoutRecordFromSession(session);
  if (!derived) {
    return null;
  }

  const nowIso = new Date().toISOString();
  const existing = await readCreatorHubStripeCheckoutSessionRecord(session.id);
  const transactionId =
    getStripeCheckoutSessionTransactionId(session) ||
    existing?.transactionId ||
    session.id;
  const paymentCompleted = isCreatorHubStripeSessionPaid(session);
  const paymentTimestamp = paymentCompleted
    ? existing?.paymentTimestamp || nowIso
    : existing?.paymentTimestamp || null;

  const record: CreatorHubStripeCheckoutSessionRecord = {
    ...existing,
    ...derived,
    transactionId,
    paymentCompleted,
    checkoutStatus: deriveCreatorHubCheckoutStatus(session),
    paymentTimestamp,
    stripeSubscriptionId:
      getStripeCheckoutSessionSubscriptionId(session) ||
      existing?.stripeSubscriptionId ||
      null,
    stripeCustomerId:
      getStripeCheckoutSessionCustomerId(session) ||
      existing?.stripeCustomerId ||
      null,
    createdAt: existing?.createdAt || derived.createdAt,
    updatedAt: nowIso,
  };

  await writeCreatorHubStripeCheckoutSessionRecord(record);

  if (!paymentCompleted) {
    return record;
  }

  return markCreatorHubStripeCheckoutRecordPaid(record, {
    transactionId,
    completedAt: paymentTimestamp || nowIso,
    amountMinor: record.amountMinor,
    amountMajor: record.amountMajor,
    stripeSubscriptionId: record.stripeSubscriptionId,
    stripeCustomerId: record.stripeCustomerId,
  });
}

function getStripeInvoicePaymentIntent(
  invoice: Stripe.Invoice,
): string | Stripe.PaymentIntent | null {
  const paymentIntent = (invoice as Stripe.Invoice & {
    payment_intent?: string | Stripe.PaymentIntent | null;
  }).payment_intent;
  return paymentIntent || null;
}

function getCreatorHubStripeInvoiceTransactionId(invoice: Stripe.Invoice) {
  const subscriptionId = getStripeInvoiceSubscriptionId(invoice);
  if (subscriptionId) {
    return subscriptionId;
  }

  const paymentIntent = getStripeInvoicePaymentIntent(invoice);
  if (typeof paymentIntent === "string") {
    return paymentIntent;
  }
  if (paymentIntent && typeof paymentIntent === "object" && "id" in paymentIntent) {
    return String(paymentIntent.id || "");
  }
  return invoice.id;
}

function getCreatorHubStripeInvoiceFailureMessage(invoice: unknown) {
  const paymentError = normalizeMailConfigValue(
    (invoice as { last_payment_error?: { message?: string | null } | null })
      .last_payment_error?.message,
  );
  if (paymentError) {
    return paymentError;
  }

  return "Stripe klarte ikke å gjennomføre betalingen. Oppdater betalingsinformasjonen i CreatorHub for å fortsette abonnementet.";
}

async function syncCreatorHubStripeInvoice(invoice: Stripe.Invoice) {
  const subscriptionId = getStripeInvoiceSubscriptionId(invoice);
  if (!subscriptionId) {
    return null;
  }

  const storedRecord =
    await readCreatorHubStripeCheckoutRecordBySubscriptionId(subscriptionId);
  if (!storedRecord) {
    return null;
  }

  const amountMinor =
    typeof invoice.amount_paid === "number" && Number.isFinite(invoice.amount_paid)
      ? invoice.amount_paid
      : storedRecord.amountMinor;
  const amountMajor =
    typeof invoice.amount_paid === "number" && Number.isFinite(invoice.amount_paid)
      ? invoice.amount_paid / 100
      : storedRecord.amountMajor;
  const customerId =
    (typeof invoice.customer === "string"
      ? invoice.customer
      : invoice.customer && typeof invoice.customer === "object"
        ? String(invoice.customer.id || "")
        : "") || storedRecord.stripeCustomerId;

  return markCreatorHubStripeCheckoutRecordPaid(storedRecord, {
    transactionId: getCreatorHubStripeInvoiceTransactionId(invoice),
    completedAt: new Date().toISOString(),
    amountMinor,
    amountMajor,
    stripeSubscriptionId: subscriptionId,
    stripeCustomerId: customerId,
  });
}

async function clearCreatorHubStripeSubscription(
  source: Stripe.Invoice | Stripe.Subscription,
  options?: {
    suppressFailureEmail?: boolean;
    suppressCancellationEmail?: boolean;
    failureMessage?: string | null;
  },
) {
  const subscriptionId =
    "subscription" in source
      ? getStripeInvoiceSubscriptionId(source)
      : source.id;
  if (!subscriptionId) {
    return null;
  }

  const storedRecord =
    await readCreatorHubStripeCheckoutRecordBySubscriptionId(subscriptionId);
  if (!storedRecord) {
    return null;
  }

  const customerId =
    "customer" in source
      ? typeof source.customer === "string"
        ? source.customer
        : source.customer && typeof source.customer === "object"
          ? String(source.customer.id || "")
          : ""
      : "";
  const failureMessage =
    options?.failureMessage ||
    ("subscription" in source
      ? getCreatorHubStripeInvoiceFailureMessage(source)
      : "Abonnementet ble avsluttet i Stripe. Oppdater betalingsinformasjonen i CreatorHub for å gjenoppta tilgangen.");

  const isSubscriptionDeletedEvent = !("subscription" in source);
  const clearedRecord = await markCreatorHubStripeCheckoutRecordPaymentFailed(
    storedRecord,
    {
      transactionId: subscriptionId,
      stripeSubscriptionId: subscriptionId,
      stripeCustomerId: customerId || storedRecord.stripeCustomerId,
      failureMessage,
    },
    {
      suppressFailureEmail:
        options?.suppressFailureEmail === true || isSubscriptionDeletedEvent,
    },
  );

  if (
    isSubscriptionDeletedEvent &&
    options?.suppressCancellationEmail !== true &&
    storedRecord.email
  ) {
    const recipient = await resolveCreatorHubBillingRecipientContext(storedRecord);
    if (recipient.email) {
      await sendCreatorHubSubscriptionCancelledEmail({
        recipientEmail: recipient.email,
        recipientName: recipient.recipientName,
        planName: storedRecord.planName,
        creatorHubUrl: getDefaultCreatorHubPublicOrigin(),
      }).catch((error) => {
        console.error("CreatorHub subscription cancelled email failed:", error);
      });
    }
  }

  return clearedRecord;
}

function isRoleRoomStripeSessionPaid(session: Stripe.Checkout.Session) {
  if (session.payment_status === "paid") {
    return true;
  }

  const subscription = session.subscription;
  if (subscription && typeof subscription === "object" && "status" in subscription) {
    return (
      subscription.status === "active" || subscription.status === "trialing"
    );
  }

  return false;
}

function deriveRoleRoomCommercialCheckoutRecordFromStripeSession(
  session: Stripe.Checkout.Session,
): RoleRoomCommercialCheckoutSessionRecord | null {
  const metadata = session.metadata || {};
  const persona = normalizeRoleRoomCommercialPersona(metadata.rr_persona);
  const organizationNumber = String(metadata.rr_org_number || "").replace(
    /\D/g,
    "",
  );
  const planId = normalizeMailConfigValue(metadata.rr_plan_id);
  const planName = normalizeMailConfigValue(metadata.rr_plan_name);
  const teamLeadEmail = normalizeMailConfigValue(
    metadata.rr_team_lead_email,
  ).toLowerCase();
  const companyName = normalizeMailConfigValue(metadata.rr_company_name);
  const monthlyTotalExVat = Number(metadata.rr_monthly_total_ex_vat || 0);
  const seatPriceExVat = Number(metadata.rr_seat_price_ex_vat || 0);
  const billableSeatCount = Number(metadata.rr_billable_seat_count || 0);

  if (
    !persona ||
    !organizationNumber ||
    !planId ||
    !planName ||
    !teamLeadEmail ||
    !Number.isFinite(monthlyTotalExVat) ||
    monthlyTotalExVat <= 0
  ) {
    return null;
  }

  const memberEmails = normalizeMailConfigValue(metadata.rr_member_emails)
    .split(",")
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);

  const createdAt = new Date(
    (session.created || Math.floor(Date.now() / 1000)) * 1000,
  ).toISOString();

  return {
    sessionId: session.id,
    requestIds: [],
    organizationNumber,
    companyName,
    persona,
    planId,
    planName,
    teamLeadEmail,
    memberEmails,
    monthlyTotalExVat,
    seatPriceExVat:
      Number.isFinite(seatPriceExVat) && seatPriceExVat > 0
        ? seatPriceExVat
        : monthlyTotalExVat,
    billableSeatCount:
      Number.isFinite(billableSeatCount) && billableSeatCount > 0
        ? billableSeatCount
        : 1,
    paymentCompleted: isRoleRoomStripeSessionPaid(session),
    checkoutStatus: isRoleRoomStripeSessionPaid(session)
      ? "completed"
      : "created",
    paymentTimestamp: null,
    transactionId: null,
    stripeSubscriptionId: getStripeCheckoutSessionSubscriptionId(session) || null,
    stripeCustomerId: getStripeCheckoutSessionCustomerId(session) || null,
    createdAt,
    updatedAt: createdAt,
  };
}

async function getRoleRoomCommercialInviteRequestsForBillingRecord(
  record: RoleRoomCommercialCheckoutSessionRecord,
) {
  if (!(await hasTable("invite_requests"))) {
    return [] as Record<string, unknown>[];
  }

  if (record.requestIds.length > 0) {
    const result = await pool.query(
      `SELECT *
       FROM invite_requests
       WHERE id::text = ANY($1::text[])`,
      [record.requestIds],
    );
    return result.rows as Record<string, unknown>[];
  }

  const result = await pool.query(
    `SELECT *
     FROM invite_requests
     WHERE organization_number = $1
       AND LOWER(COALESCE(source, '')) = 'role_room'
       AND LOWER(COALESCE(selected_plan, '')) = LOWER($2)
     ORDER BY created_at DESC`,
    [record.organizationNumber, record.planId],
  );

  return (result.rows as Record<string, unknown>[]).filter((row) => {
    const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
    if (!snapshot) {
      return false;
    }
    return (
      snapshot.persona === record.persona &&
      snapshot.teamLeadEmail === record.teamLeadEmail &&
      snapshot.organizationNumber === record.organizationNumber &&
      snapshot.subscriptionType === record.planId &&
      typeof snapshot.monthlyTotalExVat === "number" &&
      Math.abs(snapshot.monthlyTotalExVat - record.monthlyTotalExVat) < 0.0001
    );
  });
}

async function markRoleRoomCommercialCheckoutRecordPaid(
  record: RoleRoomCommercialCheckoutSessionRecord,
  input: {
    transactionId: string;
    completedAt: string;
    amountMajor: number;
    stripeSubscriptionId?: string | null;
    stripeCustomerId?: string | null;
    latestInvoiceId?: string | null;
    latestInvoiceStatus?: string | null;
  },
) {
  const inviteRequests =
    await getRoleRoomCommercialInviteRequestsForBillingRecord(record);

  const requestIds: string[] = [];
  const refreshedInviteRequests: Record<string, unknown>[] = [];
  for (const inviteRequest of inviteRequests) {
    const requestId = toAdminString(inviteRequest.id);
    const email = toAdminString(inviteRequest.email);
    if (!requestId && !email) {
      continue;
    }

    const activationState = getRoleRoomCommercialActivationStatus(inviteRequest);
    const journeyStatus = activationState.approved
      ? ROLE_ROOM_ACTIVATED_JOURNEY_STATUS
      : ROLE_ROOM_ACTIVATION_REQUIRED_JOURNEY_STATUS;

    const updated = await updateInviteRequestPaymentState({
      requestId,
      email,
      userId: "guest",
      planId: record.planId,
      planName: record.planName,
      amountMajor: input.amountMajor,
      transactionId: input.transactionId,
      completedAt: input.completedAt,
      journeyStatus,
      status: "approved",
    });

    const provisioned = updated
      ? await ensureInviteRequestAccessProvisioning(updated, {
          journeyStatus,
          isActive: true,
        }).catch((error) => {
          console.error(
            "Role Room commercial access provisioning failed after payment:",
            error,
          );
          return null;
        })
      : null;

    const refreshedInvite =
      provisioned && updated?.id
        ? ((await pool
            .query("SELECT * FROM invite_requests WHERE id = $1 LIMIT 1", [
              updated.id,
            ])
            .then((result) => result.rows[0] || updated)
            .catch(() => updated)) as Record<string, unknown>)
        : ((updated || inviteRequest) as Record<string, unknown>);
    const billingUpdatedInvite = await updateRoleRoomCommercialInviteBillingSnapshot(
      refreshedInvite,
      {
        billingStatus: "active",
        stripeSubscriptionId:
          input.stripeSubscriptionId || record.stripeSubscriptionId || null,
        stripeCustomerId:
          input.stripeCustomerId || record.stripeCustomerId || null,
        latestInvoiceId: input.latestInvoiceId || null,
        latestInvoiceStatus: input.latestInvoiceStatus || "paid",
        paymentFailedAt: null,
        paymentFailureMessage: null,
        paymentPendingSince: null,
        paymentReminderCount: 0,
        paymentReminderLastSentAt: null,
        paymentReminderProvider: null,
        paymentReminderMessageId: null,
      },
    );

    const updatedId = toAdminString(billingUpdatedInvite?.id) || requestId;
    if (updatedId) {
      requestIds.push(updatedId);
    }
    refreshedInviteRequests.push(billingUpdatedInvite);
  }

  const nextRecord: RoleRoomCommercialCheckoutSessionRecord = {
    ...record,
    requestIds: requestIds.length > 0 ? requestIds : record.requestIds,
    paymentCompleted: true,
    checkoutStatus: "completed",
    paymentTimestamp: input.completedAt,
    transactionId: input.transactionId,
    stripeSubscriptionId:
      input.stripeSubscriptionId || record.stripeSubscriptionId,
    stripeCustomerId: input.stripeCustomerId || record.stripeCustomerId,
    updatedAt: new Date().toISOString(),
  };
  await writeRoleRoomCommercialCheckoutSessionRecord(nextRecord);
  if (record.checkoutStatus === "payment_failed") {
    await sendRoleRoomCommercialPaymentRecoveryEmail({
      companyName: record.companyName,
      planName: record.planName,
      recipientEmail: record.teamLeadEmail,
      recipientName: record.teamLeadEmail.split("@")[0] || "Role Room-teamleder",
      organizationNumber: record.organizationNumber,
      monthlyTotalExVat: input.amountMajor,
      memberCount: record.billableSeatCount,
      roleRoomUrl: getDefaultRoleRoomPublicOrigin(),
    }).catch((error) => {
      console.error(
        "Role Room commercial payment recovery email failed:",
        error,
      );
    });
  }
  await ensureRoleRoomCommercialActivationEmails(
    nextRecord,
    refreshedInviteRequests.length > 0 ? refreshedInviteRequests : inviteRequests,
  );
  return nextRecord;
}

async function markRoleRoomCommercialCheckoutRecordPending(
  record: RoleRoomCommercialCheckoutSessionRecord,
  options?: {
    billingStatus?: RoleRoomCommercialBillingStatus;
    latestInvoiceId?: string | null;
    latestInvoiceStatus?: string | null;
    paymentFailureMessage?: string | null;
    paymentFailedAt?: string | null;
  },
) {
  const inviteRequests =
    await getRoleRoomCommercialInviteRequestsForBillingRecord(record);

  const requestIds: string[] = [];
  for (const inviteRequest of inviteRequests) {
    const requestId = toAdminString(inviteRequest.id);
    if (!requestId) {
      continue;
    }
    await resetRoleRoomCommercialInvitePaymentState(requestId, "role_room_pending_payment", {
      billingStatus: options?.billingStatus || "pending_payment",
      stripeSubscriptionId: record.stripeSubscriptionId,
      stripeCustomerId: record.stripeCustomerId,
      latestInvoiceId: options?.latestInvoiceId || null,
      latestInvoiceStatus: options?.latestInvoiceStatus || null,
      paymentFailureMessage: options?.paymentFailureMessage || null,
      paymentFailedAt: options?.paymentFailedAt || null,
    });
    requestIds.push(requestId);
  }

  const nextRecord: RoleRoomCommercialCheckoutSessionRecord = {
    ...record,
    requestIds: requestIds.length > 0 ? requestIds : record.requestIds,
    paymentCompleted: false,
    checkoutStatus:
      options?.billingStatus === "payment_failed" ? "payment_failed" : "created",
    paymentTimestamp: null,
    transactionId: null,
    updatedAt: new Date().toISOString(),
  };
  await writeRoleRoomCommercialCheckoutSessionRecord(nextRecord);
  return nextRecord;
}

async function syncRoleRoomCommercialStripeCheckoutSession(
  session: Stripe.Checkout.Session,
  completedAtOverride?: string | null,
) {
  const storedRecord =
    (await readRoleRoomCommercialCheckoutSessionRecord(session.id)) ||
    deriveRoleRoomCommercialCheckoutRecordFromStripeSession(session);

  if (!storedRecord) {
    return null;
  }

  if (!isRoleRoomStripeSessionPaid(session)) {
    await writeRoleRoomCommercialCheckoutSessionRecord({
      ...storedRecord,
      stripeSubscriptionId:
        getStripeCheckoutSessionSubscriptionId(session) ||
        storedRecord.stripeSubscriptionId,
      stripeCustomerId:
        getStripeCheckoutSessionCustomerId(session) || storedRecord.stripeCustomerId,
      updatedAt: new Date().toISOString(),
    });
    return storedRecord;
  }

  return markRoleRoomCommercialCheckoutRecordPaid(storedRecord, {
    transactionId: getStripeCheckoutSessionTransactionId(session),
    completedAt: completedAtOverride || new Date().toISOString(),
    amountMajor: storedRecord.monthlyTotalExVat,
    stripeSubscriptionId:
      getStripeCheckoutSessionSubscriptionId(session) ||
      storedRecord.stripeSubscriptionId,
    stripeCustomerId:
      getStripeCheckoutSessionCustomerId(session) || storedRecord.stripeCustomerId,
  });
}

async function syncRoleRoomCommercialStripeInvoice(
  invoice: Stripe.Invoice,
  completedAtOverride?: string | null,
) {
  const subscriptionId = getStripeInvoiceSubscriptionId(invoice);
  if (!subscriptionId) {
    return null;
  }

  const storedRecord =
    await readRoleRoomCommercialCheckoutRecordBySubscriptionId(subscriptionId);
  if (!storedRecord) {
    return null;
  }

  return markRoleRoomCommercialCheckoutRecordPaid(storedRecord, {
    transactionId: subscriptionId,
    completedAt: completedAtOverride || new Date().toISOString(),
    amountMajor:
      typeof invoice.amount_paid === "number" && Number.isFinite(invoice.amount_paid)
        ? invoice.amount_paid / 100
        : storedRecord.monthlyTotalExVat,
    stripeSubscriptionId: subscriptionId,
    stripeCustomerId:
      (typeof invoice.customer === "string"
        ? invoice.customer
        : invoice.customer && typeof invoice.customer === "object"
          ? String(invoice.customer.id || "")
          : "") || storedRecord.stripeCustomerId,
    latestInvoiceId: invoice.id,
    latestInvoiceStatus: invoice.status || "paid",
  });
}

async function clearRoleRoomCommercialStripeSubscription(
  source: Stripe.Invoice | Stripe.Subscription,
) {
  const subscriptionId =
    "subscription" in source
      ? getStripeInvoiceSubscriptionId(source)
      : source.id;

  if (!subscriptionId) {
    return null;
  }

  const storedRecord =
    await readRoleRoomCommercialCheckoutRecordBySubscriptionId(subscriptionId);
  if (!storedRecord) {
    return null;
  }

  const failureMessage =
    "status_transitions" in source
      ? "Stripe registrerte manglende betaling på abonnementet. Oppdater betalingsinformasjonen for å fortsette."
      : "Abonnementet ble avsluttet i Stripe. Oppdater betalingsinformasjonen for å gjenoppta tilgangen.";
  const clearedRecord = await markRoleRoomCommercialCheckoutRecordPending(
    storedRecord,
    {
      billingStatus: "payment_failed",
      latestInvoiceId: "id" in source ? String(source.id || "") : null,
      latestInvoiceStatus:
        "status" in source && typeof source.status === "string"
          ? source.status
          : null,
      paymentFailureMessage: failureMessage,
      paymentFailedAt: new Date().toISOString(),
    },
  );

  await sendRoleRoomCommercialPaymentFailedEmail({
    companyName: storedRecord.companyName,
    planName: storedRecord.planName,
    recipientEmail: storedRecord.teamLeadEmail,
    recipientName: storedRecord.teamLeadEmail.split("@")[0] || "Role Room-teamleder",
    organizationNumber: storedRecord.organizationNumber,
    monthlyTotalExVat: storedRecord.monthlyTotalExVat,
    memberCount: storedRecord.billableSeatCount,
    roleRoomUrl: getDefaultRoleRoomPublicOrigin(),
    failureMessage,
  }).catch((error) => {
    console.error("Role Room commercial payment failure email failed:", error);
  });

  return clearedRecord;
}

async function ensureRoleRoomCommercialAccess(input: {
  persona: unknown;
  organizationNumber: unknown;
  companyName?: unknown;
  teamMembers?: unknown;
}) {
  const persona = normalizeRoleRoomCommercialPersona(input.persona);
  if (!persona) {
    throw new RoleRoomCommercialAccessError(
      400,
      "persona må være production_team eller content_producer",
    );
  }

  const organizationNumber = String(input.organizationNumber || "").replace(
    /\D/g,
    "",
  );
  if (!isValidNorwegianOrgNumber(organizationNumber)) {
    throw new RoleRoomCommercialAccessError(
      400,
      "Organisasjonsnummer må være et gyldig norsk organisasjonsnummer.",
    );
  }

  const brregLookup = await lookupInviteRequestBrregCompany(organizationNumber);
  if (brregLookup.lookupStatus === "not_found") {
    throw new RoleRoomCommercialAccessError(
      400,
      "Organisasjonsnummeret ble ikke funnet i Brønnøysundregistrene.",
    );
  }

  const plan = getRoleRoomCommercialPlan(persona);
  const membersRaw = Array.isArray(input.teamMembers)
    ? (input.teamMembers as Array<Record<string, unknown>>)
    : [];

  const normalizedMembers = membersRaw
    .map((entry, index) => {
      const name = toAdminString(entry?.name)?.trim() || "";
      const email = toAdminString(entry?.email)?.trim().toLowerCase() || "";
      const roleId = toAdminString(entry?.roleId)?.trim() || "";
      const roleLabel = toAdminString(entry?.roleLabel)?.trim() || null;
      if (!name || !email || !roleId) {
        return null;
      }
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return null;
      }
      return {
        name,
        email,
        roleId,
        roleLabel,
        isLeader: entry?.isLeader === true || index === 0,
      } satisfies RoleRoomCommercialAccessPayloadMember;
    })
    .filter(
      (entry): entry is RoleRoomCommercialAccessPayloadMember => Boolean(entry),
    );

  const dedupedMembers = Array.from(
    new Map(
      normalizedMembers.map((member) => [member.email, member] as const),
    ).values(),
  );

  if (dedupedMembers.length < plan.minimumSeats) {
    throw new RoleRoomCommercialAccessError(
      400,
      persona === "production_team"
        ? "Produksjonsteam må ha minst 3 personer."
        : "Innholdsprodusent må ha minst 1 person.",
    );
  }

  const companyName =
    brregLookup.company?.name?.trim() ||
    toAdminString(input.companyName)?.trim() ||
    `Foretak ${organizationNumber}`;
  const teamLead =
    dedupedMembers.find((member) => member.isLeader) || dedupedMembers[0];
  const monthlyTotalExVat = dedupedMembers.length * plan.seatPriceExVat;
  const requests: Record<string, unknown>[] = [];
  let currentSetupPaid = true;
  const pendingPaymentStartedAt = new Date().toISOString();

  for (const member of dedupedMembers) {
    const existingInvite = await findAdminInviteRequest(member.email, member.email);
    const existingSnapshot = parseRoleRoomCommercialAccessSnapshot(
      existingInvite?.message,
    );
    const currentPaymentCompleted = doesRoleRoomCommercialPaymentMatchCurrentSetup(
      {
        inviteRequest: existingInvite,
        planId: plan.planId,
        monthlyTotalExVat,
      },
    );
    const existingStatus = toAdminString(existingInvite?.status);
    const existingJourneyStatus = toAdminString(existingInvite?.user_journey_status);
    const { firstName, lastName } = splitRoleRoomContactName(member.name);

    if (existingInvite?.id && Boolean(existingInvite.payment_completed) && !currentPaymentCompleted) {
      await resetRoleRoomCommercialInvitePaymentState(String(existingInvite.id));
    }

    const preservePendingState = shouldPreserveRoleRoomCommercialPendingPaymentState(
      {
        existingSnapshot,
        inviteRequest: existingInvite,
        planId: plan.planId,
        organizationNumber,
        teamLeadEmail: teamLead.email,
        teamSize: dedupedMembers.length,
        monthlyTotalExVat,
      },
    );

    const serializedMetadata = buildRoleRoomCommercialInviteMessage({
      persona,
      plan,
      companyName,
      organizationNumber,
      teamLead,
      members: dedupedMembers,
      member,
      monthlyTotalExVat,
      existingSnapshot,
      payment: currentPaymentCompleted
        ? {
            pendingSince: null,
            reminderCount: 0,
            reminderLastSentAt: null,
            reminderProvider: null,
            reminderMessageId: null,
          }
        : {
            pendingSince:
              preservePendingState && existingSnapshot?.paymentPendingSince
                ? existingSnapshot.paymentPendingSince
                : pendingPaymentStartedAt,
            reminderCount: preservePendingState
              ? existingSnapshot?.paymentReminderCount ?? 0
              : 0,
            reminderLastSentAt: preservePendingState
              ? existingSnapshot?.paymentReminderLastSentAt ?? null
              : null,
            reminderProvider: preservePendingState
              ? existingSnapshot?.paymentReminderProvider ?? null
              : null,
            reminderMessageId: preservePendingState
              ? existingSnapshot?.paymentReminderMessageId ?? null
              : null,
          },
    });

    const inviteRequest = await upsertAdminInviteRequest({
      email: member.email,
      firstName,
      lastName,
      profession: member.roleId,
      businessName: companyName,
      organizationNumber,
      status:
        currentPaymentCompleted && existingStatus ? existingStatus : "pending",
      userJourneyStatus: currentPaymentCompleted
        ? existingJourneyStatus || "role_room_payment_completed"
        : "role_room_pending_payment",
      source: "role_room",
      selectedPlan: plan.planId,
      planName: plan.planName,
      planPrice: monthlyTotalExVat,
      paymentCompleted: currentPaymentCompleted,
      message: serializedMetadata,
    });

    if (!currentPaymentCompleted) {
      currentSetupPaid = false;
    }
    requests.push((inviteRequest as Record<string, unknown> | null) || {});
  }

  return {
    persona,
    organizationNumber,
    companyName,
    plan,
    teamLead,
    members: dedupedMembers,
    monthlyTotalExVat,
    paymentCompleted:
      currentSetupPaid && requests.length === dedupedMembers.length,
    requestIds: requests
      .map((request) => toAdminString(request.id))
      .filter((value): value is string => Boolean(value)),
    requests,
  } satisfies RoleRoomCommercialAccessResult;
}

