async function sendRoleRoomEducationInquiryAdminEmail(options: {
  requestId: string;
  companyName: string;
  organizationNumber: string;
  contactName: string;
  contactEmail: string;
  metadata: RoleRoomEducationInquiryMetadata;
}) {
  const transporter = getRoleRoomEducationInquiryMailer();
  if (!transporter) {
    return {
      sent: false,
      reason: "missing_email_config",
      accepted: [] as string[],
    };
  }

  const adminEmail =
    normalizeMailConfigValue(process.env.GOOGLE_ADMIN_EMAIL) ||
    "daniel@creatorhubn.com";
  const fromEmail =
    normalizeMailConfigValue(process.env.GMAIL_USER) ||
    normalizeMailConfigValue(process.env.GOOGLE_WORKSPACE_EMAIL) ||
    adminEmail;

  const { metadata } = options;
  const rendered = await renderRoleRoomPlatformEmail({
    templateId: "role_room_education_inquiry_admin",
    variables: {
      requestId: options.requestId,
      companyName: options.companyName,
      organizationNumber: options.organizationNumber,
      contactName: options.contactName,
      contactEmail: options.contactEmail,
      contactRole: metadata.contactRole,
      institutionTypeLabel: metadata.institutionTypeLabel,
      programName: metadata.programName,
      studentSeatLabel: metadata.studentSeatLabel,
      staffSeatLabel: metadata.staffSeatLabel,
      desiredStartWindowLabel: metadata.desiredStartWindowLabel,
      useCase: metadata.useCase,
    },
    replyToEmail: options.contactEmail,
    detailRows: [
      { label: "Forespørsel-ID", value: options.requestId },
      { label: "Institusjon", value: options.companyName },
      { label: "Organisasjonsnummer", value: options.organizationNumber },
      { label: "Kontaktperson", value: options.contactName },
      { label: "Stilling", value: metadata.contactRole },
      { label: "E-post", value: options.contactEmail },
      { label: "Institusjonstype", value: metadata.institutionTypeLabel },
      { label: "Studieprogram", value: metadata.programName },
      { label: "Studentomfang", value: metadata.studentSeatLabel },
      { label: "Faglærere / koordinatorer", value: metadata.staffSeatLabel },
      { label: "Ønsket oppstart", value: metadata.desiredStartWindowLabel },
    ],
    noticeSection: {
      label: "Bruksområde",
      body: metadata.useCase,
      tone: "neutral",
    },
  });

  const gmailSender = await resolveRoleRoomEducationInquiryGmailSender().catch(
    (error) => {
      console.error(
        "Role Room education inquiry Gmail API sender lookup failed:",
        error,
      );
      return null;
    },
  );

  if (gmailSender) {
    const gmail = google.gmail({
      version: "v1",
      auth: gmailSender.authorized.oauthClient,
    });

    const response = await gmail.users.messages.send({
      userId: "me",
      requestBody: {
        raw: await buildGmailRawMessage({
          to: gmailSender.adminEmail,
          from: `CreatorHub Norge <${gmailSender.senderEmail}>`,
          replyTo: options.contactEmail,
          subject: rendered.subject,
          text: rendered.text,
          html: rendered.html,
        }),
      },
    });

    return {
      sent: true,
      reason: null,
      accepted: [gmailSender.adminEmail],
      provider: "gmail_api",
      messageId: normalizeMailConfigValue(response.data.id),
    };
  }

  const info = await transporter.sendMail({
    from: `CreatorHub Norge <${fromEmail}>`,
    to: adminEmail,
    replyTo: options.contactEmail,
    subject: rendered.subject,
    text: rendered.text,
    html: rendered.html,
  });

  return {
    sent: true,
    reason: null,
    accepted: Array.isArray(info.accepted)
      ? info.accepted.map((value) => String(value))
      : [],
    provider: "smtp",
    messageId: normalizeMailConfigValue(info.messageId),
  };
}

async function updateRoleRoomCommercialInviteRecord(input: {
  inviteRequest: Record<string, unknown>;
  message?: string | null;
  journeyStatus?: string | null;
  status?: string | null;
  processed?: boolean;
}) {
  const inviteRequestId = toAdminString(input.inviteRequest.id);
  if (!inviteRequestId || !(await hasTable("invite_requests"))) {
    return input.inviteRequest;
  }

  const inviteColumns = await getTableColumns("invite_requests");
  const updates: string[] = [];
  const values: unknown[] = [];
  const pushValue = (column: string, value: unknown) => {
    values.push(value);
    updates.push(`${column} = $${values.length}`);
  };

  if (inviteColumns.has("message") && input.message !== undefined) {
    pushValue("message", input.message);
  }
  if (
    inviteColumns.has("user_journey_status") &&
    input.journeyStatus !== undefined
  ) {
    pushValue("user_journey_status", input.journeyStatus);
  }
  if (inviteColumns.has("status") && input.status !== undefined) {
    pushValue("status", input.status);
  }
  if (inviteColumns.has("processed_at") && input.processed) {
    updates.push("processed_at = COALESCE(processed_at, NOW())");
  }
  if (inviteColumns.has("updated_at")) {
    updates.push("updated_at = NOW()");
  }

  if (updates.length === 0) {
    return input.inviteRequest;
  }

  values.push(inviteRequestId);
  const result = await pool.query(
    `UPDATE invite_requests
     SET ${updates.join(", ")}
     WHERE id = $${values.length}
     RETURNING *`,
    values,
  );

  return (result.rows[0] as Record<string, unknown> | undefined) || input.inviteRequest;
}

async function updateRoleRoomCommercialInviteBillingSnapshot(
  inviteRequest: Record<string, unknown>,
  input: {
    billingStatus?: RoleRoomCommercialBillingStatus | null;
    stripeSubscriptionId?: string | null;
    stripeCustomerId?: string | null;
    latestInvoiceId?: string | null;
    latestInvoiceStatus?: string | null;
    paymentFailedAt?: string | null;
    paymentFailureMessage?: string | null;
    paymentPendingSince?: string | null;
    paymentReminderCount?: number | null;
    paymentReminderLastSentAt?: string | null;
    paymentReminderProvider?: string | null;
    paymentReminderMessageId?: string | null;
  },
) {
  const snapshot = parseRoleRoomCommercialAccessSnapshot(inviteRequest.message);
  if (!snapshot) {
    return inviteRequest;
  }

  return updateRoleRoomCommercialInviteRecord({
    inviteRequest,
    message: serializeRoleRoomCommercialAccessSnapshot({
      ...snapshot,
      billingStatus:
        input.billingStatus === undefined
          ? snapshot.billingStatus
          : input.billingStatus,
      stripeSubscriptionId:
        input.stripeSubscriptionId === undefined
          ? snapshot.stripeSubscriptionId
          : input.stripeSubscriptionId,
      stripeCustomerId:
        input.stripeCustomerId === undefined
          ? snapshot.stripeCustomerId
          : input.stripeCustomerId,
      latestInvoiceId:
        input.latestInvoiceId === undefined
          ? snapshot.latestInvoiceId
          : input.latestInvoiceId,
      latestInvoiceStatus:
        input.latestInvoiceStatus === undefined
          ? snapshot.latestInvoiceStatus
          : input.latestInvoiceStatus,
      paymentFailedAt:
        input.paymentFailedAt === undefined
          ? snapshot.paymentFailedAt
          : input.paymentFailedAt,
      paymentFailureMessage:
        input.paymentFailureMessage === undefined
          ? snapshot.paymentFailureMessage
          : input.paymentFailureMessage,
      paymentPendingSince:
        input.paymentPendingSince === undefined
          ? snapshot.paymentPendingSince
          : input.paymentPendingSince,
      paymentReminderCount:
        input.paymentReminderCount === undefined
          ? snapshot.paymentReminderCount
          : Math.max(0, input.paymentReminderCount || 0),
      paymentReminderLastSentAt:
        input.paymentReminderLastSentAt === undefined
          ? snapshot.paymentReminderLastSentAt
          : input.paymentReminderLastSentAt,
      paymentReminderProvider:
        input.paymentReminderProvider === undefined
          ? snapshot.paymentReminderProvider
          : input.paymentReminderProvider,
      paymentReminderMessageId:
        input.paymentReminderMessageId === undefined
          ? snapshot.paymentReminderMessageId
          : input.paymentReminderMessageId,
    }),
  });
}

