async function ensureRoleRoomCommercialActivationEmails(
  record: RoleRoomCommercialCheckoutSessionRecord,
  inviteRequests: Record<string, unknown>[],
  options?: {
    forceResend?: boolean;
    isReminder?: boolean;
  },
) {
  const results: Array<{
    inviteRequestId: string | null;
    email: string;
    sent: boolean;
    provider: string | null;
    messageId: string | null;
  }> = [];

  for (const inviteRequest of inviteRequests) {
    const snapshot = parseRoleRoomCommercialAccessSnapshot(inviteRequest.message);
    const activationState = getRoleRoomCommercialActivationStatus(inviteRequest);
    const inviteEmail =
      toAdminString(inviteRequest.email)?.trim().toLowerCase() ||
      snapshot?.memberEmail ||
      "";

    if (!inviteEmail || activationState.approved) {
      continue;
    }

    if (
      !options?.forceResend &&
      activationState.pendingApproval &&
      activationState.emailSent
    ) {
      continue;
    }

    const member =
      snapshot?.members.find((entry) => entry.email === inviteEmail) || {
        name:
          `${toAdminString(inviteRequest.first_name) || ""} ${toAdminString(inviteRequest.last_name) || ""}`.trim() ||
          inviteEmail.split("@")[0] ||
          "Role Room-medlem",
        email: inviteEmail,
        roleId:
          snapshot?.memberRoleId ||
          toAdminString(inviteRequest.profession) ||
          "team_member",
        roleLabel:
          snapshot?.memberRoleLabel ||
          toAdminString(inviteRequest.profession) ||
          "Teammedlem",
        isLeader:
          snapshot?.memberIsLeader === true ||
          snapshot?.teamLeadEmail === inviteEmail,
      };

    const plan = getRoleRoomCommercialPlan(record.persona);
    const token = generateRoleRoomActivationToken();
    const tokenHash = hashRoleRoomActivationToken(token);
    const tokenExpiresAt = new Date(
      Date.now() + ROLE_ROOM_ACTIVATION_TOKEN_TTL_MS,
    ).toISOString();
    const paymentClearedState = {
      pendingSince: null,
      reminderCount: 0,
      reminderLastSentAt: null,
      reminderProvider: null,
      reminderMessageId: null,
    } as const;
    const preparedMessage = buildRoleRoomCommercialInviteMessage({
      persona: record.persona,
      plan,
      companyName: record.companyName,
      organizationNumber: record.organizationNumber,
      teamLead:
        snapshot?.members.find((entry) => entry.isLeader) || member,
      members:
        snapshot?.members.length && snapshot.members.length > 0
          ? snapshot.members
          : [member],
      member,
      monthlyTotalExVat: record.monthlyTotalExVat,
      existingSnapshot: snapshot,
      payment: paymentClearedState,
      activation: {
        status: "pending_approval",
        tokenHash,
        tokenExpiresAt,
        approvedAt: null,
        emailSentAt: null,
        emailProvider: null,
        emailMessageId: null,
      },
    });

    const preparedInvite = await updateRoleRoomCommercialInviteRecord({
      inviteRequest,
      message: preparedMessage,
      journeyStatus: ROLE_ROOM_ACTIVATION_REQUIRED_JOURNEY_STATUS,
      status: "approved",
      processed: true,
    });
    const activationUrl = buildRoleRoomActivationUrl({
      token,
      browserOrigin: getDefaultRoleRoomPublicOrigin(),
      returnPath: "/",
    });

    let emailResult:
      | Awaited<ReturnType<typeof sendRoleRoomCommercialActivationEmail>>
      | null = null;
    try {
      emailResult = await sendRoleRoomCommercialActivationEmail({
        companyName: record.companyName,
        planName: record.planName,
        recipientEmail: inviteEmail,
        recipientName: member.name,
        activationUrl,
        memberRoleLabel: member.roleLabel,
        isLeader: member.isLeader,
        monthlyTotalExVat: record.monthlyTotalExVat,
        isReminder: options?.isReminder === true,
      });
    } catch (error) {
      console.error("Role Room commercial activation email failed:", error);
    }

    const reminderSentAt =
      options?.isReminder === true && emailResult?.sent
        ? new Date().toISOString()
        : null;
    const activationEmailSentAt =
      emailResult?.sent
        ? new Date().toISOString()
        : snapshot?.activationEmailSentAt || null;
    const activationTokenHash =
      emailResult?.sent || !snapshot?.activationTokenHash
        ? tokenHash
        : snapshot.activationTokenHash;
    const activationTokenExpiresAt =
      emailResult?.sent || !snapshot?.activationTokenHash
        ? tokenExpiresAt
        : snapshot?.activationTokenExpiresAt || null;

    const finalMessage = buildRoleRoomCommercialInviteMessage({
      persona: record.persona,
      plan,
      companyName: record.companyName,
      organizationNumber: record.organizationNumber,
      teamLead:
        snapshot?.members.find((entry) => entry.isLeader) || member,
      members:
        snapshot?.members.length && snapshot.members.length > 0
          ? snapshot.members
          : [member],
      member,
      monthlyTotalExVat: record.monthlyTotalExVat,
      existingSnapshot: parseRoleRoomCommercialAccessSnapshot(
        preparedInvite.message,
      ),
      payment: paymentClearedState,
      activation: {
        status: "pending_approval",
        tokenHash: activationTokenHash,
        tokenExpiresAt: activationTokenExpiresAt,
        approvedAt: null,
        emailSentAt: activationEmailSentAt,
        emailProvider:
          emailResult?.sent
            ? emailResult?.provider || null
            : snapshot?.activationEmailProvider || null,
        emailMessageId:
          emailResult?.sent
            ? emailResult?.messageId || null
            : snapshot?.activationEmailMessageId || null,
      },
      activationReminder:
        options?.isReminder === true
          ? {
              count:
                (snapshot?.activationReminderCount || 0) +
                (emailResult?.sent ? 1 : 0),
              lastSentAt:
                reminderSentAt || snapshot?.activationReminderLastSentAt || null,
              provider:
                emailResult?.sent
                  ? emailResult?.provider || null
                  : snapshot?.activationReminderProvider || null,
              messageId:
                emailResult?.sent
                  ? emailResult?.messageId || null
                  : snapshot?.activationReminderMessageId || null,
            }
          : undefined,
    });

    await updateRoleRoomCommercialInviteRecord({
      inviteRequest: preparedInvite,
      message: finalMessage,
      journeyStatus: ROLE_ROOM_ACTIVATION_REQUIRED_JOURNEY_STATUS,
      status: "approved",
      processed: true,
    });

    results.push({
      inviteRequestId: toAdminString(inviteRequest.id),
      email: inviteEmail,
      sent: Boolean(emailResult?.sent),
      provider: emailResult?.provider || null,
      messageId: emailResult?.messageId || null,
    });
  }

  return results;
}

function compareRoleRoomInviteRowsByRecency(
  left: Record<string, unknown>,
  right: Record<string, unknown>,
) {
  const leftTime =
    Date.parse(
      toAdminString(left.updated_at) || toAdminString(left.created_at) || "",
    ) || 0;
  const rightTime =
    Date.parse(
      toAdminString(right.updated_at) || toAdminString(right.created_at) || "",
    ) || 0;

  return rightTime - leftTime;
}

function buildRoleRoomCommercialReminderTeamKey(
  snapshot: RoleRoomCommercialAccessSnapshot,
) {
  return [
    snapshot.persona || "",
    snapshot.organizationNumber || "",
    snapshot.subscriptionType || "",
    snapshot.teamLeadEmail || "",
    snapshot.monthlyTotalExVat || 0,
  ].join("::");
}

function buildRoleRoomCommercialReminderActivationKey(
  inviteRequest: Record<string, unknown>,
  snapshot: RoleRoomCommercialAccessSnapshot,
) {
  return [
    toAdminString(inviteRequest.email)?.trim().toLowerCase() || "",
    snapshot.organizationNumber || "",
    snapshot.subscriptionType || "",
  ].join("::");
}

async function listRoleRoomCommercialReminderInviteRequests() {
  if (!(await hasTable("invite_requests"))) {
    return [] as Record<string, unknown>[];
  }

  const inviteColumns = await getTableColumns("invite_requests");
  const selectColumns =
    inviteColumns.size > 0 ? Array.from(inviteColumns).join(", ") : "*";
  const clauses: string[] = [];
  const orderBy = [
    inviteColumns.has("updated_at")
      ? "updated_at DESC NULLS LAST"
      : inviteColumns.has("created_at")
        ? "created_at DESC NULLS LAST"
        : null,
    inviteColumns.has("created_at") ? "created_at DESC NULLS LAST" : null,
    "email ASC",
  ]
    .filter(Boolean)
    .join(", ");
  if (inviteColumns.has("source")) {
    clauses.push("LOWER(COALESCE(source, '')) = 'role_room'");
  }
  const result = await pool.query(
    `SELECT ${selectColumns}
     FROM invite_requests${
       clauses.length > 0 ? ` WHERE ${clauses.join(" AND ")}` : ""
     }
     ORDER BY ${orderBy}`,
  );

  return (result.rows as Record<string, unknown>[]).filter((row) => {
    const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
    return Boolean(
      snapshot && normalizeRoleRoomCommercialPersona(snapshot.persona) != null,
    );
  });
}

function buildRoleRoomCommercialCheckoutRecordFromInviteRequest(
  inviteRequest: Record<string, unknown>,
) {
  const snapshot = parseRoleRoomCommercialAccessSnapshot(inviteRequest.message);
  const persona = normalizeRoleRoomCommercialPersona(snapshot?.persona);
  if (!snapshot || !persona) {
    return null;
  }

  const plan = getRoleRoomCommercialPlan(persona);
  const createdAt =
    toAdminString(inviteRequest.created_at) || new Date().toISOString();
  const updatedAt = toAdminString(inviteRequest.updated_at) || createdAt;
  const memberEmails =
    snapshot.members.length > 0
      ? snapshot.members.map((entry) => entry.email)
      : [
          snapshot.memberEmail ||
            toAdminString(inviteRequest.email)?.trim().toLowerCase() ||
            "",
        ].filter(Boolean);

  return {
    sessionId: `invite:${toAdminString(inviteRequest.id) || snapshot.memberEmail || crypto.randomUUID()}`,
    requestIds: [toAdminString(inviteRequest.id)].filter(
      (value): value is string => Boolean(value),
    ),
    organizationNumber:
      snapshot.organizationNumber ||
      toAdminString(inviteRequest.organization_number) ||
      "",
    companyName:
      snapshot.companyName ||
      toAdminString(inviteRequest.company_name) ||
      "The Role Room",
    persona,
    planId: snapshot.subscriptionType || plan.planId,
    planName: snapshot.subscriptionLabel || plan.planName,
    teamLeadEmail:
      snapshot.teamLeadEmail ||
      memberEmails[0] ||
      toAdminString(inviteRequest.email)?.trim().toLowerCase() ||
      "",
    memberEmails,
    monthlyTotalExVat:
      snapshot.monthlyTotalExVat ||
      Number(inviteRequest.payment_amount || inviteRequest.plan_price || 0),
    seatPriceExVat: snapshot.seatPriceExVat || plan.seatPriceExVat,
    billableSeatCount: snapshot.teamSize || memberEmails.length || 1,
    paymentCompleted: Boolean(inviteRequest.payment_completed),
    checkoutStatus: Boolean(inviteRequest.payment_completed)
      ? "completed"
      : snapshot.billingStatus === "payment_failed"
        ? "payment_failed"
        : "created",
    paymentTimestamp: toAdminString(inviteRequest.payment_timestamp),
    transactionId: toAdminString(inviteRequest.payment_transaction_id),
    stripeSubscriptionId:
      snapshot.stripeSubscriptionId ||
      toAdminString(inviteRequest.payment_transaction_id),
    stripeCustomerId: snapshot.stripeCustomerId || null,
    createdAt,
    updatedAt,
  } satisfies RoleRoomCommercialCheckoutSessionRecord;
}

function expandRoleRoomCommercialCheckoutRecordWithTeamRows(
  record: RoleRoomCommercialCheckoutSessionRecord | null,
  snapshot: RoleRoomCommercialAccessSnapshot | null,
  teamRows: Record<string, unknown>[],
) {
  if (!record || !snapshot) {
    return record;
  }

  const requestIds = teamRows
    .map((row) => toAdminString(row.id))
    .filter((value): value is string => Boolean(value));
  const latestUpdatedAt = teamRows
    .map((row) => Date.parse(toAdminString(row.updated_at) || ""))
    .filter((value) => Number.isFinite(value))
    .sort((left, right) => right - left)[0];

  return {
    ...record,
    requestIds: requestIds.length > 0 ? requestIds : record.requestIds,
    memberEmails:
      snapshot.members.length > 0
        ? snapshot.members.map((member) => member.email)
        : record.memberEmails,
    updatedAt: latestUpdatedAt
      ? new Date(latestUpdatedAt).toISOString()
      : record.updatedAt,
  } satisfies RoleRoomCommercialCheckoutSessionRecord;
}

type RoleRoomCommercialRequestIdentity = {
  userId: string | null;
  email: string | null;
  role: string | null;
  loginAs: string | null;
  requestedRole: string | null;
};

type RoleRoomCommercialResolvedAccount = {
  identity: RoleRoomCommercialRequestIdentity;
  currentRow: Record<string, unknown>;
  leaderRow: Record<string, unknown>;
  teamRows: Record<string, unknown>[];
  snapshot: RoleRoomCommercialAccessSnapshot;
  currentMember: RoleRoomCommercialAccessMemberSnapshot | null;
  teamLeadMember: RoleRoomCommercialAccessMemberSnapshot | null;
  record: RoleRoomCommercialCheckoutSessionRecord | null;
  paymentStatus: RoleRoomCommercialBillingStatus;
  subscriptionStatus: string | null;
  stripeSubscriptionId: string | null;
  stripeCustomerId: string | null;
  latestInvoiceId: string | null;
  latestInvoiceStatus: string | null;
  nextPaymentAttemptAt: string | null;
};

function readRoleRoomCommercialRequestIdentity(
  req: express.Request,
): RoleRoomCommercialRequestIdentity {
  const session = getActiveSessionFromRequest(req);
  const readHeaderValue = (headerName: string) => {
    const raw = req.headers[headerName.toLowerCase()];
    const value = Array.isArray(raw) ? raw[0] : raw;
    return typeof value === "string" && value.trim().length > 0
      ? value.trim()
      : null;
  };

  const sessionEmail = normalizeMailConfigValue(session?.email).toLowerCase();

  return {
    userId:
      normalizeMailConfigValue(session?.userId) ||
      readHeaderValue("x-role-room-user-id") ||
      readHeaderValue("x-user-id") ||
      null,
    email:
      sessionEmail ||
      normalizeMailConfigValue(readHeaderValue("x-role-room-email")).toLowerCase() ||
      null,
    role:
      normalizeMailConfigValue(session?.role) ||
      readHeaderValue("x-role-room-role") ||
      null,
    loginAs:
      normalizeMailConfigValue(session?.loginAs) ||
      readHeaderValue("x-role-room-login-as") ||
      null,
    requestedRole:
      normalizeMailConfigValue(session?.requestedRole) ||
      readHeaderValue("x-role-room-requested-role") ||
      null,
  };
}

function scoreRoleRoomCommercialInviteRow(row: Record<string, unknown>) {
  const paymentCompleted = Boolean(row.payment_completed) ? 1000 : 0;
  const updatedAt = Date.parse(toAdminString(row.updated_at) || "") || 0;
  const createdAt = Date.parse(toAdminString(row.created_at) || "") || 0;
  return paymentCompleted + Math.max(updatedAt, createdAt);
}

function deriveRoleRoomCommercialPaymentStatus(input: {
  snapshot: RoleRoomCommercialAccessSnapshot;
  rowPaymentCompleted: boolean;
  record: RoleRoomCommercialCheckoutSessionRecord | null;
  subscriptionStatus: string | null;
  latestInvoiceStatus: string | null;
}) {
  if (
    input.subscriptionStatus &&
    ["past_due", "unpaid", "incomplete", "incomplete_expired", "canceled"].includes(
      input.subscriptionStatus,
    )
  ) {
    return "payment_failed" as const;
  }

  if (
    input.latestInvoiceStatus &&
    ["open", "uncollectible", "void"].includes(input.latestInvoiceStatus)
  ) {
    return "payment_failed" as const;
  }

  if (input.rowPaymentCompleted || input.record?.paymentCompleted) {
    return "active" as const;
  }

  if (
    input.snapshot.billingStatus === "payment_failed" ||
    Boolean(input.snapshot.stripeSubscriptionId) ||
    input.record?.checkoutStatus === "payment_failed"
  ) {
    return "payment_failed" as const;
  }

  return "pending_payment" as const;
}

function getStripeInvoiceSubscriptionId(invoice: unknown) {
  const invoiceRecord = isRecord(invoice) ? invoice : {};
  const subscription = invoiceRecord.subscription;
  if (typeof subscription === "string" && subscription.trim()) {
    return subscription;
  }

  if (
    subscription &&
    typeof subscription === "object" &&
    "id" in subscription &&
    typeof subscription.id === "string" &&
    subscription.id.trim()
  ) {
    return subscription.id;
  }

  const parent = invoiceRecord.parent;
  const parentSubscription =
    parent &&
    typeof parent === "object" &&
    "subscription_details" in parent &&
    parent.subscription_details &&
    typeof parent.subscription_details === "object" &&
    "subscription" in parent.subscription_details
      ? parent.subscription_details.subscription
      : null;
  if (typeof parentSubscription === "string" && parentSubscription.trim()) {
    return parentSubscription;
  }

  const linesRecord = invoiceRecord.lines;
  const lines =
    linesRecord &&
    typeof linesRecord === "object" &&
    "data" in linesRecord &&
    Array.isArray(linesRecord.data)
      ? linesRecord.data
      : [];
  for (const line of lines) {
    const lineParent =
      line && typeof line === "object" && "parent" in line ? line.parent : null;
    if (!lineParent || typeof lineParent !== "object") {
      continue;
    }

    if (
      "subscription_item_details" in lineParent &&
      lineParent.subscription_item_details &&
      typeof lineParent.subscription_item_details === "object" &&
      typeof lineParent.subscription_item_details.subscription === "string" &&
      lineParent.subscription_item_details.subscription.trim()
    ) {
      return lineParent.subscription_item_details.subscription;
    }

    if (
      "license_fee_subscription_details" in lineParent &&
      lineParent.license_fee_subscription_details &&
      typeof lineParent.license_fee_subscription_details === "object" &&
      typeof lineParent.license_fee_subscription_details.subscription === "string" &&
      lineParent.license_fee_subscription_details.subscription.trim()
    ) {
      return lineParent.license_fee_subscription_details.subscription;
    }
  }

  return "";
}

const resolveStripeCustomerForCastingProject: ProjectCustomerResolver = async (
  projectId,
) => {
  try {
    const ownerResult = await pool.query<{ email: string | null }>(
      `SELECT LOWER(COALESCE(u.email, '')) AS email
         FROM casting_projects cp
         LEFT JOIN users u ON u.id::text = cp.created_by
        WHERE cp.id = $1
        LIMIT 1`,
      [projectId],
    );
    const ownerEmail = ownerResult.rows[0]?.email?.trim() || "";
    if (!ownerEmail) return { stripeCustomerId: null };

    const allRows = await listRoleRoomCommercialReminderInviteRequests();
    for (const row of allRows) {
      const rowEmail = toAdminString(row.email)?.trim().toLowerCase() || "";
      if (rowEmail !== ownerEmail) continue;
      const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
      const customerId = snapshot?.stripeCustomerId?.trim() || "";
      if (customerId) return { stripeCustomerId: customerId };
    }
    return { stripeCustomerId: null };
  } catch (error) {
    console.warn("[casting-sms-invoice] customer resolve failed", {
      projectId,
      error: error instanceof Error ? error.message : String(error),
    });
    return { stripeCustomerId: null };
  }
};

async function resolveRoleRoomCommercialAccountForRequest(
  req: express.Request,
): Promise<RoleRoomCommercialResolvedAccount | null> {
  const identity = readRoleRoomCommercialRequestIdentity(req);
  if (!identity.userId && !identity.email) {
    return null;
  }

  const allRows = await listRoleRoomCommercialReminderInviteRequests();
  const candidateRows = allRows
    .filter((row) => {
      const rowEmail = toAdminString(row.email)?.trim().toLowerCase() || "";
      const registeredUserId = toAdminString(row.registered_user_id);
      return (
        (identity.email && rowEmail === identity.email) ||
        (identity.userId && registeredUserId === identity.userId)
      );
    })
    .sort((left, right) => scoreRoleRoomCommercialInviteRow(right) - scoreRoleRoomCommercialInviteRow(left));

  const currentRow = candidateRows.find((row) =>
    Boolean(parseRoleRoomCommercialAccessSnapshot(row.message)),
  );
  if (!currentRow) {
    return null;
  }

  const snapshot = parseRoleRoomCommercialAccessSnapshot(currentRow.message);
  if (!snapshot) {
    return null;
  }

  const teamKey = buildRoleRoomCommercialReminderTeamKey(snapshot);
  const teamRows = allRows.filter((row) => {
    const rowSnapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
    return rowSnapshot && buildRoleRoomCommercialReminderTeamKey(rowSnapshot) === teamKey;
  });
  const leaderRow =
    teamRows.find((row) => {
      const rowEmail = toAdminString(row.email)?.trim().toLowerCase() || "";
      return snapshot.teamLeadEmail && rowEmail === snapshot.teamLeadEmail;
    }) || currentRow;

  const currentEmail =
    identity.email ||
    toAdminString(currentRow.email)?.trim().toLowerCase() ||
    snapshot.memberEmail ||
    null;
  const currentMember =
    snapshot.members.find((member) => member.email === currentEmail) || null;
  const teamLeadMember =
    snapshot.members.find((member) => member.isLeader) ||
    (snapshot.teamLeadEmail
      ? snapshot.members.find((member) => member.email === snapshot.teamLeadEmail) ||
        null
      : null);

  const record = expandRoleRoomCommercialCheckoutRecordWithTeamRows(
    buildRoleRoomCommercialCheckoutRecordFromInviteRequest(leaderRow),
    snapshot,
    teamRows,
  );
  const stripe = getRoleRoomStripeClient();

  let subscriptionStatus: string | null = null;
  let stripeSubscriptionId =
    snapshot.stripeSubscriptionId || record?.stripeSubscriptionId || null;
  let stripeCustomerId =
    snapshot.stripeCustomerId || record?.stripeCustomerId || null;
  let latestInvoiceId = snapshot.latestInvoiceId || null;
  let latestInvoiceStatus = snapshot.latestInvoiceStatus || null;
  let nextPaymentAttemptAt: string | null = null;

  if (stripe && stripeSubscriptionId) {
    try {
      const subscription = await stripe.subscriptions.retrieve(stripeSubscriptionId, {
        expand: ["latest_invoice"],
      });
      subscriptionStatus = subscription.status || null;
      stripeCustomerId =
        stripeCustomerId ||
        (typeof subscription.customer === "string"
          ? subscription.customer
          : subscription.customer && typeof subscription.customer === "object"
            ? String(subscription.customer.id || "")
            : null);
      if (subscription.latest_invoice) {
        if (typeof subscription.latest_invoice === "string") {
          latestInvoiceId = subscription.latest_invoice;
        } else if (typeof subscription.latest_invoice === "object") {
          latestInvoiceId = String(subscription.latest_invoice.id || "") || latestInvoiceId;
          latestInvoiceStatus = subscription.latest_invoice.status || latestInvoiceStatus;
          const nextPaymentAttempt = subscription.latest_invoice.next_payment_attempt;
          if (typeof nextPaymentAttempt === "number" && Number.isFinite(nextPaymentAttempt)) {
            nextPaymentAttemptAt = new Date(nextPaymentAttempt * 1000).toISOString();
          }
        }
      }
    } catch (error) {
      console.error("Role Room commercial subscription lookup failed:", error);
    }
  }

  return {
    identity,
    currentRow,
    leaderRow,
    teamRows,
    snapshot,
    currentMember,
    teamLeadMember,
    record,
    paymentStatus: deriveRoleRoomCommercialPaymentStatus({
      snapshot,
      rowPaymentCompleted: Boolean(currentRow.payment_completed),
      record,
      subscriptionStatus,
      latestInvoiceStatus,
    }),
    subscriptionStatus,
    stripeSubscriptionId,
    stripeCustomerId,
    latestInvoiceId,
    latestInvoiceStatus,
    nextPaymentAttemptAt,
  };
}

async function writeRoleRoomCommercialReminderStatus(
  summary: RoleRoomCommercialReminderSweepSummary,
) {
  await compatStoreSet(ROLE_ROOM_REMINDER_STATUS_COMPAT_KEY, summary);
}

async function readRoleRoomCommercialReminderStatus() {
  return compatStoreGet<RoleRoomCommercialReminderSweepSummary>(
    ROLE_ROOM_REMINDER_STATUS_COMPAT_KEY,
  );
}

async function sendRoleRoomCommercialPaymentReminderForRows(input: {
  leaderRow: Record<string, unknown>;
  teamRows: Record<string, unknown>[];
}) {
  const snapshot = parseRoleRoomCommercialAccessSnapshot(input.leaderRow.message);
  if (!snapshot) {
    return {
      sent: false,
      reason: "missing_snapshot",
      accepted: [],
      provider: null,
      messageId: null,
    } satisfies RoleRoomCommercialReminderDeliverySummary;
  }

  const recipientEmail =
    snapshot.teamLeadEmail ||
    toAdminString(input.leaderRow.email)?.trim().toLowerCase() ||
    "";
  if (!recipientEmail) {
    return {
      sent: false,
      reason: "missing_team_lead_email",
      accepted: [],
      provider: null,
      messageId: null,
    } satisfies RoleRoomCommercialReminderDeliverySummary;
  }

  const delivery = await sendRoleRoomCommercialPaymentReminderEmail({
    companyName:
      snapshot.companyName ||
      toAdminString(input.leaderRow.company_name) ||
      "The Role Room",
    planName: snapshot.subscriptionLabel || "The Role Room",
    recipientEmail,
    recipientName:
      snapshot.teamLeadName ||
      recipientEmail.split("@")[0] ||
      "Role Room-teamleder",
    organizationNumber:
      snapshot.organizationNumber ||
      toAdminString(input.leaderRow.organization_number) ||
      "",
    monthlyTotalExVat:
      snapshot.monthlyTotalExVat ||
      Number(input.leaderRow.plan_price || input.leaderRow.payment_amount || 0),
    memberCount: snapshot.teamSize || snapshot.members.length || input.teamRows.length,
    roleRoomUrl: getDefaultRoleRoomPublicOrigin(),
  });

  if (!delivery.sent) {
    return delivery;
  }

  const sentAt = new Date().toISOString();
  for (const row of input.teamRows) {
    const rowSnapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
    if (!rowSnapshot) {
      continue;
    }

    await updateRoleRoomCommercialInviteRecord({
      inviteRequest: row,
      message: serializeRoleRoomCommercialAccessSnapshot({
        ...rowSnapshot,
        paymentReminderCount: (rowSnapshot.paymentReminderCount || 0) + 1,
        paymentReminderLastSentAt: sentAt,
        paymentReminderProvider: delivery.provider || null,
        paymentReminderMessageId: delivery.messageId || null,
      }),
    });
  }

  return delivery;
}

let roleRoomCommercialReminderSweepPromise:
  | Promise<RoleRoomCommercialReminderSweepSummary>
  | null = null;
let roleRoomCommercialReminderSchedulerStarted = false;

async function runRoleRoomCommercialReminderSweep(
  reason: "startup" | "interval" | "manual",
) {
  if (roleRoomCommercialReminderSweepPromise) {
    const current = await readRoleRoomCommercialReminderStatus();
    return (
      current || {
        ...buildRoleRoomCommercialReminderSummary(reason),
        isRunning: true,
        notes: ["En reminder-kjøring pågår allerede."],
      }
    );
  }

  const task = (async () => {
    const summary = buildRoleRoomCommercialReminderSummary(reason);
    await writeRoleRoomCommercialReminderStatus(summary);

    try {
      const rows = await listRoleRoomCommercialReminderInviteRequests();
      const paymentGroups = new Map<
        string,
        {
          latestRow: Record<string, unknown>;
          leaderRow: Record<string, unknown> | null;
          rows: Record<string, unknown>[];
        }
      >();
      const activationRows = new Map<string, Record<string, unknown>>();

      for (const row of rows) {
        const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
        if (!snapshot) {
          continue;
        }

        const normalizedEmail =
          toAdminString(row.email)?.trim().toLowerCase() || "";
        const isLeaderRow =
          snapshot.memberIsLeader === true ||
          (snapshot.teamLeadEmail || "") === normalizedEmail;

        if (!Boolean(row.payment_completed)) {
          const teamKey = buildRoleRoomCommercialReminderTeamKey(snapshot);
          const existingGroup = paymentGroups.get(teamKey);
          if (!existingGroup) {
            paymentGroups.set(teamKey, {
              latestRow: row,
              leaderRow: isLeaderRow ? row : null,
              rows: [row],
            });
          } else {
            existingGroup.rows.push(row);
            if (compareRoleRoomInviteRowsByRecency(row, existingGroup.latestRow) < 0) {
              existingGroup.latestRow = row;
            }
            if (
              isLeaderRow &&
              (!existingGroup.leaderRow ||
                compareRoleRoomInviteRowsByRecency(row, existingGroup.leaderRow) < 0)
            ) {
              existingGroup.leaderRow = row;
            }
          }
        } else {
          const activationState = getRoleRoomCommercialActivationStatus(row);
          if (!activationState.approved) {
            const activationKey = buildRoleRoomCommercialReminderActivationKey(
              row,
              snapshot,
            );
            const existingRow = activationRows.get(activationKey);
            if (
              !existingRow ||
              compareRoleRoomInviteRowsByRecency(row, existingRow) < 0
            ) {
              activationRows.set(activationKey, row);
            }
          }
        }
      }

      const paymentCandidates = Array.from(paymentGroups.values()).map((group) => ({
        leaderRow: group.leaderRow || group.latestRow,
        rows: group.rows,
      }));
      summary.paymentCandidates = paymentCandidates.length;

      for (const candidate of paymentCandidates) {
        const snapshot = parseRoleRoomCommercialAccessSnapshot(
          candidate.leaderRow.message,
        );
        if (!snapshot) {
          summary.skipped += 1;
          continue;
        }

        const due = shouldSendRoleRoomReminder({
          anchorAt: getRoleRoomCommercialPaymentPendingSince(
            candidate.leaderRow,
            snapshot,
          ),
          lastSentAt: snapshot.paymentReminderLastSentAt,
          sentCount: snapshot.paymentReminderCount,
          thresholdHours: ROLE_ROOM_PAYMENT_REMINDER_HOURS,
          repeatHours: ROLE_ROOM_PAYMENT_REMINDER_REPEAT_HOURS,
        });
        if (!due) {
          summary.skipped += 1;
          continue;
        }

        try {
          const delivery = await sendRoleRoomCommercialPaymentReminderForRows({
            leaderRow: candidate.leaderRow,
            teamRows: candidate.rows,
          });
          if (delivery.sent) {
            summary.paymentRemindersSent += 1;
          } else {
            summary.failures += 1;
            if (delivery.reason) {
              summary.notes.push(
                `Betalingspåminnelse hoppet over for ${
                  snapshot.teamLeadEmail || snapshot.companyName || "ukjent team"
                }: ${delivery.reason}`,
              );
            }
          }
        } catch (error) {
          summary.failures += 1;
          summary.notes.push(
            `Betalingspåminnelse feilet for ${
              snapshot.teamLeadEmail || snapshot.companyName || "ukjent team"
            }.`,
          );
          console.error("Role Room payment reminder sweep failed:", error);
        }
      }

      const activationCandidates = Array.from(activationRows.values());
      summary.activationCandidates = activationCandidates.length;

      for (const row of activationCandidates) {
        const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
        if (!snapshot) {
          summary.skipped += 1;
          continue;
        }
        const activationState = getRoleRoomCommercialActivationStatus(row);
        const due =
          !activationState.emailSent ||
          shouldSendRoleRoomReminder({
            anchorAt:
              snapshot.activationEmailSentAt ||
              toAdminString(row.payment_timestamp) ||
              toAdminString(row.updated_at) ||
              toAdminString(row.created_at),
            lastSentAt: snapshot.activationReminderLastSentAt,
            sentCount: snapshot.activationReminderCount,
            thresholdHours: ROLE_ROOM_ACTIVATION_REMINDER_HOURS,
            repeatHours: ROLE_ROOM_ACTIVATION_REMINDER_REPEAT_HOURS,
          });

        if (!due) {
          summary.skipped += 1;
          continue;
        }

        const record = buildRoleRoomCommercialCheckoutRecordFromInviteRequest(row);
        if (!record) {
          summary.failures += 1;
          summary.notes.push(
            `Aktiveringspåminnelse hoppet over for ${snapshot.memberEmail || toAdminString(row.email) || "ukjent bruker"}: mangler billing-kontekst.`,
          );
          continue;
        }

        try {
          const deliveries = await ensureRoleRoomCommercialActivationEmails(
            record,
            [row],
            {
              forceResend: true,
              isReminder: true,
            },
          );
          if (deliveries.some((delivery) => delivery.sent)) {
            summary.activationRemindersSent += 1;
          } else {
            summary.failures += 1;
            summary.notes.push(
              `Aktiveringspåminnelse hoppet over for ${snapshot.memberEmail || toAdminString(row.email) || "ukjent bruker"}.`,
            );
          }
        } catch (error) {
          summary.failures += 1;
          summary.notes.push(
            `Aktiveringspåminnelse feilet for ${snapshot.memberEmail || toAdminString(row.email) || "ukjent bruker"}.`,
          );
          console.error("Role Room activation reminder sweep failed:", error);
        }
      }
    } catch (error) {
      summary.failures += 1;
      summary.notes.push("Reminder-sweepen feilet på servernivå.");
      console.error("Role Room reminder sweep failed:", error);
    } finally {
      summary.isRunning = false;
      summary.finishedAt = new Date().toISOString();
      await writeRoleRoomCommercialReminderStatus(summary);
    }

    return summary;
  })();

  roleRoomCommercialReminderSweepPromise = task;
  try {
    return await task;
  } finally {
    if (roleRoomCommercialReminderSweepPromise === task) {
      roleRoomCommercialReminderSweepPromise = null;
    }
  }
}

function maybeStartRoleRoomCommercialReminderSweep() {
  if (
    roleRoomCommercialReminderSchedulerStarted ||
    !isRoleRoomReminderRunnerEnabled()
  ) {
    return;
  }

  roleRoomCommercialReminderSchedulerStarted = true;
  setTimeout(() => {
    void runRoleRoomCommercialReminderSweep("startup");
  }, 15000).unref();
  setInterval(() => {
    void runRoleRoomCommercialReminderSweep("interval");
  }, ROLE_ROOM_REMINDER_INTERVAL_MS).unref();
}

// GDPR Art. 30: retention of role_room_ai_audit_log is 365 days. A daily
// prune keeps the table size stable and ensures we never hold audit rows
// past their retention window. Safe to run concurrently with writes
// because the DELETE predicate is on created_at.
const ROLE_ROOM_AI_AUDIT_PRUNE_INTERVAL_MS = 24 * 60 * 60 * 1000;
let roleRoomAiAuditPruneStarted = false;

async function runRoleRoomAiAuditPrune(trigger: string): Promise<void> {
  try {
    const deleted = await pruneAiAuditLog(pool);
    if (deleted > 0) {
      console.log(
        `[role-room-ai-audit] Pruned ${deleted} rows older than 365 days (trigger=${trigger})`,
      );
    }
  } catch (error) {
    console.error("[role-room-ai-audit] prune failed", error);
  }
  try {
    const dropped = await pruneAgentCache(pool);
    if (dropped > 0) {
      console.log(
        `[role-room-agent-cache] Dropped ${dropped} expired rows (trigger=${trigger})`,
      );
    }
  } catch (error) {
    console.error("[role-room-agent-cache] prune failed", error);
  }
}

function maybeStartRoleRoomAiAuditPrune() {
  if (roleRoomAiAuditPruneStarted) return;
  roleRoomAiAuditPruneStarted = true;
  // Give the app ~60 s after startup to settle before the first prune.
  setTimeout(() => {
    void runRoleRoomAiAuditPrune("startup");
  }, 60_000).unref();
  setInterval(() => {
    void runRoleRoomAiAuditPrune("interval");
  }, ROLE_ROOM_AI_AUDIT_PRUNE_INTERVAL_MS).unref();
}

// Proactive daily scan — the Role Room Agent looks at every active
// project with AI consent and drops risk notifications into Innboks.
// Disabled unless ROLE_ROOM_AGENT_DAILY_SCAN_ENABLED === "true".
let roleRoomAgentDailyScanStarted = false;
const ROLE_ROOM_AGENT_DAILY_SCAN_INTERVAL_MS = 24 * 60 * 60 * 1000;

async function runRoleRoomAgentDailyScan(trigger: string): Promise<void> {
  try {
    const result = await runDailyAgentScan(pool);
    if (result.scanned > 0) {
      console.log(
        `[role-room-agent-daily-scan] Scanned ${result.scanned} projects (trigger=${trigger})`,
      );
    }
  } catch (error) {
    console.error("[role-room-agent-daily-scan] scan failed", error);
  }
}

function maybeStartRoleRoomAgentDailyScan() {
  if (roleRoomAgentDailyScanStarted) return;
  if (process.env.ROLE_ROOM_AGENT_DAILY_SCAN_ENABLED !== "true") return;
  roleRoomAgentDailyScanStarted = true;
  // Wait ~5 min after boot before the first scan so the rest of the app
  // is fully warm and we don't spike startup load.
  setTimeout(() => {
    void runRoleRoomAgentDailyScan("startup");
  }, 5 * 60 * 1000).unref();
  setInterval(() => {
    void runRoleRoomAgentDailyScan("interval");
  }, ROLE_ROOM_AGENT_DAILY_SCAN_INTERVAL_MS).unref();
}

async function findRoleRoomCommercialInviteByActivationToken(token: string) {
  if (!(await hasTable("invite_requests"))) {
    return null;
  }

  const tokenHash = hashRoleRoomActivationToken(token);
  const inviteColumns = await getTableColumns("invite_requests");
  const selectColumns =
    inviteColumns.size > 0 ? Array.from(inviteColumns).join(", ") : "*";
  const clauses: string[] = [];
  if (inviteColumns.has("payment_completed")) {
    clauses.push("payment_completed = true");
  }
  if (inviteColumns.has("source")) {
    clauses.push("LOWER(COALESCE(source, '')) = 'role_room'");
  }
  const query = `SELECT ${selectColumns} FROM invite_requests${
    clauses.length > 0 ? ` WHERE ${clauses.join(" AND ")}` : ""
  } ORDER BY updated_at DESC NULLS LAST, created_at DESC`;
  const result = await pool.query(query);

  return (
    (result.rows as Record<string, unknown>[]).find((row) => {
      const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
      return snapshot?.activationTokenHash === tokenHash;
    }) || null
  );
}

async function findLatestRoleRoomCommercialInviteRequestByEmail(email: string) {
  if (!(await hasTable("invite_requests"))) {
    return null;
  }

  const inviteColumns = await getTableColumns("invite_requests");
  const selectColumns =
    inviteColumns.size > 0 ? Array.from(inviteColumns).join(", ") : "*";
  const clauses = ["LOWER(email) = LOWER($1)"];
  if (inviteColumns.has("source")) {
    clauses.push("LOWER(COALESCE(source, '')) = 'role_room'");
  }

  const result = await pool.query(
    `SELECT ${selectColumns}
     FROM invite_requests
     WHERE ${clauses.join(" AND ")}
     ORDER BY created_at DESC`,
    [email],
  );

  return (
    (result.rows as Record<string, unknown>[]).find((row) => {
      const snapshot = parseRoleRoomCommercialAccessSnapshot(row.message);
      return Boolean(
        snapshot &&
          normalizeRoleRoomCommercialPersona(snapshot.persona) != null,
      );
    }) || null
  );
}

async function getRoleRoomCommercialLoginGate(input: {
  email: string;
  loginAs?: unknown;
  requestedRole?: unknown;
}) {
  if (
    !isRoleRoomCommercialLoginIntent({
      loginAs: input.loginAs,
      requestedRole: input.requestedRole,
    })
  ) {
    return {
      required: false,
      allowed: true,
      reason: null as string | null,
      inviteRequest: null as Record<string, unknown> | null,
    };
  }

  const inviteRequest = await findLatestRoleRoomCommercialInviteRequestByEmail(
    input.email,
  );
  const snapshot = parseRoleRoomCommercialAccessSnapshot(inviteRequest?.message);
  const isCommercialInvite =
    Boolean(snapshot) &&
    normalizeRoleRoomCommercialPersona(snapshot?.persona) != null;

  if (!inviteRequest || !isCommercialInvite) {
    return {
      required: true,
      allowed: false,
      reason:
        "Kontoen din er ikke aktivert for The Role Room. Fullfør bestilling og kontogodkjenning først.",
      inviteRequest: inviteRequest || null,
    };
  }

  if (!Boolean(inviteRequest.payment_completed)) {
    return {
      required: true,
      allowed: false,
      reason:
        "Betalingen er ikke bekreftet ennå. Fullfør Stripe-betalingen før du logger inn.",
      inviteRequest,
    };
  }

  const activationState = getRoleRoomCommercialActivationStatus(inviteRequest);
  if (!activationState.approved) {
    return {
      required: true,
      allowed: false,
      reason:
        "Sjekk e-posten din og godkjenn kontoen før første innlogging i The Role Room.",
      inviteRequest,
    };
  }

  return {
    required: true,
    allowed: true,
    reason: null as string | null,
    inviteRequest,
  };
}

