const academyPresentationIsRecord = (
  value: unknown,
): value is Record<string, unknown> =>
  Boolean(value) && typeof value === "object" && !Array.isArray(value);

const academyPresentationClamp = (
  value: number,
  min: number,
  max: number,
): number => Math.max(min, Math.min(max, value));

const academyPresentationNormalizeTemplateId = (
  value: unknown,
): AcademyPresentationTemplateId | null => {
  const normalized = String(readString(value) || "").toLowerCase();
  if (
    normalized === "product-overview" ||
    normalized === "walkthrough" ||
    normalized === "onboarding-flow" ||
    normalized === "feature-explainer" ||
    normalized === "training-deep-dive"
  ) {
    return normalized;
  }
  return null;
};

const academyPresentationNormalizeThemeId = (
  value: unknown,
): AcademyPresentationVisualThemeId | null => {
  const normalized = String(readString(value) || "").toLowerCase();
  if (
    normalized === "neutral-modern" ||
    normalized === "sales-command" ||
    normalized === "operations-grid" ||
    normalized === "offshore-briefing"
  ) {
    return normalized;
  }
  return null;
};

const academyPresentationNormalizeDisplayMode = (
  value: unknown,
): AcademyPresentationDisplayMode => {
  const normalized = String(readString(value) || "").toLowerCase();
  if (
    normalized === "picture-in-picture" ||
    normalized === "side-panel" ||
    normalized === "split-screen" ||
    normalized === "full-frame"
  ) {
    return normalized;
  }
  return "split-screen";
};

const academyPresentationNormalizeSplitLayoutVariant = (
  value: unknown,
): AcademyPresentationSplitLayoutVariant | null => {
  const normalized = String(readString(value) || "").toLowerCase();
  if (
    normalized === "balanced" ||
    normalized === "presenter-focus" ||
    normalized === "slide-focus"
  ) {
    return normalized;
  }
  return null;
};

const academyPresentationNormalizeTextLines = (value: unknown): string[] => {
  if (Array.isArray(value)) {
    return value
      .map((entry) => String(readString(entry) || "").trim())
      .filter(Boolean)
      .slice(0, 16);
  }
  return [];
};

const academyPresentationNormalizeSlideInput = (
  value: unknown,
  index: number,
): AcademyPresentationDesignSlideInput | null => {
  if (!academyPresentationIsRecord(value)) return null;

  const id = String(readString(value.id) || `slide-${index + 1}`);
  const title = String(readString(value.title) || `Slide ${index + 1}`);
  const startTime = Number(readNumber(value.startTime) || 0);
  const duration = academyPresentationClamp(
    Number(readNumber(value.duration) || 8),
    1,
    240,
  );
  const layout = academyPresentationNormalizeDisplayMode(value.layout);
  const speakerNotes = String(readString(value.speakerNotes) || "");
  const textLines = academyPresentationNormalizeTextLines(value.textLines);

  return {
    id,
    title,
    startTime,
    duration,
    layout,
    speakerNotes,
    textLines,
  };
};

const academyPresentationNormalizeVisualType = (
  value: unknown,
): AcademyPresentationVisualType | null => {
  const normalized = String(readString(value) || "").toLowerCase();
  if (
    normalized === "title" ||
    normalized === "agenda" ||
    normalized === "problem" ||
    normalized === "solution" ||
    normalized === "feature" ||
    normalized === "process" ||
    normalized === "kpi" ||
    normalized === "timeline" ||
    normalized === "roadmap" ||
    normalized === "architecture" ||
    normalized === "scenario" ||
    normalized === "knowledge-check" ||
    normalized === "comparison" ||
    normalized === "demo" ||
    normalized === "quote" ||
    normalized === "cta" ||
    normalized === "summary"
  ) {
    return normalized;
  }
  return null;
};

const academyPresentationNormalizeGraphicKind = (
  value: unknown,
): AcademyPresentationGraphicKind | null => {
  const normalized = String(readString(value) || "").toLowerCase();
  if (
    normalized === "chart" ||
    normalized === "icon" ||
    normalized === "screenshot" ||
    normalized === "illustration" ||
    normalized === "photo" ||
    normalized === "shape" ||
    normalized === "badge"
  ) {
    return normalized;
  }
  return null;
};

const academyPresentationReadStringArray = (
  value: unknown,
  maxItems = 8,
  maxLength = 180,
): string[] => {
  if (!Array.isArray(value)) return [];
  return value
    .map((entry) => String(readString(entry) || "").trim())
    .filter((entry) => entry.length > 0)
    .slice(0, maxItems)
    .map((entry) => entry.slice(0, maxLength));
};

const academyPresentationNormalizeGraphicSlots = (
  value: unknown,
  fallbackSlideId: string,
): AcademyPresentationDesignGraphicSlot[] => {
  if (!Array.isArray(value)) return [];
  return value
    .map((entry, index) => {
      if (!academyPresentationIsRecord(entry)) return null;
      const kind = academyPresentationNormalizeGraphicKind(entry.kind);
      if (!kind) return null;
      const id = String(
        readString(entry.id) || `${fallbackSlideId}-slot-${index + 1}`,
      );
      const label = String(
        readString(entry.label) || `Graphic ${index + 1}`,
      ).slice(0, 80);
      const prompt = String(readString(entry.prompt) || label).slice(0, 180);
      const x = academyPresentationClamp(
        Number(readNumber(entry.x) || 56),
        0,
        100,
      );
      const y = academyPresentationClamp(
        Number(readNumber(entry.y) || 14),
        0,
        100,
      );
      const width = academyPresentationClamp(
        Number(readNumber(entry.width) || 28),
        1,
        100,
      );
      const height = academyPresentationClamp(
        Number(readNumber(entry.height) || 18),
        1,
        100,
      );
      return {
        id,
        kind,
        label,
        prompt,
        x,
        y,
        width,
        height,
      } satisfies AcademyPresentationDesignGraphicSlot;
    })
    .filter((entry): entry is AcademyPresentationDesignGraphicSlot =>
      Boolean(entry),
    )
    .slice(0, 8);
};

const academyPresentationNormalizeGrammarId = (
  value: unknown,
): SharedAcademyPresentationSlideGrammarId | null => {
  const normalized = String(readString(value) || "").toLowerCase();
  return normalized in ACADEMY_PRESENTATION_GRAMMAR_BUDGETS
    ? (normalized as SharedAcademyPresentationSlideGrammarId)
    : null;
};

const academyPresentationNormalizeVisualNeeds = (
  value: unknown,
): SharedAcademyPresentationVisualNeed[] => {
  if (!Array.isArray(value)) return [];
  return value
    .map((entry) => {
      if (!academyPresentationIsRecord(entry)) return null;
      const kind = academyPresentationNormalizeGraphicKind(entry.kind);
      if (!kind) return null;
      const label = String(readString(entry.label) || "")
        .trim()
        .slice(0, 80);
      const prompt = String(readString(entry.prompt) || label)
        .trim()
        .slice(0, 180);
      const priorityRaw = String(
        readString(entry.priority) || "secondary",
      ).toLowerCase();
      const priority = priorityRaw === "primary" ? "primary" : "secondary";
      return {
        kind,
        label: label || "Visual",
        prompt: prompt || label || "Supporting visual",
        priority,
      } satisfies SharedAcademyPresentationVisualNeed;
    })
    .filter((entry): entry is SharedAcademyPresentationVisualNeed =>
      Boolean(entry),
    )
    .slice(0, 4);
};

const academyPresentationBuildSlidePlan = ({
  slide,
  index,
  totalSlides,
  useNorwegian,
  visualType,
  confidence,
  reasons,
  intentTags,
  preferredGrammarId,
  preferredSubtitle,
  preferredBullets,
  preferredQuoteText,
  preferredQuoteAttribution,
  preferredCtaLabel,
  preferredCtaSupport,
  preferredMediaIntent,
  preferredVisualNeeds,
}: {
  slide: AcademyPresentationDesignSlideInput;
  index: number;
  totalSlides: number;
  useNorwegian: boolean;
  visualType: AcademyPresentationVisualType;
  confidence: number;
  reasons: string[];
  intentTags: string[];
  preferredGrammarId?: SharedAcademyPresentationSlideGrammarId | null;
  preferredSubtitle?: string;
  preferredBullets?: string[];
  preferredQuoteText?: string;
  preferredQuoteAttribution?: string;
  preferredCtaLabel?: string;
  preferredCtaSupport?: string;
  preferredMediaIntent?: string;
  preferredVisualNeeds?: SharedAcademyPresentationVisualNeed[];
}): AcademyPresentationDesignSlidePlan => {
  const baseTitle = academyPresentationSuggestTitle(
    slide.title,
    visualType,
    useNorwegian,
    index,
  );
  const bodyLines = academyPresentationBuildBodyLines(slide, useNorwegian);
  const grammarPlan = academyPresentationBuildGrammarPlan({
    slideId: slide.id,
    title: baseTitle,
    bodyLines:
      preferredBullets && preferredBullets.length > 0
        ? preferredBullets
        : bodyLines,
    visualType,
    index,
    totalSlides,
    useNorwegian,
    preferredGrammarId: preferredGrammarId || null,
    preferredSubtitle,
    preferredBullets,
    preferredQuoteText,
    preferredQuoteAttribution,
    preferredCtaLabel,
    preferredCtaSupport,
    preferredMediaIntent,
  });

  return {
    slideId: slide.id,
    visualType,
    grammarId: grammarPlan.grammarId,
    narrativeRole: grammarPlan.narrativeRole,
    layoutHint:
      grammarPlan.grammarId === "stats" || grammarPlan.grammarId === "chart"
        ? "Use numeric contrast and one primary chart area."
        : grammarPlan.grammarId === "timeline" ||
            grammarPlan.grammarId === "process"
          ? "Flow should be readable in sequence with equal spacing."
          : grammarPlan.grammarId === "comparison"
            ? "Keep mirrored card widths and equal content weight."
            : grammarPlan.grammarId === "demo"
              ? "Keep slide visual dominant and reserve text as guidance, not transcript."
              : grammarPlan.grammarId === "hero"
                ? "Promote one idea and keep text density low."
                : "Balance presenter and slide with strict content budgets.",
    recommendedLayout: grammarPlan.recommendedLayout,
    confidence: Number(confidence.toFixed(2)),
    reasons,
    intentTags,
    contentBudget: grammarPlan.contentBudget,
    structuredContent: grammarPlan.structuredContent,
    repairActions: grammarPlan.repairActions,
    visualNeeds:
      preferredVisualNeeds && preferredVisualNeeds.length > 0
        ? preferredVisualNeeds
        : grammarPlan.visualNeeds,
    copySuggestions: {
      title: grammarPlan.structuredContent.title,
      body:
        grammarPlan.structuredContent.bullets.length > 0
          ? grammarPlan.structuredContent.bullets
          : grammarPlan.structuredContent.steps.length > 0
            ? grammarPlan.structuredContent.steps.map((entry) =>
                `${entry.title}: ${entry.body}`.trim(),
              )
            : grammarPlan.structuredContent.columns.length > 0
              ? grammarPlan.structuredContent.columns.map((entry) =>
                  `${entry.title}: ${entry.body}`.trim(),
                )
              : grammarPlan.structuredContent.stats.map((entry) =>
                  `${entry.value} ${entry.label}`.trim(),
                ),
      cta:
        grammarPlan.structuredContent.ctaLabel ||
        academyPresentationSuggestCta(visualType, useNorwegian),
    },
    graphicSlots: grammarPlan.graphicSlots,
    continuation: grammarPlan.continuation,
  };
};

const academyPresentationNormalizeToken = (value: string): string =>
  String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9æøåäöüéèáàíìóòúùñçß]+/gi, " ")
    .replace(/\s+/g, " ")
    .trim();

const academyPresentationInferVisualType = (
  text: string,
  index: number,
  totalSlides: number,
): { type: AcademyPresentationVisualType; score: number; reason: string } => {
  const normalizedText = academyPresentationNormalizeToken(text);
  if (!normalizedText) {
    if (index === 0) {
      return { type: "title", score: 0.6, reason: "first slide default" };
    }
    if (totalSlides > 2 && index >= totalSlides - 1) {
      return { type: "summary", score: 0.58, reason: "last slide default" };
    }
    return { type: "feature", score: 0.52, reason: "generic default" };
  }

  if (
    index === 0 &&
    /\b(welcome|velkommen|intro|introduction)\b/i.test(normalizedText)
  ) {
    return {
      type: "title",
      score: 0.86,
      reason: "intro keywords on first slide",
    };
  }

  const scores = new Map<AcademyPresentationVisualType, number>();
  ACADEMY_PRESENTATION_VISUAL_KEYWORDS.forEach((entry) => {
    let points = 0;
    entry.keywords.forEach((keyword) => {
      const normalizedKeyword = academyPresentationNormalizeToken(keyword);
      if (!normalizedKeyword) return;
      if (normalizedText.includes(normalizedKeyword)) {
        points += normalizedKeyword.length > 5 ? 2 : 1;
      }
    });
    if (points > 0) {
      scores.set(entry.type, points);
    }
  });

  if (scores.size === 0) {
    if (index === 0)
      return { type: "title", score: 0.62, reason: "first slide fallback" };
    if (totalSlides > 2 && index >= totalSlides - 1) {
      return { type: "summary", score: 0.6, reason: "last slide fallback" };
    }
    return { type: "feature", score: 0.56, reason: "mid deck fallback" };
  }

  let bestType: AcademyPresentationVisualType = "feature";
  let bestScore = -1;
  scores.forEach((score, type) => {
    if (score > bestScore) {
      bestScore = score;
      bestType = type;
    }
  });

  const bestTypeValue = String(bestType);
  if (
    totalSlides > 2 &&
    index >= totalSlides - 1 &&
    bestTypeValue !== "cta" &&
    bestTypeValue !== "summary"
  ) {
    bestType = "summary";
    bestScore = Math.max(bestScore, 2);
  }

  const confidence = academyPresentationClamp(
    0.48 + bestScore * 0.11,
    0.5,
    0.95,
  );
  return {
    type: bestType,
    score: confidence,
    reason: `matched ${bestScore} intent keywords`,
  };
};

const academyPresentationLayoutForVisualType = (
  type: AcademyPresentationVisualType,
): AcademyPresentationDisplayMode => {
  if (type === "title") return "full-frame";
  if (type === "agenda" || type === "summary") return "side-panel";
  if (type === "quote" || type === "cta") return "picture-in-picture";
  return "split-screen";
};

