const academyPresentationParseJsonObjectFromText = (
  rawContent: string,
): Record<string, unknown> | null => {
  const raw = String(rawContent || "").trim();
  if (!raw) return null;

  const tryParse = (value: string): Record<string, unknown> | null => {
    try {
      const parsed = JSON.parse(value) as unknown;
      return academyPresentationIsRecord(parsed) ? parsed : null;
    } catch {
      return null;
    }
  };

  const direct = tryParse(raw);
  if (direct) return direct;

  const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenceMatch?.[1]) {
    const fenced = tryParse(String(fenceMatch[1]).trim());
    if (fenced) return fenced;
  }

  const objectStart = raw.indexOf("{");
  const objectEnd = raw.lastIndexOf("}");
  if (objectStart >= 0 && objectEnd > objectStart) {
    const sliced = tryParse(raw.slice(objectStart, objectEnd + 1));
    if (sliced) return sliced;
  }

  return null;
};

const academyPresentationParseModelList = (rawValue: unknown): string[] => {
  const raw = String(readString(rawValue) || "");
  if (!raw) return [];
  const dedupe = new Set<string>();
  return raw
    .split(",")
    .map((entry) => entry.trim())
    .filter((entry) => entry.length > 0)
    .filter((entry) => {
      const key = entry.toLowerCase();
      if (dedupe.has(key)) return false;
      dedupe.add(key);
      return true;
    });
};

const academyPresentationNormalizeTemplateMemoryKind = (
  value: unknown,
): AcademyPresentationTemplateMemoryKind => {
  const normalized = String(readString(value) || "")
    .trim()
    .toLowerCase();
  if (normalized === "brand-kit") return "brand-kit";
  if (normalized === "preset") return "preset";
  return "deck";
};

const academyPresentationNormalizeTemplateMemoryItem = (
  value: unknown,
  index: number,
): AcademyPresentationTemplateMemoryItem | null => {
  if (!academyPresentationIsRecord(value)) return null;
  const id = String(readString(value.id) || `template-memory-${index + 1}`)
    .trim()
    .slice(0, 120);
  if (!id) return null;
  const name = String(readString(value.name) || "")
    .trim()
    .slice(0, 180);
  const summary = String(readString(value.summary) || "")
    .trim()
    .slice(0, 260);
  const searchText = String(readString(value.searchText) || "")
    .trim()
    .slice(0, 3600);
  if (!name || !searchText) return null;
  return {
    id,
    kind: academyPresentationNormalizeTemplateMemoryKind(value.kind),
    name,
    summary,
    templateId:
      academyPresentationNormalizeTemplateId(value.templateId) ||
      academyPresentationNormalizeTemplateId(value.template) ||
      "walkthrough",
    visualThemeId:
      academyPresentationNormalizeThemeId(value.visualThemeId) ||
      academyPresentationNormalizeThemeId(value.themeId) ||
      "neutral-modern",
    displayMode: academyPresentationNormalizeDisplayMode(value.displayMode),
    splitLayoutVariant:
      academyPresentationNormalizeSplitLayoutVariant(
        value.splitLayoutVariant,
      ) || "balanced",
    searchText,
    brandName: String(readString(value.brandName) || "")
      .trim()
      .slice(0, 120),
  };
};

const academyPresentationNormalizeBrandContext = (
  value: unknown,
): AcademyPresentationBrandContext | null => {
  if (!academyPresentationIsRecord(value)) return null;
  const name = String(readString(value.name) || "")
    .trim()
    .slice(0, 120);
  if (!name) return null;
  return {
    name,
    primary: String(readString(value.primary) || "")
      .trim()
      .slice(0, 24),
    secondary: String(readString(value.secondary) || "")
      .trim()
      .slice(0, 24),
    accent: String(readString(value.accent) || "")
      .trim()
      .slice(0, 24),
    headingFont: String(readString(value.headingFont) || "")
      .trim()
      .slice(0, 80),
    bodyFont: String(readString(value.bodyFont) || "")
      .trim()
      .slice(0, 80),
    chartStyle:
      String(readString(value.chartStyle) || "")
        .trim()
        .toLowerCase() === "line"
        ? "line"
        : String(readString(value.chartStyle) || "")
              .trim()
              .toLowerCase() === "cards"
          ? "cards"
          : "bars",
    imageStyle:
      String(readString(value.imageStyle) || "")
        .trim()
        .toLowerCase() === "clean-card"
        ? "clean-card"
        : String(readString(value.imageStyle) || "")
              .trim()
              .toLowerCase() === "technical"
          ? "technical"
          : "editorial",
    logoText: String(readString(value.logoText) || "")
      .trim()
      .slice(0, 80),
    footerText: String(readString(value.footerText) || "")
      .trim()
      .slice(0, 180),
    minContrastRatio: academyPresentationClamp(
      Number(readNumber(value.minContrastRatio) || 4.5),
      3,
      7,
    ),
  };
};

const academyPresentationBuildTemplateMemoryQuery = (params: {
  deckName: string;
  projectTemplateId: string;
  slides: AcademyPresentationDesignSlideInput[];
}): string =>
  [
    params.deckName,
    params.projectTemplateId,
    params.slides
      .slice(0, 12)
      .map((slide) =>
        [
          slide.title,
          slide.speakerNotes.slice(0, 220),
          slide.textLines.slice(0, 5).join(" "),
        ]
          .filter(Boolean)
          .join(" · "),
      )
      .join("\n"),
  ]
    .filter((entry) => String(entry || "").trim().length > 0)
    .join("\n")
    .slice(0, 4200);

const academyPresentationResolveTemplateMemoryMatches = async (params: {
  query: string;
  items: AcademyPresentationTemplateMemoryItem[];
}): Promise<{
  matches: AcademyPresentationTemplateMemoryMatch[];
  meta: AcademyPresentationTemplateMemoryMeta;
}> => {
  const query = String(params.query || "").trim();
  const items = params.items.slice(0, 80);
  if (!query || items.length === 0) {
    return {
      matches: [],
      meta: {
        provider: "lexical",
        candidateCount: items.length,
        matchedCount: 0,
      },
    };
  }

  const lexicalQueryTokens = academyPresentationNormalizeTokenSet(query);
  const lexicalScores = items.map((item) =>
    academyPresentationScoreLexicalMatch(
      {
        id: item.id,
        title: item.name,
        subtitle: `${item.summary} ${item.brandName}`.trim(),
        text: item.searchText,
        tags: [
          item.kind,
          item.templateId,
          item.visualThemeId,
          item.displayMode,
          item.splitLayoutVariant,
        ],
        searchText: item.searchText,
      },
      query,
      lexicalQueryTokens,
    ),
  );

  let semanticScores = items.map(() => 0);
  let rerankerScores: number[] | null = null;
  let usedEmbeddingModel = "";
  let usedRerankerModel = "";

  const huggingFaceToken =
    readString(process.env.HUGGINGFACE_TOKEN) ||
    readString(process.env.HF_TOKEN);
  const embeddingModel =
    readString(process.env.ACADEMY_PRESENTATION_SEARCH_EMBEDDING_MODEL) ||
    readString(process.env.ACADEMY_PRESENTATION_HF_EMBEDDING_MODEL) ||
    "BAAI/bge-m3";
  const rerankerModel =
    readString(process.env.ACADEMY_PRESENTATION_SEARCH_RERANKER_MODEL) ||
    readString(process.env.ACADEMY_PRESENTATION_HF_RERANKER_MODEL) ||
    "BAAI/bge-reranker-v2-m3";

  if (huggingFaceToken) {
    const searchTexts = items.map((item) => item.searchText.slice(0, 2600));
    const embeddings = await academyPresentationRequestHfEmbeddings({
      token: huggingFaceToken,
      model: embeddingModel,
      inputs: [query, ...searchTexts],
    });
    if (embeddings && embeddings.length === searchTexts.length + 1) {
      const queryVector = embeddings[0];
      semanticScores = embeddings
        .slice(1)
        .map((vector) =>
          Number(
            (
              (academyPresentationCosineSimilarity(queryVector, vector) + 1) /
              2
            ).toFixed(4),
          ),
        );
      usedEmbeddingModel = embeddingModel;
    }

    const candidateIndexes = items
      .map((item, index) => ({
        id: item.id,
        index,
        seedScore: lexicalScores[index] * 0.26 + semanticScores[index] * 0.74,
      }))
      .sort((left, right) => right.seedScore - left.seedScore)
      .slice(0, Math.min(18, items.length))
      .map((entry) => entry.index);
    if (candidateIndexes.length > 0) {
      const rerankerDocuments = candidateIndexes.map((index) =>
        items[index].searchText.slice(0, 1800),
      );
      const rawRerankerScores =
        await academyPresentationRequestHfRerankerScores({
          token: huggingFaceToken,
          model: rerankerModel,
          query,
          documents: rerankerDocuments,
        });
      if (
        rawRerankerScores &&
        rawRerankerScores.length === candidateIndexes.length
      ) {
        const normalizedRerankerScores =
          academyPresentationNormalizeScoreSeries(rawRerankerScores);
        rerankerScores = items.map(() => 0);
        candidateIndexes.forEach((index, offset) => {
          if (!rerankerScores) return;
          rerankerScores[index] = Number(
            normalizedRerankerScores[offset].toFixed(4),
          );
        });
        usedRerankerModel = rerankerModel;
      }
    }
  }

  const ranked = items
    .map((item, index) => {
      const lexicalScore = lexicalScores[index] || 0;
      const semanticScore = semanticScores[index] || 0;
      const rerankScore = rerankerScores ? rerankerScores[index] : null;
      const score = rerankerScores
        ? lexicalScore * 0.2 + semanticScore * 0.35 + (rerankScore || 0) * 0.45
        : lexicalScore * 0.34 + semanticScore * 0.66;
      return {
        id: item.id,
        kind: item.kind,
        name: item.name,
        summary: item.summary,
        templateId: item.templateId,
        visualThemeId: item.visualThemeId,
        displayMode: item.displayMode,
        splitLayoutVariant: item.splitLayoutVariant,
        brandName: item.brandName,
        score: Number(score.toFixed(4)),
        lexicalScore: Number(lexicalScore.toFixed(4)),
        semanticScore: Number(semanticScore.toFixed(4)),
        rerankScore:
          rerankScore === null ? null : Number(rerankScore.toFixed(4)),
      } satisfies AcademyPresentationTemplateMemoryMatch;
    })
    .sort((left, right) => right.score - left.score)
    .filter(
      (entry) =>
        entry.score >= 0.16 ||
        entry.lexicalScore >= 0.14 ||
        entry.semanticScore >= 0.18,
    )
    .slice(0, 4);

  return {
    matches: ranked,
    meta: {
      provider:
        usedEmbeddingModel || usedRerankerModel ? "huggingface" : "lexical",
      embeddingModel: usedEmbeddingModel || undefined,
      rerankerModel: usedRerankerModel || undefined,
      candidateCount: items.length,
      matchedCount: ranked.length,
    },
  };
};

const academyPresentationTryLlmDesignPlan = async (
  params: AcademyPresentationLlmPlanParams,
): Promise<AcademyPresentationLlmPlanResult | null> => {
  const openAiApiKey = readString(process.env.OPENAI_API_KEY);
  const huggingFaceToken =
    readString(process.env.HUGGINGFACE_TOKEN) ||
    readString(process.env.HF_TOKEN);

  const provider = String(
    readString(process.env.ACADEMY_PRESENTATION_DESIGN_PROVIDER) || "",
  ).toLowerCase();
  const openAiModel =
    readString(process.env.ACADEMY_PRESENTATION_DESIGN_OPENAI_MODEL) ||
    readString(process.env.ACADEMY_PRESENTATION_DESIGN_MODEL) ||
    "gpt-4o-mini";
  const huggingFacePrimaryModel =
    readString(process.env.ACADEMY_PRESENTATION_DESIGN_HF_MODEL_PRIMARY) ||
    readString(process.env.ACADEMY_PRESENTATION_DESIGN_HF_MODEL) ||
    "Qwen/Qwen3-30B-A3B-Instruct-2507";
  const huggingFaceFallbackModels = academyPresentationParseModelList(
    readString(process.env.ACADEMY_PRESENTATION_DESIGN_HF_FALLBACK_MODELS),
  );
  if (huggingFaceFallbackModels.length === 0) {
    huggingFaceFallbackModels.push("Qwen/Qwen3-4B-Instruct-2507");
  }
  const huggingFaceModels = [
    huggingFacePrimaryModel,
    ...huggingFaceFallbackModels,
  ].filter(
    (entry, index, source) =>
      source.findIndex(
        (candidate) => candidate.toLowerCase() === entry.toLowerCase(),
      ) === index,
  );
  const memoryQuery = academyPresentationBuildTemplateMemoryQuery({
    deckName: params.deckName,
    projectTemplateId: params.projectTemplateId,
    slides: params.slides,
  });
  const templateMemoryContext =
    await academyPresentationResolveTemplateMemoryMatches({
      query: memoryQuery,
      items: params.templateMemory,
    });
  if (!openAiApiKey && !huggingFaceToken) return null;
  const slidePayload = params.slides.slice(0, 50).map((slide, index) => ({
    id: slide.id,
    index: index + 1,
    title: slide.title,
    startTime: Number(slide.startTime.toFixed(2)),
    duration: Number(slide.duration.toFixed(2)),
    layout: slide.layout,
    speakerNotes: slide.speakerNotes.slice(0, 260),
    textLines: slide.textLines.slice(0, 6),
  }));

  const systemPrompt =
    "You are a presentation planning orchestrator that outputs strict JSON only. Decide narrative structure, slide grammar, content importance, and repair intent. Do not invent pixel positions. Keep text concise and within budget. Use the provided slide grammar values only. Treat template memory and brand context as soft constraints, never as permission to override the actual brief. Never include markdown.";
  const userPayload = {
    language: params.useNorwegian ? "no" : "en",
    scope: params.scope,
    projectTemplateId: params.projectTemplateId,
    deckName: params.deckName,
    currentRecommendations: {
      templateId: params.recommendedTemplateId,
      visualThemeId: params.recommendedVisualThemeId,
      displayMode: params.recommendedDisplayMode,
      splitLayoutVariant: params.recommendedSplitLayoutVariant,
    },
    allowedValues: {
      templateIds: [
        "product-overview",
        "walkthrough",
        "onboarding-flow",
        "feature-explainer",
        "training-deep-dive",
      ],
      visualThemeIds: [
        "neutral-modern",
        "sales-command",
        "operations-grid",
        "offshore-briefing",
      ],
      displayModes: [
        "picture-in-picture",
        "side-panel",
        "split-screen",
        "full-frame",
      ],
      splitLayoutVariants: ["balanced", "presenter-focus", "slide-focus"],
      visualTypes: [
        "title",
        "agenda",
        "problem",
        "solution",
        "feature",
        "process",
        "kpi",
        "timeline",
        "comparison",
        "demo",
        "quote",
        "cta",
        "summary",
      ],
      slideGrammars: [
        "hero",
        "agenda",
        "comparison",
        "before-after",
        "timeline",
        "process",
        "stats",
        "chart",
        "quote",
        "team",
        "case-study",
        "faq",
        "checklist",
        "demo",
        "cta",
        "summary",
        "content-grid",
      ],
      graphicKinds: [
        "chart",
        "icon",
        "screenshot",
        "illustration",
        "photo",
        "shape",
        "badge",
      ],
    },
    outputSchema: {
      recommendedTemplateId: "string",
      recommendedVisualThemeId: "string",
      recommendedDisplayMode: "string",
      recommendedSplitLayoutVariant: "string",
      slides: [
        {
          slideId: "string",
          visualType: "string",
          grammarId: "string",
          narrativeRole: "string",
          confidence: "number 0..1",
          reasons: ["string"],
          intentTags: ["string"],
          structuredContent: {
            title: "string",
            subtitle: "string",
            bullets: ["string"],
            quoteText: "string",
            quoteAttribution: "string",
            ctaLabel: "string",
            ctaSupport: "string",
            mediaIntent: "string",
          },
          visualNeeds: [
            {
              kind: "string",
              label: "string",
              prompt: "string",
              priority: "string",
            },
          ],
        },
      ],
    },
    brandContext: params.brandContext
      ? {
          name: params.brandContext.name,
          primary: params.brandContext.primary,
          secondary: params.brandContext.secondary,
          accent: params.brandContext.accent,
          headingFont: params.brandContext.headingFont,
          bodyFont: params.brandContext.bodyFont,
          chartStyle: params.brandContext.chartStyle,
          imageStyle: params.brandContext.imageStyle,
          logoText: params.brandContext.logoText,
          footerText: params.brandContext.footerText,
          minContrastRatio: params.brandContext.minContrastRatio,
        }
      : null,
    repairFocus: params.repairFocus.slice(0, 8),
    templateMemoryMatches: templateMemoryContext.matches.map((entry) => ({
      id: entry.id,
      kind: entry.kind,
      name: entry.name,
      summary: entry.summary,
      templateId: entry.templateId,
      visualThemeId: entry.visualThemeId,
      displayMode: entry.displayMode,
      splitLayoutVariant: entry.splitLayoutVariant,
      brandName: entry.brandName,
      score: entry.score,
      lexicalScore: entry.lexicalScore,
      semanticScore: entry.semanticScore,
      rerankScore: entry.rerankScore,
    })),
    retrievalMeta: templateMemoryContext.meta,
    slides: slidePayload,
  };

  const parsePlanPayload = (
    contentPayload: Record<string, unknown>,
    modelName: string,
    providerName: "huggingface" | "openai",
  ): AcademyPresentationLlmPlanResult | null => {
    const recommendedTemplateId =
      academyPresentationNormalizeTemplateId(
        contentPayload.recommendedTemplateId,
      ) || params.recommendedTemplateId;
    const recommendedVisualThemeId =
      academyPresentationNormalizeThemeId(
        contentPayload.recommendedVisualThemeId,
      ) || params.recommendedVisualThemeId;
    const recommendedDisplayMode = academyPresentationNormalizeDisplayMode(
      contentPayload.recommendedDisplayMode,
    );
    const recommendedSplitLayoutVariant =
      academyPresentationNormalizeSplitLayoutVariant(
        contentPayload.recommendedSplitLayoutVariant,
      ) || params.recommendedSplitLayoutVariant;

    const overridesBySlideId = new Map<string, Record<string, unknown>>();
    if (Array.isArray(contentPayload.slides)) {
      contentPayload.slides.forEach((entry) => {
        if (!academyPresentationIsRecord(entry)) return;
        const slideId = readString(entry.slideId);
        if (!slideId) return;
        overridesBySlideId.set(slideId, entry);
      });
    }

    const mergedSlides = params.heuristicSlides.map((slidePlan) => {
      const override = overridesBySlideId.get(slidePlan.slideId);
      if (!override) return slidePlan;

      const overrideVisualType =
        academyPresentationNormalizeVisualType(override.visualType) ||
        slidePlan.visualType;
      const overrideConfidence = academyPresentationClamp(
        Number(readNumber(override.confidence) ?? slidePlan.confidence),
        0,
        1,
      );
      const overrideReasons = academyPresentationReadStringArray(
        override.reasons,
        6,
        140,
      );
      const overrideIntentTags = academyPresentationReadStringArray(
        override.intentTags,
        10,
        60,
      );
      const structuredOverride = academyPresentationIsRecord(
        override.structuredContent,
      )
        ? override.structuredContent
        : {};
      const overrideTitle = String(
        readString(structuredOverride.title) ||
          slidePlan.structuredContent.title,
      ).slice(0, 120);
      const overrideSubtitle = String(
        readString(structuredOverride.subtitle) ||
          slidePlan.structuredContent.subtitle,
      ).slice(0, 160);
      const overrideBullets = academyPresentationReadStringArray(
        structuredOverride.bullets,
        8,
        160,
      );
      const overrideQuoteText = String(
        readString(structuredOverride.quoteText) ||
          slidePlan.structuredContent.quoteText,
      ).slice(0, 260);
      const overrideQuoteAttribution = String(
        readString(structuredOverride.quoteAttribution) ||
          slidePlan.structuredContent.quoteAttribution,
      ).slice(0, 80);
      const overrideCtaLabel = String(
        readString(structuredOverride.ctaLabel) ||
          slidePlan.structuredContent.ctaLabel,
      ).slice(0, 120);
      const overrideCtaSupport = String(
        readString(structuredOverride.ctaSupport) ||
          slidePlan.structuredContent.ctaSupport,
      ).slice(0, 160);
      const overrideMediaIntent = String(
        readString(structuredOverride.mediaIntent) ||
          slidePlan.structuredContent.mediaIntent,
      ).slice(0, 160);
      const overrideGrammarId =
        academyPresentationNormalizeGrammarId(override.grammarId) ||
        slidePlan.grammarId;
      const overrideVisualNeeds = academyPresentationNormalizeVisualNeeds(
        override.visualNeeds,
      );

      const sourceSlide =
        params.slides.find((candidate) => candidate.id === slidePlan.slideId) ||
        params.slides[0];
      const rebuiltPlan = academyPresentationBuildSlidePlan({
        slide: {
          ...sourceSlide,
          title: overrideTitle || sourceSlide.title,
        },
        index: Math.max(
          0,
          params.slides.findIndex(
            (candidate) => candidate.id === slidePlan.slideId,
          ),
        ),
        totalSlides: params.slides.length,
        useNorwegian: params.useNorwegian,
        visualType: overrideVisualType,
        confidence: Number(overrideConfidence.toFixed(2)),
        reasons:
          overrideReasons.length > 0 ? overrideReasons : slidePlan.reasons,
        intentTags:
          overrideIntentTags.length > 0
            ? overrideIntentTags
            : slidePlan.intentTags,
        preferredGrammarId: overrideGrammarId,
        preferredSubtitle: overrideSubtitle,
        preferredBullets:
          overrideBullets.length > 0
            ? overrideBullets
            : slidePlan.copySuggestions.body,
        preferredQuoteText: overrideQuoteText,
        preferredQuoteAttribution: overrideQuoteAttribution,
        preferredCtaLabel: overrideCtaLabel,
        preferredCtaSupport: overrideCtaSupport,
        preferredMediaIntent: overrideMediaIntent,
        preferredVisualNeeds: overrideVisualNeeds,
      });

      return {
        ...rebuiltPlan,
      } satisfies AcademyPresentationDesignSlidePlan;
    });

    return {
      recommendedTemplateId,
      recommendedVisualThemeId,
      recommendedDisplayMode,
      recommendedSplitLayoutVariant:
        recommendedDisplayMode === "split-screen"
          ? recommendedSplitLayoutVariant
          : params.recommendedSplitLayoutVariant,
      slides: mergedSlides,
      model: modelName,
      provider: providerName,
      templateMatches: templateMemoryContext.matches,
      retrievalMeta: templateMemoryContext.meta,
    };
  };

  const requestOpenAiPlan =
    async (): Promise<AcademyPresentationLlmPlanResult | null> => {
      if (!openAiApiKey) return null;
      const requestBody = {
        model: openAiModel,
        temperature: 0.2,
        response_format: { type: "json_object" as const },
        messages: [
          {
            role: "system" as const,
            content: systemPrompt,
          },
          {
            role: "user" as const,
            content: JSON.stringify(userPayload),
          },
        ],
      };

      try {
        const response = await fetch(
          "https://api.openai.com/v1/chat/completions",
          {
            method: "POST",
            headers: {
              Authorization: `Bearer ${openAiApiKey}`,
              "Content-Type": "application/json",
            },
            body: JSON.stringify(requestBody),
            signal: AbortSignal.timeout(25_000),
          },
        );
        if (!response.ok) {
          const errorBody = await response.text().catch(() => "");
          console.warn(
            "Academy design plan OpenAI request failed:",
            response.status,
            errorBody,
          );
          return null;
        }

        const parsed = (await response.json()) as Record<string, unknown>;
        const choices = Array.isArray(parsed.choices) ? parsed.choices : [];
        const firstChoice = academyPresentationIsRecord(choices[0])
          ? choices[0]
          : null;
        const message = academyPresentationIsRecord(firstChoice?.message)
          ? firstChoice.message
          : null;
        const contentRaw = readString(message?.content);
        if (!contentRaw) return null;
        const contentPayload =
          academyPresentationParseJsonObjectFromText(contentRaw);
        if (!contentPayload) return null;
        return parsePlanPayload(contentPayload, openAiModel, "openai");
      } catch (error) {
        console.warn("Academy design plan OpenAI error:", error);
        return null;
      }
    };

  const requestHuggingFacePlanForModel = async (
    modelName: string,
  ): Promise<AcademyPresentationLlmPlanResult | null> => {
    if (!huggingFaceToken) return null;
    const routerRequestBody = {
      model: modelName,
      temperature: 0.2,
      messages: [
        { role: "system" as const, content: systemPrompt },
        { role: "user" as const, content: JSON.stringify(userPayload) },
      ],
    };

    try {
      const routerResponse = await fetch(
        "https://router.huggingface.co/v1/chat/completions",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${huggingFaceToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify(routerRequestBody),
          signal: AbortSignal.timeout(30_000),
        },
      );
      if (routerResponse.ok) {
        const parsed = (await routerResponse.json()) as Record<string, unknown>;
        const choices = Array.isArray(parsed.choices) ? parsed.choices : [];
        const firstChoice = academyPresentationIsRecord(choices[0])
          ? choices[0]
          : null;
        const message = academyPresentationIsRecord(firstChoice?.message)
          ? firstChoice.message
          : null;
        const contentRaw = readString(message?.content);
        if (contentRaw) {
          const contentPayload =
            academyPresentationParseJsonObjectFromText(contentRaw);
          if (contentPayload) {
            return parsePlanPayload(contentPayload, modelName, "huggingface");
          }
        }
      } else {
        const errorBody = await routerResponse.text().catch(() => "");
        console.warn(
          "Academy design plan HF router request failed:",
          modelName,
          routerResponse.status,
          errorBody,
        );
      }
    } catch (error) {
      console.warn("Academy design plan HF router error:", modelName, error);
    }

    try {
      const inferencePrompt = [
        systemPrompt,
        "",
        "Return strict JSON object only.",
        JSON.stringify(userPayload),
      ].join("\n");
      const inferenceResponse = await fetch(
        `https://api-inference.huggingface.co/models/${encodeURIComponent(modelName)}`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${huggingFaceToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            inputs: inferencePrompt,
            parameters: {
              max_new_tokens: 1800,
              temperature: 0.2,
              return_full_text: false,
            },
            options: {
              wait_for_model: true,
              use_cache: false,
            },
          }),
          signal: AbortSignal.timeout(45_000),
        },
      );
      if (!inferenceResponse.ok) {
        const errorBody = await inferenceResponse.text().catch(() => "");
        console.warn(
          "Academy design plan HF inference request failed:",
          modelName,
          inferenceResponse.status,
          errorBody,
        );
        return null;
      }

      const parsed = (await inferenceResponse.json()) as unknown;
      let generatedText = "";
      if (Array.isArray(parsed) && academyPresentationIsRecord(parsed[0])) {
        generatedText = String(
          readString((parsed[0] as Record<string, unknown>).generated_text) ||
            readString((parsed[0] as Record<string, unknown>).text) ||
            "",
        );
      } else if (academyPresentationIsRecord(parsed)) {
        generatedText = String(
          readString(parsed.generated_text) || readString(parsed.text) || "",
        );
      }
      if (!generatedText) return null;
      const contentPayload =
        academyPresentationParseJsonObjectFromText(generatedText);
      if (!contentPayload) return null;
      return parsePlanPayload(contentPayload, modelName, "huggingface");
    } catch (error) {
      console.warn("Academy design plan HF inference error:", modelName, error);
      return null;
    }
  };

  const requestHuggingFacePlan =
    async (): Promise<AcademyPresentationLlmPlanResult | null> => {
      if (!huggingFaceToken) return null;
      for (const modelName of huggingFaceModels) {
        const result = await requestHuggingFacePlanForModel(modelName);
        if (result) return result;
      }
      return null;
    };

  const preferHuggingFace =
    provider === "huggingface" ||
    provider === "hf" ||
    provider === "qwen" ||
    (!provider && Boolean(huggingFaceToken));

  if (preferHuggingFace) {
    const hfResult = await requestHuggingFacePlan();
    if (hfResult) return hfResult;
  }

  const openAiResult = await requestOpenAiPlan();
  if (openAiResult) return openAiResult;

  if (!preferHuggingFace) {
    const hfFallback = await requestHuggingFacePlan();
    if (hfFallback) return hfFallback;
  }

  return null;
};

app.post("/api/academy/presentation/design-plan", async (req, res) => {
  try {
    if (!(await requireAcademySession(req, res, "instructor"))) {
      return;
    }
    const body = academyPresentationIsRecord(req.body) ? req.body : {};
    const scope: AcademyPresentationScope =
      readString(body.scope) === "skill" ? "skill" : "course";
    const courseId = String(readString(body.courseId) || "");
    const lessonId = String(readString(body.lessonId) || "");
    const projectTemplateId = String(
      readString(body.projectTemplateId) || "",
    ).toLowerCase();
    const useNorwegian = readBoolean(body.useNorwegian) === true;
    const deckName = String(readString(body.deckName) || "").trim();
    const requestedTemplate = academyPresentationNormalizeTemplateId(
      body.deckTemplate,
    );
    const requestedTheme = academyPresentationNormalizeThemeId(
      body.deckVisualThemeId,
    );
    const templateMemory = Array.isArray(body.templateMemory)
      ? body.templateMemory
          .map((entry, index) =>
            academyPresentationNormalizeTemplateMemoryItem(entry, index),
          )
          .filter((entry): entry is AcademyPresentationTemplateMemoryItem =>
            Boolean(entry),
          )
          .slice(0, 80)
      : [];
    const brandContext = academyPresentationNormalizeBrandContext(
      body.brandContext,
    );
    const repairFocus = Array.isArray(body.repairFocus)
      ? body.repairFocus
          .map((entry) =>
            String(readString(entry) || "")
              .trim()
              .slice(0, 220),
          )
          .filter(Boolean)
          .slice(0, 12)
      : [];

    const slides = Array.isArray(body.slides)
      ? body.slides
          .map((entry, index) =>
            academyPresentationNormalizeSlideInput(entry, index),
          )
          .filter((entry): entry is AcademyPresentationDesignSlideInput =>
            Boolean(entry),
          )
      : [];

    if (slides.length === 0) {
      return res.status(400).json({
        success: false,
        error: "slides is required",
      });
    }

    const projectTemplate =
      ACADEMY_PRESENTATION_PROJECT_TO_TEMPLATE[projectTemplateId];
    const inferredTemplate = academyPresentationInferTemplateFromSlides(slides);
    const recommendedTemplateId =
      projectTemplate || requestedTemplate || inferredTemplate || "walkthrough";
    const recommendedVisualThemeId =
      ACADEMY_PRESENTATION_PROJECT_TO_THEME[projectTemplateId] ||
      requestedTheme ||
      academyPresentationInferThemeFromTemplate(recommendedTemplateId);
    const templatePreset =
      ACADEMY_PRESENTATION_TEMPLATE_PRESETS[recommendedTemplateId];

    const visualCounts: Record<AcademyPresentationVisualType, number> = {
      title: 0,
      agenda: 0,
      problem: 0,
      solution: 0,
      feature: 0,
      process: 0,
      kpi: 0,
      timeline: 0,
      roadmap: 0,
      architecture: 0,
      scenario: 0,
      "knowledge-check": 0,
      comparison: 0,
      demo: 0,
      quote: 0,
      cta: 0,
      summary: 0,
    };
    const layoutCounts: Record<AcademyPresentationDisplayMode, number> = {
      "picture-in-picture": 0,
      "side-panel": 0,
      "split-screen": 0,
      "full-frame": 0,
    };

    const slidePlans: AcademyPresentationDesignSlidePlan[] = slides.map(
      (slide, index) => {
        const bodyLines = academyPresentationBuildBodyLines(
          slide,
          useNorwegian,
        );
        const classification = academyPresentationInferVisualType(
          `${slide.title} ${bodyLines.join(" ")} ${slide.speakerNotes}`,
          index,
          slides.length,
        );
        const visualType = classification.type;
        visualCounts[visualType] += 1;
        const intentTags = [
          visualType,
          recommendedTemplateId,
          recommendedVisualThemeId,
        ];
        const reasons = [
          classification.reason,
          `slide ${index + 1}/${slides.length}`,
          `duration ${Math.round(slide.duration)}s`,
        ];
        const slidePlan = academyPresentationBuildSlidePlan({
          slide,
          index,
          totalSlides: slides.length,
          useNorwegian,
          visualType,
          confidence: classification.score,
          reasons,
          intentTags,
        });
        layoutCounts[slidePlan.recommendedLayout] += 1;
        slidePlan.intentTags = [
          ...slidePlan.intentTags,
          slidePlan.recommendedLayout,
        ];
        return slidePlan;
      },
    );

    let heuristicRecommendedDisplayMode: AcademyPresentationDisplayMode =
      templatePreset.defaultMode;
    let bestLayoutScore = -1;
    (Object.keys(layoutCounts) as AcademyPresentationDisplayMode[]).forEach(
      (layout) => {
        const score = layoutCounts[layout];
        if (score > bestLayoutScore) {
          bestLayoutScore = score;
          heuristicRecommendedDisplayMode = layout;
        }
      },
    );

    let finalTemplateId = recommendedTemplateId;
    let finalVisualThemeId = recommendedVisualThemeId;
    let finalDisplayMode = heuristicRecommendedDisplayMode;
    let finalSplitLayoutVariant =
      ACADEMY_PRESENTATION_THEME_TO_SPLIT_VARIANT[recommendedVisualThemeId] ||
      templatePreset.splitLayoutVariant;
    let finalSlides = slidePlans;
    let generatedBy = "academy-design-plan-grammar-engine-v2";
    let generatedModel = "";
    let generatedProvider: "huggingface" | "openai" | "rule-engine" =
      "rule-engine";
    const localTemplateMemoryContext =
      await academyPresentationResolveTemplateMemoryMatches({
        query: academyPresentationBuildTemplateMemoryQuery({
          deckName,
          projectTemplateId,
          slides,
        }),
        items: templateMemory,
      });
    let templateMatches: AcademyPresentationTemplateMemoryMatch[] =
      localTemplateMemoryContext.matches;
    let retrievalMeta: AcademyPresentationTemplateMemoryMeta =
      localTemplateMemoryContext.meta;

    const llmPlan = await academyPresentationTryLlmDesignPlan({
      scope,
      courseId,
      lessonId,
      deckName,
      projectTemplateId,
      useNorwegian,
      slides,
      recommendedTemplateId: finalTemplateId,
      recommendedVisualThemeId: finalVisualThemeId,
      recommendedDisplayMode: finalDisplayMode,
      recommendedSplitLayoutVariant: finalSplitLayoutVariant,
      heuristicSlides: slidePlans,
      templateMemory,
      brandContext,
      repairFocus,
    });
    if (llmPlan) {
      finalTemplateId = llmPlan.recommendedTemplateId;
      finalVisualThemeId = llmPlan.recommendedVisualThemeId;
      finalDisplayMode = llmPlan.recommendedDisplayMode;
      finalSplitLayoutVariant = llmPlan.recommendedSplitLayoutVariant;
      finalSlides = llmPlan.slides;
      generatedBy = "academy-design-plan-orchestrator-v2";
      generatedModel = llmPlan.model;
      generatedProvider = llmPlan.provider;
      templateMatches = llmPlan.templateMatches;
      retrievalMeta = llmPlan.retrievalMeta;
    }

    const grammarCounts = finalSlides.reduce(
      (acc, slidePlan) => {
        acc[slidePlan.grammarId] = (acc[slidePlan.grammarId] || 0) + 1;
        return acc;
      },
      {} as Record<string, number>,
    );
    const repairActionsCount = finalSlides.reduce(
      (acc, slidePlan) => acc + slidePlan.repairActions.length,
      0,
    );

    const responsePayload = {
      success: true,
      data: {
        scope,
        courseId,
        lessonId: scope === "skill" ? lessonId : "",
        deckName,
        recommendedTemplateId: finalTemplateId,
        recommendedVisualThemeId: finalVisualThemeId,
        recommendedDisplayMode: finalDisplayMode,
        recommendedSplitLayoutVariant: finalSplitLayoutVariant,
        summary: {
          generatedBy,
          provider: generatedProvider,
          model: generatedModel || undefined,
          slideCount: slides.length,
          visualCounts,
          grammarCounts,
          repairActionsCount,
          templateMemoryMatches: templateMatches,
          retrievalMeta,
          brandContextName: brandContext?.name || undefined,
          pipeline: [
            "brief-to-narrative",
            "template-memory-retrieval",
            "narrative-to-slide-plan",
            "grammar-budget-repair",
            "theme-token-apply",
          ],
        },
        brandTokens: ACADEMY_PRESENTATION_THEME_TOKENS[finalVisualThemeId],
        slides: finalSlides,
        generatedAt: new Date().toISOString(),
      },
    };

    return res.status(200).json(responsePayload);
  } catch (error) {
    console.error("Error generating academy presentation design plan:", error);
    return res.status(500).json({
      success: false,
      error: "Could not generate presentation design plan",
    });
  }
});

const academyPresentationNormalizeCritiqueSeverity = (
  value: unknown,
): AcademyPresentationCritiqueSeverity =>
  String(readString(value) || "")
    .trim()
    .toLowerCase() === "error"
    ? "error"
    : "warning";

const academyPresentationNormalizeCritiqueCategory = (
  value: unknown,
): AcademyPresentationCritiqueCategory => {
  const normalized = String(readString(value) || "")
    .trim()
    .toLowerCase();
  if (
    normalized === "content" ||
    normalized === "hierarchy" ||
    normalized === "visual" ||
    normalized === "balance" ||
    normalized === "grammar" ||
    normalized === "narrative" ||
    normalized === "brand"
  ) {
    return normalized;
  }
  return "content";
};

const academyPresentationNormalizeStructuredContentForCritique = (
  value: unknown,
  fallbackTitle: string,
): SharedAcademyPresentationStructuredContent => {
  const record = academyPresentationIsRecord(value) ? value : {};
  return {
    eyebrow: String(readString(record.eyebrow) || "")
      .trim()
      .slice(0, 80),
    title: String(readString(record.title) || fallbackTitle)
      .trim()
      .slice(0, 120),
    subtitle: String(readString(record.subtitle) || "")
      .trim()
      .slice(0, 220),
    bullets: academyPresentationReadStringArray(record.bullets, 10, 200),
    columns: Array.isArray(record.columns)
      ? record.columns
          .map((entry) => {
            if (!academyPresentationIsRecord(entry)) return null;
            const title = String(readString(entry.title) || "")
              .trim()
              .slice(0, 80);
            const body = String(readString(entry.body) || "")
              .trim()
              .slice(0, 180);
            if (!title && !body) return null;
            return { title, body };
          })
          .filter(
            (
              entry,
            ): entry is SharedAcademyPresentationStructuredContent["columns"][number] =>
              Boolean(entry),
          )
          .slice(0, 6)
      : [],
    steps: Array.isArray(record.steps)
      ? record.steps
          .map((entry) => {
            if (!academyPresentationIsRecord(entry)) return null;
            const title = String(readString(entry.title) || "")
              .trim()
              .slice(0, 80);
            const body = String(readString(entry.body) || "")
              .trim()
              .slice(0, 180);
            if (!title && !body) return null;
            return { title, body };
          })
          .filter(
            (
              entry,
            ): entry is SharedAcademyPresentationStructuredContent["steps"][number] =>
              Boolean(entry),
          )
          .slice(0, 8)
      : [],
    stats: Array.isArray(record.stats)
      ? record.stats
          .map((entry) => {
            if (!academyPresentationIsRecord(entry)) return null;
            const valueText = String(readString(entry.value) || "")
              .trim()
              .slice(0, 40);
            const label = String(readString(entry.label) || "")
              .trim()
              .slice(0, 80);
            const context = String(readString(entry.context) || "")
              .trim()
              .slice(0, 120);
            if (!valueText && !label && !context) return null;
            return { value: valueText, label, context };
          })
          .filter(
            (
              entry,
            ): entry is SharedAcademyPresentationStructuredContent["stats"][number] =>
              Boolean(entry),
          )
          .slice(0, 6)
      : [],
    quoteText: String(readString(record.quoteText) || "")
      .trim()
      .slice(0, 320),
    quoteAttribution: String(readString(record.quoteAttribution) || "")
      .trim()
      .slice(0, 120),
    ctaLabel: String(readString(record.ctaLabel) || "")
      .trim()
      .slice(0, 140),
    ctaSupport: String(readString(record.ctaSupport) || "")
      .trim()
      .slice(0, 220),
    mediaIntent: String(readString(record.mediaIntent) || "")
      .trim()
      .slice(0, 220),
    emphasis: academyPresentationReadStringArray(record.emphasis, 8, 120),
  };
};

const academyPresentationNormalizeBudgetForCritique = (
  value: unknown,
  grammarId: SharedAcademyPresentationSlideGrammarId,
): SharedAcademyPresentationSlideBudget => {
  const baseBudget =
    ACADEMY_PRESENTATION_GRAMMAR_BUDGETS[grammarId] ||
    ACADEMY_PRESENTATION_GRAMMAR_BUDGETS["content-grid"];
  const record = academyPresentationIsRecord(value) ? value : {};
  return {
    titleMaxChars: academyPresentationClamp(
      Number(readNumber(record.titleMaxChars) || baseBudget.titleMaxChars),
      20,
      140,
    ),
    subtitleMaxChars: academyPresentationClamp(
      Number(
        readNumber(record.subtitleMaxChars) || baseBudget.subtitleMaxChars,
      ),
      40,
      260,
    ),
    maxBullets: academyPresentationClamp(
      Number(readNumber(record.maxBullets) || baseBudget.maxBullets),
      1,
      10,
    ),
    bulletMaxChars: academyPresentationClamp(
      Number(readNumber(record.bulletMaxChars) || baseBudget.bulletMaxChars),
      30,
      220,
    ),
    maxColumns: academyPresentationClamp(
      Number(readNumber(record.maxColumns) || baseBudget.maxColumns),
      1,
      6,
    ),
    maxTimelineSteps: academyPresentationClamp(
      Number(
        readNumber(record.maxTimelineSteps) || baseBudget.maxTimelineSteps,
      ),
      1,
      8,
    ),
    maxStats: academyPresentationClamp(
      Number(readNumber(record.maxStats) || baseBudget.maxStats),
      1,
      8,
    ),
    maxQuoteChars: academyPresentationClamp(
      Number(readNumber(record.maxQuoteChars) || baseBudget.maxQuoteChars),
      40,
      360,
    ),
    maxCtaChars: academyPresentationClamp(
      Number(readNumber(record.maxCtaChars) || baseBudget.maxCtaChars),
      20,
      180,
    ),
  };
};

const academyPresentationNormalizeCritiqueSlideInput = (
  value: unknown,
  index: number,
): AcademyPresentationCritiqueSlideInput | null => {
  if (!academyPresentationIsRecord(value)) return null;
  const slideId = String(readString(value.slideId) || `slide-${index + 1}`)
    .trim()
    .slice(0, 120);
  const title = String(readString(value.title) || `Slide ${index + 1}`)
    .trim()
    .slice(0, 160);
  const visualType =
    academyPresentationNormalizeVisualType(value.visualType) || "feature";
  const grammarId =
    academyPresentationNormalizeGrammarId(value.grammarId) || "content-grid";
  const layout = academyPresentationNormalizeDisplayMode(value.layout);
  const previewImageUrl = String(readString(value.previewImageUrl) || "")
    .trim()
    .slice(0, 220_000);
  const structuredContent =
    academyPresentationNormalizeStructuredContentForCritique(
      value.structuredContent,
      title,
    );
  return {
    slideId,
    title,
    visualType,
    grammarId,
    layout,
    previewImageUrl,
    structuredContent,
    contentBudget: academyPresentationNormalizeBudgetForCritique(
      value.contentBudget,
      grammarId,
    ),
    visualNeeds: academyPresentationNormalizeVisualNeeds(value.visualNeeds),
  };
};

const academyPresentationNormalizeCritiqueFinding = (
  value: unknown,
  index: number,
  useNorwegian: boolean,
): AcademyPresentationCritiqueFinding | null => {
  if (!academyPresentationIsRecord(value)) return null;
  const messageNo = String(
    readString(value.messageNo) ||
      readString(value.message) ||
      readString(value.messageEn) ||
      "",
  )
    .trim()
    .slice(0, 280);
  const messageEn = String(
    readString(value.messageEn) ||
      readString(value.message) ||
      readString(value.messageNo) ||
      "",
  )
    .trim()
    .slice(0, 280);
  const repairHintNo = String(
    readString(value.repairHintNo) ||
      readString(value.repairHint) ||
      readString(value.repairHintEn) ||
      "",
  )
    .trim()
    .slice(0, 240);
  const repairHintEn = String(
    readString(value.repairHintEn) ||
      readString(value.repairHint) ||
      readString(value.repairHintNo) ||
      "",
  )
    .trim()
    .slice(0, 240);
  if (!(messageNo || messageEn)) return null;
  return {
    id: String(readString(value.id) || `critique-${index + 1}`)
      .trim()
      .slice(0, 120),
    slideId:
      String(readString(value.slideId) || "")
        .trim()
        .slice(0, 120) || undefined,
    severity: academyPresentationNormalizeCritiqueSeverity(value.severity),
    category: academyPresentationNormalizeCritiqueCategory(value.category),
    messageNo: messageNo || (useNorwegian ? messageEn : ""),
    messageEn: messageEn || (!useNorwegian ? messageNo : ""),
    repairHintNo: repairHintNo || (useNorwegian ? repairHintEn : ""),
    repairHintEn: repairHintEn || (!useNorwegian ? repairHintNo : ""),
    recommendedGrammarId:
      academyPresentationNormalizeGrammarId(value.recommendedGrammarId) ||
      undefined,
    recommendedVisualKind:
      academyPresentationNormalizeGraphicKind(value.recommendedVisualKind) ||
      undefined,
    confidence: academyPresentationClamp(
      Number(readNumber(value.confidence) || 0.68),
      0,
      1,
    ),
  };
};

const academyPresentationBuildHeuristicCritique = (params: {
  slides: AcademyPresentationCritiqueSlideInput[];
  useNorwegian: boolean;
  brandContext: AcademyPresentationBrandContext | null;
}): AcademyPresentationCritiqueResult => {
  const findings: AcademyPresentationCritiqueFinding[] = [];
  const t = (no: string, en: string) => (params.useNorwegian ? no : en);

  params.slides.forEach((slide, index) => {
    const titleLength = slide.structuredContent.title.length;
    const subtitleLength = slide.structuredContent.subtitle.length;
    const bulletCount = slide.structuredContent.bullets.length;
    const longestBullet = slide.structuredContent.bullets.reduce(
      (max, entry) => Math.max(max, String(entry || "").trim().length),
      0,
    );
    const columnCount = slide.structuredContent.columns.length;
    const stepCount = slide.structuredContent.steps.length;
    const statCount = slide.structuredContent.stats.length;
    const hasPrimaryVisual = slide.visualNeeds.some(
      (entry) => entry.priority === "primary",
    );

    if (titleLength > slide.contentBudget.titleMaxChars) {
      findings.push({
        id: `${slide.slideId}-title-overflow`,
        slideId: slide.slideId,
        severity: "warning",
        category: "content",
        messageNo: `"${slide.title}" har for lang tittel for ${slide.grammarId}.`,
        messageEn: `"${slide.title}" has a title that is too long for ${slide.grammarId}.`,
        repairHintNo: "Forkort tittelen eller promotér resten til undertekst.",
        repairHintEn: "Shorten the title or demote the rest into the subtitle.",
        recommendedGrammarId: slide.grammarId,
        confidence: 0.84,
      });
    }
    if (subtitleLength > slide.contentBudget.subtitleMaxChars) {
      findings.push({
        id: `${slide.slideId}-subtitle-overflow`,
        slideId: slide.slideId,
        severity: "warning",
        category: "content",
        messageNo: `"${slide.title}" har for lang undertekst.`,
        messageEn: `"${slide.title}" has a subtitle that is too long.`,
        repairHintNo:
          "Komprimer underteksten eller flytt detaljer til speaker notes.",
        repairHintEn:
          "Compress the subtitle or move detail into speaker notes.",
        recommendedGrammarId: slide.grammarId,
        confidence: 0.8,
      });
    }
    if (
      bulletCount > slide.contentBudget.maxBullets ||
      longestBullet > slide.contentBudget.bulletMaxChars
    ) {
      findings.push({
        id: `${slide.slideId}-bullet-density`,
        slideId: slide.slideId,
        severity:
          bulletCount > slide.contentBudget.maxBullets + 1
            ? "error"
            : "warning",
        category: "content",
        messageNo: `"${slide.title}" har for tett tekstmengde i punktene.`,
        messageEn: `"${slide.title}" has overly dense bullet content.`,
        repairHintNo:
          "Kort ned punktene, del sliden, eller bytt til checklist/process.",
        repairHintEn:
          "Shorten bullets, split the slide, or switch to checklist/process.",
        recommendedGrammarId:
          slide.grammarId === "hero" || slide.grammarId === "summary"
            ? "checklist"
            : slide.grammarId,
        confidence: 0.82,
      });
    }
    if (
      (slide.grammarId === "comparison" ||
        slide.grammarId === "before-after" ||
        slide.grammarId === "faq") &&
      columnCount < 2
    ) {
      findings.push({
        id: `${slide.slideId}-missing-columns`,
        slideId: slide.slideId,
        severity: "warning",
        category: "grammar",
        messageNo: `"${slide.title}" mangler nok kolonner/kort for valgt slide-type.`,
        messageEn: `"${slide.title}" does not have enough cards/columns for the chosen slide type.`,
        repairHintNo: "Fyll inn minst to kort eller bytt til content-grid.",
        repairHintEn: "Provide at least two cards or switch to content-grid.",
        recommendedGrammarId: "content-grid",
        confidence: 0.78,
      });
    }
    if (
      (slide.grammarId === "timeline" || slide.grammarId === "process") &&
      stepCount < 2
    ) {
      findings.push({
        id: `${slide.slideId}-missing-steps`,
        slideId: slide.slideId,
        severity: "warning",
        category: "grammar",
        messageNo: `"${slide.title}" mangler nok steg for timeline/process.`,
        messageEn: `"${slide.title}" is missing enough steps for timeline/process.`,
        repairHintNo:
          "Bryt innholdet ned i tydelige steg eller bytt slide-type.",
        repairHintEn:
          "Break the content into clear steps or switch slide type.",
        recommendedGrammarId: "content-grid",
        confidence: 0.8,
      });
    }
    if (
      (slide.grammarId === "stats" || slide.grammarId === "chart") &&
      statCount < 2
    ) {
      findings.push({
        id: `${slide.slideId}-missing-stats`,
        slideId: slide.slideId,
        severity: "warning",
        category: "grammar",
        messageNo: `"${slide.title}" mangler nok tallgrunnlag for stats/chart.`,
        messageEn: `"${slide.title}" lacks enough numeric content for stats/chart.`,
        repairHintNo:
          "Legg inn minst to tall eller bytt til hero/content-grid.",
        repairHintEn:
          "Add at least two numbers or switch to hero/content-grid.",
        recommendedGrammarId: "content-grid",
        confidence: 0.79,
      });
    }
    if (hasPrimaryVisual && !slide.previewImageUrl) {
      findings.push({
        id: `${slide.slideId}-missing-preview-visual`,
        slideId: slide.slideId,
        severity: "warning",
        category: "visual",
        messageNo: `"${slide.title}" mangler preview for primærvisual.`,
        messageEn: `"${slide.title}" is missing a preview for the primary visual.`,
        repairHintNo: "Generer ny designstruktur eller bytt visual-slot.",
        repairHintEn:
          "Generate a new design structure or change the visual slot.",
        recommendedVisualKind: slide.visualNeeds[0]?.kind,
        confidence: 0.72,
      });
    }
    if (
      index === 0 &&
      slide.grammarId !== "hero" &&
      slide.visualType !== "title"
    ) {
      findings.push({
        id: `${slide.slideId}-opening-weak`,
        slideId: slide.slideId,
        severity: "warning",
        category: "narrative",
        messageNo: `Åpningssliden "${slide.title}" mangler tydelig hook.`,
        messageEn: `Opening slide "${slide.title}" is missing a clear hook.`,
        repairHintNo: "Bytt til hero eller gi sliden et tydelig åpningsløfte.",
        repairHintEn:
          "Switch to hero or give the slide a stronger opening promise.",
        recommendedGrammarId: "hero",
        confidence: 0.7,
      });
    }
    if (
      index === params.slides.length - 1 &&
      slide.grammarId !== "cta" &&
      slide.grammarId !== "summary"
    ) {
      findings.push({
        id: `${slide.slideId}-closing-weak`,
        slideId: slide.slideId,
        severity: "warning",
        category: "narrative",
        messageNo: `Siste slide "${slide.title}" avslutter uten tydelig oppsummering eller CTA.`,
        messageEn: `Final slide "${slide.title}" closes without a clear summary or CTA.`,
        repairHintNo: "Avslutt med summary eller CTA.",
        repairHintEn: "Close with a summary or CTA.",
        recommendedGrammarId: "cta",
        confidence: 0.76,
      });
    }
  });

  if (params.brandContext) {
    if (!params.brandContext.logoText.trim()) {
      findings.push({
        id: "brand-wordmark-missing",
        severity: "warning",
        category: "brand",
        messageNo: "Brand-konteksten mangler wordmark/logo-tekst.",
        messageEn: "The brand context is missing wordmark/logo text.",
        repairHintNo: "Legg til wordmark for tydeligere brand-signatur.",
        repairHintEn: "Add a wordmark for a clearer brand signature.",
        confidence: 0.66,
      });
    }
    if (
      params.brandContext.minContrastRatio > 4.5 &&
      !params.brandContext.footerText.trim()
    ) {
      findings.push({
        id: "brand-footer-missing",
        severity: "warning",
        category: "brand",
        messageNo:
          "Brand-konteksten mangler footer selv om brand-styringen er streng.",
        messageEn:
          "The brand context is missing a footer even though brand governance is strict.",
        repairHintNo: "Vurder footer for konsekvent brand governance.",
        repairHintEn:
          "Consider adding a footer for consistent brand governance.",
        confidence: 0.58,
      });
    }
  }

  const byCategory = (category: AcademyPresentationCritiqueCategory) =>
    findings
      .filter((entry) => entry.category === category)
      .reduce((sum, entry) => sum + (entry.severity === "error" ? 16 : 8), 0);
  const narrativePenalty = byCategory("narrative");
  const contentPenalty = byCategory("content");
  const grammarPenalty = byCategory("grammar");
  const visualPenalty = byCategory("visual");
  const brandPenalty = byCategory("brand");
  const designPenalty = Math.round(
    (contentPenalty + grammarPenalty + visualPenalty) / 3,
  );
  const overallPenalty = Math.round(
    (narrativePenalty +
      contentPenalty +
      grammarPenalty +
      visualPenalty +
      brandPenalty) /
      5,
  );

  return {
    provider: "heuristic",
    model: "academy-presentation-heuristics-v1",
    overall: academyPresentationClamp(100 - overallPenalty, 0, 100),
    narrative: academyPresentationClamp(100 - narrativePenalty, 0, 100),
    pedagogy: academyPresentationClamp(
      100 - Math.round((contentPenalty + grammarPenalty) / 2),
      0,
      100,
    ),
    design: academyPresentationClamp(100 - designPenalty, 0, 100),
    visuals: academyPresentationClamp(100 - visualPenalty, 0, 100),
    brand: academyPresentationClamp(100 - brandPenalty, 0, 100),
    findings,
  };
};

const academyPresentationTryHuggingFaceCritique = async (params: {
  slides: AcademyPresentationCritiqueSlideInput[];
  deckName: string;
  scope: AcademyPresentationScope;
  projectTemplateId: string;
  useNorwegian: boolean;
  brandContext: AcademyPresentationBrandContext | null;
  heuristic: AcademyPresentationCritiqueResult;
}): Promise<AcademyPresentationCritiqueResult | null> => {
  const huggingFaceToken =
    readString(process.env.HUGGINGFACE_TOKEN) ||
    readString(process.env.HF_TOKEN);
  if (!huggingFaceToken) return null;

  const visionPrimaryModel =
    readString(
      process.env.ACADEMY_PRESENTATION_CRITIQUE_HF_VISION_MODEL_PRIMARY,
    ) || "Qwen/Qwen2.5-VL-72B-Instruct";
  const visionFallbackModels = academyPresentationParseModelList(
    readString(
      process.env.ACADEMY_PRESENTATION_CRITIQUE_HF_VISION_FALLBACK_MODELS,
    ) || "Qwen/Qwen2.5-VL-7B-Instruct",
  );
  const textFallbackModels = academyPresentationParseModelList(
    readString(process.env.ACADEMY_PRESENTATION_CRITIQUE_HF_TEXT_MODELS) ||
      readString(process.env.ACADEMY_PRESENTATION_DESIGN_HF_MODELS) ||
      "Qwen/Qwen3-32B,Qwen/Qwen3-14B",
  );

  const normalizedSlides = params.slides.slice(0, 12).map((slide) => ({
    slideId: slide.slideId,
    title: slide.title,
    visualType: slide.visualType,
    grammarId: slide.grammarId,
    layout: slide.layout,
    contentBudget: slide.contentBudget,
    structuredContent: {
      title: slide.structuredContent.title,
      subtitle: slide.structuredContent.subtitle,
      bullets: slide.structuredContent.bullets.slice(0, 6),
      columns: slide.structuredContent.columns.slice(0, 4),
      steps: slide.structuredContent.steps.slice(0, 5),
      stats: slide.structuredContent.stats.slice(0, 4),
      quoteText: slide.structuredContent.quoteText,
      ctaLabel: slide.structuredContent.ctaLabel,
      mediaIntent: slide.structuredContent.mediaIntent,
    },
    visualNeeds: slide.visualNeeds.slice(0, 4),
  }));

  const systemPrompt =
    "You are a presentation design critic. Review narrative, pedagogy, design quality, brand fit, and slide grammar. Return strict JSON only. Base your critique on the brief, structured slide content, budgets, and any preview images provided. Prefer actionable repair hints. Never include markdown.";
  const userPayload = {
    language: params.useNorwegian ? "no" : "en",
    scope: params.scope,
    projectTemplateId: params.projectTemplateId,
    deckName: params.deckName,
    brandContext: params.brandContext,
    heuristicBaseline: {
      overall: params.heuristic.overall,
      narrative: params.heuristic.narrative,
      pedagogy: params.heuristic.pedagogy,
      design: params.heuristic.design,
      visuals: params.heuristic.visuals,
      brand: params.heuristic.brand,
      topIssues: params.heuristic.findings.slice(0, 6).map((entry) => ({
        slideId: entry.slideId,
        category: entry.category,
        severity: entry.severity,
        messageNo: entry.messageNo,
        repairHintNo: entry.repairHintNo,
      })),
    },
    allowedValues: {
      severity: ["warning", "error"],
      categories: [
        "content",
        "hierarchy",
        "visual",
        "balance",
        "grammar",
        "narrative",
        "brand",
      ],
      slideGrammars: Object.keys(ACADEMY_PRESENTATION_GRAMMAR_BUDGETS),
      visualKinds: [
        "chart",
        "icon",
        "screenshot",
        "illustration",
        "photo",
        "shape",
        "badge",
      ],
    },
    outputSchema: {
      overall: "number 0..100",
      narrative: "number 0..100",
      pedagogy: "number 0..100",
      design: "number 0..100",
      visuals: "number 0..100",
      brand: "number 0..100",
      findings: [
        {
          slideId: "string",
          severity: "warning|error",
          category: "content|hierarchy|visual|balance|grammar|narrative|brand",
          messageNo: "string",
          messageEn: "string",
          repairHintNo: "string",
          repairHintEn: "string",
          recommendedGrammarId: "string optional",
          recommendedVisualKind: "string optional",
          confidence: "number 0..1",
        },
      ],
    },
    slides: normalizedSlides,
  };

  const parseCritiquePayload = (
    payload: Record<string, unknown>,
    model: string,
    provider: "huggingface" | "heuristic" = "huggingface",
  ): AcademyPresentationCritiqueResult | null => {
    const findings = Array.isArray(payload.findings)
      ? payload.findings
          .map((entry, index) =>
            academyPresentationNormalizeCritiqueFinding(
              entry,
              index,
              params.useNorwegian,
            ),
          )
          .filter((entry): entry is AcademyPresentationCritiqueFinding =>
            Boolean(entry),
          )
          .slice(0, 20)
      : [];
    const score = (value: unknown, fallback: number) =>
      academyPresentationClamp(Number(readNumber(value) || fallback), 0, 100);
    return {
      provider,
      model,
      overall: score(payload.overall, params.heuristic.overall),
      narrative: score(payload.narrative, params.heuristic.narrative),
      pedagogy: score(payload.pedagogy, params.heuristic.pedagogy),
      design: score(payload.design, params.heuristic.design),
      visuals: score(payload.visuals, params.heuristic.visuals),
      brand: score(payload.brand, params.heuristic.brand),
      findings: findings.length > 0 ? findings : params.heuristic.findings,
    };
  };

  const previewSlides = params.slides
    .filter(
      (slide) =>
        slide.previewImageUrl && slide.previewImageUrl.length <= 220_000,
    )
    .slice(0, 4);
  const visionModels = [visionPrimaryModel, ...visionFallbackModels].filter(
    (entry, index, source) =>
      source.findIndex(
        (candidate) => candidate.toLowerCase() === entry.toLowerCase(),
      ) === index,
  );

  for (const modelName of visionModels) {
    try {
      const content: Array<Record<string, unknown>> = [
        {
          type: "text",
          text: JSON.stringify(userPayload),
        },
      ];
      previewSlides.forEach((slide) => {
        content.push({
          type: "text",
          text: `Preview for ${slide.slideId}: ${slide.title}`,
        });
        content.push({
          type: "image_url",
          image_url: {
            url: slide.previewImageUrl,
          },
        });
      });
      const routerResponse = await fetch(
        "https://router.huggingface.co/v1/chat/completions",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${huggingFaceToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            model: modelName,
            temperature: 0.1,
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content },
            ],
          }),
          signal: AbortSignal.timeout(40_000),
        },
      );
      if (!routerResponse.ok) {
        const errorBody = await routerResponse.text().catch(() => "");
        console.warn(
          "Academy presentation critique vision router failed:",
          modelName,
          routerResponse.status,
          errorBody,
        );
        continue;
      }
      const parsed = (await routerResponse.json()) as Record<string, unknown>;
      const choices = Array.isArray(parsed.choices) ? parsed.choices : [];
      const firstChoice = academyPresentationIsRecord(choices[0])
        ? choices[0]
        : null;
      const message = academyPresentationIsRecord(firstChoice?.message)
        ? firstChoice.message
        : null;
      const contentValue = message?.content;
      const contentRaw = Array.isArray(contentValue)
        ? contentValue
            .map((entry) =>
              academyPresentationIsRecord(entry)
                ? String(readString(entry.text) || "")
                : String(entry || ""),
            )
            .join("\n")
        : String(readString(contentValue) || "");
      const payload = academyPresentationParseJsonObjectFromText(contentRaw);
      if (payload) {
        const critique = parseCritiquePayload(
          payload,
          modelName,
          "huggingface",
        );
        if (critique) return critique;
      }
    } catch (error) {
      console.warn(
        "Academy presentation critique vision error:",
        modelName,
        error,
      );
    }
  }

  for (const modelName of textFallbackModels) {
    try {
      const routerResponse = await fetch(
        "https://router.huggingface.co/v1/chat/completions",
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${huggingFaceToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({
            model: modelName,
            temperature: 0.1,
            messages: [
              { role: "system", content: systemPrompt },
              { role: "user", content: JSON.stringify(userPayload) },
            ],
          }),
          signal: AbortSignal.timeout(30_000),
        },
      );
      if (!routerResponse.ok) continue;
      const parsed = (await routerResponse.json()) as Record<string, unknown>;
      const choices = Array.isArray(parsed.choices) ? parsed.choices : [];
      const firstChoice = academyPresentationIsRecord(choices[0])
        ? choices[0]
        : null;
      const message = academyPresentationIsRecord(firstChoice?.message)
        ? firstChoice.message
        : null;
      const contentRaw = String(readString(message?.content) || "");
      const payload = academyPresentationParseJsonObjectFromText(contentRaw);
      if (payload) {
        const critique = parseCritiquePayload(
          payload,
          modelName,
          "huggingface",
        );
        if (critique) return critique;
      }
    } catch (error) {
      console.warn(
        "Academy presentation critique text fallback error:",
        modelName,
        error,
      );
    }
  }

  return null;
};

app.post("/api/academy/presentation/critique", async (req, res) => {
  try {
    if (!(await requireAcademySession(req, res, "instructor"))) {
      return;
    }
    const body = academyPresentationIsRecord(req.body) ? req.body : {};
    const scope: AcademyPresentationScope =
      readString(body.scope) === "skill" ? "skill" : "course";
    const projectTemplateId = String(
      readString(body.projectTemplateId) || "",
    ).toLowerCase();
    const useNorwegian = readBoolean(body.useNorwegian) === true;
    const deckName =
      String(readString(body.deckName) || "").trim() || "Presentation";
    const brandContext = academyPresentationNormalizeBrandContext(
      body.brandContext,
    );
    const slides = Array.isArray(body.slides)
      ? body.slides
          .map((entry, index) =>
            academyPresentationNormalizeCritiqueSlideInput(entry, index),
          )
          .filter((entry): entry is AcademyPresentationCritiqueSlideInput =>
            Boolean(entry),
          )
          .slice(0, 16)
      : [];

    if (slides.length === 0) {
      return res.status(400).json({
        success: false,
        error: "slides is required",
      });
    }

    const heuristic = academyPresentationBuildHeuristicCritique({
      slides,
      useNorwegian,
      brandContext,
    });
    const critique =
      (await academyPresentationTryHuggingFaceCritique({
        slides,
        deckName,
        scope,
        projectTemplateId,
        useNorwegian,
        brandContext,
        heuristic,
      })) || heuristic;

    return res.status(200).json({
      success: true,
      data: {
        scope,
        deckName,
        provider: critique.provider,
        model: critique.model,
        overall: critique.overall,
        narrative: critique.narrative,
        pedagogy: critique.pedagogy,
        design: critique.design,
        visuals: critique.visuals,
        brand: critique.brand,
        findings: critique.findings,
        generatedAt: new Date().toISOString(),
        pipeline:
          critique.provider === "huggingface"
            ? [
                "heuristic-baseline",
                "qwen-vl-critique",
                "text-fallback-if-needed",
              ]
            : ["heuristic-baseline"],
      },
    });
  } catch (error) {
    console.error("Error generating academy presentation critique:", error);
    return res.status(500).json({
      success: false,
      error: "Could not critique presentation deck",
    });
  }
});

type AcademyCurriculumFoundationQuestionId =
  | "competencyTopic"
  | "competencySubtype"
  | "targetAudience"
  | "desiredTransformation"
  | "contextConstraint";

interface AcademyCurriculumFoundationQuestion {
  id: AcademyCurriculumFoundationQuestionId;
  question: string;
  placeholder: string;
  helpText: string;
  suggestions: string[];
}

interface AcademyCurriculumFoundationAnswer {
  id: AcademyCurriculumFoundationQuestionId;
  question: string;
  answer: string;
}

interface AcademyCurriculumFoundationSkillMapItem {
  title: string;
  focus: string;
}

type AcademyCurriculumFoundationCompetencyLevel =
  | "basic"
  | "operational"
  | "advanced";

interface AcademyCurriculumFoundationCompetencyMapItem {
  title: string;
  description: string;
  basic: string[];
  operational: string[];
  advanced: string[];
}

interface AcademyCurriculumFoundationSkillSuggestion {
  title: string;
  competency: string;
  level: AcademyCurriculumFoundationCompetencyLevel;
  objective: string;
  recommendedDurationMinutes: number;
}

type AcademyCurriculumFoundationQuizSuggestionType =
  | "single-choice"
  | "multi-select"
  | "true-false"
  | "short-answer";

interface AcademyCurriculumFoundationQuizSuggestionOption {
  label: string;
  text: string;
  isCorrect: boolean;
  explanation?: string;
}

interface AcademyCurriculumFoundationQuizSuggestion {
  prompt: string;
  hint: string;
  competency: string;
  skillTitle?: string;
  level: AcademyCurriculumFoundationCompetencyLevel;
  type: AcademyCurriculumFoundationQuizSuggestionType;
  options: AcademyCurriculumFoundationQuizSuggestionOption[];
  acceptedAnswers: string[];
  explanation: string;
  timestampRatio: number;
  duration: number;
  tags: string[];
}

interface AcademyCurriculumFoundationAnnotationSuggestion {
  type: AcademyAnnotationRecommendationType;
  title: string;
  content: string;
  competency: string;
  skillTitle?: string;
  level: AcademyCurriculumFoundationCompetencyLevel;
  startRatio: number;
  endRatio: number;
  actionType?: AcademyAnnotationRecommendationActionType;
  actionTarget?: string;
}

interface AcademyCurriculumFoundationStudioSuggestions {
  skills: AcademyCurriculumFoundationSkillSuggestion[];
  quiz: AcademyCurriculumFoundationQuizSuggestion[];
  annotations: AcademyCurriculumFoundationAnnotationSuggestion[];
}

interface AcademyCurriculumFoundationArchitecture {
  purpose: string;
  audience: string;
  transformation: string;
  competencies: string[];
  skills: string[];
  transformations: string[];
  skillMap: AcademyCurriculumFoundationSkillMapItem[];
  competencyMap?: AcademyCurriculumFoundationCompetencyMapItem[];
  problemsSolved: string[];
  learningJourney: string;
  practiceDesign: string;
  proofOfLearning: string;
  studioSuggestions?: AcademyCurriculumFoundationStudioSuggestions;
}

interface AcademyCurriculumFoundationRecommendation {
  competencyName: string;
  recommendedProjectTemplateId: string;
  rationale: string[];
  architecture: AcademyCurriculumFoundationArchitecture;
}

