const adminRoleCatalogById = new Map(
  ADMIN_ROLE_CATALOG.map((entry) => [entry.id, entry]),
);

const toAdminString = (value: unknown): string | null => {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : null;
};

const toAdminBoolean = (value: unknown): boolean | null => {
  if (typeof value === "boolean") return value;
  if (typeof value === "string") {
    const normalized = value.trim().toLowerCase();
    if (normalized === "true") return true;
    if (normalized === "false") return false;
  }
  return null;
};

const adminUsernameFromEmail = (email: string): string => {
  const base =
    email
      .split("@")[0]
      ?.toLowerCase()
      .replace(/[^a-z0-9._-]/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .slice(0, 48) || "creatorhub-user";
  return base;
};

const normalizeAdminRoleId = (value: unknown): string => {
  const raw = toAdminString(value)?.toLowerCase().replace(/\s+/g, "_") || "";
  if (!raw) return "user";
  return adminRoleCatalogById.has(raw) ? raw : raw;
};

const inferAdminRoleFromProfession = (profession: unknown): string => {
  const normalized = toAdminString(profession)?.toLowerCase() || "";
  if (normalized === "admin") return "admin";
  if (normalized === "academy_admin") return "academy_admin";
  if (normalized === "prototype_tester") return "prototype_tester";
  if (normalized === "content_producer") return "content_producer";
  if (normalized === "client_reviewer") return "client_reviewer";
  if (normalized === "couple") return "couple";
  if (normalized === "vendor") return "vendor";
  if (normalized === "enterprise") return "enterprise_admin";
  if (normalized === "instructor") return "instructor";
  return "user";
};

const normalizeAdminProfession = (
  profession: unknown,
  roleId?: string | null,
): string | null => {
  const directProfession = toAdminString(profession)?.toLowerCase() || null;
  if (directProfession) return directProfession;
  if (roleId === "vendor") return "vendor";
  if (roleId === "enterprise_admin") return "enterprise";
  if (roleId === "academy_admin") return "instructor";
  if (roleId === "instructor") return "instructor";
  if (roleId === "admin" || roleId === "super_admin") return "admin";
  return null;
};

const resolveAdminProfessionForPersistence = ({
  profession,
  roleId,
  fallbackProfession,
}: {
  profession: unknown;
  roleId?: string | null;
  fallbackProfession?: unknown;
}): string => {
  const normalizedRole = normalizeAdminRoleId(roleId);
  const directProfession = normalizeAdminProfession(profession, normalizedRole);
  if (directProfession) {
    return directProfession;
  }

  const fallback = normalizeAdminProfession(fallbackProfession, normalizedRole);
  if (fallback) {
    return fallback;
  }

  if (normalizedRole === "vendor") return "vendor";
  if (normalizedRole === "enterprise_admin") return "enterprise";
  if (normalizedRole === "academy_admin") return "instructor";
  if (normalizedRole === "instructor") return "instructor";
  if (normalizedRole === "admin" || normalizedRole === "super_admin") {
    return "admin";
  }
  return "photographer";
};

const buildAdminRoleEntry = (roleId: string): AdminRoleCatalogEntry => {
  const existing = adminRoleCatalogById.get(roleId);
  if (existing) return existing;

  const formatted = roleId
    .split(/[_\s-]+/)
    .filter(Boolean)
    .map((segment) => segment.charAt(0).toUpperCase() + segment.slice(1))
    .join(" ");

  return {
    id: roleId,
    name: formatted || "Bruker",
    description: "Dynamisk rolle registrert i brukerdatabasen.",
    permissions: [],
  };
};

type AdminAccessProfile = {
  scopeId: string;
  scopeLabel: string;
  description: string;
  sortOrder: number;
  isPlatformAdmin: boolean;
  isAcademyAdmin: boolean;
};

const buildAdminAccessProfile = (
  roleId: string,
  permissions: unknown,
): AdminAccessProfile => {
  const permissionSet = new Set(normalizeSessionPermissions(permissions));
  const isPlatformAdmin = ADMIN_SESSION_ROLES.has(roleId);
  const isAcademyAdmin =
    isPlatformAdmin ||
    ACADEMY_ADMIN_ROLES.has(roleId) ||
    permissionSet.has("academy:admin");

  if (isPlatformAdmin) {
    return {
      scopeId: "platform_admin",
      scopeLabel: "Plattform-admin",
      description:
        "Full kontroll over CreatorHub, brukere, roller, billing og Academy.",
      sortOrder: 0,
      isPlatformAdmin: true,
      isAcademyAdmin: true,
    };
  }

  if (isAcademyAdmin) {
    return {
      scopeId: "academy_admin",
      scopeLabel: "Academy-admin",
      description:
        "Kan administrere Academy-innhold og Academy-tilganger, men ikke plattformadmin.",
      sortOrder: 1,
      isPlatformAdmin: false,
      isAcademyAdmin: true,
    };
  }

  if (roleId === "instructor" || permissionSet.has("academy:write")) {
    return {
      scopeId: "academy_editor",
      scopeLabel: "Academy-redaktør",
      description: "Kan vedlikeholde Academy-innhold, uten admin-tilgang.",
      sortOrder: 2,
      isPlatformAdmin: false,
      isAcademyAdmin: false,
    };
  }

  return {
    scopeId: "workspace_user",
    scopeLabel: "Standardtilgang",
    description: "Rolle- og produktstyrt tilgang uten admin-rettigheter.",
    sortOrder: 3,
    isPlatformAdmin: false,
    isAcademyAdmin: false,
  };
};

const formatAdminUserIdentity = (
  record: Record<string, unknown> | null | undefined,
): string | null => {
  if (!record) return null;

  const fullName = [
    toAdminString(record.first_name),
    toAdminString(record.last_name),
  ]
    .filter(Boolean)
    .join(" ");

  if (fullName) {
    return fullName;
  }

  return (
    toAdminString(record.username) ||
    toAdminString(record.email) ||
    null
  );
};

const sortAdminUsersByRecency = (
  a: Record<string, unknown>,
  b: Record<string, unknown>,
): number => {
  const aAccessSortOrder =
    typeof a.accessSortOrder === "number"
      ? a.accessSortOrder
      : Number(a.accessSortOrder) || 99;
  const bAccessSortOrder =
    typeof b.accessSortOrder === "number"
      ? b.accessSortOrder
      : Number(b.accessSortOrder) || 99;
  if (aAccessSortOrder !== bAccessSortOrder) {
    return aAccessSortOrder - bAccessSortOrder;
  }
  const aTime = Date.parse(String(a.createdAt || a.updatedAt || "")) || 0;
  const bTime = Date.parse(String(b.createdAt || b.updatedAt || "")) || 0;
  if (bTime !== aTime) return bTime - aTime;
  return String(a.email || "").localeCompare(String(b.email || ""), "nb");
};

