// ============================================================
// PROJECTS CRUD API (ProjectContext + ProjectCreationWithMemoryCards)
// ============================================================

// Helper: extract userId from request headers
function getUserIdFromAuth(req: any): string | null {
  // Check X-User-Id header first (explicit user identification)
  const userId = req.headers["x-user-id"];
  if (userId) return userId;
  // Fallback: try Authorization header
  const auth = req.headers.authorization;
  if (auth?.startsWith("Bearer ")) return auth.substring(7);
  return null;
}

// Helper: map projects row to camelCase ProjectData
function mapProjectRow(r: any) {
  return {
    id: r.id,
    name: r.name || r.title || "",
    title: r.title || r.name || "",
    description: r.description || "",
    clientName: r.client_name || r.client_email || "",
    clientEmail: r.client_email || "",
    clientPhone: r.client_phone || "",
    eventDate: r.event_date || r.date || "",
    location: r.location || "",
    projectType: r.category || r.profession || "",
    profession: r.profession || "",
    status: r.status || "draft",
    priority: r.priority || "medium",
    budget: r.budget ? parseFloat(r.budget) : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    createdBy: r.user_id || "",
    userId: r.user_id || "",
    settings: r.settings || {},
    metadata: r.metadata || {},
    integrations: {
      googleDrive: r.drive_backup_enabled || false,
      googlePhotos: false,
      weddingTimeline: false,
      showcase: false,
      worklog: false,
    },
    coverImage: r.cover_image || null,
    slug: r.slug || null,
    estimatedHours: r.estimated_hours || 0,
    actualHours: r.actual_hours || 0,
    expenses: r.expenses || 0,
    featured: r.featured || false,
    published: r.published || false,
    customerId: r.customer_id || null,
  };
}

// GET /api/projects — list projects for user
app.get("/api/projects", async (req, res) => {
  try {
    const authUserId = readString(getUserIdFromAuth(req));
    const queryUserId = readString(req.query.userId);
    const profession = readString(req.query.profession);
    const status = readString(req.query.status);
    const customerId =
      readString(req.query.customerId) || readString(req.query.clientId);
    const requestedUserId = queryUserId || authUserId;
    const isLocalDevelopmentWorkspaceUserId = (
      value: string | null | undefined,
    ): boolean =>
      typeof value === "string" &&
      (value === "local-admin" ||
        value === "dev-local-user" ||
        value.startsWith("dev-"));
    const scopedUserId =
      requestedUserId && !isLocalDevelopmentWorkspaceUserId(requestedUserId)
        ? requestedUserId
        : null;
    let query = "SELECT * FROM legacy.projects";
    const params: any[] = [];
    let idx = 1;
    const filters: string[] = [];

    if (customerId) {
      filters.push(`customer_id = $${idx++}`);
      params.push(customerId);
    }

    if (profession) {
      filters.push(`profession = $${idx++}`);
      params.push(profession);
    }

    if (status) {
      filters.push(`status = $${idx++}`);
      params.push(status);
    }

    if (scopedUserId) {
      filters.push(`user_id = $${idx++}`);
      params.push(scopedUserId);
    }

    if (filters.length > 0) {
      query += ` WHERE ${filters.join(" AND ")}`;
    }

    query += " ORDER BY created_at DESC";

    const result = await pool.query(query, params);
    res.json(result.rows.map(mapProjectRow));
  } catch (error) {
    console.error("Error fetching projects:", error);
    res.status(500).json({ error: "Kunne ikke hente prosjekter" });
  }
});

