async function compatReadProjectMetadata(
  projectId: string,
): Promise<Record<string, unknown> | null> {
  try {
    const result = await pool.query(
      "SELECT metadata FROM legacy.projects WHERE id = $1 LIMIT 1",
      [projectId],
    );
    if (!result.rowCount || result.rowCount === 0) return null;
    const raw = result.rows[0]?.metadata;
    if (!raw) return {};
    if (typeof raw === "object") return raw as Record<string, unknown>;
    if (typeof raw === "string") {
      try {
        const parsed = JSON.parse(raw);
        return typeof parsed === "object" && parsed ? parsed : {};
      } catch {
        return {};
      }
    }
    return {};
  } catch {
    return null;
  }
}

async function compatMergeProjectMetadata(
  projectId: string,
  patch: Record<string, unknown>,
) {
  try {
    await pool.query(
      `UPDATE legacy.projects
       SET metadata = COALESCE(metadata, '{}')::jsonb || $1::jsonb,
           updated_at = NOW()
       WHERE id = $2`,
      [JSON.stringify(patch), projectId],
    );
  } catch {
    // Metadata persistence is best-effort for compatibility routes.
  }
}

function compatPushProjectAudit(
  projectId: string,
  action: string,
  details?: Record<string, unknown>,
) {
  const state = ensureCompatProjectState(projectId);
  state.auditTrail.unshift({
    id: crypto.randomUUID(),
    action,
    details: details || {},
    timestamp: new Date().toISOString(),
  });
  if (state.auditTrail.length > 500) state.auditTrail.length = 500;
  compatProjectStateStore.set(projectId, state);
  void compatStoreSet(dbCompatProjectStateKey(projectId), state);
}

// Wedding projects alias used by universal dashboard/showcase
app.get("/api/wedding-projects", async (req, res) => {
  try {
    const userId = compatResolveUserId(req);
    const params: Array<string> = [];
    const clauses = [
      `(COALESCE(category, '') ILIKE 'wedding%' OR COALESCE(profession, '') IN ('photographer','wedding'))`,
    ];
    if (userId && userId !== "guest") {
      params.push(userId);
      clauses.push(`user_id = $${params.length}`);
    }
    const query = `
      SELECT * FROM legacy.projects
      WHERE ${clauses.join(" AND ")}
      ORDER BY created_at DESC
      LIMIT 200
    `;
    const result = await pool.query(query, params);
    const projects = result.rows.map((row: any) => ({
      ...mapProjectRow(row),
      projectType: "wedding",
    }));
    res.json({ success: true, projects });
  } catch (error) {
    console.warn(
      "Wedding projects query failed, returning empty list:",
      (error as Error).message,
    );
    res.json({ success: true, projects: [] });
  }
});

