// POST /api/projects/:projectId/shots/:shotId/link-asset — mark a shot
// in the shot list as captured by linking it to an uploaded asset.
// Used by the iPad (Phase 2B Lag D follow-up) and can also be called
// from the web review surface.
app.post(
  "/api/projects/:projectId/shots/:shotId/link-asset",
  async (req, res) => {
    try {
      const { projectId, shotId } = req.params;
      const userId = getUserIdFromAuth(req);
      if (!userId) {
        return res.status(401).json({ error: "unauthorized" });
      }
      const capturedAssetId =
        typeof req.body?.capturedAssetId === "string" && req.body.capturedAssetId
          ? req.body.capturedAssetId
          : req.body?.capturedAssetId === null
            ? null
            : undefined;
      if (capturedAssetId === undefined) {
        return res
          .status(400)
          .json({ error: "capturedAssetId is required (use null to unlink)" });
      }
      const result = await linkShotToAsset(
        db as any,
        userId,
        projectId,
        shotId,
        capturedAssetId,
      );
      if (!result.ok) {
        return res.status(404).json({ error: result.error });
      }
      // Push the link change to every iPad/web surface signed in as
      // this photographer so their Live Set dashboards swap the
      // missing-tile for a thumbnail without polling. Best-effort.
      broadcastUserEvent(userId, {
        kind: "shot.captured",
        projectId,
        shotId,
        capturedAssetId,
        timestamp: new Date().toISOString(),
      });
      res.json({ success: true, data: result.data });
    } catch (error) {
      console.error("Error linking shot to asset:", error);
      res.status(500).json({ error: "Kunne ikke knytte shot til asset" });
    }
  },
);

// GET /api/user/meeting-preferences — load meeting preferences
app.get("/api/user/meeting-preferences", async (req, res) => {
  try {
    const userId = getUserIdFromAuth(req);
    const profession =
      typeof req.query.profession === "string" ? req.query.profession : null;
    const tableCheck = await pool.query(
      `SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'user_meeting_preferences')`,
    );
    if (!tableCheck.rows[0].exists) {
      return res.json({ meetingOption: "auto", meetingDuration: 60 });
    }

    let result;
    if (userId) {
      result = await pool.query(
        "SELECT * FROM user_meeting_preferences WHERE user_id = $1 ORDER BY created_at DESC LIMIT 1",
        [userId],
      );
    } else if (profession) {
      result = await pool.query(
        "SELECT * FROM user_meeting_preferences WHERE profession = $1 ORDER BY created_at DESC LIMIT 1",
        [profession],
      );
    } else {
      return res.json({ meetingOption: "auto", meetingDuration: 60 });
    }

    if (result.rowCount === 0) {
      return res.json({ meetingOption: "auto", meetingDuration: 60 });
    }

    const prefs = result.rows[0];
    res.json({
      meetingOption: prefs.meeting_option || "auto",
      meetingDuration: prefs.meeting_duration || 60,
      meetingTime: prefs.meeting_time || null,
      profession: prefs.profession || profession,
    });
  } catch (error) {
    console.error("Error fetching meeting preferences:", error);
    res.json({ meetingOption: "auto", meetingDuration: 60 });
  }
});

// POST /api/user/meeting-preferences — save meeting preferences
app.post("/api/user/meeting-preferences", async (req, res) => {
  try {
    const userId = getUserIdFromAuth(req);
    const { meetingOption, meetingDuration, meetingTime, profession } =
      req.body;

    const tableCheck = await pool.query(
      `SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'user_meeting_preferences')`,
    );
    if (!tableCheck.rows[0].exists) {
      return res.json({ success: true });
    }

    // Delete existing preferences for this user, then insert fresh
    if (userId) {
      await pool.query(
        "DELETE FROM user_meeting_preferences WHERE user_id = $1",
        [userId],
      );
    }

    await pool.query(
      `INSERT INTO user_meeting_preferences (user_id, profession, meeting_option, meeting_duration, meeting_time, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, NOW(), NOW())`,
      [
        userId || "anonymous",
        profession || "photographer",
        meetingOption || "auto",
        meetingDuration || 60,
        meetingTime || null,
      ],
    );

    res.json({ success: true, message: "Møtepreferanser lagret" });
  } catch (error) {
    console.error("Error saving meeting preferences:", error);
    res.json({ success: true });
  }
});

// POST /api/worklog — create worklog entry
app.post("/api/worklog", async (req, res) => {
  try {
    const { projectId, description, hours, date, type, userId, task } =
      req.body;

    const tableCheck = await pool.query(
      `SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'worklogs')`,
    );

    if (tableCheck.rows[0].exists) {
      // worklogs table has: id, project_id, task, description, time_spent, date, status, tags
      const result = await pool.query(
        `INSERT INTO worklogs (id, project_id, task, description, time_spent, date, status, created_at, updated_at)
         VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, NOW(), NOW())
         RETURNING *`,
        [
          projectId || null,
          task || type || "general",
          description || "",
          hours ? hours * 60 : 0,
          date || new Date().toISOString(),
          "completed",
        ],
      );
      return res.status(201).json(result.rows[0]);
    }

    // Fallback: try worklog_entries table
    const entryTableCheck = await pool.query(
      `SELECT EXISTS (SELECT FROM information_schema.tables WHERE table_name = 'worklog_entries')`,
    );
    if (entryTableCheck.rows[0].exists) {
      // worklog_entries has: id, user_id, project_id, day, title, description, time_spent, category
      const result = await pool.query(
        `INSERT INTO worklog_entries (id, user_id, project_id, title, description, time_spent, category, date, created_at, updated_at)
         VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, $7, NOW(), NOW())
         RETURNING *`,
        [
          userId || getUserIdFromAuth(req) || null,
          projectId || null,
          task || type || "general",
          description || "",
          hours ? hours * 60 : 0,
          type || "general",
          date || new Date().toISOString(),
        ],
      );
      return res.status(201).json(result.rows[0]);
    }

    // Return mock success if no worklog table
    res
      .status(201)
      .json({
        id: `wl_${Date.now()}`,
        description,
        hours,
        date,
        type,
        projectId,
      });
  } catch (error) {
    console.error("Error creating worklog:", error);
    res.status(500).json({ error: "Kunne ikke opprette arbeidslogg" });
  }
});

// PATCH /api/worklog/:id — Update worklog entry
app.patch("/api/worklog/:id", async (req, res) => {
  try {
    const { id } = req.params;
    const {
      title,
      description,
      timeSpent,
      category,
      mood,
      nextSteps,
      isPrivate,
      day,
    } = req.body || {};
    const internalNotes = JSON.stringify({ mood, nextSteps, day });

    const milestoneUpdate = await pool.query(
      `UPDATE project_milestones
       SET title = COALESCE($1, title),
           description = COALESCE($2, description),
           category = COALESCE($3, category),
           time_spent = COALESCE($4, time_spent),
           client_visible = COALESCE($5, client_visible),
           internal_notes = COALESCE($6, internal_notes),
           updated_at = NOW()
       WHERE id = $7 AND type = 'worklog'
       RETURNING *`,
      [
        title || null,
        description || null,
        category || null,
        timeSpent ?? null,
        typeof isPrivate === "boolean" ? !isPrivate : null,
        internalNotes || null,
        id,
      ],
    );

    if (milestoneUpdate.rowCount) {
      return res.json(milestoneUpdate.rows[0]);
    }

    const entryUpdate = await pool.query(
      `UPDATE worklog_entries
       SET title = COALESCE($1, title),
           description = COALESCE($2, description),
           category = COALESCE($3, category),
           time_spent = COALESCE($4, time_spent),
           updated_at = NOW()
       WHERE id = $5
       RETURNING *`,
      [
        title || null,
        description || null,
        category || null,
        timeSpent ?? null,
        id,
      ],
    );

    if (entryUpdate.rowCount) {
      return res.json(entryUpdate.rows[0]);
    }

    const legacyUpdate = await pool.query(
      `UPDATE worklogs
       SET task = COALESCE($1, task),
           description = COALESCE($2, description),
           time_spent = COALESCE($3, time_spent),
           updated_at = NOW()
       WHERE id = $4
       RETURNING *`,
      [title || null, description || null, timeSpent ?? null, id],
    );

    if (!legacyUpdate.rowCount) {
      return res.status(404).json({ error: "Arbeidslogg ikke funnet" });
    }

    res.json(legacyUpdate.rows[0]);
  } catch (error) {
    console.error("Error updating worklog:", error);
    res.status(500).json({ error: "Kunne ikke oppdatere arbeidslogg" });
  }
});

// DELETE /api/worklog/:id — Delete worklog entry
app.delete("/api/worklog/:id", async (req, res) => {
  try {
    const { id } = req.params;

    const milestoneDelete = await pool.query(
      `DELETE FROM project_milestones WHERE id = $1 AND type = 'worklog' RETURNING id`,
      [id],
    );
    if (milestoneDelete.rowCount) {
      return res.json({ deleted: true, id });
    }

    const entryDelete = await pool.query(
      `DELETE FROM worklog_entries WHERE id = $1 RETURNING id`,
      [id],
    );
    if (entryDelete.rowCount) {
      return res.json({ deleted: true, id });
    }

    const legacyDelete = await pool.query(
      `DELETE FROM worklogs WHERE id = $1 RETURNING id`,
      [id],
    );
    if (legacyDelete.rowCount) {
      return res.json({ deleted: true, id });
    }

    res.status(404).json({ error: "Arbeidslogg ikke funnet" });
  } catch (error) {
    console.error("Error deleting worklog:", error);
    res.status(500).json({ error: "Kunne ikke slette arbeidslogg" });
  }
});

