// ============================================================================
// EVENDI API PROXY + PLANNING TIMELINES
// (formerly WEDFLOW — rebranded to Evendi event ecosystem)
// ============================================================================

// Backward-compat middleware: /api/wedflow/* → rewrite to /api/evendi/*
// so legacy clients that still call /api/wedflow/* continue to work.
// All canonical routes are now registered under /api/evendi/*.
app.use("/api/wedflow", (req, _res, next) => {
  const originalUrl = req.originalUrl;
  req.url = originalUrl.replace("/api/wedflow", "/api/evendi");
  next("route");
});
app.all("/api/wedflow/*", (req, res, next) => {
  req.url = req.url.replace("/api/wedflow", "/api/evendi");
  req.originalUrl = req.originalUrl.replace("/api/wedflow", "/api/evendi");
  (req.app as any).handle(req, res, next);
});

const CREATORHUB_API_KEY = process.env.CREATORHUB_API_KEY || "";
const EVENDI_SMOKE_SECRET =
  process.env.EVENDI_ADMIN_SECRET ||
  process.env.WEDFLOW_ADMIN_SECRET ||
  process.env.EXPO_PUBLIC_ADMIN_SECRET ||
  "";

const isEvendiSmokeAuthorized = (req: any) => {
  if (!EVENDI_SMOKE_SECRET) return false;
  const header = req.get("x-admin-secret") || req.get("x-evendi-admin-secret");
  return header && header === EVENDI_SMOKE_SECRET;
};

async function runEvendiSmoke(path: string) {
  const url = `${EVENDI_API_URL}${path}`;
  const response = await fetch(url, {
    headers: {
      "Content-Type": "application/json",
      "X-API-Key": CREATORHUB_API_KEY,
    },
  });
  const contentType = response.headers.get("content-type") || "";
  const payload = contentType.includes("application/json")
    ? await response.json()
    : await response.text();

  return {
    status: response.status,
    ok: response.ok,
    data: payload,
  };
}

// ── Couple Planning Timelines (MUST be registered BEFORE the wildcard proxy) ──

// Helper: resolve :coupleId param — accepts UUID, email, or resolves from project
async function resolveCoupleId(coupleIdParam: string): Promise<string | null> {
  // If it's already a UUID, verify it exists
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (uuidRegex.test(coupleIdParam)) {
    const r = await pool.query("SELECT id FROM couple_profiles WHERE id = $1", [
      coupleIdParam,
    ]);
    return r.rowCount && r.rowCount > 0 ? r.rows[0].id : null;
  }
  // Try by email
  const byEmail = await pool.query(
    "SELECT id FROM couple_profiles WHERE email = $1",
    [coupleIdParam],
  );
  if (byEmail.rowCount && byEmail.rowCount > 0) return byEmail.rows[0].id;
  // Try by display_name (partial)
  const byName = await pool.query(
    "SELECT id FROM couple_profiles WHERE LOWER(display_name) LIKE $1 LIMIT 1",
    [`%${coupleIdParam.toLowerCase()}%`],
  );
  if (byName.rowCount && byName.rowCount > 0) return byName.rows[0].id;
  return null;
}

// GET /api/evendi/planning/project/:projectId/couple — resolve couple from project
app.get("/api/evendi/planning/project/:projectId/couple", async (req, res) => {
  try {
    const { projectId } = req.params;
    // Get project client email from legacy.projects
    const proj = await pool.query(
      "SELECT client_email, name, title FROM legacy.projects WHERE id = $1",
      [projectId],
    );
    if (proj.rowCount === 0)
      return res.status(404).json({ error: "Prosjekt ikke funnet" });

    const {
      client_email,
      name: projectName,
      title: projectTitle,
    } = proj.rows[0];
    if (!client_email)
      return res
        .status(404)
        .json({ error: "Prosjektet har ingen klient-epost" });

    // Find or create couple_profile
    let cp = await pool.query(
      "SELECT id, email, display_name FROM couple_profiles WHERE email = $1",
      [client_email],
    );
    if (cp.rowCount === 0) {
      // Auto-create couple_profile from project client info
      const newId = crypto.randomUUID();
      cp = await pool.query(
        `INSERT INTO couple_profiles (id, email, display_name, password, created_at, updated_at)
         VALUES ($1, $2, $3, 'auto_created', NOW(), NOW()) RETURNING id, email, display_name`,
        [newId, client_email, projectName || projectTitle || "Brudepar"],
      );
    }
    res.json({
      coupleId: cp.rows[0].id,
      email: cp.rows[0].email,
      displayName: cp.rows[0].display_name,
      projectId,
    });
  } catch (error) {
    console.error("Error resolving couple from project:", error);
    res.status(500).json({ error: "Kunne ikke finne brudepar" });
  }
});

// Helper: map a couple planning timeline row
function mapPlanningTimeline(tableName: string, row: any) {
  const category = tableName
    .replace("couple_", "")
    .replace("_timeline", "")
    .replace("_timelines", "");
  return { ...row, category, tableName };
}

// GET /api/evendi/planning/:coupleId — get all planning progress for a couple
app.get("/api/evendi/planning/:coupleId", async (req, res) => {
  try {
    const coupleId =
      (await resolveCoupleId(req.params.coupleId)) || req.params.coupleId;
    const planningTables = [
      { table: "couple_venue_timelines", category: "venue", label: "Lokale" },
      { table: "couple_cake_timeline", category: "cake", label: "Kake" },
      {
        table: "couple_catering_timeline",
        category: "catering",
        label: "Catering",
      },
      { table: "couple_dress_timeline", category: "dress", label: "Kjole" },
      {
        table: "couple_flower_timeline",
        category: "flower",
        label: "Blomster",
      },
      {
        table: "couple_hair_makeup_timeline",
        category: "hair_makeup",
        label: "Hår & Makeup",
      },
      {
        table: "couple_transport_timeline",
        category: "transport",
        label: "Transport",
      },
    ];

    const results: any[] = [];
    for (const pt of planningTables) {
      try {
        const r = await pool.query(
          `SELECT * FROM ${pt.table} WHERE couple_id = $1`,
          [coupleId],
        );
        if (r.rowCount && r.rowCount > 0) {
          results.push({
            ...r.rows[0],
            category: pt.category,
            label: pt.label,
          });
        } else {
          results.push({
            couple_id: coupleId,
            category: pt.category,
            label: pt.label,
            status: "not_started",
          });
        }
      } catch {
        /* table may not exist */
      }
    }

    // Also fetch schedule events
    try {
      const schedEvts = await pool.query(
        "SELECT * FROM schedule_events WHERE couple_id = $1 ORDER BY sort_order",
        [coupleId],
      );
      results.push({
        category: "schedule",
        label: "Tidsplan",
        events: schedEvts.rows,
      });
    } catch {
      /* table may not exist */
    }

    res.json({ coupleId, planning: results });
  } catch (error) {
    console.error("Error fetching planning data:", error);
    res.status(500).json({ error: "Kunne ikke hente planleggingsdata" });
  }
});

