type AiModelCategory =
  | "enhancement"
  | "analysis"
  | "story_arc"
  | "audio"
  | "video";
type AiModelStorageType = "r2" | "local" | "virtual";

interface AiModelSpec {
  id: string;
  modelType: string;
  storageType: AiModelStorageType;
  r2Key: string | null;
  basePath: string | null;
  required: boolean;
  categories: AiModelCategory[];
  description: string;
  aliases: string[];
  candidateKeys: string[];
  dependencyIds: string[];
}

interface AiModelStatus {
  id: string;
  modelType: string;
  aliases: string[];
  categories: AiModelCategory[];
  storageType: AiModelStorageType;
  required: boolean;
  available: boolean;
  reason: string;
  checkedAt: string;
  resolvedPath: string | null;
  dependencyIds: string[];
  r2: {
    bucket: string;
    key: string;
    folder: string;
  } | null;
}

interface AiModelStatusPayload {
  initialized: boolean;
  modelCount: number;
  modelCountRequired: number;
  availableCount: number;
  unavailableCount: number;
  modelCountByCategory: Record<AiModelCategory, number>;
  modelTypes: Record<AiModelCategory, string[]>;
  models: AiModelStatus[];
  checkedAt: string;
  cacheHit: boolean;
  r2: {
    enabled: boolean;
    endpoint: string | null;
    buckets: string[];
    prefixes: string[];
  };
}

interface R2RuntimeConfig {
  enabled: boolean;
  endpoint: string | null;
  accessKeyId: string | null;
  secretAccessKey: string | null;
  buckets: string[];
  prefixes: string[];
}

interface R2ResolutionResult {
  found: boolean;
  bucket: string | null;
  key: string | null;
  folder: string | null;
  reason: string;
}

