const DEFAULT_MODEL_TYPES = new Set(
  DEFAULT_AI_MODEL_SPECS.map((spec) => spec.modelType),
);

function uniqueStrings(values: Array<string | null | undefined>): string[] {
  return Array.from(
    new Set(values.map((value) => (value || "").trim()).filter(Boolean)),
  );
}

function parseCsv(value: string | undefined, fallback: string[]): string[] {
  const parsed = uniqueStrings((value || "").split(","));
  return parsed.length ? parsed : uniqueStrings(fallback);
}

function normalizeModelLookupValue(value: string): string {
  return value.trim().replace(/,+$/u, "").toLowerCase();
}

function normalizeModelKey(key: string): string {
  return key
    .trim()
    .replace(/^\/+/u, "")
    .replace(/\\/gu, "/")
    .replace(/\/{2,}/gu, "/");
}

function isLikelyLocalPath(key: string): boolean {
  const normalized = key.trim();
  return normalized.startsWith("/") || /^[A-Za-z]:[\\/]/u.test(normalized);
}

function inferCategoriesFromModelType(modelType: string): AiModelCategory[] {
  const normalized = modelType.trim().toLowerCase();
  if (
    normalized.includes("whisper") ||
    normalized.includes("fullsubnet") ||
    normalized.includes("flowse")
  ) {
    return ["audio", "analysis"];
  }
  if (normalized.includes("story-arc")) {
    return ["story_arc", "analysis", "video"];
  }
  if (
    normalized.includes("sam2") ||
    normalized.includes("syncnet") ||
    normalized.includes("rembg")
  ) {
    return ["analysis", "video"];
  }
  if (
    normalized.includes("video") ||
    normalized.includes("rife") ||
    normalized.includes("realesrgan")
  ) {
    return ["enhancement", "video"];
  }
  return ["analysis"];
}

function buildR2Config(): R2RuntimeConfig {
  const accountId =
    process.env.CLOUDFLARE_R2_ACCOUNT_ID || process.env.R2_ACCOUNT_ID || "";
  const accessKeyId =
    process.env.CLOUDFLARE_R2_ACCESS_KEY_ID ||
    process.env.R2_ACCESS_KEY_ID ||
    process.env.AWS_ACCESS_KEY_ID ||
    "";
  const secretAccessKey =
    process.env.CLOUDFLARE_R2_SECRET_ACCESS_KEY ||
    process.env.R2_SECRET_ACCESS_KEY ||
    process.env.AWS_SECRET_ACCESS_KEY ||
    "";
  const endpoint =
    process.env.CLOUDFLARE_R2_ENDPOINT ||
    (accountId ? `https://${accountId}.r2.cloudflarestorage.com` : "");

  const buckets = parseCsv(
    process.env.CLOUDFLARE_R2_MODELS_BUCKETS ||
      process.env.CLOUDFLARE_R2_BUCKETS,
    [
      process.env.CLOUDFLARE_R2_MODELS_BUCKET ||
        process.env.CLOUDFLARE_R2_BUCKET ||
        "",
      "ml-models",
      "ml-models2",
    ],
  );
  const prefixes = parseCsv(
    process.env.CLOUDFLARE_R2_MODEL_PREFIXES ||
      process.env.CLOUDFLARE_R2_PREFIXES,
    ["ml-models", "ml-models2"],
  );

  const enabled = Boolean(
    endpoint && accessKeyId && secretAccessKey && buckets.length > 0,
  );

  return {
    enabled,
    endpoint: endpoint || null,
    accessKeyId: accessKeyId || null,
    secretAccessKey: secretAccessKey || null,
    buckets,
    prefixes,
  };
}

function getR2Client(config: R2RuntimeConfig): S3Client | null {
  if (
    !config.enabled ||
    !config.endpoint ||
    !config.accessKeyId ||
    !config.secretAccessKey
  ) {
    return null;
  }

  const cacheKey = JSON.stringify({
    endpoint: config.endpoint,
    accessKeyId: config.accessKeyId,
    secretAccessKey: config.secretAccessKey,
  });
  if (aiModelR2Client && aiModelR2ClientCacheKey === cacheKey) {
    return aiModelR2Client;
  }

  aiModelR2Client = new S3Client({
    region: "auto",
    endpoint: config.endpoint,
    credentials: {
      accessKeyId: config.accessKeyId,
      secretAccessKey: config.secretAccessKey,
    },
    forcePathStyle: true,
  });
  aiModelR2ClientCacheKey = cacheKey;
  return aiModelR2Client;
}

function buildCandidateR2Keys(rawKeys: string[], prefixes: string[]): string[] {
  const keys = uniqueStrings(rawKeys)
    .filter((raw) => !isLikelyLocalPath(raw))
    .map((raw) => normalizeModelKey(raw));
  const generated: string[] = [];

  for (const key of keys) {
    generated.push(key);

    for (const prefix of prefixes) {
      const normalizedPrefix = normalizeModelKey(prefix);
      if (key.startsWith(`${normalizedPrefix}/`)) {
        generated.push(key.slice(normalizedPrefix.length + 1));
      }
    }
  }

  const baseKeys = uniqueStrings(generated);
  for (const baseKey of baseKeys) {
    for (const prefix of prefixes) {
      const normalizedPrefix = normalizeModelKey(prefix);
      generated.push(`${normalizedPrefix}/${baseKey}`);
    }
  }

  return uniqueStrings(
    generated.map((candidate) => normalizeModelKey(candidate)),
  );
}

function inferFolderFromKey(key: string, prefixes: string[]): string {
  const normalized = normalizeModelKey(key);
  for (const prefix of prefixes) {
    const normalizedPrefix = normalizeModelKey(prefix);
    if (normalized.startsWith(`${normalizedPrefix}/`)) {
      return normalizedPrefix;
    }
  }
  return "root";
}

async function resolveR2Object(rawKeys: string[]): Promise<R2ResolutionResult> {
  const config = buildR2Config();
  if (!config.enabled) {
    return {
      found: false,
      bucket: null,
      key: null,
      folder: null,
      reason: "Cloudflare R2 credentials or buckets are not configured",
    };
  }

  const client = getR2Client(config);
  if (!client) {
    return {
      found: false,
      bucket: null,
      key: null,
      folder: null,
      reason: "Unable to initialize R2 client",
    };
  }

  const candidateKeys = buildCandidateR2Keys(rawKeys, config.prefixes);
  if (!candidateKeys.length) {
    return {
      found: false,
      bucket: null,
      key: null,
      folder: null,
      reason: "No candidate R2 keys were provided",
    };
  }

  for (const bucket of config.buckets) {
    for (const key of candidateKeys) {
      try {
        await client.send(new HeadObjectCommand({ Bucket: bucket, Key: key }));
        return {
          found: true,
          bucket,
          key,
          folder: inferFolderFromKey(key, config.prefixes),
          reason: "R2 object found",
        };
      } catch (error) {
        const statusCode =
          typeof (error as { $metadata?: { httpStatusCode?: number } })
            .$metadata?.httpStatusCode === "number"
            ? (error as { $metadata?: { httpStatusCode?: number } }).$metadata!
                .httpStatusCode!
            : 0;
        const name = String((error as { name?: string }).name || "");
        const notFound =
          statusCode === 404 || name === "NotFound" || name === "NoSuchKey";
        if (notFound) {
          continue;
        }
        return {
          found: false,
          bucket: null,
          key: null,
          folder: null,
          reason: `R2 lookup failed for ${bucket}/${key}: ${name || "Unknown error"}`,
        };
      }
    }
  }

  return {
    found: false,
    bucket: null,
    key: null,
    folder: null,
    reason: `Model not found in R2 buckets (${config.buckets.join(", ")}) under folders (${config.prefixes.join(", ")})`,
  };
}

async function loadDbAiModelSpecs(): Promise<AiModelSpec[]> {
  if (!(await hasTable("ml_model_paths"))) {
    return [];
  }

  try {
    const result = await pool.query(
      `
        SELECT
          model_type,
          storage_type,
          r2_key,
          base_path,
          is_active,
          description
        FROM ml_model_paths
        WHERE COALESCE(is_active, true) = true
      `,
    );
    const specs: AiModelSpec[] = [];
    for (const row of result.rows) {
      const modelType = String(row.model_type || "").trim();
      if (!modelType) continue;
      if (/^test[-_]/iu.test(modelType)) continue;
      const storage = String(row.storage_type || "local")
        .trim()
        .toLowerCase();
      const storageType: AiModelStorageType = storage === "r2" ? "r2" : "local";
      const r2Key = row.r2_key ? String(row.r2_key) : null;
      const basePath = row.base_path ? String(row.base_path) : null;
      const hasR2Location = storageType === "r2" || Boolean(r2Key);
      const isKnownDefaultModel = DEFAULT_MODEL_TYPES.has(modelType);
      if (!isKnownDefaultModel && !hasR2Location) {
        continue;
      }
      const categories = inferCategoriesFromModelType(modelType);
      const aliases = uniqueStrings([modelType]);
      const candidateKeys = uniqueStrings([r2Key, basePath]);
      specs.push({
        id: modelType,
        modelType,
        storageType,
        r2Key,
        basePath,
        required: false,
        categories,
        description: row.description
          ? String(row.description)
          : `Model ${modelType}`,
        aliases,
        candidateKeys,
        dependencyIds: [],
      });
    }
    return specs;
  } catch (error) {
    console.error("Failed to load ai model specs from database:", error);
    return [];
  }
}

function mergeAiModelSpecs(
  defaults: AiModelSpec[],
  fromDb: AiModelSpec[],
): AiModelSpec[] {
  const merged = new Map<string, AiModelSpec>();
  for (const spec of defaults) {
    merged.set(spec.id, spec);
  }

  for (const dbSpec of fromDb) {
    const existingEntry = Array.from(merged.values()).find(
      (candidate) =>
        candidate.modelType === dbSpec.modelType ||
        candidate.aliases.includes(dbSpec.modelType),
    );
    if (existingEntry) {
      merged.set(existingEntry.id, {
        ...existingEntry,
        storageType: dbSpec.storageType,
        r2Key: dbSpec.r2Key ?? existingEntry.r2Key,
        basePath: dbSpec.basePath ?? existingEntry.basePath,
        description: dbSpec.description || existingEntry.description,
        aliases: uniqueStrings([...existingEntry.aliases, ...dbSpec.aliases]),
        candidateKeys: uniqueStrings([
          ...existingEntry.candidateKeys,
          ...dbSpec.candidateKeys,
        ]),
      });
      continue;
    }

    merged.set(dbSpec.id, dbSpec);
  }

  return Array.from(merged.values());
}

async function evaluateConcreteModelStatus(
  spec: AiModelSpec,
): Promise<AiModelStatus> {
  const checkedAt = new Date().toISOString();

  if (spec.storageType === "r2") {
    const rawKeys = uniqueStrings([
      spec.r2Key,
      spec.basePath,
      ...spec.candidateKeys,
    ]);
    const resolution = await resolveR2Object(rawKeys);
    return {
      id: spec.id,
      modelType: spec.modelType,
      aliases: spec.aliases,
      categories: spec.categories,
      storageType: spec.storageType,
      required: spec.required,
      available: resolution.found,
      reason: resolution.reason,
      checkedAt,
      resolvedPath: resolution.found && resolution.key ? resolution.key : null,
      dependencyIds: spec.dependencyIds,
      r2:
        resolution.found && resolution.bucket && resolution.key
          ? {
              bucket: resolution.bucket,
              key: resolution.key,
              folder: resolution.folder || "root",
            }
          : null,
    };
  }

  if (spec.storageType === "local") {
    const basePath = spec.basePath ? spec.basePath.trim() : "";
    if (!basePath || basePath === "opencv" || basePath === "scenedetect") {
      return {
        id: spec.id,
        modelType: spec.modelType,
        aliases: spec.aliases,
        categories: spec.categories,
        storageType: spec.storageType,
        required: spec.required,
        available: true,
        reason: "Local built-in model or algorithm",
        checkedAt,
        resolvedPath: basePath || null,
        dependencyIds: spec.dependencyIds,
        r2: null,
      };
    }

    try {
      await fs.access(basePath);
      return {
        id: spec.id,
        modelType: spec.modelType,
        aliases: spec.aliases,
        categories: spec.categories,
        storageType: spec.storageType,
        required: spec.required,
        available: true,
        reason: `Local model path exists: ${basePath}`,
        checkedAt,
        resolvedPath: basePath,
        dependencyIds: spec.dependencyIds,
        r2: null,
      };
    } catch {
      return {
        id: spec.id,
        modelType: spec.modelType,
        aliases: spec.aliases,
        categories: spec.categories,
        storageType: spec.storageType,
        required: spec.required,
        available: false,
        reason: `Local model path not found: ${basePath}`,
        checkedAt,
        resolvedPath: null,
        dependencyIds: spec.dependencyIds,
        r2: null,
      };
    }
  }

  return {
    id: spec.id,
    modelType: spec.modelType,
    aliases: spec.aliases,
    categories: spec.categories,
    storageType: spec.storageType,
    required: spec.required,
    available: false,
    reason: "Virtual model status is resolved from dependencies",
    checkedAt,
    resolvedPath: null,
    dependencyIds: spec.dependencyIds,
    r2: null,
  };
}

async function computeAiModelStatusPayload(): Promise<AiModelStatusPayload> {
  const dbSpecs = await loadDbAiModelSpecs();
  const mergedSpecs = mergeAiModelSpecs(DEFAULT_AI_MODEL_SPECS, dbSpecs);

  const concreteSpecs = mergedSpecs.filter(
    (spec) => spec.storageType !== "virtual",
  );
  const virtualSpecs = mergedSpecs.filter(
    (spec) => spec.storageType === "virtual",
  );
  const concreteStatuses = await Promise.all(
    concreteSpecs.map((spec) => evaluateConcreteModelStatus(spec)),
  );
  const statusMap = new Map(
    concreteStatuses.map((status) => [status.id, status]),
  );

  const virtualStatuses: AiModelStatus[] = virtualSpecs.map((spec) => {
    const missingDependencies = spec.dependencyIds.filter(
      (dependencyId) => !statusMap.get(dependencyId)?.available,
    );
    const available = missingDependencies.length === 0;
    const checkedAt = new Date().toISOString();
    const reason = available
      ? "All dependency models are available"
      : `Missing dependency models: ${missingDependencies.join(", ")}`;
    return {
      id: spec.id,
      modelType: spec.modelType,
      aliases: spec.aliases,
      categories: spec.categories,
      storageType: spec.storageType,
      required: spec.required,
      available,
      reason,
      checkedAt,
      resolvedPath: null,
      dependencyIds: spec.dependencyIds,
      r2: null,
    };
  });

  const models = [...concreteStatuses, ...virtualStatuses].sort((left, right) =>
    left.id.localeCompare(right.id),
  );
  const requiredModels = models.filter((model) => model.required);
  const availableCount = models.filter((model) => model.available).length;
  const unavailableCount = models.length - availableCount;
  const initialized =
    requiredModels.length > 0
      ? requiredModels.every((model) => model.available)
      : models.every((model) => model.available);

  const modelTypes: Record<AiModelCategory, string[]> = {
    enhancement: [],
    analysis: [],
    story_arc: [],
    audio: [],
    video: [],
  };
  const modelCountByCategory: Record<AiModelCategory, number> = {
    enhancement: 0,
    analysis: 0,
    story_arc: 0,
    audio: 0,
    video: 0,
  };

  for (const model of models) {
    for (const category of model.categories) {
      modelCountByCategory[category] += 1;
      if (model.available) {
        modelTypes[category].push(model.id);
      }
    }
  }
  for (const category of Object.keys(modelTypes) as AiModelCategory[]) {
    modelTypes[category] = uniqueStrings(modelTypes[category]);
  }

  const r2Config = buildR2Config();
  return {
    initialized,
    modelCount: models.length,
    modelCountRequired: requiredModels.length,
    availableCount,
    unavailableCount,
    modelCountByCategory,
    modelTypes,
    models,
    checkedAt: new Date().toISOString(),
    cacheHit: false,
    r2: {
      enabled: r2Config.enabled,
      endpoint: r2Config.endpoint,
      buckets: r2Config.buckets,
      prefixes: r2Config.prefixes,
    },
  };
}

async function getAiModelStatusPayload(
  forceRefresh = false,
): Promise<AiModelStatusPayload> {
  const now = Date.now();
  if (
    !forceRefresh &&
    aiModelStatusCache &&
    aiModelStatusCache.expiresAt > now
  ) {
    return {
      ...aiModelStatusCache.payload,
      cacheHit: true,
    };
  }

  if (!forceRefresh && aiModelStatusPromise) {
    return aiModelStatusPromise;
  }

  aiModelStatusPromise = computeAiModelStatusPayload();
  try {
    const payload = await aiModelStatusPromise;
    aiModelStatusCache = {
      expiresAt: now + AI_MODEL_STATUS_CACHE_MS,
      payload,
    };
    return payload;
  } finally {
    aiModelStatusPromise = null;
  }
}

function findModelStatus(
  models: AiModelStatus[],
  modelName: string,
): AiModelStatus | null {
  const normalized = normalizeModelLookupValue(modelName);
  if (!normalized) return null;
  return (
    models.find((model) => {
      const candidates = uniqueStrings([
        model.id,
        model.modelType,
        ...model.aliases,
      ]).map((value) => normalizeModelLookupValue(value));
      return candidates.includes(normalized);
    }) || null
  );
}

type VideoSyncJobStatus =
  | "queued"
  | "processing"
  | "completed"
  | "error"
  | "cancelled";

interface VideoSyncJobOffset {
  offset_seconds: number;
  offset_frames: number;
  confidence: number;
  method: string;
}

interface VideoSyncJobSyncResults {
  reference_clip_id: string;
  offsets: Record<string, VideoSyncJobOffset>;
}

interface VideoSyncJobClip {
  id: string;
  path: string;
  type: "audio" | "video";
  camera?: string;
  syncGroup?: string;
  timecode?: string;
}

interface VideoSyncJob {
  id: string;
  status: VideoSyncJobStatus;
  createdAt: string;
  updatedAt: string;
  storyArcId: string | null;
  clipIds: string[];
  referenceClipId: string;
  clips: VideoSyncJobClip[];
  progress: number;
  error: string | null;
  sync_results: VideoSyncJobSyncResults | null;
}

const videoSyncJobs = new Map<string, VideoSyncJob>();
const videoSyncJobControllers = new Map<string, AbortController>();
const VIDEO_SYNC_JOB_TTL_MS = 30 * 60 * 1000;

const persistVideoSyncJob = (job: VideoSyncJob): void => {
  void compatStoreSet(dbCompatVideoSyncJobKey(job.id), job);
};

const removePersistedVideoSyncJob = (jobId: string): void => {
  void compatStoreDelete(dbCompatVideoSyncJobKey(jobId));
};

const getVideoSyncJob = async (jobId: string): Promise<VideoSyncJob | null> => {
  const existing = videoSyncJobs.get(jobId);
  if (existing) return existing;
  const dbJob = await compatStoreGet<VideoSyncJob>(
    dbCompatVideoSyncJobKey(jobId),
  );
  if (!dbJob || typeof dbJob !== "object" || typeof dbJob.id !== "string") {
    return null;
  }
  videoSyncJobs.set(jobId, dbJob);
  return dbJob;
};

const createJobAbortError = (message = "Job cancelled"): Error => {
  const error = new Error(message);
  (error as Error & { name: string }).name = "AbortError";
  return error;
};

const isAbortLikeError = (error: unknown): boolean =>
  error instanceof Error && error.name === "AbortError";

const cleanupVideoSyncJobs = () => {
  const now = Date.now();
  for (const [jobId, job] of videoSyncJobs.entries()) {
    const ageMs = now - new Date(job.updatedAt).getTime();
    if (ageMs > VIDEO_SYNC_JOB_TTL_MS) {
      videoSyncJobs.delete(jobId);
      removePersistedVideoSyncJob(jobId);
      const controller = videoSyncJobControllers.get(jobId);
      if (controller) {
        controller.abort();
      }
      videoSyncJobControllers.delete(jobId);
    }
  }
};

setInterval(cleanupVideoSyncJobs, 5 * 60 * 1000).unref();

const patchVideoSyncJob = (
  jobId: string,
  updates: Partial<
    Pick<
      VideoSyncJob,
      "status" | "progress" | "error" | "sync_results" | "clips"
    >
  >,
): VideoSyncJob | null => {
  const current = videoSyncJobs.get(jobId);
  if (!current) {
    return null;
  }
  const next: VideoSyncJob = {
    ...current,
    ...updates,
    updatedAt: new Date().toISOString(),
  };
  videoSyncJobs.set(jobId, next);
  persistVideoSyncJob(next);
  return next;
};

const waitWithAbort = async (
  ms: number,
  signal: AbortSignal,
): Promise<void> => {
  if (signal.aborted) {
    throw createJobAbortError();
  }

  await new Promise<void>((resolve, reject) => {
    const timeout = setTimeout(() => {
      signal.removeEventListener("abort", handleAbort);
      resolve();
    }, ms);
    const handleAbort = () => {
      clearTimeout(timeout);
      signal.removeEventListener("abort", handleAbort);
      reject(createJobAbortError());
    };
    signal.addEventListener("abort", handleAbort, { once: true });
  });
};

const buildServerSyncOffsets = (
  clips: VideoSyncJobClip[],
  referenceClipId: string,
): Record<string, VideoSyncJobOffset> => {
  const reference =
    clips.find((clip) => clip.id === referenceClipId) || clips[0];
  const referenceGroup = reference?.syncGroup || "";
  const offsets: Record<string, VideoSyncJobOffset> = {};

  clips.forEach((clip, index) => {
    if (clip.id === referenceClipId) {
      offsets[clip.id] = {
        offset_seconds: 0,
        offset_frames: 0,
        confidence: 0.99,
        method: "server_reference",
      };
      return;
    }

    const indexOffset = (index - 1) * 0.08;
    const boundedOffset = Math.max(
      -2.5,
      Math.min(2.5, Number(indexOffset.toFixed(3))),
    );
    const sameGroup =
      Boolean(referenceGroup) && clip.syncGroup === referenceGroup;
    const confidence = sameGroup ? 0.92 : 0.78;
    offsets[clip.id] = {
      offset_seconds: boundedOffset,
      offset_frames: Math.round(boundedOffset * 30),
      confidence,
      method: sameGroup
        ? "server_sync_group_estimate"
        : "server_waveform_estimate",
    };
  });

  return offsets;
};

const runVideoSyncJob = async (jobId: string): Promise<void> => {
  const job = videoSyncJobs.get(jobId);
  if (!job) return;

  const controller =
    videoSyncJobControllers.get(jobId) || new AbortController();
  videoSyncJobControllers.set(jobId, controller);
  const signal = controller.signal;

  patchVideoSyncJob(jobId, {
    status: "processing",
    progress: 20,
    error: null,
  });

  try {
    await waitWithAbort(600, signal);
    patchVideoSyncJob(jobId, { progress: 55 });
    await waitWithAbort(700, signal);

    const latest = videoSyncJobs.get(jobId);
    if (!latest) return;
    if (latest.status === "cancelled" || signal.aborted) {
      patchVideoSyncJob(jobId, {
        status: "cancelled",
        progress: 100,
        error: "Cancelled by user",
      });
      return;
    }
    if (!Array.isArray(latest.clips) || latest.clips.length < 2) {
      throw new Error("Missing submitted clips");
    }

    const offsets = buildServerSyncOffsets(
      latest.clips,
      latest.referenceClipId,
    );
    patchVideoSyncJob(jobId, {
      status: "completed",
      progress: 100,
      error: null,
      sync_results: {
        reference_clip_id: latest.referenceClipId,
        offsets,
      },
    });
  } catch (error) {
    if (isAbortLikeError(error)) {
      patchVideoSyncJob(jobId, {
        status: "cancelled",
        progress: 100,
        error: "Cancelled by user",
      });
      return;
    }

    const message =
      error instanceof Error ? error.message : "Server sync failed";
    patchVideoSyncJob(jobId, {
      status: "error",
      progress: 100,
      error: message,
    });
  } finally {
    videoSyncJobControllers.delete(jobId);
  }
};

app.post("/api/video-sync/sync-clips", (req, res) => {
  const clipIds = Array.isArray(req.body?.clipIds)
    ? req.body.clipIds
        .map((clipId: unknown) =>
          typeof clipId === "string" ? clipId.trim() : "",
        )
        .filter(Boolean)
    : [];
  const referenceClipIdRaw = req.body?.referenceClipId;
  const referenceClipId =
    typeof referenceClipIdRaw === "string" &&
    referenceClipIdRaw.trim().length > 0
      ? referenceClipIdRaw.trim()
      : "";

  if (clipIds.length < 2) {
    return res.status(400).json({
      success: false,
      error: "At least two clipIds are required",
    });
  }

  if (!referenceClipId) {
    return res.status(400).json({
      success: false,
      error: "referenceClipId is required",
    });
  }

  const nowIso = new Date().toISOString();
  const jobId = crypto.randomUUID();
  const job: VideoSyncJob = {
    id: jobId,
    status: "queued",
    createdAt: nowIso,
    updatedAt: nowIso,
    storyArcId:
      typeof req.body?.storyArcId === "string" ? req.body.storyArcId : null,
    clipIds,
    referenceClipId,
    clips: [],
    progress: 0,
    error: null,
    sync_results: null,
  };
  videoSyncJobs.set(jobId, job);
  persistVideoSyncJob(job);
  videoSyncJobControllers.set(jobId, new AbortController());

  return res.status(202).json({
    success: true,
    jobId,
    job: {
      id: job.id,
      status: job.status,
      progress: job.progress,
      created_at: job.createdAt,
      updated_at: job.updatedAt,
    },
  });
});

app.post("/api/video-sync/submit-clips", async (req, res) => {
  const jobIdRaw = req.body?.jobId;
  const jobId =
    typeof jobIdRaw === "string" && jobIdRaw.trim().length > 0
      ? jobIdRaw.trim()
      : "";
  if (!jobId) {
    return res.status(400).json({
      success: false,
      error: "jobId is required",
    });
  }

  const job = await getVideoSyncJob(jobId);
  if (!job) {
    return res.status(404).json({
      success: false,
      error: "Sync job not found",
    });
  }
  if (job.status === "cancelled") {
    return res.status(409).json({
      success: false,
      error: "Sync job is cancelled",
    });
  }

  const rawClips = Array.isArray(req.body?.clips) ? req.body.clips : [];
  const parsedClips: VideoSyncJobClip[] = rawClips
    .map((clip: unknown) => {
      if (!clip || typeof clip !== "object") {
        return null;
      }
      const source = clip as Record<string, unknown>;
      const id = typeof source.id === "string" ? source.id.trim() : "";
      const pathValue =
        typeof source.path === "string" ? source.path.trim() : "";
      const typeRaw =
        typeof source.type === "string" ? source.type.trim().toLowerCase() : "";
      if (!id || !pathValue || (typeRaw !== "audio" && typeRaw !== "video")) {
        return null;
      }
      return {
        id,
        path: pathValue,
        type: typeRaw as "audio" | "video",
        camera: typeof source.camera === "string" ? source.camera : undefined,
        syncGroup:
          typeof source.syncGroup === "string" ? source.syncGroup : undefined,
        timecode:
          typeof source.timecode === "string" ? source.timecode : undefined,
      };
    })
    .filter(
      (clip: VideoSyncJobClip | null): clip is VideoSyncJobClip =>
        clip !== null,
    );

  if (parsedClips.length < 2) {
    return res.status(400).json({
      success: false,
      error: "At least two valid clips are required",
    });
  }

  patchVideoSyncJob(jobId, {
    clips: parsedClips,
    status: "processing",
    progress: 10,
    error: null,
  });

  void runVideoSyncJob(jobId);

  return res.status(202).json({
    success: true,
    jobId,
    status: "processing",
  });
});

app.get("/api/video-sync/jobs/:jobId", async (req, res) => {
  const job = await getVideoSyncJob(req.params.jobId);
  if (!job) {
    return res.status(404).json({
      success: false,
      error: "Sync job not found",
    });
  }

  return res.json({
    success: true,
    job: {
      id: job.id,
      status: job.status,
      progress: job.progress,
      error: job.error,
      sync_results: job.sync_results,
      created_at: job.createdAt,
      updated_at: job.updatedAt,
    },
  });
});

app.post("/api/video-sync/jobs/:jobId/cancel", async (req, res) => {
  const jobId = req.params.jobId;
  const job = await getVideoSyncJob(jobId);
  if (!job) {
    return res.status(404).json({
      success: false,
      error: "Sync job not found",
    });
  }

  if (
    job.status === "completed" ||
    job.status === "error" ||
    job.status === "cancelled"
  ) {
    return res.json({
      success: true,
      job: {
        id: job.id,
        status: job.status,
        progress: job.progress,
      },
    });
  }

  const controller = videoSyncJobControllers.get(jobId);
  if (controller) {
    controller.abort();
  }
  patchVideoSyncJob(jobId, {
    status: "cancelled",
    progress: 100,
    error: "Cancelled by user",
  });

  return res.json({
    success: true,
    job: {
      id: job.id,
      status: "cancelled",
      progress: 100,
    },
  });
});

type StoryArcAutoEditPreset = "reel-30" | "story-60" | "interview";
type StoryArcAutoEditJobStatus =
  | "queued"
  | "processing"
  | "completed"
  | "failed"
  | "cancelled";

interface StoryArcAutoEditClipInput {
  id: string;
  name: string;
  start: number;
  duration: number;
  trackId: string;
  tags: string[];
  metadata: Record<string, unknown>;
}

interface StoryArcAutoEditTrackInput {
  id: string;
  name: string;
  type: string;
}

interface StoryArcAutoEditOptionsInput {
  preset: StoryArcAutoEditPreset;
  targetDurationSeconds: number;
  includeAssemble: boolean;
  includePolish: boolean;
  addMarkers: boolean;
  addAudioBed: boolean;
  transitionDensity: number;
}

interface StoryArcAutoEditClipContextInput {
  scene: string | null;
  shotName: string | null;
  camera: string | null;
  syncGroup: string | null;
  tags: string[];
  markerLabels: string[];
  transcriptKeywords: string[];
  transcriptText: string | null;
  transcriptPhrases: string[];
  speakerName: string | null;
  moodHints: string[];
}

interface StoryArcAutoEditContextInput {
  storyTitle: string | null;
  storyType: string | null;
  goalKeywords: string[];
  avoidKeywords: string[];
  culturalMoments: string[];
  beatHints: string[];
  intentProfileId: string | null;
  intentProfileName: string | null;
  intentGoalKeywords: string[];
  intentAvoidKeywords: string[];
  forbiddenPatterns: string[];
  feedbackByClipId: Record<string, "approved" | "rejected">;
  clipContextById: Record<string, StoryArcAutoEditClipContextInput>;
}

type StoryArcNarrativeBeat =
  | "hook"
  | "build"
  | "climax"
  | "resolution"
  | "bridge";

interface StoryArcAutoEditBeatClassification {
  beat: StoryArcNarrativeBeat;
  confidence: number;
  reason: string;
  source: "llm" | "heuristic";
}

interface StoryArcAutoEditRankingResult {
  clipScores: Record<string, number>;
  rankedClipIds: string[];
  confidence: number;
  summary: string[];
  modelUsed: string;
  analyzerAvailable: boolean;
  analyzerReason: string | null;
  beatByClipId: Record<string, StoryArcAutoEditBeatClassification>;
  beatDistribution: Record<StoryArcNarrativeBeat, number>;
  llmBeatClassificationUsed: boolean;
  clipSignalsById: Record<string, StoryArcAutoEditContextSignals>;
}

interface StoryArcAutoEditJobInput {
  storyArcId: string | null;
  clips: StoryArcAutoEditClipInput[];
  tracks: StoryArcAutoEditTrackInput[];
  options: StoryArcAutoEditOptionsInput;
  frameRate: number;
  context: StoryArcAutoEditContextInput;
}

interface StoryArcAutoEditJob {
  id: string;
  status: StoryArcAutoEditJobStatus;
  progress: number;
  createdAt: string;
  updatedAt: string;
  input: StoryArcAutoEditJobInput;
  result: StoryArcAutoEditRankingResult | null;
  error: string | null;
}

interface StoryArcAutoEditPresetConfig {
  duration: number;
  minClipDuration: number;
  idealClipDuration: number;
  maxClipDuration: number;
}

const STORY_ARC_AUTO_EDIT_PRESET_CONFIG: Record<
  StoryArcAutoEditPreset,
  StoryArcAutoEditPresetConfig
> = {
  "reel-30": {
    duration: 30,
    minClipDuration: 0.8,
    idealClipDuration: 2.1,
    maxClipDuration: 4,
  },
  "story-60": {
    duration: 60,
    minClipDuration: 1.2,
    idealClipDuration: 3.1,
    maxClipDuration: 5.6,
  },
  interview: {
    duration: 120,
    minClipDuration: 2,
    idealClipDuration: 5.6,
    maxClipDuration: 11,
  },
};

const storyArcAutoEditJobs = new Map<string, StoryArcAutoEditJob>();
const storyArcAutoEditJobControllers = new Map<string, AbortController>();
const STORY_ARC_AUTO_EDIT_JOB_TTL_MS = 30 * 60 * 1000;

const persistStoryArcAutoEditJob = (job: StoryArcAutoEditJob): void => {
  void compatStoreSet(dbCompatStoryArcAutoEditJobKey(job.id), job);
};

const removePersistedStoryArcAutoEditJob = (jobId: string): void => {
  void compatStoreDelete(dbCompatStoryArcAutoEditJobKey(jobId));
};

const getStoryArcAutoEditJob = async (
  jobId: string,
): Promise<StoryArcAutoEditJob | null> => {
  const existing = storyArcAutoEditJobs.get(jobId);
  if (existing) return existing;
  const dbJob = await compatStoreGet<StoryArcAutoEditJob>(
    dbCompatStoryArcAutoEditJobKey(jobId),
  );
  if (!dbJob || typeof dbJob !== "object" || typeof dbJob.id !== "string") {
    return null;
  }
  storyArcAutoEditJobs.set(jobId, dbJob);
  return dbJob;
};

const isUnknownRecord = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === "object";

const clampAutoEditValue = (
  value: number,
  minValue: number,
  maxValue: number,
): number => Math.max(minValue, Math.min(maxValue, value));

const normalizeAutoEditPreset = (value: unknown): StoryArcAutoEditPreset => {
  const normalized =
    normalizeModelLookupValue(readString(value) || "") || "story-60";
  if (normalized === "reel30" || normalized === "reel-30") {
    return "reel-30";
  }
  if (normalized === "interview" || normalized === "intervju") {
    return "interview";
  }
  return "story-60";
};

const normalizeAutoEditOptions = (
  value: unknown,
): StoryArcAutoEditOptionsInput => {
  const source = isUnknownRecord(value) ? value : {};
  const preset = normalizeAutoEditPreset(source.preset);
  const presetDefaults = STORY_ARC_AUTO_EDIT_PRESET_CONFIG[preset];
  const targetDurationRaw = readNumber(source.targetDurationSeconds);
  const transitionDensityRaw = readNumber(source.transitionDensity);

  return {
    preset,
    targetDurationSeconds: Number(
      clampAutoEditValue(
        targetDurationRaw ?? presetDefaults.duration,
        6,
        20 * 60,
      ).toFixed(3),
    ),
    includeAssemble: readBoolean(source.includeAssemble) ?? true,
    includePolish: readBoolean(source.includePolish) ?? true,
    addMarkers: readBoolean(source.addMarkers) ?? true,
    addAudioBed: readBoolean(source.addAudioBed) ?? true,
    transitionDensity: Number(
      clampAutoEditValue(transitionDensityRaw ?? 0.65, 0, 1).toFixed(3),
    ),
  };
};

const normalizeAutoEditClipInput = (
  value: unknown,
  index: number,
): StoryArcAutoEditClipInput | null => {
  if (!isUnknownRecord(value)) {
    return null;
  }

  const id = readString(value.id) || `clip-${index + 1}`;
  const start = readNumber(value.start);
  const duration = readNumber(value.duration);
  const trackId = readString(value.trackId) || "video-1";
  const sourceTags = Array.isArray(value.tags) ? value.tags : [];
  const tags = sourceTags
    .map((entry) => readString(entry))
    .filter((entry): entry is string => Boolean(entry))
    .slice(0, 24);
  const metadata = isUnknownRecord(value.metadata) ? { ...value.metadata } : {};

  if (duration === null || duration <= 0) {
    return null;
  }

  return {
    id,
    name: readString(value.name) || id,
    start: Number(clampAutoEditValue(start ?? 0, 0, 24 * 3600).toFixed(3)),
    duration: Number(clampAutoEditValue(duration, 0.04, 24 * 3600).toFixed(3)),
    trackId,
    tags,
    metadata,
  };
};

const normalizeAutoEditTrackInput = (
  value: unknown,
  index: number,
): StoryArcAutoEditTrackInput | null => {
  if (!isUnknownRecord(value)) {
    return null;
  }
  const id = readString(value.id) || `track-${index + 1}`;
  const name = readString(value.name) || id;
  const type = readString(value.type) || "video";
  return { id, name, type };
};

const normalizeAutoEditKeywordToken = (value: string): string =>
  value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "");

const normalizeAutoEditKeywordList = (
  value: unknown,
  maxItems = 24,
): string[] => {
  const values: string[] = [];
  if (Array.isArray(value)) {
    value.forEach((entry) => {
      const normalized = readString(entry);
      if (normalized) {
        values.push(normalized);
      }
    });
  } else {
    const single = readString(value);
    if (single) {
      values.push(single);
    }
  }

  const unique: string[] = [];
  const seen = new Set<string>();
  values.forEach((entry) => {
    entry
      .split(/[\s,;|/]+/)
      .map((token) => normalizeAutoEditKeywordToken(token))
      .filter((token) => token.length >= 3)
      .forEach((token) => {
        if (seen.has(token) || unique.length >= maxItems) {
          return;
        }
        seen.add(token);
        unique.push(token);
      });
  });

  return unique;
};

const normalizeAutoEditNarrativeText = (
  value: unknown,
  maxLength = 1600,
): string | null => {
  const raw = readString(value);
  if (!raw) {
    return null;
  }
  const normalized = raw
    .replace(/\s+/g, " ")
    .replace(/\u0000/g, "")
    .trim();
  if (!normalized) {
    return null;
  }
  return normalized.slice(0, maxLength);
};

const normalizeAutoEditPhraseList = (
  value: unknown,
  maxItems = 12,
  maxLength = 160,
): string[] => {
  const unique: string[] = [];
  const seen = new Set<string>();
  const appendPhrase = (entry: unknown) => {
    const normalized = normalizeAutoEditNarrativeText(entry, maxLength);
    if (!normalized) {
      return;
    }
    const dedupeKey = normalized.toLowerCase();
    if (seen.has(dedupeKey) || unique.length >= maxItems) {
      return;
    }
    seen.add(dedupeKey);
    unique.push(normalized);
  };

  if (Array.isArray(value)) {
    value.forEach(appendPhrase);
    return unique;
  }

  appendPhrase(value);
  return unique;
};

const normalizeAutoEditClipContextInput = (
  value: unknown,
): StoryArcAutoEditClipContextInput | null => {
  if (!isUnknownRecord(value)) {
    return null;
  }
  const transcriptText = normalizeAutoEditNarrativeText(
    value.transcriptText,
    1800,
  );
  const transcriptPhrases = normalizeAutoEditPhraseList(
    value.transcriptPhrases,
    16,
    180,
  );
  const transcriptKeywords = normalizeAutoEditKeywordList(
    [value.transcriptKeywords, transcriptText, ...transcriptPhrases],
    36,
  );
  const speakerName = normalizeAutoEditNarrativeText(value.speakerName, 100);

  return {
    scene: readString(value.scene),
    shotName: readString(value.shotName),
    camera: readString(value.camera),
    syncGroup: readString(value.syncGroup),
    tags: normalizeAutoEditKeywordList(value.tags, 36),
    markerLabels: normalizeAutoEditKeywordList(value.markerLabels, 24),
    transcriptKeywords,
    transcriptText,
    transcriptPhrases,
    speakerName,
    moodHints: normalizeAutoEditKeywordList(value.moodHints, 24),
  };
};

const normalizeAutoEditContextInput = (
  value: unknown,
): StoryArcAutoEditContextInput => {
  const source = isUnknownRecord(value) ? value : {};
  const clipContextById: Record<string, StoryArcAutoEditClipContextInput> = {};
  const feedbackByClipId: Record<string, "approved" | "rejected"> = {};
  const rawClipContextById = isUnknownRecord(source.clipContextById)
    ? source.clipContextById
    : {};
  Object.entries(rawClipContextById).forEach(([clipId, clipContext]) => {
    const normalizedId = readString(clipId);
    if (!normalizedId) {
      return;
    }
    const normalizedContext = normalizeAutoEditClipContextInput(clipContext);
    if (normalizedContext) {
      clipContextById[normalizedId] = normalizedContext;
    }
  });
  const rawFeedbackByClipId = isUnknownRecord(source.feedbackByClipId)
    ? source.feedbackByClipId
    : {};
  Object.entries(rawFeedbackByClipId).forEach(([clipId, feedbackValue]) => {
    const normalizedId = readString(clipId);
    if (!normalizedId) {
      return;
    }
    const normalizedFeedback = normalizeModelLookupValue(
      readString(feedbackValue) || "",
    );
    if (
      normalizedFeedback === "approved" ||
      normalizedFeedback === "rejected"
    ) {
      feedbackByClipId[normalizedId] = normalizedFeedback;
    }
  });

  return {
    storyTitle: readString(source.storyTitle),
    storyType: readString(source.storyType),
    goalKeywords: normalizeAutoEditKeywordList(source.goalKeywords, 48),
    avoidKeywords: normalizeAutoEditKeywordList(source.avoidKeywords, 24),
    culturalMoments: normalizeAutoEditKeywordList(source.culturalMoments, 24),
    beatHints: normalizeAutoEditKeywordList(source.beatHints, 32),
    intentProfileId: readString(source.intentProfileId),
    intentProfileName: readString(source.intentProfileName),
    intentGoalKeywords: normalizeAutoEditKeywordList(
      source.intentGoalKeywords,
      36,
    ),
    intentAvoidKeywords: normalizeAutoEditKeywordList(
      source.intentAvoidKeywords,
      24,
    ),
    forbiddenPatterns: normalizeAutoEditKeywordList(
      source.forbiddenPatterns,
      24,
    ),
    feedbackByClipId,
    clipContextById,
  };
};

const isAutoEditAudioTrack = (
  trackId: string,
  tracks: StoryArcAutoEditTrackInput[],
): boolean => {
  const normalizedTrackId = trackId.trim().toLowerCase();
  if (
    normalizedTrackId.startsWith("audio") ||
    /^a\d+$/.test(normalizedTrackId)
  ) {
    return true;
  }
  const matchingTrack = tracks.find((track) => track.id === trackId);
  if (!matchingTrack) {
    return false;
  }
  const normalizedType = matchingTrack.type.trim().toLowerCase();
  const normalizedName = matchingTrack.name.trim().toLowerCase();
  return normalizedType === "audio" || normalizedName.includes("audio");
};

interface StoryArcAutoEditContextSignals {
  boost: number;
  penalty: number;
  beatAlignmentBoost: number;
  feedbackBoost: number;
  goalHits: number;
  avoidHits: number;
  culturalHits: number;
  beatHits: number;
  markerHits: number;
  forbiddenHits: number;
  transcriptCoverage: number;
  narrativeConnectorHits: number;
  impactPhraseHits: number;
  fillerHits: number;
}

