const patchStoryArcV2Job = (
  jobId: string,
  patch: Partial<Omit<StoryArcV2Job, "jobId" | "createdAt" | "request">>,
): StoryArcV2Job | null => {
  const current = storyArcV2Jobs.get(jobId);
  if (!current) return null;
  const now = Date.now();
  const next: StoryArcV2Job = {
    ...current,
    ...patch,
    updatedAt: new Date(now).toISOString(),
  };
  storyArcV2Jobs.set(jobId, next);
  persistStoryArcV2Job(next);

  const runtime = storyArcV2JobRuntimeContext.get(jobId) || {
    phase: current.phase,
    phaseStartedAt: current.updatedAt || current.createdAt,
    phaseStartedAtMs:
      Number(new Date(current.updatedAt || current.createdAt).getTime()) || now,
  };
  if (runtime.phase !== next.phase) {
    runtime.phase = next.phase;
    runtime.phaseStartedAt = next.updatedAt;
    runtime.phaseStartedAtMs = now;
    storyArcV2JobRuntimeContext.set(jobId, runtime);
  }

  const transitionedToTerminal =
    !isStoryArcV2TerminalStatus(current.status) &&
    isStoryArcV2TerminalStatus(next.status);
  if (transitionedToTerminal) {
    const terminalStatus = next.status as StoryArcV2PhaseMetricStatus;
    const latencyMs = Math.max(1, now - runtime.phaseStartedAtMs);
    recordStoryArcV2PhaseMetricSample({
      phase: runtime.phase,
      status: terminalStatus,
      latencyMs,
      startedAt: runtime.phaseStartedAt,
      endedAt: next.updatedAt,
      jobId,
      context: {
        source: "job",
        progress: next.progress,
        error: next.error,
      },
    });
    storyArcV2JobRuntimeContext.delete(jobId);
  } else if (!storyArcV2JobRuntimeContext.has(jobId)) {
    storyArcV2JobRuntimeContext.set(jobId, runtime);
  }

  void persistStoryArcV2TablePayload(
    "storyarc_job_checkpoints",
    "job_id",
    jobId,
    "checkpoint_payload",
    {
      phase: next.phase,
      status: next.status,
      progress: next.progress,
      checkpoint: next.checkpoint,
      warnings: next.warnings,
      resultRef: next.resultRef,
      error: next.error,
      updatedAt: next.updatedAt,
    },
  );
  return next;
};

const createStoryArcV2AnalyzeJob = (
  input: StoryArcV2AnalyzeInput,
): StoryArcV2Job => {
  const now = new Date().toISOString();
  const job: StoryArcV2Job = {
    jobId: toStoryArcV2Id("storyarc-v2-job"),
    phase: "analyze",
    status: "queued",
    progress: 0,
    checkpoint: { stage: "queued" },
    warnings: [],
    resultRef: null,
    result: null,
    error: null,
    request: {
      projectId: input.projectId,
      mediaCount: input.media.length,
      media: input.media,
      intentProfileId: input.intentProfileId,
      languageHint: input.languageHint,
      musicTrackId: input.musicTrackId,
      projectProfile: input.projectProfile,
      editingMode: input.editingMode,
      culturalProfile: input.culturalProfile,
      culturalModules: input.culturalModules,
      mustIncludeMoments: input.mustIncludeMoments,
      avoidMoments: input.avoidMoments,
    },
    createdAt: now,
    updatedAt: now,
  };
  storyArcV2Jobs.set(job.jobId, job);
  persistStoryArcV2Job(job);
  storyArcV2JobControllers.set(job.jobId, new AbortController());
  storyArcV2JobRuntimeContext.set(job.jobId, {
    phase: job.phase,
    phaseStartedAt: now,
    phaseStartedAtMs: Date.now(),
  });
  return job;
};

const runStoryArcV2AnalyzeJob = async (
  jobId: string,
  input: StoryArcV2AnalyzeInput,
): Promise<void> => {
  const controller =
    storyArcV2JobControllers.get(jobId) || new AbortController();
  storyArcV2JobControllers.set(jobId, controller);
  const signal = controller.signal;

  patchStoryArcV2Job(jobId, {
    status: "processing",
    progress: 8,
    checkpoint: { stage: "preparing_media", mediaCount: input.media.length },
  });

  try {
    const analyzedMedia: StoryArcV2AnalyzedMedia[] = [];
    const warnings: string[] = [];
    const analyzeLanguageHint = normalizeStoryArcV2LanguageHint(
      input.languageHint,
    );
    const projectProfile = resolveStoryArcV2ProjectProfile(
      input.projectProfile,
    );
    const editingMode = resolveStoryArcV2EditingMode(
      input.editingMode,
      projectProfile,
    );
    const culturalProfile = resolveStoryArcV2CulturalProfile(
      input.culturalProfile,
    );
    const culturalModules = resolveStoryArcV2CulturalModules(
      input.culturalModules,
    );
    const culturalRulebook = mergeStoryArcV2CulturalRulebook({
      profile: culturalProfile,
      modules: culturalModules,
    });
    const mustIncludeMoments = Array.from(
      new Set([
        ...normalizeStoryArcV2MomentTokenList(input.mustIncludeMoments),
        ...normalizeStoryArcV2MomentTokenList(
          culturalRulebook.mustIncludeDefaults,
        ),
      ]),
    ).slice(0, 48);
    const avoidMoments = normalizeStoryArcV2MomentTokenList(input.avoidMoments);

    for (let index = 0; index < input.media.length; index += 1) {
      if (signal.aborted) throw createJobAbortError();
      const media = input.media[index];
      patchStoryArcV2Job(jobId, {
        progress: Number(
          (15 + (index / Math.max(1, input.media.length)) * 65).toFixed(1),
        ),
        checkpoint: {
          stage: "analyzing_media",
          mediaId: media.id,
          mediaIndex: index + 1,
          mediaTotal: input.media.length,
        },
      });

      const mediaLanguageHint = resolveStoryArcV2MediaLanguageHint(
        media,
        input.languageHint,
      );
      const transcribeResult = await transcribeVideoSource(
        media.path,
        mediaLanguageHint ?? analyzeLanguageHint,
        signal,
      );
      const sceneResult = await detectScenesFromVideo(
        media.path,
        0.3,
        0.5,
        signal,
      );

      const semanticProfiles = buildStoryArcV2SemanticProfiles(
        media.id,
        sceneResult.result.scenes,
        transcribeResult.transcription,
      );
      const visualFeatures = buildStoryArcV2VisualFeaturesForMedia({
        mediaId: media.id,
        profile: projectProfile,
        culturalProfile,
        semanticProfiles,
        detectedText: transcribeResult.detected_text,
      });
      const musicAnalysis = await analyzeStoryArcV2MusicFromVideo(
        media.path,
        signal,
      );
      const detectedEvents = detectStoryArcV2EventsForMedia({
        mediaId: media.id,
        profile: projectProfile,
        rulebook: culturalRulebook,
        mustIncludeMoments,
        avoidMoments,
        transcription: transcribeResult.transcription,
        semanticProfiles,
        detectedText: transcribeResult.detected_text,
      });
      const eventMarkers = buildStoryArcV2EventMarkersForMedia({
        mediaId: media.id,
        events: detectedEvents,
        semanticProfiles,
      });
      const narrativeAnchors = buildStoryArcV2NarrativeAnchorsForMedia({
        mediaId: media.id,
        profile: projectProfile,
        rulebook: culturalRulebook,
        transcription: transcribeResult.transcription,
        events: detectedEvents,
      });

      analyzedMedia.push({
        mediaId: media.id,
        path: media.path,
        durationSeconds: sceneResult.result.duration_seconds,
        scenes: sceneResult.result.scenes,
        detectedText: transcribeResult.detected_text,
        transcription: transcribeResult.transcription,
        audioTracks: transcribeResult.audio_tracks,
        musicAnalysis,
        transcriptionProvider: transcribeResult.transcription_provider,
        alignmentProvider: transcribeResult.alignment_provider,
        detectedEvents,
        narrativeAnchors,
        warnings: [...transcribeResult.warnings, ...sceneResult.warnings],
        semanticProfiles,
        visualFeatures,
        eventMarkers,
      });

      warnings.push(
        ...transcribeResult.warnings,
        ...sceneResult.warnings,
        ...musicAnalysis.warnings,
      );
    }

    const sceneCount = analyzedMedia.reduce(
      (sum, media) => sum + media.scenes.length,
      0,
    );
    const totalDuration = analyzedMedia.reduce(
      (sum, media) => sum + media.durationSeconds,
      0,
    );
    const transcriptionSegments = analyzedMedia.reduce(
      (sum, media) => sum + media.transcription.segments.length,
      0,
    );
    const detectedSpeakerSet = new Set<string>();
    analyzedMedia.forEach((media) => {
      media.transcription.segments.forEach((segment) => {
        const speaker = readString(segment.speaker);
        if (speaker) detectedSpeakerSet.add(speaker);
      });
    });
    const detectedEvents = analyzedMedia
      .flatMap((media) => media.detectedEvents)
      .sort((left, right) => left.start - right.start);
    const narrativeAnchors = analyzedMedia
      .flatMap((media) => media.narrativeAnchors)
      .sort((left, right) => left.start - right.start);
    const musicAnalysis = mergeStoryArcV2MusicAnalysis(analyzedMedia);
    const visualFeatures = analyzedMedia.flatMap(
      (media) => media.visualFeatures,
    );
    const eventMarkers = analyzedMedia.flatMap((media) => media.eventMarkers);

    const analysisRun: StoryArcV2AnalysisRun = {
      analysisId: toStoryArcV2Id("analysis"),
      projectId: input.projectId,
      intentProfileId: input.intentProfileId,
      languageHint: input.languageHint,
      musicTrackId: input.musicTrackId,
      projectProfile,
      editingMode,
      culturalProfile,
      culturalModules,
      mustIncludeMoments,
      avoidMoments,
      media: analyzedMedia,
      detectedEvents,
      narrativeAnchors,
      musicAnalysis,
      visualFeatures,
      eventMarkers,
      summary: {
        sceneCount,
        totalDuration: Number(totalDuration.toFixed(3)),
        transcriptionSegments,
        detectedSpeakers: detectedSpeakerSet.size,
        detectedEvents: detectedEvents.length,
        narrativeAnchors: narrativeAnchors.length,
        musicBeats: musicAnalysis.beats.length,
        visualFeaturePoints: visualFeatures.length,
        eventMarkers: eventMarkers.length,
      },
      warnings: warnings.slice(0, 120),
      createdAt: new Date().toISOString(),
    };

    const personIdentities = buildStoryArcV2PersonIdentities(
      analysisRun.analysisId,
      analyzedMedia,
    );

    storyArcV2AnalysisRuns.set(analysisRun.analysisId, analysisRun);
    void persistStoryArcV2TablePayload(
      "storyarc_analysis_runs",
      "analysis_id",
      analysisRun.analysisId,
      "analysis_payload",
      analysisRun as unknown as Record<string, unknown>,
    );
    void persistStoryArcV2SemanticProfiles(
      analysisRun.analysisId,
      analyzedMedia,
    );
    void persistStoryArcV2PersonIdentities(
      analysisRun.analysisId,
      personIdentities,
    );

    const primaryMedia = analysisRun.media[0];
    const resultPayload = {
      analysisId: analysisRun.analysisId,
      projectId: analysisRun.projectId,
      summary: analysisRun.summary,
      scenes: primaryMedia?.scenes || [],
      projectProfile: analysisRun.projectProfile,
      editingMode: analysisRun.editingMode,
      culturalProfile: analysisRun.culturalProfile,
      culturalModules: analysisRun.culturalModules,
      mustIncludeMoments: analysisRun.mustIncludeMoments,
      avoidMoments: analysisRun.avoidMoments,
      culturalRulebook,
      audioTracks: primaryMedia?.audioTracks || null,
      musicAnalysis: analysisRun.musicAnalysis,
      transcriptionProvider: primaryMedia?.transcriptionProvider || null,
      alignmentProvider: primaryMedia?.alignmentProvider || null,
      semanticProfiles: analysisRun.media
        .flatMap((media) => media.semanticProfiles)
        .slice(0, 250),
      detectedEvents: analysisRun.detectedEvents.slice(0, 250),
      narrativeAnchors: analysisRun.narrativeAnchors.slice(0, 250),
      visualFeatures: analysisRun.visualFeatures.slice(0, 500),
      eventMarkers: analysisRun.eventMarkers.slice(0, 250),
      personIdentities: personIdentities.slice(0, 100),
      warnings: analysisRun.warnings,
      createdAt: analysisRun.createdAt,
    };

    patchStoryArcV2Job(jobId, {
      status: "completed",
      progress: 100,
      checkpoint: { stage: "completed" },
      warnings: analysisRun.warnings,
      resultRef: analysisRun.analysisId,
      result: resultPayload,
      error: null,
    });
  } catch (error) {
    if (isAbortLikeError(error) || signal.aborted) {
      patchStoryArcV2Job(jobId, {
        status: "cancelled",
        progress: 100,
        checkpoint: { stage: "cancelled" },
        error: "Cancelled by user",
      });
      return;
    }
    const message =
      error instanceof Error ? error.message : "Story Arc V2 analyze failed";
    patchStoryArcV2Job(jobId, {
      status: "failed",
      progress: 100,
      checkpoint: { stage: "failed" },
      error: message,
    });
  } finally {
    storyArcV2JobControllers.delete(jobId);
  }
};

app.get("/api/story-arc/v2/feature-status", (_req, res) => {
  return res.json({
    success: true,
    enabled: isStoryArcV2Enabled(),
    mode: "co-pilot",
    compute: "cloud-gpu",
    priority: "best-quality",
    supportedProjectProfiles: STORY_ARC_V2_SUPPORTED_PROJECT_PROFILES,
    supportedEditingModes: STORY_ARC_V2_SUPPORTED_EDITING_MODES,
    supportedCulturalProfiles: STORY_ARC_V2_SUPPORTED_CULTURAL_PROFILES,
    defaults: {
      projectProfile: "wedding",
      editingMode: "highlight_music_sync",
      culturalProfile: "mixed",
      culturalModules: ["sikh", "pakistani", "norwegian"],
    },
    transcription: {
      whisperxEnabled: VIDEO_ANALYSIS_WHISPERX_ENABLED,
      whisperxUrl: WHISPERX_TRANSCRIPTION_URL,
      diarizationEnabled: VIDEO_ANALYSIS_DIARIZATION_ENABLED,
    },
    audioTracks: {
      masterSampleRateHz: VIDEO_ANALYSIS_MASTER_TRACK_SAMPLE_RATE_HZ,
      analysisSampleRateHz: VIDEO_ANALYSIS_ANALYSIS_TRACK_SAMPLE_RATE_HZ,
      demucsEnabled: VIDEO_ANALYSIS_ANALYSIS_TRACK_USE_DEMUCS,
    },
  });
});

app.get("/api/story-arc/v2/cultural-profiles", (_req, res) => {
  const profiles = STORY_ARC_V2_SUPPORTED_CULTURAL_PROFILES.map((profile) => {
    const rulebook = mergeStoryArcV2CulturalRulebook({
      profile,
      modules:
        profile === "mixed"
          ? (["sikh", "pakistani", "norwegian"] as StoryArcV2CulturalProfile[])
          : [],
    });
    const eventTaxonomy = rulebook.eventRules
      .slice()
      .sort(
        (left, right) =>
          STORY_ARC_V2_EVENT_PRIORITY_SCORE[right.priority] -
          STORY_ARC_V2_EVENT_PRIORITY_SCORE[left.priority],
      )
      .map((rule) => ({
        type: rule.type,
        priority: rule.priority,
        noCut: Boolean(rule.noCut),
        sacred: Boolean(rule.sacred),
        minClipLenSec: rule.minClipLenSec || null,
        keywords: rule.keywords.slice(0, 24),
      }));
    return {
      profile,
      label: rulebook.label,
      mustIncludeDefaults: rulebook.mustIncludeDefaults,
      noCutEventTypes: rulebook.noCutEventTypes,
      sacredEventTypes: rulebook.sacredEventTypes,
      minClipLenByEventType: rulebook.minClipLenByEventType,
      pacing: rulebook.pacing,
      eventTaxonomy,
    };
  });
  return res.json({
    success: true,
    profiles,
  });
});

app.post("/api/story-arc/v2/warmup", async (_req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("analyze", {
    operation: "manual_warmup",
    target: PYANNOTE_DIARIZATION_URL,
  });
  try {
    const warmup = await requestPyannoteWarmup("manual-trigger");
    let whisperx: Record<string, unknown> = {
      enabled: VIDEO_ANALYSIS_WHISPERX_ENABLED,
      status: "skipped",
    };
    if (VIDEO_ANALYSIS_WHISPERX_ENABLED) {
      try {
        const whisperxWarmup = await requestWhisperxWarmup("manual-trigger");
        whisperx = {
          enabled: true,
          status: "ok",
          statusCode: whisperxWarmup.statusCode,
          warmup: whisperxWarmup.payload,
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        whisperx = {
          enabled: true,
          status: "degraded",
          error: message,
        };
      }
    }
    completePhaseMetric("completed", {
      statusCode: warmup.statusCode,
      warmupStatus: readString(warmup.payload.status) || "ok",
      whisperxStatus: readString(whisperx.status) || "skipped",
    });
    return res.json({
      success: true,
      statusCode: warmup.statusCode,
      warmup: warmup.payload,
      whisperx,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Story Arc V2 warmup failed";
    completePhaseMetric("failed", { error: message });
    return res.status(500).json({
      success: false,
      error: message,
    });
  }
});

app.post("/api/story-arc/v2/analyze/start", (req, res) => {
  if (!isStoryArcV2Enabled()) {
    return res.status(503).json({
      success: false,
      error: "Story Arc V2 is disabled by feature flag",
    });
  }

  const mediaRaw = Array.isArray(req.body?.media) ? req.body.media : [];
  const media = mediaRaw
    .map((entry: unknown, index: number) =>
      normalizeStoryArcV2MediaInput(entry, index),
    )
    .filter(
      (entry: StoryArcV2MediaInput | null): entry is StoryArcV2MediaInput =>
        entry !== null,
    );

  if (media.length === 0) {
    return res.status(400).json({
      success: false,
      error: "At least one media item with path is required",
    });
  }

  const projectProfile = resolveStoryArcV2ProjectProfile(
    readString(req.body?.projectProfile) || readString(req.body?.profile),
  );
  const editingMode = resolveStoryArcV2EditingMode(
    readString(req.body?.editingMode),
    projectProfile,
  );
  const culturalProfile = resolveStoryArcV2CulturalProfile(
    readString(req.body?.culturalProfile) ||
      readString(req.body?.cultureProfile),
  );
  const culturalModules = resolveStoryArcV2CulturalModules(
    req.body?.culturalModules || req.body?.cultureModules,
  );

  const input: StoryArcV2AnalyzeInput = {
    projectId: readString(req.body?.projectId),
    media,
    intentProfileId: readString(req.body?.intentProfileId),
    languageHint: normalizeStoryArcV2LanguageHint(
      readString(req.body?.languageHint) || readString(req.body?.language),
    ),
    musicTrackId: readString(req.body?.musicTrackId),
    projectProfile,
    editingMode,
    culturalProfile,
    culturalModules,
    mustIncludeMoments: normalizeStoryArcV2MomentTokenList(
      req.body?.mustIncludeMoments || req.body?.mustInclude,
    ),
    avoidMoments: normalizeStoryArcV2MomentTokenList(
      req.body?.avoidMoments || req.body?.mustAvoid || req.body?.excludeMoments,
    ),
  };

  const job = createStoryArcV2AnalyzeJob(input);
  void runStoryArcV2AnalyzeJob(job.jobId, input);
  return res.status(202).json({
    success: true,
    jobId: job.jobId,
    phase: job.phase,
    status: job.status,
    progress: job.progress,
    createdAt: job.createdAt,
    updatedAt: job.updatedAt,
  });
});

app.get("/api/story-arc/v2/jobs/:jobId", async (req, res) => {
  const job = await getStoryArcV2Job(req.params.jobId);
  if (!job) {
    return res.status(404).json({
      success: false,
      error: "Story Arc V2 job not found",
    });
  }
  return res.json({
    success: true,
    ...job,
  });
});

app.post("/api/story-arc/v2/jobs/:jobId/cancel", async (req, res) => {
  const job = await getStoryArcV2Job(req.params.jobId);
  if (!job) {
    return res.status(404).json({
      success: false,
      error: "Story Arc V2 job not found",
    });
  }
  if (
    job.status === "completed" ||
    job.status === "failed" ||
    job.status === "cancelled"
  ) {
    return res.json({
      success: true,
      ...job,
    });
  }
  const controller = storyArcV2JobControllers.get(job.jobId);
  if (controller) {
    controller.abort();
  }
  const next = patchStoryArcV2Job(job.jobId, {
    status: "cancelled",
    progress: 100,
    checkpoint: { stage: "cancelled" },
    error: "Cancelled by user",
  });
  return res.json({
    success: true,
    ...(next || job),
  });
});

app.post("/api/story-arc/v2/jobs/:jobId/retry", async (req, res) => {
  const job = await getStoryArcV2Job(req.params.jobId);
  if (!job) {
    return res.status(404).json({
      success: false,
      error: "Story Arc V2 job not found",
    });
  }
  if (job.phase !== "analyze") {
    return res.status(400).json({
      success: false,
      error: "Only analyze jobs are retryable in V2 foundation",
    });
  }
  if (job.status === "queued" || job.status === "processing") {
    return res.json({
      success: true,
      ...job,
    });
  }
  const requestMedia = Array.isArray(job.request?.media)
    ? job.request.media
    : [];
  const media = requestMedia
    .map((entry: unknown, index: number) =>
      normalizeStoryArcV2MediaInput(entry, index),
    )
    .filter(
      (entry: StoryArcV2MediaInput | null): entry is StoryArcV2MediaInput =>
        entry !== null,
    );
  if (media.length === 0) {
    return res.status(400).json({
      success: false,
      error: "Retry payload missing media",
    });
  }
  const projectProfile = resolveStoryArcV2ProjectProfile(
    readString(job.request?.projectProfile) || readString(job.request?.profile),
  );
  const editingMode = resolveStoryArcV2EditingMode(
    readString(job.request?.editingMode),
    projectProfile,
  );
  const culturalProfile = resolveStoryArcV2CulturalProfile(
    readString(job.request?.culturalProfile) ||
      readString(job.request?.cultureProfile),
  );
  const culturalModules = resolveStoryArcV2CulturalModules(
    job.request?.culturalModules || job.request?.cultureModules,
  );

  const input: StoryArcV2AnalyzeInput = {
    projectId: readString(job.request?.projectId),
    media,
    intentProfileId: readString(job.request?.intentProfileId),
    languageHint: normalizeStoryArcV2LanguageHint(
      readString(job.request?.languageHint) ||
        readString(job.request?.language),
    ),
    musicTrackId: readString(job.request?.musicTrackId),
    projectProfile,
    editingMode,
    culturalProfile,
    culturalModules,
    mustIncludeMoments: normalizeStoryArcV2MomentTokenList(
      job.request?.mustIncludeMoments || job.request?.mustInclude,
    ),
    avoidMoments: normalizeStoryArcV2MomentTokenList(
      job.request?.avoidMoments ||
        job.request?.mustAvoid ||
        job.request?.excludeMoments,
    ),
  };
  storyArcV2JobControllers.set(job.jobId, new AbortController());
  storyArcV2JobRuntimeContext.set(job.jobId, {
    phase: "analyze",
    phaseStartedAt: new Date().toISOString(),
    phaseStartedAtMs: Date.now(),
  });
  patchStoryArcV2Job(job.jobId, {
    status: "queued",
    progress: 0,
    checkpoint: { stage: "queued" },
    warnings: [],
    resultRef: null,
    result: null,
    error: null,
  });
  void runStoryArcV2AnalyzeJob(job.jobId, input);
  const next = storyArcV2Jobs.get(job.jobId) || job;
  return res.status(202).json({
    success: true,
    ...next,
  });
});

app.post("/api/story-arc/v2/script/generate", async (req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("script", {
    operation: "generate",
  });
  try {
    const analysisId = readString(req.body?.analysisId);
    if (!analysisId) {
      completePhaseMetric("failed", { reason: "missing_analysis_id" });
      return res.status(400).json({
        success: false,
        error: "Missing analysisId",
      });
    }
    const analysis = await loadStoryArcV2AnalysisRunFromDb(analysisId);
    if (!analysis) {
      completePhaseMetric("failed", {
        reason: "analysis_not_found",
        analysisId,
      });
      return res.status(404).json({
        success: false,
        error: "Analysis run not found",
      });
    }
    const targetDurationSeconds = Number(
      clampStoryArcV2Number(
        readNumber(req.body?.targetDuration) ?? 90,
        20,
        1800,
      ).toFixed(2),
    );
    const mustIncludeMoments = normalizeStoryArcV2MomentTokenList(
      req.body?.mustInclude || req.body?.mustIncludeMoments,
    );
    const mustAvoidMoments = normalizeStoryArcV2MomentTokenList(
      req.body?.mustAvoid || req.body?.avoidMoments,
    );
    const feedbackProfile = await ensureStoryArcV2FeedbackProfile(
      resolveStoryArcV2ProjectKey(analysis.projectId),
    );
    const script = buildStoryArcV2Script(
      analysis,
      targetDurationSeconds,
      feedbackProfile,
      {
        mustInclude: mustIncludeMoments,
        mustAvoid: mustAvoidMoments,
      },
    );
    storyArcV2Scripts.set(script.scriptId, script);
    void persistStoryArcV2TablePayload(
      "storyarc_story_scripts",
      "script_id",
      script.scriptId,
      "script_payload",
      script as unknown as Record<string, unknown>,
    );
    void persistStoryArcV2ScriptNodes(script);
    const storyGraph = buildStoryArcV2StoryGraph(script);
    const culturalRulebook = mergeStoryArcV2CulturalRulebook({
      profile: resolveStoryArcV2CulturalProfile(
        readString(analysis.culturalProfile),
      ),
      modules: resolveStoryArcV2CulturalModules(analysis.culturalModules),
    });

    const storyArc = {
      id: `story-${script.scriptId}`,
      title: script.title,
      profile: analysis.projectProfile,
      editingMode: analysis.editingMode,
      culturalProfile: analysis.culturalProfile,
      culturalModules: analysis.culturalModules,
      culturalRulebook: {
        label: culturalRulebook.label,
        noCutEventTypes: culturalRulebook.noCutEventTypes,
        sacredEventTypes: culturalRulebook.sacredEventTypes,
        mustIncludeDefaults: culturalRulebook.mustIncludeDefaults,
      },
      beats: script.nodes.map((node) => ({
        id: node.id,
        beat: node.beat,
        text: node.text,
        start: node.start,
        end: node.end,
        confidence: node.confidence,
        narrativeScore: node.narrativeScore,
        primaryThread: node.primaryThread,
        storyThreads: node.storyThreads,
      })),
      storyGraph,
      narrativeAnchors: analysis.narrativeAnchors
        .slice(0, 60)
        .map((anchor) => ({
          id: anchor.anchorId,
          type: anchor.type,
          beat: anchor.beatHint,
          start: anchor.start,
          end: anchor.end,
          score: anchor.score,
          text: anchor.text,
          speaker: anchor.speaker,
          eventType: anchor.eventType,
        })),
      events: analysis.detectedEvents.slice(0, 120).map((event) => ({
        id: event.eventId,
        type: event.type,
        priority: event.priority,
        culturalProfile: event.culturalProfile,
        beatHint: event.beatHint,
        start: event.start,
        end: event.end,
        confidence: event.confidence,
        source: event.source,
      })),
      musicSuggestions: analysis.musicAnalysis.sections
        .slice(0, 48)
        .map((section) => ({
          cue: section.label,
          start: section.start,
          end: section.end,
          energy: section.energyLevel,
          rationale: `Use ${section.energyLevel} pacing in ${section.label}.`,
        })),
      transitionPoints: script.nodes
        .slice(0, Math.max(0, script.nodes.length - 1))
        .map((node) => ({
          at: Number((node.start + node.duration).toFixed(3)),
          type:
            node.beat === "turning_point" || node.beat === "resolution"
              ? "cross_dissolve"
              : "cut",
        })),
    };

    completePhaseMetric("completed", {
      analysisId,
      scriptId: script.scriptId,
      nodeCount: script.nodes.length,
    });
    return res.json({
      success: true,
      script,
      storyArc,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to generate script";
    completePhaseMetric("failed", { reason: "exception", error: message });
    return res.status(500).json({ success: false, error: message });
  }
});

app.post("/api/story-arc/v2/script/edit", async (req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("script", {
    operation: "edit",
  });
  try {
    const scriptId = readString(req.body?.scriptId);
    if (!scriptId) {
      completePhaseMetric("failed", { reason: "missing_script_id" });
      return res
        .status(400)
        .json({ success: false, error: "Missing scriptId" });
    }
    const script =
      storyArcV2Scripts.get(scriptId) ||
      (await loadStoryArcV2ScriptFromDb(scriptId));
    if (!script) {
      completePhaseMetric("failed", { reason: "script_not_found", scriptId });
      return res
        .status(404)
        .json({ success: false, error: "Script not found" });
    }
    storyArcV2Scripts.set(scriptId, script);

    const analysis = await loadStoryArcV2AnalysisRunFromDb(script.analysisId);
    const projectKey = resolveStoryArcV2ProjectKey(analysis?.projectId || null);
    const feedbackProfile = await ensureStoryArcV2FeedbackProfile(projectKey);

    const operations = Array.isArray(req.body?.operations)
      ? req.body.operations
      : [];
    const nextScript: StoryArcV2StoryScript = {
      ...script,
      nodes: script.nodes.map((node) => ({
        ...node,
        candidateClipIds: [...node.candidateClipIds],
        brollPlaceholders: (node.brollPlaceholders || []).map(
          (placeholder) => ({
            ...placeholder,
            candidateClipIds: [...placeholder.candidateClipIds],
          }),
        ),
      })),
      bannedClipIds: [...script.bannedClipIds],
    };

    const feedbackEvents: Array<Record<string, unknown>> = [];

    operations.forEach((operationRaw: unknown) => {
      if (!isUnknownRecord(operationRaw)) return;
      const op = normalizeModelLookupValue(readString(operationRaw.op) || "");
      if (op === "reorder") {
        const fromIndex = Math.max(
          0,
          Math.round(readNumber(operationRaw.fromIndex) ?? -1),
        );
        const toIndex = Math.max(
          0,
          Math.round(readNumber(operationRaw.toIndex) ?? -1),
        );
        if (
          fromIndex < nextScript.nodes.length &&
          toIndex < nextScript.nodes.length &&
          fromIndex !== toIndex
        ) {
          const [moved] = nextScript.nodes.splice(fromIndex, 1);
          nextScript.nodes.splice(toIndex, 0, moved);
        }
        return;
      }

      const nodeId = readString(operationRaw.nodeId);
      const node = nextScript.nodes.find((entry) => entry.id === nodeId);

      if (op === "locknode" && node) {
        node.locked = readBoolean(operationRaw.locked) !== false;
        return;
      }
      if (op === "replacecandidate" && node) {
        const clipId = readString(operationRaw.clipId);
        const replacementClipId = readString(operationRaw.replacementClipId);
        if (!clipId || !replacementClipId) return;
        const candidateIndex = node.candidateClipIds.indexOf(clipId);
        if (candidateIndex >= 0) {
          node.candidateClipIds[candidateIndex] = replacementClipId;
        } else {
          node.candidateClipIds.unshift(replacementClipId);
        }
        return;
      }
      if (op === "banclip") {
        const clipId = readString(operationRaw.clipId);
        if (clipId && !nextScript.bannedClipIds.includes(clipId)) {
          nextScript.bannedClipIds.push(clipId);
          feedbackEvents.push({
            scriptId,
            analysisId: script.analysisId,
            projectKey,
            type: "ban_clip",
            clipId,
            speaker: node?.speaker || null,
            reason: readString(operationRaw.reason),
            createdAt: new Date().toISOString(),
          });
        }
        return;
      }
      if (op === "approvenode" && node) {
        const clipId =
          readString(operationRaw.clipId) || node.candidateClipIds[0] || null;
        node.pinned = true;
        if (clipId) {
          feedbackEvents.push({
            scriptId,
            analysisId: script.analysisId,
            projectKey,
            type: "approve_node",
            nodeId: node.id,
            clipId,
            speaker: node.speaker || null,
            reason: readString(operationRaw.reason),
            createdAt: new Date().toISOString(),
          });
        }
        return;
      }
      if (op === "regeneratenode" && node && node.candidateClipIds.length > 1) {
        const [first] = node.candidateClipIds.splice(0, 1);
        node.candidateClipIds.push(first);
      }
    });

    feedbackEvents.forEach((eventPayload) => {
      const eventType = normalizeModelLookupValue(
        readString(eventPayload.type) || "",
      );
      if (eventType === "ban_clip") {
        applyStoryArcV2FeedbackToProfile(feedbackProfile, {
          type: "ban",
          clipId: readString(eventPayload.clipId),
          speaker: readString(eventPayload.speaker),
          reason: readString(eventPayload.reason),
        });
      }
      if (eventType === "approve_node") {
        applyStoryArcV2FeedbackToProfile(feedbackProfile, {
          type: "approve",
          clipId: readString(eventPayload.clipId),
          speaker: readString(eventPayload.speaker),
          reason: readString(eventPayload.reason),
        });
      }
      void persistStoryArcV2TablePayload(
        "storyarc_feedback_events",
        "event_id",
        toStoryArcV2Id("feedback"),
        "event_payload",
        eventPayload,
      );
    });
    storyArcV2FeedbackProfiles.set(projectKey, feedbackProfile);

    nextScript.revision += 1;
    nextScript.updatedAt = new Date().toISOString();
    storyArcV2Scripts.set(scriptId, nextScript);
    void persistStoryArcV2TablePayload(
      "storyarc_story_scripts",
      "script_id",
      nextScript.scriptId,
      "script_payload",
      nextScript as unknown as Record<string, unknown>,
    );
    void persistStoryArcV2ScriptNodes(nextScript);
    completePhaseMetric("completed", {
      scriptId: nextScript.scriptId,
      revision: nextScript.revision,
      operations: operations.length,
      feedbackEvents: feedbackEvents.length,
    });
    return res.json({
      success: true,
      script: nextScript,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to edit script";
    completePhaseMetric("failed", { reason: "exception", error: message });
    return res.status(500).json({ success: false, error: message });
  }
});

app.post("/api/story-arc/v2/timeline/plan", async (req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("timeline", {
    operation: "plan",
  });
  try {
    const scriptId = readString(req.body?.scriptId);
    if (!scriptId) {
      completePhaseMetric("failed", { reason: "missing_script_id" });
      return res
        .status(400)
        .json({ success: false, error: "Missing scriptId" });
    }
    const script =
      storyArcV2Scripts.get(scriptId) ||
      (await loadStoryArcV2ScriptFromDb(scriptId));
    if (!script) {
      completePhaseMetric("failed", { reason: "script_not_found", scriptId });
      return res
        .status(404)
        .json({ success: false, error: "Script not found" });
    }
    storyArcV2Scripts.set(scriptId, script);
    const variantRaw = normalizeModelLookupValue(
      readString(req.body?.variant) || "balanced",
    );
    const selectedVariant: StoryArcV2Variant =
      variantRaw === "safe" || variantRaw === "bold"
        ? (variantRaw as StoryArcV2Variant)
        : "balanced";
    const constraintsRecord = isUnknownRecord(req.body?.constraints)
      ? req.body.constraints
      : {};
    const shotMin = Number(
      clampStoryArcV2Number(
        readNumber(constraintsRecord.shotMin) ?? 1.2,
        0.3,
        30,
      ).toFixed(3),
    );
    const shotMax = Number(
      clampStoryArcV2Number(
        readNumber(constraintsRecord.shotMax) ?? 8,
        shotMin,
        90,
      ).toFixed(3),
    );
    const noOverlap = readBoolean(constraintsRecord.noOverlap) !== false;
    const beatCoverageRequired =
      readBoolean(constraintsRecord.beatCoverageRequired) !== false;
    const repetitionCapsRaw = isUnknownRecord(constraintsRecord.repetitionCaps)
      ? constraintsRecord.repetitionCaps
      : {};
    const repetitionCaps: Record<string, number> = {};
    Object.entries(repetitionCapsRaw).forEach(([key, value]) => {
      const numeric = readNumber(value);
      if (numeric !== null) {
        repetitionCaps[key] = Math.max(1, Math.round(numeric));
      }
    });

    const constraints = {
      shotMin,
      shotMax,
      noOverlap,
      repetitionCaps,
      beatCoverageRequired,
    };

    const analysis = await loadStoryArcV2AnalysisRunFromDb(script.analysisId);
    const proposal = createStoryArcV2TimelineProposal(
      script,
      selectedVariant,
      constraints,
      analysis,
    );

    storyArcV2TimelineProposals.set(proposal.proposalId, proposal);
    void persistStoryArcV2TablePayload(
      "storyarc_timeline_proposals",
      "proposal_id",
      proposal.proposalId,
      "proposal_payload",
      proposal as unknown as Record<string, unknown>,
    );

    completePhaseMetric("completed", {
      scriptId,
      proposalId: proposal.proposalId,
      selectedVariant: proposal.selectedVariant,
      selectedClipCount:
        proposal.variants[proposal.selectedVariant]?.timeline.clips.length || 0,
    });
    return res.json({
      success: true,
      proposal,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to plan timeline";
    completePhaseMetric("failed", { reason: "exception", error: message });
    return res.status(500).json({ success: false, error: message });
  }
});

app.post("/api/story-arc/v2/timeline/apply", async (req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("apply", {
    operation: "apply",
  });
  try {
    const proposalId = readString(req.body?.proposalId);
    const revision = Math.round(readNumber(req.body?.revision) ?? -1);
    if (!proposalId) {
      completePhaseMetric("failed", { reason: "missing_proposal_id" });
      return res
        .status(400)
        .json({ success: false, error: "Missing proposalId" });
    }
    const proposal = await loadStoryArcV2ProposalFromDb(proposalId);
    if (!proposal) {
      completePhaseMetric("failed", {
        reason: "proposal_not_found",
        proposalId,
      });
      return res
        .status(404)
        .json({ success: false, error: "Proposal not found" });
    }
    if (revision > 0 && revision !== proposal.revision) {
      completePhaseMetric("failed", {
        reason: "revision_mismatch",
        proposalId,
        requestedRevision: revision,
        currentRevision: proposal.revision,
      });
      return res.status(409).json({
        success: false,
        error: `Revision mismatch. Requested ${revision}, current ${proposal.revision}.`,
      });
    }
    const ledgerKey = `${proposalId}:${proposal.revision}`;
    const existing = storyArcV2ApplyLedger.get(ledgerKey);
    if (existing && !existing.revertedAt) {
      completePhaseMetric("completed", {
        proposalId,
        revision: proposal.revision,
        idempotent: true,
      });
      return res.json({
        success: true,
        idempotent: true,
        proposalId,
        revision: proposal.revision,
        appliedAt: existing.appliedAt,
        applyCount: existing.applyCount,
        revertedAt: existing.revertedAt,
        revertCount: existing.revertCount,
        timeline: proposal.variants[proposal.selectedVariant]?.timeline || null,
        editDecisions: proposal.editDecisions,
      });
    }

    const entry: StoryArcV2ApplyLedgerEntry = {
      appliedAt: new Date().toISOString(),
      applyCount: (existing?.applyCount || 0) + 1,
      revertedAt: null,
      revertCount: existing?.revertCount || 0,
    };
    storyArcV2ApplyLedger.set(ledgerKey, entry);
    void persistStoryArcV2TimelineApplyEvent({
      proposalId,
      scriptId: proposal.scriptId,
      revision: proposal.revision,
      applyKey: ledgerKey,
      eventType: "apply",
      eventPayload: {
        idempotent: false,
        appliedAt: entry.appliedAt,
        applyCount: entry.applyCount,
        revertedAt: entry.revertedAt,
        revertCount: entry.revertCount,
      },
    });
    completePhaseMetric("completed", {
      proposalId,
      revision: proposal.revision,
      idempotent: false,
    });
    return res.json({
      success: true,
      idempotent: false,
      proposalId,
      revision: proposal.revision,
      appliedAt: entry.appliedAt,
      applyCount: entry.applyCount,
      revertedAt: entry.revertedAt,
      revertCount: entry.revertCount,
      timeline: proposal.variants[proposal.selectedVariant]?.timeline || null,
      editDecisions: proposal.editDecisions,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to apply timeline";
    completePhaseMetric("failed", { reason: "exception", error: message });
    return res.status(500).json({ success: false, error: message });
  }
});

app.post("/api/story-arc/v2/timeline/revert", async (req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("apply", {
    operation: "revert",
  });
  try {
    const proposalId = readString(req.body?.proposalId);
    const revision = Math.round(readNumber(req.body?.revision) ?? -1);
    const reason = readString(req.body?.reason);
    if (!proposalId) {
      completePhaseMetric("failed", { reason: "missing_proposal_id" });
      return res
        .status(400)
        .json({ success: false, error: "Missing proposalId" });
    }
    const proposal = await loadStoryArcV2ProposalFromDb(proposalId);
    if (!proposal) {
      completePhaseMetric("failed", {
        reason: "proposal_not_found",
        proposalId,
      });
      return res
        .status(404)
        .json({ success: false, error: "Proposal not found" });
    }
    if (revision > 0 && revision !== proposal.revision) {
      completePhaseMetric("failed", {
        reason: "revision_mismatch",
        proposalId,
        requestedRevision: revision,
        currentRevision: proposal.revision,
      });
      return res.status(409).json({
        success: false,
        error: `Revision mismatch. Requested ${revision}, current ${proposal.revision}.`,
      });
    }

    const ledgerKey = `${proposalId}:${proposal.revision}`;
    const existing = storyArcV2ApplyLedger.get(ledgerKey);
    if (!existing) {
      completePhaseMetric("failed", {
        reason: "apply_missing_before_revert",
        proposalId,
        revision: proposal.revision,
      });
      return res.status(409).json({
        success: false,
        error: "Timeline has not been applied yet for this proposal revision.",
      });
    }
    if (existing.revertedAt) {
      completePhaseMetric("completed", {
        proposalId,
        revision: proposal.revision,
        idempotent: true,
      });
      return res.json({
        success: true,
        idempotent: true,
        proposalId,
        revision: proposal.revision,
        appliedAt: existing.appliedAt,
        applyCount: existing.applyCount,
        revertedAt: existing.revertedAt,
        revertCount: existing.revertCount,
      });
    }

    const next: StoryArcV2ApplyLedgerEntry = {
      ...existing,
      revertedAt: new Date().toISOString(),
      revertCount: existing.revertCount + 1,
    };
    storyArcV2ApplyLedger.set(ledgerKey, next);
    void persistStoryArcV2TimelineApplyEvent({
      proposalId,
      scriptId: proposal.scriptId,
      revision: proposal.revision,
      applyKey: ledgerKey,
      eventType: "revert",
      eventPayload: {
        idempotent: false,
        reason: reason || null,
        appliedAt: next.appliedAt,
        applyCount: next.applyCount,
        revertedAt: next.revertedAt,
        revertCount: next.revertCount,
      },
    });
    completePhaseMetric("completed", {
      proposalId,
      revision: proposal.revision,
      idempotent: false,
    });
    return res.json({
      success: true,
      idempotent: false,
      proposalId,
      revision: proposal.revision,
      appliedAt: next.appliedAt,
      applyCount: next.applyCount,
      revertedAt: next.revertedAt,
      revertCount: next.revertCount,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to revert timeline";
    completePhaseMetric("failed", { reason: "exception", error: message });
    return res.status(500).json({ success: false, error: message });
  }
});

app.post("/api/story-arc/v2/quality/evaluate", async (req, res) => {
  try {
    const proposalId = readString(req.body?.proposalId);
    if (!proposalId) {
      return res
        .status(400)
        .json({ success: false, error: "Missing proposalId" });
    }

    const proposal = await loadStoryArcV2ProposalFromDb(proposalId);
    if (!proposal) {
      return res
        .status(404)
        .json({ success: false, error: "Proposal not found" });
    }

    const script = await loadStoryArcV2ScriptFromDb(proposal.scriptId);
    if (!script) {
      return res
        .status(404)
        .json({ success: false, error: "Script not found for proposal" });
    }

    const analysis = await loadStoryArcV2AnalysisRunFromDb(script.analysisId);
    const feedbackProfile = await ensureStoryArcV2FeedbackProfile(
      resolveStoryArcV2ProjectKey(analysis?.projectId || null),
    );

    const scorecard = evaluateStoryArcV2QualityScorecard(
      script,
      proposal,
      feedbackProfile,
    );
    storyArcV2QualityScorecards.set(scorecard.scorecardId, scorecard);
    void persistStoryArcV2QualityScorecard(scorecard);

    return res.json({
      success: true,
      scorecard,
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to evaluate quality";
    return res.status(500).json({ success: false, error: message });
  }
});

app.get("/api/story-arc/v2/quality/scorecards", async (req, res) => {
  try {
    const requestedProjectKey = resolveStoryArcV2ProjectKey(
      readString(req.query?.projectId) || null,
    );
    const filterByProject = Boolean(readString(req.query?.projectId));
    const limit = Math.max(
      1,
      Math.min(100, Math.round(readNumber(req.query?.limit) ?? 20)),
    );

    const fromMemory = Array.from(storyArcV2QualityScorecards.values())
      .filter((entry) =>
        filterByProject
          ? resolveStoryArcV2ProjectKey(entry.projectId) === requestedProjectKey
          : true,
      )
      .sort((left, right) => right.generatedAt.localeCompare(left.generatedAt));

    if (
      fromMemory.length < limit &&
      (await hasTable("storyarc_quality_scorecards"))
    ) {
      const dbRows = filterByProject
        ? await pool.query(
            `select scorecard_payload from storyarc_quality_scorecards
             where coalesce(project_id, 'global') = $1
             order by created_at desc
             limit $2`,
            [requestedProjectKey, limit],
          )
        : await pool.query(
            `select scorecard_payload from storyarc_quality_scorecards
             order by created_at desc
             limit $1`,
            [limit],
          );

      dbRows.rows.forEach((row) => {
        if (!isUnknownRecord(row.scorecard_payload)) return;
        const scorecard =
          row.scorecard_payload as unknown as StoryArcV2QualityScorecard;
        if (!scorecard.scorecardId) return;
        storyArcV2QualityScorecards.set(scorecard.scorecardId, scorecard);
      });
    }

    const scorecards = Array.from(storyArcV2QualityScorecards.values())
      .filter((entry) =>
        filterByProject
          ? resolveStoryArcV2ProjectKey(entry.projectId) === requestedProjectKey
          : true,
      )
      .sort((left, right) => right.generatedAt.localeCompare(left.generatedAt))
      .slice(0, limit);

    return res.json({
      success: true,
      total: scorecards.length,
      scorecards,
    });
  } catch (error) {
    const message =
      error instanceof Error
        ? error.message
        : "Failed to list quality scorecards";
    return res.status(500).json({ success: false, error: message });
  }
});

