app.post("/api/story-arc/v2/benchmark/golden/run", async (req, res) => {
  try {
    const datasetName =
      readString(req.body?.datasetName) || "storyarc-v2-golden";
    const rawCases = Array.isArray(req.body?.cases) ? req.body.cases : [];
    const testCases: StoryArcV2GoldenBenchmarkCase[] = rawCases
      .map((entry: unknown, index: number) => {
        if (!isUnknownRecord(entry)) return null;
        const analysisId = readString(entry.analysisId);
        if (!analysisId) return null;
        const variantRaw = normalizeModelLookupValue(
          readString(entry.variant) || "balanced",
        );
        const variant: StoryArcV2Variant =
          variantRaw === "safe" || variantRaw === "bold"
            ? (variantRaw as StoryArcV2Variant)
            : "balanced";
        return {
          caseId: readString(entry.caseId) || `case-${index + 1}`,
          analysisId,
          targetDuration: Number(
            clampStoryArcV2Number(
              readNumber(entry.targetDuration) ?? 90,
              20,
              1800,
            ).toFixed(2),
          ),
          variant,
          minOverallScore: Number(
            clampStoryArcV2Number(
              readNumber(entry.minOverallScore) ?? 0.65,
              0,
              1,
            ).toFixed(3),
          ),
          minBeatCoverage: Number(
            clampStoryArcV2Number(
              readNumber(entry.minBeatCoverage) ?? 0.95,
              0,
              1,
            ).toFixed(3),
          ),
        };
      })
      .filter(
        (
          entry: StoryArcV2GoldenBenchmarkCase | null,
        ): entry is StoryArcV2GoldenBenchmarkCase => entry !== null,
      );

    if (testCases.length === 0) {
      return res
        .status(400)
        .json({
          success: false,
          error: "At least one valid benchmark case is required",
        });
    }

    const run = await runStoryArcV2GoldenBenchmark(datasetName, testCases);
    return res.json({ success: true, run });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to run golden benchmark";
    return res.status(500).json({ success: false, error: message });
  }
});

app.get("/api/story-arc/v2/benchmark/golden/runs", async (req, res) => {
  try {
    const limit = Math.max(
      1,
      Math.min(50, Math.round(readNumber(req.query?.limit) ?? 10)),
    );
    let runs = Array.from(storyArcV2GoldenBenchmarkRuns.values()).sort(
      (left, right) => right.startedAt.localeCompare(left.startedAt),
    );

    if (
      runs.length < limit &&
      (await hasTable("storyarc_golden_benchmark_runs"))
    ) {
      const result = await pool.query(
        `select run_payload from storyarc_golden_benchmark_runs
         order by created_at desc
         limit $1`,
        [limit],
      );
      result.rows.forEach((row) => {
        if (!isUnknownRecord(row.run_payload)) return;
        const run = row.run_payload as unknown as StoryArcV2GoldenBenchmarkRun;
        if (!run.runId) return;
        storyArcV2GoldenBenchmarkRuns.set(run.runId, run);
      });
      runs = Array.from(storyArcV2GoldenBenchmarkRuns.values()).sort(
        (left, right) => right.startedAt.localeCompare(left.startedAt),
      );
    }

    return res.json({
      success: true,
      total: Math.min(limit, runs.length),
      runs: runs.slice(0, limit),
    });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Failed to list benchmark runs";
    return res.status(500).json({ success: false, error: message });
  }
});

