function normalizeCommunityProfession(rawValue: unknown): string {
  const normalized = String(rawValue || "")
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");

  switch (normalized) {
    case "photo":
    case "photographer":
      return "photographer";
    case "video":
    case "videographer":
      return "videographer";
    case "music":
    case "producer":
    case "musicproducer":
    case "music_producer":
      return "music_producer";
    case "enterprise":
      return "enterprise";
    case "vendor":
      return "vendor";
    case "cross_profession":
    case "all":
      return "cross_profession";
    default:
      return normalized || "photographer";
  }
}

function getCommunityProfessionLabel(profession: string): string {
  switch (normalizeCommunityProfession(profession)) {
    case "videographer":
      return "videografer";
    case "music_producer":
      return "music producers";
    case "enterprise":
      return "enterprise-team";
    case "vendor":
      return "partnere";
    case "cross_profession":
      return "skapere";
    case "photographer":
    default:
      return "fotografer";
  }
}

function getCommunityAccessUserId(req: express.Request): string {
  const headerUserId = req.header("x-user-id");
  if (headerUserId && headerUserId.trim()) {
    return headerUserId.trim();
  }
  if (typeof req.body?.userId === "string" && req.body.userId.trim()) {
    return req.body.userId.trim();
  }
  return "";
}

