// ============================================
// User Interface Preferences API - DB Persistence
// ============================================

type InterfacePreferencesPayload = {
  theme: string;
  language: string;
  notificationsEnabled: boolean;
  dashboardLayout: string;
  timezone: string;
  currency: string;
};

function getDefaultInterfacePreferences(): InterfacePreferencesPayload {
  return {
    theme: "light",
    language: "nb-NO",
    notificationsEnabled: true,
    dashboardLayout: "cards",
    timezone: "Europe/Oslo",
    currency: "NOK",
  };
}

function normalizeInterfacePreferencesRecord(
  row: Record<string, unknown> | null | undefined,
): InterfacePreferencesPayload {
  const defaults = getDefaultInterfacePreferences();
  const preferences = readJsonObject(row?.preferences);
  const dashboard = readJsonObject(row?.dashboard);
  const notifications = readJsonObject(row?.notifications);

  const notificationsEnabled =
    typeof notifications.enabled === "boolean"
      ? notifications.enabled
      : typeof preferences.notificationsEnabled === "boolean"
        ? preferences.notificationsEnabled
        : defaults.notificationsEnabled;

  const dashboardLayout =
    readString(dashboard.layout) ||
    readString(preferences.dashboardLayout) ||
    defaults.dashboardLayout;

  return {
    theme:
      readString(row?.theme) || readString(preferences.theme) || defaults.theme,
    language:
      readString(row?.language) ||
      readString(preferences.language) ||
      defaults.language,
    notificationsEnabled,
    dashboardLayout,
    timezone:
      readString(row?.timezone) ||
      readString(preferences.timezone) ||
      defaults.timezone,
    currency: readString(preferences.currency) || defaults.currency,
  };
}

// Get user interface preferences
app.get("/api/user/interface-preferences/:sessionId", async (req, res) => {
  const { sessionId } = req.params;
  const fromCompatMemory = compatInterfacePreferencesStore.get(sessionId);
  if (fromCompatMemory) {
    return res.json({
      success: true,
      preferences: fromCompatMemory,
      source: "compat-store",
    });
  }

  const fromCompatDb = await compatStoreGet<Record<string, unknown>>(
    dbCompatInterfacePreferencesKey(sessionId),
  );
  if (fromCompatDb && typeof fromCompatDb === "object") {
    compatInterfacePreferencesStore.set(sessionId, fromCompatDb);
    return res.json({
      success: true,
      preferences: fromCompatDb,
      source: "compat-store",
    });
  }

  try {
    const prefs = await pool.query<Record<string, unknown>>(
      `SELECT id, user_id, preferences, theme, language, timezone, notifications, dashboard, created_at, updated_at
       FROM user_preferences
       WHERE user_id = $1
       ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
       LIMIT 1`,
      [sessionId],
    );

    if (prefs.rows.length > 0) {
      const normalized = normalizeInterfacePreferencesRecord(prefs.rows[0]);
      compatInterfacePreferencesStore.set(sessionId, normalized);
      await compatStoreSet(
        dbCompatInterfacePreferencesKey(sessionId),
        normalized,
      );
      return res.json({
        success: true,
        preferences: normalized,
        source: "database",
      });
    }

    // Return defaults if no preferences found
    res.json({
      success: true,
      preferences: getDefaultInterfacePreferences(),
      source: "defaults",
    });
  } catch (error) {
    console.error("Error fetching interface preferences:", error);
    res.json({
      success: true,
      preferences: getDefaultInterfacePreferences(),
      source: "defaults",
    });
  }
});

// Save user interface preferences
app.put("/api/user/interface-preferences/:sessionId", async (req, res) => {
  const { sessionId } = req.params;
  const preferences = req.body;
  const compatNext = {
    ...(compatInterfacePreferencesStore.get(sessionId) || {}),
    ...(preferences || {}),
    updatedAt: new Date().toISOString(),
  };
  compatInterfacePreferencesStore.set(sessionId, compatNext);
  await compatStoreSet(dbCompatInterfacePreferencesKey(sessionId), compatNext);

  try {
    const normalized = {
      ...getDefaultInterfacePreferences(),
      ...(preferences || {}),
    };
    const existing = await pool.query<{ id: string }>(
      `SELECT id
       FROM user_preferences
       WHERE user_id = $1
       ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
       LIMIT 1`,
      [sessionId],
    );

    const dashboardPayload = {
      layout: normalized.dashboardLayout,
    };
    const notificationsPayload = {
      enabled: normalized.notificationsEnabled,
    };
    const preferencesPayload = {
      theme: normalized.theme,
      language: normalized.language,
      notificationsEnabled: normalized.notificationsEnabled,
      dashboardLayout: normalized.dashboardLayout,
      timezone: normalized.timezone,
      currency: normalized.currency,
    };

    if (existing.rows.length > 0) {
      // Update existing
      await pool.query(
        `UPDATE user_preferences
         SET theme = $2,
             language = $3,
             timezone = $4,
             notifications = $5::jsonb,
             dashboard = $6::jsonb,
             preferences = $7::jsonb,
             updated_at = NOW()
         WHERE id = $1`,
        [
          existing.rows[0].id,
          normalized.theme,
          normalized.language,
          normalized.timezone,
          JSON.stringify(notificationsPayload),
          JSON.stringify(dashboardPayload),
          JSON.stringify(preferencesPayload),
        ],
      );
    } else {
      // Insert new
      await pool.query(
        `INSERT INTO user_preferences (
          id, user_id, preferences, theme, language, timezone, notifications, dashboard, created_at, updated_at
        ) VALUES (
          $1, $2, $3::jsonb, $4, $5, $6, $7::jsonb, $8::jsonb, NOW(), NOW()
        )`,
        [
          crypto.randomUUID(),
          sessionId,
          JSON.stringify(preferencesPayload),
          normalized.theme,
          normalized.language,
          normalized.timezone,
          JSON.stringify(notificationsPayload),
          JSON.stringify(dashboardPayload),
        ],
      );
    }

    res.json({
      success: true,
      message: "Preferences saved to database",
      source: "database",
    });
  } catch (error) {
    console.error(
      "Error saving interface preferences to DB, using compatibility store:",
      error,
    );
    res.json({
      success: true,
      message: "Preferences saved to compatibility store",
      source: "compat-store",
    });
  }
});

