// --- Lead import stubs -------------------------------------------------
// useLeadImport queries /import/leads and /import/history via the default
// queryFn (the queryKey is used as the URL). Backed by sales_leads when a
// user id is supplied; empty arrays for anonymous sessions.
app.get("/import/leads", async (req, res) => {
  try {
    const queryUserId = readString(req.query.userId);
    const headerUserId = readString(req.headers["x-user-id"]);
    const userId = queryUserId || headerUserId;
    if (!userId || userId === "guest") {
      return res.json({ leads: [] });
    }
    const storageShape = await resolveSalesLeadsStorageShape();
    const result = await pool.query(
      `${buildSalesLeadSelectQuery(storageShape)} WHERE user_id = $1 AND status IN ('cold','warm','hot','qualified') ORDER BY updated_at DESC NULLS LAST, created_at DESC LIMIT 100`,
      [userId],
    );
    const leads = result.rows.map((row: Record<string, unknown>) => {
      const mapped = mapSalesLeadRow(row);
      return {
        id: mapped.id,
        title: mapped.notes?.slice(0, 60) || `${mapped.projectType} — ${mapped.name}`,
        clientName: mapped.name,
        clientEmail: mapped.email,
        clientPhone: mapped.phone,
        projectType: mapped.projectType,
        location: mapped.location,
        preferredDate: mapped.eventDate,
        estimatedBudget: mapped.estimatedValue,
        specialRequests: mapped.notes,
        source: mapped.source,
      };
    });
    res.json({ leads });
  } catch (error) {
    if (isMissingRelationError(error) || isMissingColumnError(error)) {
      return res.json({ leads: [] });
    }
    console.error("/import/leads failed:", error);
    res.status(500).json({ error: "Could not fetch leads for import" });
  }
});

app.get("/import/history", async (_req, res) => {
  res.json({ history: [] });
});

app.post("/import/lead/:leadId", async (req, res) => {
  try {
    const leadId = readString(req.params.leadId);
    if (!leadId) {
      return res.status(400).json({ error: "Lead ID is required" });
    }
    const storageShape = await resolveSalesLeadsStorageShape();
    const result = await pool.query(
      `${buildSalesLeadSelectQuery(storageShape)} WHERE id = $1 LIMIT 1`,
      [leadId],
    );
    if (result.rowCount === 0) {
      return res.status(404).json({ error: "Lead not found" });
    }
    const mapped = mapSalesLeadRow(result.rows[0] as Record<string, unknown>);
    res.json({
      projectData: {
        projectName: `${mapped.projectType} — ${mapped.name}`,
        projectType: mapped.projectType,
        clientName: mapped.name,
        location: mapped.location,
        projectDate: mapped.eventDate,
        totalPrice: mapped.estimatedValue,
        specialRequests: mapped.notes,
      },
    });
  } catch (error) {
    if (isMissingRelationError(error) || isMissingColumnError(error)) {
      return res.status(404).json({ error: "Lead not found" });
    }
    console.error("/import/lead/:leadId failed:", error);
    res.status(500).json({ error: "Could not import lead" });
  }
});

// ── Ergonomics telemetry ─────────────────────────────────────────
// Opt-in telemetry that tracks the cognitive cost of the photo-
// grapher's work — decision fatigue on long culls, indecision loops
// on near-duplicate frames, session-level reflect answers — so the
// product can remove the parts that drain them. The client hook
// buffers events locally and flushes in batches; every write is
// user-scoped and the aggregated summary endpoint never exposes
// individual events, only bucketed stats.

app.post("/api/telemetry/culling-session", async (req, res) => {
  const userId = getUserIdFromAuth(req);
  if (!userId) {
    return res.status(401).json({ error: "unauthorized" });
  }
  const body = req.body as { events?: unknown } | undefined;
  const rawEvents = Array.isArray(body?.events) ? body.events : [];
  // Cap per-request batch size so a misbehaving client can't flood
  // the DB. Well above the client's typical 30-second flush window.
  if (rawEvents.length === 0) {
    return res.json({ success: true, ingested: 0 });
  }
  if (rawEvents.length > 2000) {
    return res
      .status(413)
      .json({ error: "batch_too_large", max: 2000 });
  }
  try {
    const ALLOWED_KINDS = new Set([
      "session_start",
      "view",
      "decide",
      "reverse",
      "pause",
      "session_end",
    ]);
    const events = rawEvents
      .map((raw) => {
        if (!raw || typeof raw !== "object") return null;
        const r = raw as Record<string, unknown>;
        if (typeof r.sessionId !== "string" || !r.sessionId) return null;
        if (typeof r.kind !== "string" || !ALLOWED_KINDS.has(r.kind)) return null;
        return {
          sessionId: String(r.sessionId).slice(0, 128),
          kind: r.kind as
            | "session_start"
            | "view"
            | "decide"
            | "reverse"
            | "pause"
            | "session_end",
          ms: Number(r.ms) || 0,
          sequence: Number(r.sequence) || 0,
          assetId:
            typeof r.assetId === "string" ? r.assetId.slice(0, 128) : null,
          action:
            typeof r.action === "string" ? r.action.slice(0, 64) : null,
          previousAction:
            typeof r.previousAction === "string"
              ? r.previousAction.slice(0, 64)
              : null,
          newAction:
            typeof r.newAction === "string"
              ? r.newAction.slice(0, 64)
              : null,
          firstView:
            typeof r.firstView === "boolean" ? r.firstView : undefined,
        };
      })
      .filter((e): e is NonNullable<typeof e> => e !== null);
    const { ingested } = await ingestErgonomicsBatch(pool, userId, events);
    res.json({ success: true, ingested });
  } catch (error) {
    console.error("[telemetry] culling-session ingest failed:", error);
    res.status(500).json({ error: "ingest_failed" });
  }
});

app.post("/api/telemetry/reflect", async (req, res) => {
  const userId = getUserIdFromAuth(req);
  if (!userId) {
    return res.status(401).json({ error: "unauthorized" });
  }
  const body = req.body as {
    sessionId?: unknown;
    hardest?: unknown;
    regretted?: unknown;
    wouldSave?: unknown;
  } | undefined;
  if (typeof body?.sessionId !== "string" || !body.sessionId) {
    return res.status(400).json({ error: "sessionId_required" });
  }
  try {
    const { id } = await ingestErgonomicsReflect(
      pool,
      userId,
      String(body.sessionId).slice(0, 128),
      {
        hardest: typeof body.hardest === "string" ? body.hardest : undefined,
        regretted: typeof body.regretted === "string" ? body.regretted : undefined,
        wouldSave:
          typeof body.wouldSave === "string" ? body.wouldSave : undefined,
      },
    );
    res.json({ success: true, id });
  } catch (error) {
    console.error("[telemetry] reflect ingest failed:", error);
    res.status(500).json({ error: "reflect_ingest_failed" });
  }
});

// GET /api/telemetry/ergonomics/session/:sessionId — the "immediate
// value" endpoint for the post-session insights card. Compares this
// session's stats against the photographer's own last-30-days
// baseline (excluding the session itself) and returns ready-to-render
// delta headlines so the card doesn't duplicate the comparison logic
// on the client.
app.get(
  "/api/telemetry/ergonomics/session/:sessionId",
  async (req, res) => {
    const userId = getUserIdFromAuth(req);
    if (!userId) {
      return res.status(401).json({ error: "unauthorized" });
    }
    const sessionId = String(req.params.sessionId || "").slice(0, 128);
    if (!sessionId) {
      return res.status(400).json({ error: "sessionId_required" });
    }
    try {
      const session = await summariseErgonomicsSession(pool, userId, sessionId);
      const baseline = await summariseErgonomicsForUser(
        pool,
        userId,
        30,
        sessionId,
      );
      const comparison = compareErgonomicsSession(session, baseline);
      res.json({ success: true, sessionId, session, baseline, comparison });
    } catch (error) {
      console.error("[telemetry] session summary failed:", error);
      res.status(500).json({ error: "session_summary_failed" });
    }
  },
);

app.get("/api/telemetry/ergonomics/summary", async (req, res) => {
  const userId = getUserIdFromAuth(req);
  if (!userId) {
    return res.status(401).json({ error: "unauthorized" });
  }
  const lookbackDays = Number(req.query?.lookbackDays) || 30;
  try {
    const summary = await summariseErgonomicsForUser(pool, userId, lookbackDays);
    res.json({ success: true, lookbackDays, summary });
  } catch (error) {
    console.error("[telemetry] summary failed:", error);
    res.status(500).json({ error: "summary_failed" });
  }
});

// Catch-all for unhandled API routes
app.all("/api/*", (req, res) => {
  res.status(404).json({ message: "Endpoint not implemented", path: req.path });
});

// Create HTTP server for WebSocket support
const httpServer = createServer(app);
createWebSocketServer(httpServer, db);
attachCaptureWebSocket(httpServer, pool, activeSessions);
attachUserEventsWebSocket(httpServer, pool, activeSessions);

// Drive batch upload worker: periodic sweep of ``queued`` +
// ``running`` batches. Tick interval set conservatively so one
// unresponsive OAuth refresh can't starve other workers. Skipped
// automatically when the CreatorHub Google OAuth env vars are
// unset (dev environments without Google wiring).
const driveBatchWorker = startDriveBatchWorker(
  pool,
  makePgDriveClientResolver(pool),
);
// ``driveBatchWorker.stop`` is intentionally not wired to a
// shutdown hook — ``.unref()`` inside the worker lets the process
// exit on its own, and ``app.close`` isn't a pattern used elsewhere
// here. Exposed on the module scope for tests that need to reach in.
void driveBatchWorker;

httpServer.listen(PORT, "0.0.0.0", () => {
  console.log(`🚀 Backend server running on port ${PORT} (HTTP + WebSocket)`);
  maybeStartRoleRoomGoogleRedirectBridge();
  maybeStartRoleRoomLinkedInRedirectBridge();
  maybeStartRoleRoomCommercialReminderSweep();
  maybeStartAuditionReminderSweep({ pool });
  maybeStartTeamInviteSweep({ pool });
  const stripeForInvoiceRunner = getRoleRoomStripeClient();
  if (stripeForInvoiceRunner) {
    maybeStartSmsInvoiceSweep({
      pool,
      stripe: stripeForInvoiceRunner,
      resolveCustomer: resolveStripeCustomerForCastingProject,
    });
    maybeStartWhatsAppInvoiceSweep({
      pool,
      stripe: stripeForInvoiceRunner,
      resolveCustomer: resolveStripeCustomerForCastingProject,
    });
    // Pressroom (composer) månedlig faktura-sweep. Kjører første gang
    // ~120s etter boot og deretter hver 24t; idempotent via
    // composer_usage.stripe_invoice_item_id. Stripe-klient instansieres
    // internt i runneren fra STRIPE_SECRET_KEY.
    maybeStartComposerInvoiceSweep(pool);
  }
  // Page Metadata 2.0 — daglig competitor-watchlist-snapshot. Kjører
  // første sweep ~180s etter boot og deretter hver 24t; idempotent via
  // 12-timers skip-vindu på last_fetched_at.
  maybeStartCompetitorSnapshotSweep(pool);
  maybeStartRoleRoomAiAuditPrune();
  maybeStartRoleRoomAgentDailyScan();
  // Scheduled-publish worker: scan role_room_instagram_publish_jobs
  // every 30s for due rows and run them. No-op until a job actually
  // becomes due, so it's safe to always start.
  startInstagramPublishWorker(pool);
  // Cross-platform publisher registry: registrer alle plattform-implementa-
  // sjoner i social-publisher-modulen. Feed Planner / Marketing Plan
  // dispatchPublish() ruter til riktig publisher basert på platform-felt.
  registerInstagramPublisher(pool);
  registerFacebookPagePublisher(pool);
  registerLinkedInPublisher(pool);
  registerYouTubePublisher(pool);
  registerTikTokPublisher(pool);
  // Sentiment-worker for unified inbox: skanner social_events hvert 60s
  // og scorer pending events via Claude Haiku. Disabled hvis
  // ANTHROPIC_API_KEY ikke er satt.
  startSentimentWorker(pool);
  // Proaktiv token-refresh: timely sweep gjennom alle connections for å
  // refresh-e tokens innen 7 dager av expiry. Hindrer at en konto som
  // ikke brukes regelmessig ender opp med expired token. Disabled hvis
  // META_APP_ID/SECRET ikke er satt.
  startTokenRefreshWorker(pool);
  // LinkedIn-insights polling: 1-time sweep mot /v2/socialActions for
  // post-level engagement (likes + comments). LinkedIn har ingen webhooks
  // for member-level posts, så polling er eneste vei.
  startLinkedInInsightsWorker(pool);
  // YouTube-insights polling: samme mønster som LinkedIn. Henter views,
  // likes, comments-counts via youtube.videos.list og kommentar-bodies
  // via youtube.commentThreads.list. Ingen YouTube-webhooks for member-
  // channels, så polling er eneste vei.
  startYouTubeInsightsWorker(pool);
  // One-off probe so the boot log makes ffmpeg presence/absence
  // obvious without hitting /api/health. Dockerfile installs ffmpeg
  // on the Render image, so this should always log "available".
  void ffmpegAvailable().then((ok) => {
    console.log(`🎬 ffmpeg ${ok ? "available — reels will be normalised to 1080×1920 H.264" : "NOT FOUND — reels pass through unchanged"}`);
  });
  if (isStoryArcV2Enabled() && STORY_ARC_V2_STARTUP_WARMUP_ENABLED) {
    void runStoryArcV2StartupWarmup();
  }
});
